ClinicalChunks.register("data/templates-043.js",[{"id":"templates-a780db97e32df3c00ffd","key":"v1-c9ccc21dfe2a3058|templates-a780db97e32df3c00ffd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"呼吸衰竭","category":"门诊病历模板","raw":{"name":"呼吸衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历626","templates":{"主诉":"呼吸困难伴发绀1天","现病史":"患者存在基础病，为慢性阻塞性肺疾病（慢性呼衰最常见病因，此次急性加重）。于急性起病（数小时内，见于肺炎、肺栓塞、气胸，多为Ⅰ型呼衰）或慢性基础上急性加重（COPD所致，多为Ⅱ型呼衰）后出现下列表现：呼吸困难（进行性加重，静息时明显）、发绀（口唇及甲床，为低氧晚期表现，贫血者可不明显）、烦躁、嗜睡、意识模糊（由低氧或CO₂潴留引起，CO₂麻醉见于COPD高碳酸血症，表现为晨起头痛明显、嗜睡、扑翼样震颤）、球结膜水肿充血（CO₂潴留的特征性表现）、皮肤温暖多汗（CO₂潴留致血管扩张）、心率增快、血压早期升高（低氧致交感兴奋）后晚下降（循环衰竭）、杵状指（慢性低氧，与基础病相关）。呼吸衰竭定义为海平面静息呼吸空气状态下动脉血氧分压<60mmHg（Ⅰ型，单纯低氧），伴或不伴二氧化碳分压>50mmHg（Ⅱ型，低氧合并高碳酸），依据动脉血气诊断。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P108次/分（增快），R28次/分（增快，病情濒危时可减慢），BP96/60mmHg（偏低，见于晚期），SpO2 85%（低）。神志清楚、嗜睡或昏迷（提示CO₂麻醉或低氧性脑病），发绀（口唇及甲床），球结膜水肿充血（CO₂潴留），呼吸急促或浅慢（肌无力和中枢抑制者呼吸节律异常，属濒危表现）伴辅助呼吸肌参与及三凹征；肺部闻及基础病相应体征，如啰音、哮鸣音或呼吸音减低；心脏心率增快或心律失常（低氧所致）；扑翼样震颤（CO₂潴留，类似肝性脑病表现）；皮肤温暖多汗（CO₂潴留）。","辅助检查":"【必做】动脉血气分析（核心，用于确诊及分型：动脉血氧分压<60mmHg提示低氧，为Ⅰ型；动脉血二氧化碳分压>50mmHg提示高碳酸，为Ⅱ型并伴低氧；pH反映酸中毒状态，急性呼吸性酸中毒见于COPD急性加重、pH<7.35，慢性者代偿后pH可正常，据此判断急性或慢性呼衰并指导治疗决策；碳酸氢根反映代偿情况，慢性者升高），需动态监测；【基础病评估】胸部X线或CT（评估肺炎、气胸、肺水肿、肺栓塞等病因）、心电图（筛查心源性病因如心梗、心律失常）、血常规（评估感染）、电解质（低钾可致肌无力）、甲状腺功能（少见病因）；【特殊检查】疑心衰者查BNP及超声，疑肺栓塞者查D-二聚体及CTPA，疑神经肌肉疾病者必要时行肌电图，疑中枢病变者必要时行头颅CT；【监测】持续SpO2监测，用于评估呼衰严重程度及氧疗目标（Ⅱ型目标SpO2 88~92%，此项重要，可防CO₂潴留加重；Ⅰ型目标SpO2>90%）。","初步诊断":"1. 呼吸衰竭（分型：Ⅰ型（低氧性）或Ⅱ型（高碳酸性，低氧伴CO₂潴留）；病程：急性、慢性或慢性急性加重；基础病：慢性阻塞性肺疾病）\n（注：呼吸衰竭为急症，需紧急处理，治疗原则为纠正低氧、治疗原发病并给予支持通气，按类型个体化：①氧疗（立即实施，为核心）：Ⅰ型目标SpO2>90%（PaO2>60mmHg）；Ⅱ型（COPD）采用低流量控制性氧疗1~2L/min，目标SpO2 88~92%，此项重要，因高浓度氧可抑制低氧驱动、加重CO₂潴留（CO₂麻醉），故Ⅱ型呼衰氧疗须控制浓度并复查血气以警惕。②病因治疗：感染予抗感染（广谱，针对COPD急性加重）；支气管痉挛予支气管扩张剂（雾化沙丁胺醇加异丙托溴铵）及激素（COPD或哮喘予静脉甲泼尼龙，减轻气道炎症）；肺栓塞予溶栓或抗凝；气胸予引流；心衰予利尿、扩血管；神经肌肉或中枢病因作相应处理。③通气支持：无创正压通气（NIPPV）为Ⅱ型呼衰（COPD急性加重伴呼吸性酸中毒、pH<7.35）首选，可显著降低插管率及死亡率，采用BiPAP模式，此项重要；Ⅰ型（心源性肺水肿）用CPAP有效；适应证为意识清楚配合、血流动力学稳定；有创机械通气（气管插管）用于无创失败、昏迷、呼吸暂停或血流动力学不稳定者，收入ICU。④纠正酸碱及电解质紊乱：呼吸性酸中毒以改善通气为主，勿单纯补碱；代谢性酸中毒（休克、乳酸升高）予补液及治疗原发病；低钾（可致肌无力）予补钾。⑤对症治疗：祛痰（氨溴索，利于气道廓清）、镇静（仅插管患者，ICU内使用）、营养支持。⑥监测：血气（氧疗及通气调整的关键，初期每30分钟至2小时复查）、持续SpO2、神志（CO₂麻醉致嗜睡提示通气不足，需干预）、呼吸频率及节律（濒危时呼吸减慢，须立即插管）。⑦原发病长期管理：COPD稳定期规范吸入治疗（长效支气管扩张剂，必要时联合激素）、长期家庭氧疗（慢性呼衰伴低氧者每日>15小时，可改善生存，此项重要）、肺康复、戒烟及疫苗接种，以防急性加重导致呼衰反复住院。由急诊、呼吸科或ICU诊治，重症需插管，按呼衰类型个体化氧疗及通气并复查血气指导调整。）","处理方案":"【药物治疗】\n1. 支气管扩张剂：吸入用硫酸沙丁胺醇雾化溶液2.5mg＋吸入用布地奈德混悬液2mg，加生理盐水至3ml雾化吸入，bid×7天，解痉平喘、改善通气。\n2. 祛痰药：盐酸氨溴索片30mg tid×7天（或盐酸氨溴索口服溶液10ml tid），稀释痰液、促进排痰，痰液黏稠者可加用乙酰半胱氨酸泡腾片600mg qd。\n3. 抗感染治疗（感染诱发者）：左氧氟沙星片0.5g qd×7天；青霉素不过敏者亦可选阿莫西林克拉维酸钾片0.457g tid×7天，覆盖常见社区病原菌，疗程5～7天。\n4. 茶碱类：多索茶碱片0.2g bid×7天，增强呼吸肌力、改善通气；心率快、心律失常或频繁早搏者慎用或减量。\n【一般治疗及生活指导】\n1. 氧疗：存在低氧血症者予家庭氧疗，鼻导管低流量吸氧（1～2L/min），每日吸氧时间≥15小时，氧浓度不宜过高，防止二氧化碳潴留加重。\n2. 休息与体位：以卧床休息为主，取半卧位或高枕卧位以利呼吸，减少活动、避免用力排便以降低氧耗；保持室内空气流通、温湿度适宜。\n3. 饮食：高蛋白、高维生素、易消化饮食，少量多餐，无心力衰竭者每日饮水1500～2000ml以稀释痰液；避免过饱、忌辛辣油腻及产气食物。\n4. 禁忌：严格戒烟、避免二手烟及粉尘等刺激性气体；注意保暖、避免受凉感冒及去人群密集场所，预防呼吸道感染；禁用镇静催眠药（如地西泮、艾司唑仑），以免抑制呼吸。\n【随诊要求】\n1. 用药后3～5天复诊，复查血气分析、血氧饱和度及胸部影像学，评估氧疗与药物疗效，动态调整方案。\n2. 若出现呼吸困难进行性加重、口唇发绀、意识改变（嗜睡、烦躁、恍惚）或静息血氧饱和度持续低于90%，应立即急诊或住院治疗，不可延误。\n3. 慢性呼吸衰竭患者建议每月复诊1次，监测肺功能、血气及心功能，规范氧疗；每年接种流感疫苗和肺炎球菌疫苗，秋冬季节加强防范。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":758,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"220ecb01af6f673316a2e4841473e5729c68f26600525907005b81ef5ef598f1","pinyin":"huxishuaijie","initials":"hxsj","setting":"out","caseName":"门诊病历626","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历626",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d8a5787e53cc89fd2d2c","key":"v1-c9ccc21dfe2a3058|templates-d8a5787e53cc89fd2d2c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性呼吸衰竭","category":"门诊病历模板","raw":{"name":"急性呼吸衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历627","templates":{"主诉":"呼吸困难伴发绀1天","现病史":"患者1周前无明显诱因出现急性呼吸衰竭相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以呼吸困难伴发绀1天为主要表现，起病急骤，初步诊断考虑急性呼吸衰竭，需急诊即刻完善血气分析检查明确缺氧及二氧化碳潴留程度、判断呼吸衰竭类型，为氧疗及机械通气决策提供依据并动态复查；查血常规了解有无贫血、感染及血红蛋白水平对携氧能力的影响；查CRP、降钙素原两项炎症指标以明确有无细菌感染、鉴别重症肺炎所致呼吸衰竭；患者气道分泌物增多，完善痰培养+药敏检查以明确病原菌并指导抗菌药物选择；完善胸部X线片检查作为床旁基础筛查，并完善胸部CT检查以明确肺部感染、肺不张、气胸、肺水肿等病因及病变范围，排除肺梗死、肺部肿瘤；患者急性起病，需完善心电图及心肌酶检查排除急性心肌梗死、心力衰竭所致呼吸困难；完善电解质及肝肾功能检查，因低钾、低磷等电解质紊乱可加重呼吸肌疲劳，且用药需经肝肾代谢；待病情稳定后完善肺功能检查了解基础通气功能损害程度，为原发病诊断提供线索。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 急性呼吸衰竭\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 支气管舒张剂：吸入用硫酸沙丁胺醇溶液5mg＋吸入用异丙托溴铵溶液0.5mg，加入生理盐水2ml雾化吸入，bid；同时予吸入用布地奈德混悬液1mg雾化吸入，bid，以抗炎、减轻气道黏膜水肿。\n2. 糖皮质激素：甲泼尼龙片16mg qd晨服，疗程3～5天，症状缓解后渐减量至停药（用于COPD、哮喘急性加重及肺水肿相关呼吸衰竭；用药前需排除未控制的感染，或与足量抗感染药同用）。\n3. 抗感染治疗（感染诱发者）：阿莫西林克拉维酸钾片0.625g tid×5～7天；青霉素过敏者改用左氧氟沙星片0.5g qd×5～7天，并据痰培养及药敏结果调整。\n4. 祛痰治疗：盐酸氨溴索片30mg tid×7天；痰液黏稠、排痰困难者加用乙酰半胱氨酸泡腾片600mg qd，雾化后辅以有效咳嗽、拍背排痰。\n\n【一般治疗及生活指导】\n1. 吸氧：遵医嘱持续低流量吸氧（1～2L/min），维持SpO2≥90%；Ⅱ型呼吸衰竭者SpO2不宜超过92%～94%，以免加重CO2潴留，切勿自行调大氧流量。\n2. 休息与体位：绝对卧床休息，取半卧位或端坐位，减轻呼吸做功与肺淤血；减少说话和体力活动，降低机体氧耗。\n3. 饮食：予高蛋白、高维生素、易消化饮食，少食多餐，避免过饱加重呼吸困难；心功能允许时每日饮水1500ml以上以稀释痰液，忌辛辣刺激及产气食物。\n4. 禁忌：绝对戒烟，避免油烟、粉尘、冷空气等刺激；避免受凉、感冒及剧烈运动、屏气用力；禁用镇静催眠药（如地西泮、艾司唑仑）及麻醉性镇咳药，以免抑制呼吸、加重缺氧与CO2潴留。\n\n【随诊要求】\n1. 每3～7天门诊复诊，复查动脉血气分析、血常规、CRP及胸部影像学，评估氧合改善及感染控制情况，动态调整氧流量与药物疗程。\n2. 若治疗24～48小时呼吸困难无缓解或SpO2持续低于90%，或出现嗜睡、意识模糊、烦躁不安、发绀加重等，应立即急诊就诊，必要时住院行无创或有创机械通气。\n3. 复诊时携带既往血气分析、肺功能及影像资料；合并COPD、哮喘、心衰等基础病者同步至相应专科随诊，评估原发病控制情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":759,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bc5ab8df43cbfe39a8b35d9ca12d7f6495356385a50895e88ebc33715883c069","pinyin":"jixinghuxishuaijie","initials":"jxhxsj","setting":"out","caseName":"门诊病历627","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历627",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5c897a89a3e445ce03df","key":"v1-c9ccc21dfe2a3058|templates-5c897a89a3e445ce03df","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性呼吸衰竭","category":"门诊病历模板","raw":{"name":"慢性呼吸衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历628","templates":{"主诉":"气促伴发绀1周","现病史":"患者1周前无明显诱因出现慢性呼吸衰竭相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以气促伴发绀1周为主要表现，病程迁延，初步诊断考虑慢性呼吸衰竭，需完善血气分析检查明确缺氧及二氧化碳潴留程度、判断呼吸衰竭类型并评估代偿情况，为长期家庭氧疗或无创通气提供依据；查血常规了解有无红细胞增多症、贫血及感染征象，慢性缺氧可继发血红蛋白升高；查CRP、降钙素原两项炎症指标以明确有无急性加重期细菌感染、指导抗菌药物使用；患者痰液较多，完善痰培养+药敏检查明确病原菌并指导用药；完善胸部X线片检查作为基础筛查，并完善胸部CT检查以明确慢性阻塞性肺疾病、支气管扩张、肺结核后遗改变、间质性病变等基础病因及范围；完善电解质及肝肾功能检查，因慢性呼吸衰竭患者常合并低钾低氯等电解质紊乱，且利尿剂、茶碱等药物需经肝肾代谢；待病情稳定后完善肺功能检查了解通气功能障碍类型与程度，为原发病诊断及分级提供客观依据。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 慢性呼吸衰竭\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.支气管舒张剂长期规律吸入：噻托溴铵粉雾剂18μg，每日1次吸入（或异丙托溴铵气雾剂2喷 tid，必要时），联合长效β2受体激动剂如福莫特罗吸入剂，长期维持治疗，注意正确吸入方法及漱口。\n2.祛痰治疗：盐酸氨溴索片30mg tid×14天，或乙酰半胱氨酸泡腾片600mg qd×14天，稀释痰液、促进排痰。\n3.急性加重期抗感染（出现痰量增多变脓、发热等感染征象时）：阿莫西林克拉维酸钾片0.625g tid×7天，或左氧氟沙星片0.5g qd×7天（青霉素过敏者选用后者），用药前评估肾功能。\n【一般治疗及生活指导】\n1.家庭氧疗（长期氧疗LTOT）：鼻导管吸氧1.5～2.5L/min，每日吸氧时间≥15小时，维持静息血氧饱和度88%～92%，避免高浓度吸氧。\n2.戒烟，避免粉尘、烟雾及刺激性气体接触；注意保暖，预防呼吸道感染，每年接种流感疫苗和肺炎球菌疫苗。\n3.饮食：高蛋白、高维生素、易消化饮食，少食多餐、避免过饱，保证充足水分摄入以利排痰；适当卧床休息，避免劳累。\n4.呼吸康复：坚持缩唇呼吸、腹式呼吸训练，循序渐进进行步行等轻度有氧运动，运动中出现明显气促、发绀时立即停止休息。\n【随诊要求】\n1.每月门诊复诊1次，复查动脉血气分析及血氧饱和度，评估氧疗效果并调整吸氧流量。\n2.每3个月复查肺功能、胸部影像学，评估病情进展。\n3.如出现呼吸困难进行性加重、痰量增多变脓、发热、精神意识改变（嗜睡、烦躁）、发绀加重等，需立即就医或住院治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":760,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"288fb85811fb245618707a5c7460bf1965f413e8d8f17a12670dfdf325847a97","pinyin":"manxinghuxishuaijie","initials":"mxhxsj","setting":"out","caseName":"门诊病历628","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历628",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-75b9b21cb7c7b91e2d7c","key":"v1-c9ccc21dfe2a3058|templates-75b9b21cb7c7b91e2d7c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺性脑病","category":"门诊病历模板","raw":{"name":"肺性脑病","category":"门诊病历模板","case":{"case_name":"门诊病历629","templates":{"主诉":"嗜睡伴意识模糊1周","现病史":"患者1周前无明显诱因出现肺性脑病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以嗜睡伴意识模糊1周为主要表现，初步诊断考虑肺性脑病，需急诊即刻完善血气分析检查明确二氧化碳潴留及缺氧程度，判断有无呼吸性酸中毒，此为肺性脑病诊断与病情分度的关键依据并需动态复查；查血常规了解有无感染及红细胞增多，评估携氧能力；查CRP、降钙素原两项炎症指标以明确有无肺部感染诱发急性加重，指导抗菌药物使用；患者气道引流不畅，完善痰培养+药敏检查明确病原菌并指导用药；完善胸部X线片检查作为基础筛查，并完善胸部CT检查明确慢性肺病基础病变、肺部感染及有无气胸等并发症；患者意识障碍，需完善电解质及肝肾功能检查排除低钠、低钾等电解质紊乱及肝肾功能不全所致意识改变，并指导经肝肾代谢药物使用；完善血糖及头颅CT检查以排除低血糖、急性脑血管病所致意识障碍，与肺性脑病相鉴别。待病情稳定、意识转清后完善肺功能检查了解基础通气功能损害程度。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 肺性脑病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 支气管舒张剂：茶碱缓释片0.1g po bid×7天，必要时联合沙丁胺醇气雾剂100~200μg按需吸入，解除支气管痉挛、改善通气、减轻二氧化碳潴留。\n2. 祛痰药：盐酸氨溴索片30mg po tid×7~14天，稀释痰液促进排痰；痰液粘稠难咳出者可行雾化吸入化痰治疗。\n3. 糖皮质激素：醋酸泼尼松片30~40mg晨顿服 qd×5~7天，病情缓解后逐渐减量停药；用药期间监测血糖、血压，注意防治消化性溃疡及二重感染。\n4. 抗感染（有感染诱因时）：阿莫西林克拉维酸钾片0.375g po tid×7天，或左氧氟沙星片0.5g po qd×5~7天，据痰培养及药敏结果调整。\n用药禁忌：本病禁用吗啡、地西泮、巴比妥类等镇静催眠及麻醉药物，以免抑制呼吸中枢、加重二氧化碳潴留诱发昏迷。\n\n【一般治疗及生活指导】\n1. 氧疗：持续低流量吸氧1~2L/min（家庭氧疗每日不少于15小时），氧流量勿超过2L/min，目标血氧饱和度88%~92%，切忌高浓度吸氧以防二氧化碳麻醉加重。\n2. 休息与体位：卧床休息或取半卧位，减少活动与耗氧，避免情绪激动和用力排便；保证充足睡眠，烦躁失眠时应就医处理，不得自行服用安眠药。\n3. 饮食：高蛋白、高维生素、易消化饮食，适当控制碳水化合物摄入（少食多餐），每日饮水约1500ml以稀释痰液；严格戒烟戒酒，避免接触烟雾粉尘及刺激性气体。\n4. 活动与防护：病情稳定后循序渐进下床活动（如床边慢走），注意保暖、避免受凉感冒，减少出入人群密集场所，预防呼吸道感染加重。\n\n【随诊要求】\n1. 治疗后3~5天复诊，复查动脉血气分析、血常规、肝肾功能及电解质，评估低氧血症与二氧化碳潴留的改善情况。\n2. 如出现嗜睡、烦躁、胡言乱语、头痛加重、口唇发绀或呼吸困难加重等神志及呼吸异常，须立即就近急诊就诊，不可自行加用镇静安眠药物。\n3. 长期随访：每月复查血气分析1次，每3~6个月复查肺功能、胸部影像及心电图，规范治疗基础疾病（如慢阻肺），坚持长期家庭氧疗及吸入治疗，防止肺性脑病复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":761,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d8e5fee55a738c2ebb94dd18eb5dc9b7912b9db05e8a8a34a4f973d3d01dbdc3","pinyin":"feixingnaobing","initials":"fxnb","setting":"out","caseName":"门诊病历629","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历629",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4f9ebdacfd517a34f92a","key":"v1-c9ccc21dfe2a3058|templates-4f9ebdacfd517a34f92a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺栓塞","category":"门诊病历模板","raw":{"name":"肺栓塞","category":"门诊病历模板","case":{"case_name":"门诊病历630","templates":{"主诉":"突发胸痛伴呼吸困难6小时","现病史":"患者存在危险因素：下肢深静脉血栓（最常见栓子来源）、手术或骨折后制动、长期卧床、长途旅行（经济舱综合征）、肿瘤（高凝状态）、妊娠或产后、口服避孕药或激素、肥胖、高龄、既往血栓史，符合血栓形成的Virchow三要素。于6小时前突发下列表现：呼吸困难（突发，活动后加重，为最常见症状）、胸痛（肺梗死所致胸膜性胸痛，或大栓子所致心绞痛样痛，因右心缺血）、咯血（肺梗死表现，为三联征之一，少见但特异）、晕厥或晕厥前兆（大栓子致血流动力学障碍，此项重要，提示高危需紧急处理）、心悸（心动过速）、咳嗽、烦躁不安、濒死感；大块肺栓塞可致休克（低血压、发绀、右心衰、颈静脉怒张，属急症、死亡率高），慢性血栓栓塞（反复小栓塞）可致肺动脉高压及慢性肺心病。需注意有无下肢深静脉血栓表现（单侧下肢肿胀、疼痛、Homan征，应同时检查），并了解近期手术、卧床、旅行及肿瘤史（危险因素评估，可行Wells评分）。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P106次/分（增快，>100次/分），R26次/分（增快，呼吸急促），BP88/56mmHg（低血压，提示大块栓塞及休克），SpO2 89%（降低）。神志清楚、烦躁或淡漠（低氧或休克所致）。呼吸急促、发绀；肺部闻及啰音（肺梗死）、偶闻胸膜摩擦音；心脏心率增快、P2亢进（肺动脉高压致第二心音亢进，为急性右心负荷的特征性表现）、三尖瓣收缩期杂音（右心扩大致功能性反流）、右室奔马律；颈静脉怒张（右心衰）；下肢单侧肿胀、压痛（提示深静脉血栓，应测量周径评估）；肝大（右心衰）。","辅助检查":"【必做】D-二聚体（血浆D-二聚体正常可排除肺栓塞，患者感检测阴性排除价值大，为门诊低中危患者初筛核心；升高则不特异，炎症、肿瘤、手术后亦可升高，需影像学确认）、动脉血气分析（可见低氧血症、低碳酸血症（过度通气），非特异，正常不能排除）、心电图（窦性心动过速最常见，可见SⅠQⅢTⅢ（Ⅰ导联S波、Ⅲ导联Q波及T波倒置，为大块栓塞特征但非特异）、右束支传导阻滞、肺型P波）、胸部X线（可正常，或见肺不张、胸腔积液、肺动脉段突出（Westernark征，少见），主要用于排除肺炎、气胸等，非特异）、下肢静脉超声（发现深静脉血栓即栓子来源，阳性支持诊断）；【确诊】CT肺动脉造影（CTPA，增强扫描见肺动脉内充盈缺损，为确诊金标准及首选，敏感性和特异性高，同时可评估右心情况（右室增大、右室/左室比值，判断预后））；【其他】超声心动图（可见右室扩大及功能障碍，用于大块栓塞的床旁快速评估，支持诊断并指导溶栓）、V/Q肺通气灌注显像（用于CTPA禁忌者（肾功能不全或碘过敏）备选）、心肌肌钙蛋白及BNP（右心损伤标志物，用于预后评估，升高提示中高危）。","初步诊断":"1. 肺血栓栓塞症（危险分层：低危、中危或高危（伴休克或低血压，为大块栓塞）；栓子来源：下肢深静脉血栓）\n（注：肺栓塞为急症，按危险分层处理，血流动力学状态决定策略：①高危（休克或低血压，属最紧急情况）：立即溶栓，予重组组织型纤溶酶原激活物（rt-PA）100mg静脉滴注2小时；存在溶栓禁忌时行导管碎栓或外科取栓（栓子切除，紧急）；同时抗凝，收入ICU或监护病房。②中危（右心功能不全，肌钙蛋白或BNP升高，无低血压）：予抗凝并住院监护；中高危（右心明显受累且无禁忌）可考虑溶栓，但存在争论，需权衡出血风险，多数以抗凝为主并密切观察。低危：予抗凝，可门诊或短期住院；选用利伐沙班或阿哌沙班等直接口服抗凝药（一线，方案简化，无需监测），或低分子肝素桥接华法林（维持INR 2~3）；总疗程至少3个月，有明确诱发因素（如手术）且已去除者3个月，无诱因或复发者6~12个月以上或延长治疗。③抗凝具体方案：低分子肝素（依诺肝素1mg/kg q12h皮下注射）起始，疑诊即开始，不必等确诊（低出血风险者）→改为直接口服抗凝药（利伐沙班15mg bid×3周→20mg qd长期）。④支持治疗：吸氧（低氧者目标SpO2>90%）、镇痛（胸痛予吗啡，低血压者慎用）、补液（右心衰者谨慎扩容，必要时利尿以减轻肺水肿倾向）。⑤下腔静脉滤器：用于抗凝禁忌（活动性出血或近期大出血）或抗凝失败复发者，以防肺栓塞；但其本身不抗凝，血栓仍可进展，仅短期患者。⑥随访：完成抗凝疗程后评估停药；预防复发需处理危险因素（手术后尽早活动、穿弹力袜、长途旅行时活动下肢、肿瘤治疗、减重）；随访警惕慢性血栓栓塞性肺动脉高压（反复栓塞者行超声及CTEPH评估，必要时行肺动脉内膜剥脱术，转专科）。急诊处理高危肺栓塞须分秒必争，把握溶栓时间窗，此项重要。）","处理方案":"【药物治疗】\n1. 抗凝治疗（首选）：利伐沙班片（拜瑞妥）15mg bid 口服，连用21天后改为20mg qd 口服，总疗程至少3个月（适用于血流动力学稳定的非高危肺栓塞门诊患者；CrCl 15-50ml/min者减量至15mg qd）；或阿哌沙班片5mg bid 口服，总疗程至少3个月。\n2. 低分子肝素桥接（备用方案）：依诺肝素钠注射液1mg/kg（100IU/kg）皮下注射 q12h，连用5-7天，同时重叠华法林钠片2.5-3mg qd 口服，每日监测INR，待INR连续2天稳定于2.0-3.0后停用依诺肝素，继续华法林维持治疗至少3个月。\n3. 对症支持：伴低氧血症（SpO2<90%）者予鼻导管吸氧2-4L/min，维持SpO2≥90%；胸痛明显者予对乙酰氨基酚片0.5g prn，每日不超过4次。高危肺栓塞（伴低血压或休克）非门诊处理范畴，需立即急诊收入院行溶栓治疗（阿替普酶100mg静脉滴注2小时）。\n\n【一般治疗及生活指导】\n1. 休息与活动：急性期（确诊后2周内）卧床休息，避免剧烈活动和用力排便，防止血栓脱落引起再栓塞；症状缓解后逐渐离床活动，但避免久坐久站，长时间乘坐交通工具时每小时活动下肢1次。\n2. 饮食：低盐低脂、清淡易消化饮食，每日饮水1500-2000ml，多食富含膳食纤维的蔬菜水果以保持大便通畅，戒烟限酒。\n3. 禁忌：避免按摩、热敷、揉捏或剧烈按压下肢（尤其血栓侧肢体），以免血栓脱落；停用口服避孕药等含雌激素类药物；抗凝治疗期间避免使用阿司匹林等抗血小板药及非甾体抗炎药，防出血风险叠加。\n4. 并发症观察：密切观察有无咯血、突发胸痛加重、晕厥、抽搐（提示再栓塞或脑栓塞），以及皮肤瘀斑、牙龈出血、黑便、血尿等出血表现，一旦出现立即就诊；下肢穿戴医用弹力袜可减轻血栓后综合征。\n\n【随诊要求】\n1. 服用华法林者每1-2周复查凝血功能（INR目标2.0-3.0）及血常规；服用利伐沙班/阿哌沙班者每3个月复查肝肾功能、血常规及凝血功能。\n2. 规范抗凝治疗满3个月后复查CT肺动脉造影（CTPA）及双下肢静脉超声，评估血栓溶解与右心功能恢复情况，由专科医师决定是否延长抗凝疗程（如合并恶性肿瘤、抗磷脂综合征等危险因素者疗程需≥6个月甚至终身抗凝）。\n3. 治疗期间出现呼吸困难加重、胸痛、咯血、晕厥或任何不明原因出血时，随时急诊就诊；抗凝药物不可自行减量、停药或漏服，漏服利伐沙班6小时内应尽快补服。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":762,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0d6de063b39f9ac5f76fbf4440d3c63e406d030947c5f577ffe7a92fab1ffe17","pinyin":"feishuanse","initials":"fss","setting":"out","caseName":"门诊病历630","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历630",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5d4b9f0836267c0babd8","key":"v1-c9ccc21dfe2a3058|templates-5d4b9f0836267c0babd8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺梗死","category":"门诊病历模板","raw":{"name":"肺梗死","category":"门诊病历模板","case":{"case_name":"门诊病历631","templates":{"主诉":"胸痛伴咯血1周","现病史":"患者1周前无明显诱因出现肺梗死相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以胸痛伴咯血1周为主要表现，初步诊断考虑肺梗死，需急诊即刻完善血气分析检查评估氧合状况，肺梗死常表现为低氧血症及肺泡-动脉氧分压差增大，为病情评估提供依据；查血常规了解有无红细胞增多、贫血及感染征象；查CRP、降钙素原两项炎症指标以排除合并肺部感染、鉴别肺炎所致胸痛咯血；完善凝血功能及D-二聚体检查以评估高凝状态，D-二聚体阴性有助于排除肺栓塞，必要时行下肢静脉超声明确有无深静脉血栓；完善胸部X线片检查作为基础筛查，并完善胸部CT检查明确肺部楔形实变影、梗死灶部位与范围，排除肺部肿瘤、结核等疾病，必要时行CT肺动脉造影明确肺动脉内血栓；患者存在咯血，完善痰培养+药敏检查排除合并感染并指导用药；待病情稳定、抗凝治疗前完善肝肾功能检查评估用药安全性；待病情稳定后完善肺功能检查了解通气血流比例异常及弥散功能受损程度。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 肺梗死\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗凝治疗：急性期首选低分子肝素（如依诺肝素钠注射液）4000IU（40mg）皮下注射 q12h，连用至少5天；同时或序贯口服直接口服抗凝药利伐沙班片15mg bid，连服21天后改为20mg qd，总疗程至少3个月。用药期间注意观察有无皮肤黏膜出血、牙龈出血、黑便等。\n2. 如选用华法林钠片：首剂2.5-3mg qd口服，与低分子肝素重叠使用至少5天，直至INR达2.0-3.0后停用低分子肝素，此后每1-2周监测INR并按结果调整剂量。\n3. 对症止痛：胸痛明显者予布洛芬缓释胶囊0.3g bid口服，或对乙酰氨基酚片0.5g q6-8h必要时口服，疼痛缓解后即停，避免长期服用。\n4. 通便辅助：为防止用力排便诱发栓子脱落，予乳果糖口服溶液15-30ml qd，保持大便通畅。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息1-2周，避免剧烈活动、用力屏气及长时间站立；病情稳定（呼吸平稳、胸痛缓解）后逐步下床活动，活动量循序渐进。\n2. 饮食宜清淡、易消化、富含膳食纤维，每日饮水1500-2000ml，保持大便通畅；绝对戒烟限酒，避免咖啡因等刺激性饮品。\n3. 若合并下肢深静脉血栓，应抬高患肢，穿戴医用弹力袜，避免久坐久站、翘腿及按摩、挤压、热敷患肢，防止血栓脱落。\n4. 积极排查并去除诱因（久卧、手术、骨折、肿瘤、口服避孕药等），严格遵医嘱完成足疗程抗凝，切勿自行减量或停药。\n\n【随诊要求】\n1. 抗凝治疗期间每1-2周门诊复诊1次，复查血常规、肝肾功能及凝血功能（华法林者监测INR），密切观察有无咯血、牙龈出血、皮肤瘀斑、黑便、血尿等出血征象及下肢肿胀情况。\n2. 治疗满3-6个月后复查D-二聚体及肺动脉CTPA，评估血栓吸收情况，由专科医师评估是否需延长抗凝（继发于恶性肿瘤、复发性血栓者常需延长至6-12个月或更长）。\n3. 如出现突发胸痛加重、咯血、呼吸困难、晕厥或单侧肢体肿痛，立即急诊就诊，不可等待常规复诊。\n"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":763,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b356de94449bd3cd2b86344b6f3186206dfdd98b43fee0fffbb874c237cc29d6","pinyin":"feigengsi","initials":"fgs","setting":"out","caseName":"门诊病历631","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历631",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8e2db3b43f49734732cb","key":"v1-c9ccc21dfe2a3058|templates-8e2db3b43f49734732cb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺动脉高压","category":"门诊病历模板","raw":{"name":"肺动脉高压","category":"门诊病历模板","case":{"case_name":"门诊病历632","templates":{"主诉":"活动后气短伴下肢水肿2年","现病史":"患者于2年前渐出现活动后气短（进行性加重，初为爬楼后，后平路亦出现，静息时也可发生，提示心功能下降）、乏力、胸痛（活动后，因右室缺血）、晕厥或晕厥前兆（活动后，因心排血量受限，此项重要，多见于晚期或大动脉型）、心悸、干咳、咯血（少见，与肺血管病变相关）；伴有右心衰表现：腹胀、食欲差（肝淤血）、下肢水肿（晚期）、颈静脉怒张。病因线索方面需关注：特发性（IPAH，无明确病因，少见但重要）；遗传性（家族史，与BMPR2基因相关）；药物相关（既往用过食欲抑制剂如芬氟拉明）；结缔组织病（系统性硬化症最相关，PAH为其常规筛查项目）、先天性心脏病（艾森曼格综合征，左向右分流晚期致肺血管病变）、门脉高压（肝硬化致门肺高压）、HIV感染；左心疾病（二尖瓣病变或左心衰致肺静脉高压，为第二大类且最常见，经心超鉴别）；肺部疾病（COPD或间质性肺病致低氧，为第三大类）；慢性血栓栓塞性（CTEPH，第四大类，可手术治疗，区分意义重要）；血液病。有无基础病及家族史需进一步明确。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P92次/分，R20次/分，BP112/70mmHg。颈静脉怒张（右心衰）；心脏P2亢进（肺动脉瓣第二心音亢进，为肺动脉高压特征）、三尖瓣收缩期杂音（右室扩大致三尖瓣反流，提示右心衰）、右室抬举样搏动、右室奔马律（S4，源自右房）、胸骨左缘肺动脉瓣区收缩期杂音（相对性肺动脉狭窄）；肺部可见基础肺病体征；腹部肝大、腹水（右心衰）；下肢水肿（右心衰）；杵状指（低氧，与肺病相关）；发绀（右向左分流致艾森曼格综合征，为中心性发绀）。","辅助检查":"【必做】超声心动图（首选，可估测肺动脉压（依据三尖瓣反流速度推算肺动脉收缩压）、评估右室大小及功能（扩大或肥厚）、观察三尖瓣反流，同时筛查病因（左心、瓣膜、先心病），为疑诊及随访核心）；【确诊】右心导管检查（金标准，静息平均肺动脉压≥25mmHg可确诊，同时测肺毛细血管楔压（>15mmHg提示左心性，用于鉴别）、肺血管阻力，并行急性血管反应试验（用于评估钙通道阻滞剂是否适用））；【分级评估】6分钟步行试验（功能评估，用于治疗前后对比）、WHO功能分级（Ⅰ~Ⅳ级，按症状分级）；【病因筛查】胸部X线（可见肺动脉段突出、右室增大）、肺功能及血气（评估肺病及低氧）、高分辨率CT（评估间质性肺病）、V/Q显像（筛查CTEPH，此项重要，可判断能否手术）、结缔组织病抗体（抗核抗体，筛查硬皮病）、HIV、肝功能（评估门脉高压）、睡眠呼吸监测（筛查OSA，属第五类，低氧可治疗）；【其他】BNP/NT-proBNP（反映右心负荷及预后，用于随访）、肌钙蛋白（评估预后）、心电图（可见右室肥大、电轴右偏、肺型P波）。","初步诊断":"1. 肺动脉高压（分类：结缔组织病相关/特发性/左心疾病/肺病低氧/慢性血栓栓塞性；WHO功能分级Ⅱ级；确诊依据右心导管）\n（注：肺动脉高压诊治复杂，需肺动脉高压专科中心管理，治疗依病因分类并予特异性治疗：①一般治疗（所有类型的基础治疗）：避免妊娠（高危）、预防感染（接种疫苗）、低氧者予氧疗（SpO2<90%）、右心衰伴水肿予利尿、IPAH及CTEPH予抗凝（华法林或NOAC，注意出血风险）、避免剧烈运动。②基础病治疗：左心疾病者治疗心衰及瓣膜病；肺病者治疗COPD或间质性肺病并予氧疗；OSA者予CPAP；CTEPH者行肺动脉内膜剥脱术（PEA，可治愈，为关键，应转专科评估手术）或球囊肺动脉成形术（BPA，用于不能手术者）并抗凝。③特异性肺血管扩张药（PAH靶向治疗，用于第一、三、四类，按WHO分级及急性血管反应结果选择）：钙通道阻滞剂（CCB，硝苯地平或地尔硫卓，仅用于急性血管反应试验阳性者，此项重要，非阳性者使用CCB有害）；内皮素受体拮抗剂（波生坦、安立生坦或马昔腾坦）、磷酸二酯酶5抑制剂（西地那非或他达拉非，我国常用且有效）、前列环素类似物（依前列醇静脉持续泵入用于重症、曲前列尼尔、伊洛前列素吸入）、前列环素受体激动剂（司来帕格，口服）；中重度患者可不同机制联合治疗，可显著改善病情。④右心衰处理：利尿（螺内酯加呋塞米）、洋地黄（用于房颤或右心衰，低剂量慎用）、失代偿期住院予血管活性药及正性肌力药（多巴酚丁胺）。⑤随访：每3~6个月评估症状及功能分级，随访超声（估测压力）、BNP及6分钟步行（评估治疗反应，恶化者调整方案并转专科），进展者复查右心导管评估预后。预后方面，未治疗者中位生存约2~3年，现代靶向治疗显著改善（IPAH中位生存>7年），早期诊断及专科治疗是关键；靶向药须由专科处方，我国已可及并纳入医保。由心内科、呼吸科肺动脉高压专科多学科长期管理。）","处理方案":"【药物治疗】\n1.靶向药物（按WHO功能分级及肺动脉高压病因个体化选择）：\n（1）内皮素受体拮抗剂：安立生坦片5mg qd po，或马昔腾坦片10mg qd po，用药期间每1-2个月复查肝功能；\n（2）磷酸二酯酶-5抑制剂：他达拉非片20mg qd po，或西地那非片20mg tid po，禁与硝酸酯类药物合用；\n（3）前列环素类似物（中重度患者，专科中心评估后启用）：伊洛前列素雾化吸入2.5-5μg tid-qid，或曲前列尼尔持续皮下/静脉泵入。\n2.钙通道阻滞剂（仅限急性血管反应试验阳性者）：地尔硫䓬缓释片30mg tid po，或硝苯地平缓释片30mg tid po，从小剂量开始，以能耐受且不出现低血压为度。\n3.对症及抗凝治疗：右心衰伴水肿者予呋塞米片20mg qd-bid po联合螺内酯片20mg qd po，监测电解质及肾功能；合并房颤或慢性血栓栓塞性肺高压者予华法林钠片口服抗凝，维持INR 1.5-2.5；合并右心衰或快速房颤者加用地高辛片0.125mg qd po。\n【一般治疗及生活指导】\n1.休息与活动：避免剧烈运动及重体力劳动，以散步等低强度有氧活动为宜，活动量以不出现明显气促、头晕为度；避免提重物、用力屏气等等长运动。\n2.饮食：低盐低脂饮食，每日食盐摄入<3-5g，限制液体入量（约每日1500-2000ml），少量多餐避免饱餐；戒烟戒酒。\n3.环境与禁忌：避免前往高原地区（海拔>1500m）及乘坐非增压舱飞机；避免热水浴、桑拿及高温环境；育龄期女性严格避孕，禁用含雌激素避孕药；避免使用食欲抑制剂及拟交感类药物；接种流感疫苗及肺炎球菌疫苗，积极预防呼吸道感染。\n【随诊要求】\n1.每1-3个月门诊复诊1次，评估症状、WHO功能分级、6分钟步行距离、静息血氧饱和度及BNP/NT-proBNP变化，据此调整靶向药物。\n2.每6-12个月复查心脏彩超（估测肺动脉收缩压、右心室大小及功能）、心电图及胸部X线；病情稳定者每1-2年行右心导管检查评估血流动力学参数。\n3.服用安立生坦/马昔腾坦者每1-2个月复查肝功能；服用利尿剂者定期复查电解质、肾功能；服用华法林者按INR定期复查凝血功能。\n4.出现晕厥、胸痛、咯血、进行性呼吸困难或下肢水肿加重等表现时立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":764,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b9663dec97414985efe41f33518b4d2aeb336cf6be1c23e888d6f6d1565bb4d4","pinyin":"feidongmaigaoya","initials":"fdmgy","setting":"out","caseName":"门诊病历632","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历632",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a35a71d938f1bca5eff8","key":"v1-c9ccc21dfe2a3058|templates-a35a71d938f1bca5eff8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺源性心脏病","category":"门诊病历模板","raw":{"name":"肺源性心脏病","category":"门诊病历模板","case":{"case_name":"门诊病历633","templates":{"主诉":"咳喘加重伴双下肢水肿2周","现病史":"患者有慢性阻塞性肺疾病、慢支肺气肿（最常见病因，在我国多见）、支气管扩张、肺结核（毁损肺）、间质性肺病等慢性肺病史10年。于2周前受凉、感染等急性加重诱因下出现下列表现：咳喘加重（咳嗽咳痰增多，呈脓痰，提示感染）、气促加重（活动受限，甚至静息时出现）；2周来出现右心衰表现：双下肢水肿（凹陷性，晨轻暮重）、腹胀纳差（胃肠道淤血）、心悸（心动过速或心律失常）、尿少、肝区胀痛（肝淤血肿大）、颈静脉怒张、发绀加重、头痛嗜睡（CO₂潴留致肺性脑病，需警惕，属急症）。其病理生理核心为肺动脉高压→右室肥大→右心衰，由慢性低氧致肺血管收缩及重构引起。还需了解有无长期家庭氧疗（依从性）、肺功能及血气随访（基础评估）、反复急性加重住院史及吸烟情况（戒烟情况）。今日来我院呼吸科/心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P102次/分（增快），R24次/分，BP126/78mmHg，SpO2 86%（低）。神志清楚或嗜睡（肺性脑病、CO₂麻醉）；发绀（口唇明显）；球结膜水肿（CO₂潴留）；颈静脉怒张（阳性，右心衰）；桶状胸；双肺闻及干湿啰音（基础肺病）；心界右心扩大（叩诊）；肺动脉瓣第二心音亢进（P2>A2，肺动脉高压）；三尖瓣区收缩期杂音（三尖瓣反流，右心衰）；肝大（肋下、压痛，肝颈静脉回流征阳性，为右心衰特征）；腹水征可疑阳性（晚期）；双下肢凹陷性水肿（中度）；杵状指（低氧，与基础病相关）。","辅助检查":"【必做】动脉血气分析（评估低氧血症（PaO2<60mmHg）、CO₂潴留（PaCO2>50mmHg，提示Ⅱ型呼衰及肺性脑病风险，为核心指标）及pH酸碱状态）、血常规（慢性低氧代偿可致红细胞增多、血红蛋白升高）、心电图（肺型P波（P波高尖，见于Ⅱ、Ⅲ、aVF导联）、右室肥大（电轴右偏、V1导联R/S>1）、右束支传导阻滞及房性心律失常（多见））、胸部X线（显示基础肺病及肺动脉高压（右下肺动脉干增宽>15mm）、右室增大（心影改变、肺动脉段突出））；【确诊及评估】超声心动图（可见右室扩大或肥厚、肺动脉压升高（估测）、右心功能改变，为诊断及随访核心）、肺功能（评估基础肺病所致气流受限，稳定期检查）、BNP/NT-proBNP（反映右心负荷，用于鉴别左心衰及评估病情）、肝肾功能（右心衰致淤血性肝损，转氨酶升高）、电解质（利尿剂可致低钾，需监测）；【其他】痰培养（急性加重时指导抗感染）、睡眠呼吸监测（疑OSA相关低氧时检查）。","初步诊断":"1. 慢性肺源性心脏病（分期：失代偿期（合并右心衰，此次急性加重）；基础病：慢性阻塞性肺疾病；合并Ⅱ型呼吸衰竭）\n（注：肺心病急性加重期以控制呼衰为主并处理右心衰：①控制呼吸道感染（核心，为急性加重的主要诱因）：选用广谱抗生素，依痰培养结果调整，脓痰者可用阿莫西林克拉维酸或呼吸喹诺酮类，疗程7~10天。②改善通气及氧疗（核心）：持续低流量氧疗，目标SpO2 88~92%，Ⅱ型呼衰须控制性给氧以防CO₂潴留；予支气管扩张剂（雾化沙丁胺醇加异丙托溴铵）、祛痰治疗；糖皮质激素（静脉甲泼尼龙，减轻气道炎症，用于COPD加重）；无创通气（NIPPV）为Ⅱ型呼衰伴呼吸性酸中毒的首选，此项重要。③右心衰处理：利尿为核心，减轻容量负荷，予螺内酯20~40mg qd加呋塞米20~40mg小剂量联合，以防电解质紊乱（低钾可增加洋地黄中毒风险）及血液浓缩（致痰液黏稠），故利尿应适度；扩血管药（酚妥拉明，降低肺动脉压，需监测血压，用于急性期短期治疗）；强心药（洋地黄，肺心病患者易中毒（低氧、低钾），须慎用并小剂量，如西地兰，仅用于房颤或明显心衰且指征严格者，急性期多不主张使用；改善通气及氧合后右心衰多可缓解，故以氧疗、利尿为主，此项重要）。④肺性脑病处理（CO₂潴留致意识障碍，属急症）：予无创或有创通气（意识障碍加重、血气恶化者行气管插管）、呼吸兴奋剂（尼可刹米，用于无创通气不能及时实施时，短期使用，效果有限），收入ICU。⑤并发症处理：心律失常（房性多见，处理诱因如缺氧、电解质紊乱，多随呼衰纠正而好转；洋地黄或抗心律失常药须严格掌握指征）、上消化道出血（应激或淤血所致，予质子泵抑制剂）、休克（综合治疗）、DIC。⑥缓解期治疗：治疗基础肺病（COPD稳定期规范吸入治疗、戒烟，此为关键，可防急性加重）、长期家庭氧疗（慢性低氧（PaO2<55mmHg）者每日>15小时，可改善生存，此项重要）、肺康复、营养支持（营养不良影响呼吸肌力，此项重要）、接种流感及肺炎疫苗。⑦随访：稳定期评估血气及肺功能，随访超声评估右心情况；反复急性加重者需综合管理以减少住院。由呼吸科、心内科诊治，呼衰为核心，予氧疗通气加右心衰综合治疗，缓解期以防加重为主；预后方面，反复加重者右心衰难以纠正，可致死亡。）","处理方案":"【药物治疗】\n1. 抗感染治疗：头孢呋辛酯片0.25g bid×7天（或阿莫西林克拉维酸钾片0.375g tid×7天），门诊首诊可经验性用药，疗效不佳或痰培养有结果后调整。\n2. 利尿消肿：氢氯噻嗪片25mg qd×5~7天，联合螺内酯片20mg qd，注意监测血钾、血压，避免利尿过度。\n3. 祛痰平喘：盐酸氨溴索片30mg tid×7天；喘息明显时予沙丁胺醇气雾剂100~200μg按需吸入（每日不超过8喷）。\n4. 强心治疗（右心衰竭明显时）：地高辛片0.125mg qd，用药期间监测心率（<60次/分停药）及血钾，警惕洋地黄中毒。\n\n【一般治疗及生活指导】\n1. 绝对戒烟，避免粉尘及刺激性气体接触，注意保暖、预防呼吸道感染，可接种流感疫苗及肺炎球菌疫苗。\n2. 急性期卧床休息，取半卧位或坐位以减轻心脏负荷；缓解期适当活动（如慢走），以不引起气促为度，循序渐进。\n3. 低盐低脂、高蛋白易消化饮食，每日食盐量<3g，少量多餐，控制饮水量；保持大便通畅，避免用力排便诱发心衰急性加重。\n4. 慢性缺氧者建议家庭氧疗：每日吸氧≥15小时，氧流量1~2L/min。\n\n【随诊要求】\n1. 2周后复诊，复查血常规、心电图、血气分析；1个月后复查胸部CT及心脏彩超评估心功能。\n2. 出现咳嗽咳痰增多、咳黄脓痰、发热、呼吸困难进行性加重、下肢水肿加重或尿量明显减少时，立即就诊。\n3. 长期使用利尿剂及地高辛者，每1~3个月复查电解质、肝肾功能及地高辛血药浓度。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":765,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5834d0a04c3a0103c4493c16d964439d532c53086cec181419365d1420a78a4e","pinyin":"feiyuanxingxinzangbing","initials":"fyxxzb","setting":"out","caseName":"门诊病历633","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历633",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-acefa8f0aabb057af363","key":"v1-c9ccc21dfe2a3058|templates-acefa8f0aabb057af363","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺动静脉瘘","category":"门诊病历模板","raw":{"name":"肺动静脉瘘","category":"门诊病历模板","case":{"case_name":"门诊病历634","templates":{"主诉":"咯血伴气促1周","现病史":"患者1周前无明显诱因出现肺动静脉瘘相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以咯血伴气促1周为主要表现，初步诊断考虑肺动静脉瘘，需完善血常规检查了解有无红细胞增多症及贫血，慢性低氧可继发血红蛋白升高，并排除血液系统疾病所致咯血；查CRP、降钙素原两项炎症指标以排除合并肺部感染、鉴别肺炎所致咯血气促；完善血气分析检查（必要时）评估氧合状态，肺动静脉瘘因右向左分流常表现为低氧血症且吸氧难以纠正，并计算肺泡-动脉氧分压差；完善胸部X线片检查作为基础筛查，并完善胸部CT检查明确有无结节状、条索状血管影及供血动脉与引流静脉，必要时行CT肺动脉造影明确瘘口部位、数目与分流量，为介入栓塞治疗提供依据；患者存在咯血，完善痰培养+药敏检查排除合并感染并指导用药；待病情稳定后完善肺功能检查了解通气功能与弥散功能受损程度。同时应追问有无鼻出血、皮肤毛细血管扩张等遗传性出血性毛细血管扩张症表现，并筛查家族史，必要时完善腹部超声排除肝动静脉畸形。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 肺动静脉瘘\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 介入栓塞术后抗血小板治疗：阿司匹林肠溶片100mg qd口服，连用4周；不能耐受者改用氯吡格雷片75mg qd口服，连用4周，预防栓塞血管内血栓形成及远端血栓栓塞。\n2. 纠正贫血（合并铁缺乏性贫血者）：琥珀酸亚铁片0.1g tid口服（餐后服用，减少胃肠道刺激），连用4~8周，复查血常规至血红蛋白恢复正常。\n3. 预防性抗感染（合并遗传性出血性毛细血管扩张症或既往有脑脓肿病史，需行牙科或侵入性操作者）：阿莫西林胶囊2g于操作前1小时口服；青霉素过敏者改用克林霉素600mg于操作前1小时口服。\n4. 伴明显低氧血症者：给予鼻导管吸氧（1~2L/min，每日间断吸氧，使SpO₂维持在≥90%），同时避免患者升高肺动脉压及促血栓形成的药物。\n【一般治疗及生活指导】\n1. 避免剧烈运动、用力屏气（Valsalva动作）、潜水、乘坐非加压飞机及高空作业，防止瘘内血栓脱落、破裂出血及气体栓塞。\n2. 休息与体位：无症状者正常作息，避免长时间低头及头部剧烈晃动；有咯血或胸痛者卧床休息，避免用力咳嗽、用力排便。\n3. 饮食：均衡营养饮食，合并贫血者增加富含铁及维生素C食物（红肉、动物肝脏、深色蔬菜、柑橘类）；戒烟限酒，避免摄入辛辣刺激性食物。\n4. 禁忌：静脉输液或采血时务必排尽空气、避免快速输注大量液体；严禁自行停用抗血小板药物，禁止擅自使用促凝或活血类偏方药物。\n【随诊要求】\n1. 介入栓塞术后1、3、6个月门诊复查，行胸部CT血管成像（CTA）评估栓塞效果及有无再通或新生病灶，此后每1~2年复查一次。\n2. 每年复查血常规、动脉血气分析及肝肾功能，动态监测血红蛋白、红细胞压积及血氧饱和度变化。\n3. 出现咯血、胸痛、呼吸困难加重、偏头痛、一过性肢体麻木无力（TIA样发作）或不明原因发热时立即就诊。\n4. 育龄期女性拟妊娠前务必先行栓塞治疗并评估瘘口闭合情况，妊娠期间及产后半年内密切随访；合并遗传性出血性毛细血管扩张症者建议至专科行家系筛查及长期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":766,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c1fc75cc185a4f9bc6ef7b07ae5d37888cee9b2edd4c6103da794c68ea1c2e13","pinyin":"feidongjingmailou","initials":"fdjml","setting":"out","caseName":"门诊病历634","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历634",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c9ffd7c5bced6d0e7338","key":"v1-c9ccc21dfe2a3058|templates-c9ffd7c5bced6d0e7338","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脓胸","category":"门诊病历模板","raw":{"name":"脓胸","category":"门诊病历模板","case":{"case_name":"门诊病历635","templates":{"主诉":"发热、胸痛伴气短2周","现病史":"患者继发于肺炎（最常见，先为肺炎旁胸腔积液：单纯旁积液为无菌，可自行吸收；进展为复杂旁积液（已感染，pH<7.2、葡萄糖<2.2mmol/L、乳酸脱氢酶>1000U/L，需引流）；进一步发展为脓胸（脓液形成并分层，需手术干预），分期为渗出期→纤维脓性期→机化期），因肺炎未治或延迟治疗而形成脓胸；其他可能病因包括胸部手术（肺切除或食管手术后脓胸，吻合口漏致胸膜腔污染）、胸部外伤（血胸继发感染）、食管破裂（急症，致纵隔及胸膜腔污染，表现为剧烈胸痛、呕吐后发病）、结核（结核性脓胸）、肺脓肿破溃。于肺炎后出现下列表现：发热（持续，抗感染无效，呈弛张热）、胸痛（患侧，为胸膜炎症所致）、咳嗽咳痰（基础肺炎表现）、气短（积液压迫所致呼吸困难）、全身症状（乏力、盗汗、消瘦，见于慢性者）；查体见胸腔积液征（叩诊浊音、呼吸音减低），X线及超声证实胸腔积液，行胸腔穿刺（诊断性，抽出脓性或浑浊液体，涂片行细菌检查及培养，并测pH、葡萄糖、乳酸脱氢酶，为分期及处理依据，此项重要）；大量脓液或包裹性、多房性积液需引流，必要时外科处理。需了解手术史（胸科术后应评估伤口、引流及吻合口）、食管情况（呕吐后剧痛提示食管破裂，属急症，可见气胸或液气胸、皮下气肿、纵隔气肿，须急诊评估）及既往肺炎治疗情况（抗生素疗程、效果、胸片吸收及积液变化）、结核史及接触史。今日来我院呼吸科/胸外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.9℃，P104次/分，R24次/分（增快），BP112/70mmHg。急性病容或慢性消耗（盗汗、消瘦）；患侧呼吸运动减弱、语颤减弱、叩诊浊音（积液）、呼吸音减低或消失（脓胸；合并液气胸时叩诊呈鼓浊音）、早期可闻胸膜摩擦音、大量积液可致纵隔移位；发绀（呼吸困难）、心率增快；杵状指（慢性脓胸，少见）；胸壁检查术后伤口及引流管；全身评估有无脓毒症表现（重症者血压下降）。","辅助检查":"【必做】血常规（白细胞升高，提示感染）、CRP、降钙素原、血培养（脓毒症时）、肝肾功能；【影像】胸部X线（可见胸腔积液（肋膈角变钝、液平面）、胸膜增厚）、胸部CT增强（可显示积液定位及包裹（多房）、胸膜增厚（脓胸可见胸膜分离征，即强化增厚，为特征性表现）、肺内病灶（肺炎或脓肿），并评估纵隔、食管及术后情况，术前评估重要）、胸腔超声（积液定位，明确包裹及多房，用于穿刺及引流定位，床旁动态监测）；【确诊及分期】胸腔穿刺（诊断关键，抽出脓性或浑浊液体（观察外观），行涂片革兰染色及培养（明确病原，需同时做需氧及厌氧培养）、pH（<7.2提示复杂旁积液或脓胸，为引流指征，此项重要）、葡萄糖（<2.2mmol/L）、乳酸脱氢酶（>1000U/L）、细胞学（排除恶性积液），并依Light标准区分渗出液与漏出液）；【其他】疑食管破裂者行食管造影或CT（可见纵隔气，属急症，需外科处理）；疑结核者查胸水腺苷脱氨酶（结核性脓胸>45U/L，并做抗酸培养）；疑恶性者行细胞学检查。","初步诊断":"1. 脓胸（病因分类：肺炎旁脓胸；分期：纤维脓性期；病原待培养；需评估引流必要性）\n（注：治疗以抗感染加充分引流为核心，按分期处理，早期充分引流以防机化，必要时外科干预：①抗生素：经验性选用广谱抗生素，覆盖肺炎链球菌、葡萄球菌（院内感染需覆盖MRSA）、革兰阴性菌及厌氧菌（脓胸常为混合感染，覆盖厌氧菌重要），可用哌拉西林他唑巴坦，或头孢曲松加甲硝唑（覆盖厌氧菌，此项重要）；术后或院内感染者需覆盖MRSA（万古霉素）及耐药革兰阴性菌，依培养药敏结果调整；疗程3~6周，属长程治疗，需引流充分以防复发，此项重要。②胸腔引流（核心）：脓液必须引流，单纯抗生素无效；行胸腔闭式引流（置胸管于锁骨中线或腋中线），使脓液充分引流，超声定位下操作；引流指征为抽出脓液、涂片阳性、pH<7.2、葡萄糖<2.2mmol/L或乳酸脱氢酶>1000U/L的复杂积液及脓胸。③纤溶治疗：用于纤维脓性期（脓液稠厚、多房、胸管引流不畅者），胸腔内注入纤溶剂（尿激酶或链激酶）溶解纤维蛋白、改善引流，可避免手术，此项重要，能减少手术率。④手术：用于引流失败或机化期（纤维板形成致肺不张、内科引流无效）者，行电视胸腔镜手术（VATS，清创剥脱，对纤维脓性期有效且创伤小）或开胸纤维板剥脱术（用于机化期，使肺复张，可达根治，术后肺功能可恢复）。⑤病因处理：肺炎者完成抗生素疗程；术后吻合口漏需相应处理并请胸科会诊；食管破裂者急诊手术；结核者予四联抗结核（结核性脓胸需充分引流加抗结核，必要时胸膜剥脱，注意时机）。⑥支持治疗：营养支持（高蛋白，脓胸消耗明显）、对症治疗（退热镇痛）、呼吸训练（促进肺复张，引流后鼓励咳嗽及吹气球，以防机化，此项重要）。⑦随访：观察引流情况，把握拔管时机（引流液清亮、量少<50ml/日、胸片示肺复张）；复查胸片评估肺复张及吸收情况、有无机化；慢性脓胸（引流不畅、病程长、胸膜增厚、肺功能受损）需评估手术剥脱。由呼吸科、胸外科诊治，充分引流是核心，按分期使用纤溶或VATS，以防机化，此项重要。）","处理方案":"【药物治疗】\n1. 抗感染治疗：脓胸多为肺炎旁积液继发感染，常见病原菌为肺炎链球菌、金黄色葡萄球菌及厌氧菌。门诊成人首选β-内酰胺类/酶抑制剂复合制剂：阿莫西林克拉维酸钾片 0.625g 口服 每8小时1次，疗程10~14天，覆盖需氧及厌氧菌；青霉素过敏者改用 莫西沙星片 0.4g 口服 每日1次，疗程10~14天。\n2. 疑诊金黄色葡萄球菌感染（糖尿病、近期侵入性操作或置管者）：利奈唑胺片 0.6g 口服 每12小时1次，疗程7~14天；或 头孢呋辛酯片 0.5g 口服 每日2次，疗程7~14天（无头孢菌素过敏史者）。\n3. 对症治疗：发热、胸痛明显者给予 布洛芬缓释胶囊 0.3g 口服 每日2次，或 对乙酰氨基酚片 0.5g 口服 每日3次，按需使用，连续不超过3天。\n【一般治疗及生活指导】\n1. 体位与引流：取患侧卧位或半卧位，以利于脓液引流与呼吸；脓胸治疗核心在于充分引流，若胸腔积液量多、包裹分隔或口服药物3~5天疗效不佳，需及时返院行胸腔穿刺抽液或胸腔闭式引流术，单纯药物治疗难以根治。\n2. 休息与活动：急性期卧床休息，避免剧烈活动与重体力劳动；体温正常后逐步恢复活动，每日进行深呼吸训练、缩唇呼吸或吹气球练习，促进肺复张与脓腔闭合。\n3. 饮食：高蛋白、高热量、富含维生素易消化饮食（鸡蛋、瘦肉、鱼虾、牛奶、新鲜蔬果），保证每日饮水1500~2000ml（心肾功能不全者遵医嘱调整），增强机体抵抗力。\n4. 禁忌：严格戒烟、戒酒；避免受凉、劳累及去人群密集场所，预防呼吸道感染；发热期间忌食油腻、辛辣刺激性食物。\n【随诊要求】\n1. 用药后3~5天复诊，复查血常规、C反应蛋白、降钙素原及胸部X线或CT，评估感染控制及胸腔积液变化，必要时调整抗感染方案。\n2. 治疗结束后1~2周复查胸部CT，确认脓腔吸收与肺复张情况；若脓腔未闭合或有残留包裹性积液，需转胸外科评估手术时机（如脓胸廓清术、胸膜剥脱术）。\n3. 疗程中出现高热不退、胸痛加重、呼吸困难、发绀或咳大量脓臭痰者，应立即返院或急诊就诊；合并糖尿病、慢阻肺等基础疾病者，患者控制原发病基础上每月门诊复查1次，随访至影像学稳定。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":767,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"481a1a98f0fc2d34c47697a7c8eceaa78c900b7041b76be20e0bd64661b744f4","pinyin":"nongxiong","initials":"nx","setting":"out","caseName":"门诊病历635","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历635",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-06a925f13d7c9838627b","key":"v1-c9ccc21dfe2a3058|templates-06a925f13d7c9838627b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"血胸","category":"门诊病历模板","raw":{"name":"血胸","category":"门诊病历模板","case":{"case_name":"门诊病历636","templates":{"主诉":"反复血胸相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现血胸相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以反复血胸相关不适1周、加重1天就诊，初步诊断血胸，首先需评估出血量与血流动力学状态，入院即刻完善血常规检查明确血红蛋白、红细胞压积下降程度，判断失血量并指导输血；完善尿常规、便常规检查排除泌尿系及消化道出血等合并出血部位；患者需卧床并使用止血、抗感染等经肝肾代谢药物，完善肝肾功能检查排除肝肾功能不全，指导用药剂量；完善电解质检查排除电解质紊乱，完善血糖、血脂检查了解代谢状况并评估营养支持与基础疾病；查心电图了解有无心肌缺血、心律失常，血胸压迫及失血可诱发心脏改变；查胸部X线片明确胸腔积液量及纵隔有无移位，必要时急诊完成；查腹部超声排除肝脾破裂等腹腔出血来源；若胸腔积液量较多、诊断不明确，需完善胸腔穿刺抽液及胸水常规、生化、细胞学检查明确有无活动性出血及感染，必要时完善胸部CT检查鉴别肋骨骨折、肺挫伤及肿瘤所致血胸，待病情稳定后复查胸部影像观察积血吸收情况。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 血胸\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染（预防脓胸）：头孢呋辛酯片0.25g，口服，每日2次，疗程5~7天；青霉素过敏者改服左氧氟沙星片0.5g，每日1次，疗程5天。\n2. 止血：氨甲环酸片0.5g，口服，每日3次，连用3~5天，血止后停用；亦可选用酚磺乙胺片0.5g，口服，每日3次。\n3. 镇痛：洛索洛芬钠片60mg，口服，每日3次（餐后），疼痛缓解后减量或停用，连用不超过5天；胃肠不适者改服对乙酰氨基酚片0.5g，必要时每日3次。\n4. 止咳祛痰（伴咳嗽咳痰者）：盐酸氨溴索片30mg，口服，每日3次，连用7天。\n\n【一般治疗及生活指导】\n1. 休息：以卧床休息为主，取半卧位（床头抬高30°~45°）以利引流与呼吸；避免剧烈咳嗽、用力屏气及重体力活动，至胸片示积液吸收、引流停止后至少2周。\n2. 饮食：高蛋白、高维生素、易消化饮食（鱼、蛋、瘦肉、新鲜蔬果），每日饮水1500~2000ml以稀释痰液；忌辛辣刺激、忌烟酒。\n3. 活动与引流护理：胸腔闭式引流期间避免牵拉、扭曲、倒置引流管，保持引流瓶低于胸腔水平，翻身或咳嗽时按压置管处敷料防止脱管；拔管后逐步恢复活动，以不引起胸痛、气促为度。\n4. 禁忌：禁止剧烈运动、负重、对抗性运动及游泳，防止再出血；避免用力排便，便秘时可用开塞露通便；出现胸闷、气促、头晕、面色苍白或引流液突然增多时立即就诊。\n\n【随诊要求】\n1. 每周复查胸部X线或床旁超声评估胸腔积液吸收及肺复张情况，直至液气胸完全吸收；吸收缓慢或反复不吸收者需CT进一步评估。\n2. 门诊带管或拔管后1~2周返院复诊，复查胸片并评估有无残余积液、胸膜增厚或脓胸形成。\n3. 外伤性血胸患者同时随访原发损伤及肋骨骨折愈合情况（伤后3~6个月）；若出现胸痛加重、气促、咯血、发热等，随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":768,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6deed58f54e940281303ebdf6258dcb7eabaf05e494becbbc092c1e8861f3838","pinyin":"xuexiong","initials":"xx","setting":"out","caseName":"门诊病历636","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历636",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d8fb6b93b0cc5fdb5d42","key":"v1-c9ccc21dfe2a3058|templates-d8fb6b93b0cc5fdb5d42","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乳糜胸","category":"门诊病历模板","raw":{"name":"乳糜胸","category":"门诊病历模板","case":{"case_name":"门诊病历637","templates":{"主诉":"气促伴乏力1周","现病史":"患者1周前无明显诱因出现乳糜胸相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以气促伴乏力1周就诊，初步诊断乳糜胸，胸导管损伤或阻塞致乳糜液外漏，入院即刻完善血常规检查排除感染、贫血所致乏力；完善尿常规、便常规检查排除泌尿系及消化道出血、感染；患者存在营养丢失，需完善肝肾功能检查排除肝肾功能不全，并评估营养支持与用药安全；完善电解质检查排除低钠、低钾等电解质紊乱所致乏力，完善血糖、血脂检查了解营养代谢状况；查心电图排除心律失常、心肌缺血所致气促；查胸部X线片明确胸腔积液量及肺部受压情况，必要时急诊完成；查腹部超声排除腹腔积液、腹膜后病变及淋巴回流受阻因素；为明确胸水性质，完善胸腔穿刺抽液及胸水常规、生化、甘油三酯、乳糜试验检查明确乳糜胸诊断；必要时完善胸部CT及淋巴管显像检查明确胸导管损伤部位与病因，病情稳定后定期复查胸部影像观察积液变化并指导饮食与治疗。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 乳糜胸\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 奥曲肽注射液（生长抑素类似物，抑制肠淋巴液生成、减少乳糜漏出）0.1mg 皮下注射 q8h，疗程1～2周，根据引流液量及胸水消退情况调整用量与疗程。\n2. 对乙酰氨基酚片 0.5g 口服 q6h，胸痛明显时按需服用，连续使用不超过5天，避免掩盖病情进展。\n3. 维生素AD软胶囊 1粒 口服 qd，低脂饮食期间持续补充，防止脂溶性维生素缺乏。\n\n【一般治疗及生活指导】\n1. 饮食：低脂、高蛋白、高热量饮食，烹调及食用以中链甘油三酯（MCT油）替代普通油脂，避免肥肉、油炸食品、全脂乳制品、坚果等长链脂肪酸食物，减少经胸导管转运的乳糜生成；引流量＞500ml/d 者应禁食并行全肠外营养，建议住院治疗。\n2. 休息与活动：以卧床或半卧位休息为主，避免剧烈咳嗽、用力排便、提重物等增加胸腹腔压力的动作；带胸腔引流管者保持管路通畅、每日记录引流量及性状，防止脱管及感染；戒烟。\n\n【随诊要求】\n每周门诊复诊，复查胸部X线或超声评估胸腔积液量，行胸水常规、乳糜定性及甘油三酯定量检查，监测引流液量、性状及血清白蛋白、电解质；若引流量＞500ml/d 持续1周以上，或保守治疗2周无缓解、出现呼吸困难加重，应及时返院评估胸导管结扎/栓塞或胸膜固定术等介入与手术干预；肿瘤、肝硬化等病因者同时按原发病专科随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":769,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dae603c550938e3148018ea704677988e1fedc065986985671cd7278c5e81086","pinyin":"rumixiong","initials":"rmx","setting":"out","caseName":"门诊病历637","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历637",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0a55c6217458d62648b1","key":"v1-c9ccc21dfe2a3058|templates-0a55c6217458d62648b1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胸膜间皮瘤","category":"门诊病历模板","raw":{"name":"胸膜间皮瘤","category":"门诊病历模板","case":{"case_name":"门诊病历638","templates":{"主诉":"胸痛伴气促1周","现病史":"患者1周前无明显诱因出现胸膜间皮瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以胸痛伴气促1周就诊，初步诊断胸膜间皮瘤，该病多有石棉接触史且恶性程度高，入院即刻完善血常规检查排除感染、贫血；完善肝肾功能、电解质检查排除肝肾功能不全及电解质紊乱，为后续化疗用药提供依据；因需行胸腔穿刺或穿刺活检等有创操作，完善凝血功能检查排除凝血功能障碍以防出血；完善肿瘤标志物检查了解 CA125、CEA、CYFRA21-1 等水平，协助评估肿瘤负荷并鉴别转移性病变；查胸部增强CT明确胸膜增厚、结节、胸腔积液范围及胸壁、纵隔侵犯情况，查胸部MRI了解胸膜病变与胸壁软组织、椎体受累及神经根关系，必要时完善PET-CT检查评估全身代谢活性及有无远处转移；完善超声检查明确胸腔积液及可行穿刺部位；为明确病理类型，完善病理活检及免疫组化检查明确上皮样或肉瘤样间皮瘤分型，必要时完善基因检测指导靶向治疗，如怀疑骨髓受累则完善骨髓穿刺检查明确有无转移。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 胸膜间皮瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 一线全身化疗（标准方案）：培美曲塞500mg/m²静脉滴注（第1天）+顺铂75mg/m²静脉滴注（第1天），21天为一周期，共4~6周期；化疗前1周起每日口服叶酸400μg至末次用药后3周，每3周期肌内注射维生素B12 1000μg，培美曲塞给药前1天、当天及后1天口服地塞米松4mg bid预防皮疹，化疗前后充分水化并予止吐（如昂丹司琼8mg静脉或口服，化疗前30分钟及当日）。不能耐受顺铂者可用卡铂AUC 5替代。\n2. 癌性胸痛对症治疗（WHO三阶梯镇痛）：轻中度疼痛予布洛芬缓释胶囊0.3g bid po；疼痛控制不佳时升级为曲马多缓释片50~100mg q12h po或吗啡缓释片10~30mg q12h po，按疼痛评分个体化滴定，注意便秘等不良反应。\n3. 顽固性干咳对症治疗：复方甲氧那明胶囊2粒 tid po；咳嗽剧烈影响休息者短期加用可待因15~30mg tid po（按需、不超过3~5天，警惕成瘾与呼吸抑制）。\n4. 恶性胸腔积液处理：大量胸腔积液伴呼吸困难者行胸腔穿刺或置管引流，缓解后评估行胸膜固定术（滑石粉或博来霉素胸腔内灌注，博来霉素45~60mg/次胸腔内注射），以控制复发、改善通气。\n\n【一般治疗及生活指导】\n1. 休息与活动：保证充足睡眠与休息，避免剧烈运动和重体力劳动；可行散步、太极拳等轻度活动，活动量以不诱发胸闷、气促为度，有胸腔积液或气促明显时卧床休息。\n2. 饮食营养：高蛋白、高热量、富含维生素饮食（瘦肉、鱼、蛋、奶、豆制品、新鲜蔬果），少量多餐，保证每日饮水1500~2000ml（心肾功能允许时）；进食困难或明显消瘦者加用肠内营养制剂或请营养科会诊支持。\n3. 呼吸与感染防护：注意保暖、预防感冒及呼吸道感染（避免去人群密集场所，必要时接种流感疫苗）；每日练习深呼吸、缩唇呼吸改善肺功能，鼓励拍背咳痰。\n4. 禁忌：严格戒烟并远离二手烟，避免石棉粉尘、矿物纤维等职业及环境暴露（石棉为明确致病因素）；避免自行服用来源不明的中草药、保健品及\"偏方\"，以免肝损伤或加重病情，所有用药患者医生指导下进行。\n\n【随诊要求】\n1. 化疗期间每周期返院复诊，用药后每周复查血常规，每周期复查肝肾功能、电解质，监测骨髓抑制及肝肾毒性并及时处理。\n2. 每2~3个周期（约6~9周）复查胸部增强CT及肿瘤标志物评估疗效；完成6周期后每3~6个月复查胸部CT、腹部超声，每年复查全身PET-CT或相应部位影像，监测复发与远处转移。\n3. 出现胸痛加重、胸闷气促进行性加重、咯血、发热、盗汗、不明原因体重下降或新发神经症状时，随时返院就诊；置管引流者每日观察引流液性状、量及穿刺点情况，出现红、肿、热、痛或浑浊液体提示感染，及时就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":770,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ef1901a179d9ce46aa5989cd70b5be63221d70242c667bfed3da4725e64d8f07","pinyin":"xiongmojianpiliu","initials":"xmjpl","setting":"out","caseName":"门诊病历638","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历638",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8ad1a6aada71f91fcf4d","key":"v1-c9ccc21dfe2a3058|templates-8ad1a6aada71f91fcf4d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胸膜转移瘤","category":"门诊病历模板","raw":{"name":"胸膜转移瘤","category":"门诊病历模板","case":{"case_name":"门诊病历639","templates":{"主诉":"胸痛伴气促1周","现病史":"患者1周前无明显诱因出现胸膜转移瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以胸痛伴气促1周就诊，初步诊断胸膜转移瘤，提示体内存在原发恶性肿瘤可能，入院即刻完善血常规检查排除感染、贫血；完善肝肾功能、电解质检查排除肝肾功能不全及电解质紊乱，为全身治疗用药提供依据；因需行胸腔穿刺及穿刺活检，完善凝血功能检查排除凝血功能障碍以免出血；完善肿瘤标志物检查了解 CEA、CYFRA21-1、NSE、CA125 等水平，协助判断可能原发灶并评估疗效；查胸部增强CT明确胸膜结节、胸腔积液及肺内原发或转移病灶，查胸部MRI了解胸壁、椎体及神经受累情况，必要时完善PET-CT检查明确全身代谢活跃灶及原发肿瘤部位；完善超声检查明确胸腔积液及穿刺定位；为明确病理诊断，完善病理活检及免疫组化检查明确组织来源，必要时完善基因检测指导靶向治疗，如怀疑骨髓转移则完善骨髓穿刺检查明确分期。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 胸膜转移瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 胸腔内灌注化疗（控制恶性胸水）：抽尽胸水后予顺铂注射液 40～60 mg 加入生理盐水 40～60 ml 稀释后胸腔内灌注，灌注后嘱患者变换体位使药液均匀分布，每周 1 次，2～4 周为 1 疗程，视胸水控制情况调整疗程。\n2. 胸腔内灌注免疫调节剂：重组人白细胞介素-2（IL-2）100万～300万U 胸腔内灌注，可与顺铂序贯或联合使用，每周 1～2 次，疗程 2～4 周，以提高胸水控制率；灌注后注意观察发热、胸痛等反应，可对症处理。\n3. 癌痛规范化镇痛（胸痛、骨痛明显者）：盐酸羟考酮缓释片 10 mg 口服 q12h 按时给药，根据疼痛评分（NRS）每 3 天调整剂量，必要时联合非甾体抗炎药（如塞来昔布胶囊 200 mg 口服 qd）辅助镇痛。\n4. 全身抗肿瘤治疗（依据原发肿瘤病理及基因检测结果）：如肺癌 EGFR 敏感突变阳性者，予吉非替尼片 250 mg 口服 qd 长期服用，直至疾病进展或出现不可耐受毒性；用药期间每 2～4 周复查肝功能、肾功能及血常规。\n\n【一般治疗及生活指导】\n1. 休息：保证充足休息，避免剧烈活动及重体力劳动；胸闷、气促明显者取半卧位或高枕卧位以利呼吸，胸腔引流期间减少翻身及剧烈咳嗽。\n2. 饮食：高蛋白、高维生素、易消化饮食，适量增加优质蛋白摄入（鱼、蛋、奶、瘦肉），少食多餐；食欲差或消瘦明显者，可行肠内营养支持。\n3. 活动：病情平稳时适当散步等轻度活动，循序渐进、量力而行；注意保暖，避免受凉感冒及呼吸道感染，不去人群密集场所，必要时接种流感疫苗。\n4. 禁忌：严格戒烟、戒酒，避免接触粉尘及有害气体；行胸腔穿刺或置管引流者保持穿刺部位敷料清洁干燥，洗澡时保护局部，防止感染。\n\n【随诊要求】\n1. 治疗期间每周复诊 1 次（行胸腔灌注治疗者按治疗周期按时复诊），复查血常规、肝肾功能、电解质，监测化疗及靶向药物不良反应。\n2. 每 2～4 周复查胸部超声或胸部 CT，评估胸水消退情况及病灶变化，及时调整治疗方案。\n3. 出现以下情况随时急诊就诊：发热、胸痛或呼吸困难进行性加重、咯血、意识改变，或穿刺部位红肿、渗液、出血等。\n4. 全身治疗者每 2～3 个月全面复查（胸部 CT、肿瘤标志物、脏器功能），评估疗效及原发肿瘤控制情况，动态调整后续治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":771,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"742294e630535a5a9ef099a6e405bbee40fc64e617b8c6b4ccb68583e2793ea0","pinyin":"xiongmozhuanyiliu","initials":"xmzyl","setting":"out","caseName":"门诊病历639","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历639",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ebb7e374aced8f0fead5","key":"v1-c9ccc21dfe2a3058|templates-ebb7e374aced8f0fead5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"纵隔气肿","category":"门诊病历模板","raw":{"name":"纵隔气肿","category":"门诊病历模板","case":{"case_name":"门诊病历640","templates":{"主诉":"胸骨后疼痛伴颈部皮下气肿1天","现病史":"患者存在明确诱因：自发性因素包括哮喘发作（气道高压致肺泡破裂，气体沿支气管血管鞘进入纵隔，形成自发性纵隔气肿，多见于年轻男性，常因用力、屏气或剧烈咳嗽诱发）、肺气肿（肺大疱破裂）、机械通气（气压伤，因气道压力高、正压通气所致，见于ICU）、食管破裂（呕吐后发生，即Boerhaave综合征，属急症，表现为纵隔气肿合并液气胸及剧烈胸痛，此项重要，需急诊手术）、气管支气管破裂（外伤或内镜所致，少见，属急症）、颈部手术或外伤（气体进入）、气胸（气体经肺门进入纵隔，可同时存在）、医源性因素（中心静脉穿刺或气管切开）。于1天前突发下列表现：胸骨后疼痛（深呼吸或吞咽时加重，可放射至肩背）、呼吸困难（纵隔受压或并存气胸所致）、颈部皮下气肿（颈部肿胀，触诊有握雪感或捻发感，为皮下气肿的特征性表现，即触诊捻发音）、声音改变（嘶哑或含混，因喉或咽后气体）、吞咽困难或疼痛（食管周围气体所致）、发绀（严重时纵隔受压，累及上腔静脉或气道）、Hamman征（心前区收缩期捻发音或噼啪声，与心脏搏动同步，由纵隔气体所致，听诊可闻，为特征性表现但少见）、心动过速、低血压（严重时形成张力性纵隔气肿，静脉回流受阻，少见但可危及生命）、颈部增粗（广泛皮下气肿可向面部及胸部蔓延）。需评估为单纯自发性（较轻，可自限，经休息及氧疗1~2周吸收）还是继发性（食管破裂者需急诊手术，此项重要，须鉴别）。今日来我院急诊/胸外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P98次/分，R22次/分，BP118/72mmHg（严重者血压下降，提示张力性纵隔气肿）。颈部肿胀，皮下气肿，触诊有捻发感或握雪感（为特征性表现），注意气肿范围（面部、颈部、胸部）；气管居中或移位（并存张力性气胸时）；心肺听诊可闻Hamman征（心前区收缩期捻发音），心音遥远（大量气体所致），呼吸音减弱（并存气胸时）；发绀；吞咽疼痛；声音嘶哑；纵隔叩诊浊音界难以辨别，需影像学确诊。","辅助检查":"【必做】胸部X线（可见纵隔气肿（纵隔旁透亮带，气体影沿纵隔轮廓分布）、皮下气肿（颈部或胸壁皮下气体线）、并存气胸或液气胸）、颈部X线（侧位片可见气管后间隙气体，对早期纵隔气肿敏感）；【确诊及评估】胸部CT（敏感，可精确评估纵隔气体范围、纵隔内积气位置（食管旁或气管旁）、并存病变（气胸、液气胸、肺大疱）及病因；疑食管破裂者可见纵隔气合并积液，需行口服水溶性造影剂食管造影，见造影剂漏出即可确诊食管破裂，属急症；疑气管支气管损伤者行CT及支气管镜检查）；【血液】血常规、血培养（发热或疑感染、食管破裂致纵隔炎及脓毒症时）、电解质、血气分析（评估呼吸及低氧情况）；【其他】心电图（鉴别心肌梗死及心包炎所致胸痛）、心肌肌钙蛋白（排除心梗）、食管镜（疑食管破裂时评估，必要时进行）。","初步诊断":"1. 纵隔气肿（分类：自发性纵隔气肿；需评估范围及有无并存气胸或液气胸；需排除食管破裂）\n（注：治疗依病因及严重程度而定，鉴别食管破裂是关键：①单纯自发性纵隔气肿（轻症、无呼吸窘迫者）采取保守治疗：休息、吸氧（高浓度氧可促进氮气吸收，加速气体吸收，此项重要但非必需）、镇痛（胸痛予非甾体抗炎药）、观察（气肿多于数日至1~2周自行吸收）、监测（呼吸及气肿范围，扩大者需警惕）。②食管破裂（Boerhaave综合征，属急症，需急诊处理）：禁食水、予广谱抗生素（针对纵隔炎，覆盖厌氧菌、革兰阴性及阳性菌，可用哌拉西林他唑巴坦加甲硝唑，警惕脓毒症）、急诊手术（开胸或腔镜修补破裂食管并行纵隔引流，时机上24小时内手术预后较好，延迟可致纵隔炎及死亡，此项重要）、胃肠减压、营养支持（空肠造瘘或肠外营养）。③继发性纵隔气肿：气管或支气管破裂者行支气管镜检查并手术修补；机械通气所致气压伤者降低气道压力（调整通气参数、下调呼气末正压，以防张力性纵隔气肿）；张力性纵隔气肿（静脉回流受阻、低血压，属急症）行纵隔减压（穿刺或切开引流，经颈部皮下气肿处紧急减压，少见）；中心静脉穿刺后者观察，多可自限。④并存气胸者予胸管引流（参见气胸处理）。⑤并发症处理：纵隔炎（食管破裂所致，表现为发热及脓毒症，予抗感染加引流）、张力性气胸、上腔静脉受压（头颈肿胀，少见）、心包积气（致心脏压塞，罕见）。⑥随访：复查X线或CT评估气肿吸收情况、观察症状（胸痛）缓解及病因复查（控制哮喘以防复发，自发性者复发少见）。由急诊、胸外科诊治，单纯自发性者以保守治疗为主并可自限；食管破裂者须急诊手术，把握时间窗，此项重要；对胸痛伴呕吐后发病及皮下气肿者应首先考虑食管破裂。）","处理方案":"【药物治疗】\n1. 镇咳（减少咳嗽以降低纵隔内气压、防止气体继续积聚）：氢溴酸右美托咪定缓释片（右美沙芬）15mg po tid；或复方甲氧那明胶囊（阿斯美）1粒 po tid，剧咳时选用，咳嗽缓解后停用。\n2. 抗感染（预防纵隔感染及继发感染）：无青霉素过敏者予阿莫西林克拉维酸钾片（0.457g）1片 po tid×5-7天；青霉素过敏者改用头孢呋辛酯片0.25g po bid×5-7天。\n3. 止痛（胸痛明显时）：布洛芬缓释胶囊0.3g po bid，或洛索洛芬钠片60mg po tid，症状缓解后停用。\n4. 通便（保持大便通畅，避免用力屏气排便）：乳果糖口服溶液15ml po qd，必要时15ml po bid。\n\n【一般治疗及生活指导】\n1. 休息：减少活动，卧床或静养为主，避免剧烈运动、提重物、屏气发力及一切Valsalva动作（用力咳嗽、打喷嚏、用力排便、憋气用力）。\n2. 戒烟戒酒，避免二手烟及粉尘、刺激性气体；合并哮喘或COPD者须规律使用吸入性糖皮质激素/支气管扩张剂控制原发病，防治哮喘急性发作。\n3. 饮食：清淡、易消化、富纤维素饮食，多饮水，避免辛辣刺激食物及过饱，保持大便通畅。\n4. 注意观察颈前、胸骨上窝及胸前区皮下捻发感（握雪感）变化，若范围明显扩大提示病情进展。\n\n【随诊要求】\n1. 用药后3-5天门诊复诊，复查胸部CT（或床旁胸片）评估纵隔气肿吸收情况，气肿基本吸收后方可恢复正常活动。\n2. 治疗期间若出现胸闷、呼吸困难进行性加重，胸痛加剧，发热，吞咽困难，声音嘶哑，或颈部、面部皮下气肿迅速扩散，须立即急诊就诊（警惕食管破裂、张力性气胸等并发症）。\n3. 复查确认气肿完全吸收前，避免剧烈运动、长途飞行、潜水及进入高压环境，防止复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":772,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6c0d1b4da7ded0003f478ead52356e6ad2b31916dec7622ac63300dece480ef5","pinyin":"zonggeqizhong","initials":"zgqz","setting":"out","caseName":"门诊病历640","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历640",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-23bade90419a83c61da5","key":"v1-c9ccc21dfe2a3058|templates-23bade90419a83c61da5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高血压病1级","category":"门诊病历模板","raw":{"name":"高血压病1级","category":"门诊病历模板","case":{"case_name":"门诊病历641","templates":{"主诉":"头痛、头晕伴颈项板硬1周","现病史":"患者1周前无明显诱因出现高血压病1级相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以头痛、头晕伴颈项板硬1周就诊，初步诊断高血压病1级，首要任务是确认血压水平并评估靶器官损害，门诊即刻完善血常规检查排除感染、贫血所致头晕；完善生化全项检查，其中肝肾功能检查排除肝肾功能不全并指导降压药物选择与剂量，电解质检查排除低钾等电解质紊乱所致血压升高，血糖、血脂检查了解有无糖尿病、血脂异常等心血管危险因素；患者头晕明显，完善心肌酶谱及肌钙蛋白检查排除急性心肌损伤、心肌梗死所致头晕；查心电图了解有无心肌缺血、左室肥厚及心律失常；查心脏超声了解心脏结构、室壁厚度及射血分数，评估高血压心脏损害；查胸部X线片了解主动脉形态及心脏大小；完善 BNP/NT-proBNP 检查明确有无心功能不全；患者颈项板硬，完善动态心电图观察血压昼夜节律与心律失常，必要时完善冠脉CTA检查排除冠状动脉狭窄。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 高血压病1级\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.钙通道阻滞剂（CCB）：苯磺酸氨氯地平片5mg qd晨服，连用4周；血压未达标者可增至10mg qd。\n2.血管紧张素Ⅱ受体拮抗剂（ARB）：缬沙坦胶囊80mg qd晨服，连用4周；血压未达标者可增至160mg qd；若静息心率＞80次/分，可改选琥珀酸美托洛尔缓释片47.5mg qd。\n3.单药治疗4周后诊室血压仍≥140/90mmHg者，联合用药：苯磺酸氨氯地平片5mg qd＋缬沙坦胶囊80mg qd，晨服。\n【一般治疗及生活指导】\n1.低盐饮食：每日食盐摄入量＜5g，减少酱油、咸菜、腌制及加工食品摄入，多食新鲜蔬菜水果。\n2.规律运动：每周至少150分钟中等强度有氧运动（如快走、慢跑、游泳、骑车），每周5~7次，每次30分钟；运动前后监测血压。\n3.戒烟限酒：吸烟者应戒烟；饮酒者严格限酒，每日酒精摄入量男性＜25g、女性＜15g。\n4.控制体重：体质指数＜24kg/m²，腰围男性＜90cm、女性＜85cm；保持规律作息，避免熬夜及精神紧张，保持情绪平稳。\n【随诊要求】\n1.服药后2~4周复诊，评估降压疗效及药物不良反应，根据血压调整治疗方案。\n2.血压达标后每1~3个月复诊1次，复诊时测量诊室血压并记录；血压未达标者每2~4周复诊1次直至达标。\n3.每日早晚各测量1次家庭血压并记录血压日记，复诊时携带；每年至少完成1次血脂、血糖、肾功能、尿常规、心电图等常规检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":773,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"625636efe2ccbe2f42a7949c2e23dadee7a5fe4b063dfcb422ed35c22116516d","pinyin":"gaoxueyabing1ji","initials":"gxyb1j","setting":"out","caseName":"门诊病历641","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历641",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9ba1edbab408307bed3d","key":"v1-c9ccc21dfe2a3058|templates-9ba1edbab408307bed3d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高血压病2级","category":"门诊病历模板","raw":{"name":"高血压病2级","category":"门诊病历模板","case":{"case_name":"门诊病历642","templates":{"主诉":"头痛、头晕伴颈项板硬1周","现病史":"患者1周前无明显诱因出现高血压病2级相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以头痛、头晕伴颈项板硬1周就诊，初步诊断高血压病2级，血压水平更高、靶器官损害风险更大，门诊即刻完善血常规检查排除感染、贫血所致头晕；完善生化全项检查，肝肾功能检查排除肝肾功能不全并指导降压药物选择与剂量调整，电解质检查排除电解质紊乱尤其低钾所致继发性血压升高，血糖、血脂检查了解代谢危险因素；查心肌酶谱及肌钙蛋白排除急性心肌损伤；查心电图了解有无心肌缺血、左室肥厚及心律失常，查心脏超声了解心脏结构、室壁厚度、射血分数以评估高血压心脏损害；查胸部X线片了解主动脉形态及心脏大小；完善 BNP/NT-proBNP 检查明确有无心功能不全；完善动态心电图观察血压昼夜节律及心律失常，患者颈项板硬、头痛明显，必要时完善冠脉CTA检查排除冠状动脉狭窄及脑血管病变。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 高血压病2级\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 钙通道阻滞剂（CCB，首选）：苯磺酸氨氯地平片5mg qd，晨起口服；若2-4周血压未达标可增至10mg qd，长期维持治疗。\n2. 血管紧张素Ⅱ受体拮抗剂（ARB）：缬沙坦胶囊80mg qd口服，适用于合并糖尿病、蛋白尿或不能耐受CCB者，可单用或与CCB联合，长期维持。\n3. 联合治疗：单药治疗4周后诊室血压仍≥140/90mmHg者，予苯磺酸氨氯地平片5mg qd＋缬沙坦胶囊80mg qd联合降压；血压仍不达标时加用氢氯噻嗪片12.5mg qd。\n4. 若心率＞80次/分或合并冠心病，可加用美托洛尔缓释片47.5mg qd；注意监测血压心率，遵医嘱调整剂量，不可自行停药。\n\n【一般治疗及生活指导】\n1. 休息：保证充足睡眠，每晚7-8小时，避免熬夜、过度劳累及长期精神紧张，保持情绪稳定。\n2. 饮食：低盐低脂饮食，每日食盐摄入＜5g，少食腌制、油炸及高胆固醇食物，多食新鲜蔬菜水果，戒烟限酒。\n3. 活动：坚持规律中等强度有氧运动，如快走、慢跑、太极拳、游泳等，每周至少5次、每次30分钟；运动宜安排在下午或傍晚，避免晨起剧烈活动。\n4. 禁忌：避免情绪激动、用力屏气及用力排便；冬季注意保暖，避免寒冷刺激；规律作息，控制体重（BMI＜24kg/m²）。\n\n【随诊要求】\n1. 家庭自测血压每日早、晚各1次并记录，家庭血压目标＜135/85mmHg，诊室血压目标＜140/90mmHg。\n2. 初始治疗或调整用药后2-4周复诊评估降压疗效及不良反应；血压达标稳定后每1-3个月复诊1次。\n3. 每3-6个月复查血脂、血糖、肾功能、尿常规及尿微量白蛋白；每年行心电图、超声心动图及眼底检查，评估靶器官损害。\n4. 出现剧烈头痛、视物模糊、恶心呕吐、胸闷胸痛、言语不清或肢体麻木无力，或血压持续≥180/110mmHg时，立即就诊，警惕高血压急症及脑血管意外。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":774,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d6028fa3a29cd3e5e73445670be02b8eb17415377722c250df20c5d65ac4d45e","pinyin":"gaoxueyabing2ji","initials":"gxyb2j","setting":"out","caseName":"门诊病历642","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历642",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6e21f9b16a216fe87666","key":"v1-c9ccc21dfe2a3058|templates-6e21f9b16a216fe87666","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高血压病3级","category":"门诊病历模板","raw":{"name":"高血压病3级","category":"门诊病历模板","case":{"case_name":"门诊病历643","templates":{"主诉":"头痛、头晕伴颈项板硬5年","现病史":"患者存在危险因素：年龄（男>55岁、女>65岁）、吸烟、血脂异常、糖尿病或空腹血糖受损、早发心血管病家族史、肥胖（腹型）、缺乏运动。既往有高血压病史5年，血压控制不佳，用药依从性差。症状方面，多数患者可无症状，于体检时发现，也可有头痛、头晕、头胀、颈项板硬、鼻出血。靶器官损害方面需关注：心脏（左室肥厚、心衰、冠心病、心梗史）、脑（卒中或TIA史、高血压脑病）、肾（蛋白尿、肌酐升高、肾衰）、眼（高血压视网膜病变）、血管（外周动脉病）。还需排查继发性高血压线索：年轻起病（<30岁）、血压高且难治（≥3种药物仍不达标）、低钾、阵发性心悸出汗（嗜铬细胞瘤）、腹部血管杂音（肾动脉狭窄）、睡眠打鼾及呼吸暂停（OSA）、药物因素（激素、非甾体抗炎药、避孕药、甘草）、肾病病史。同时需评估诊室血压与家庭血压（白大衣高血压需家庭自测及动态血压监测评估，此项重要）。分级为1级140~159/90~99mmHg、2级160~179/100~109mmHg、3级≥180/110mmHg；危险分层依血压水平、危险因素及靶器官损害分为低危、中危、高危、极高危，用于指导治疗决策，此项重要。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P84次/分，R18次/分，BP186/112mmHg（双上肢测量取高值，必要时测下肢血压以与主动脉缩窄或外周动脉病对比），体重及BMI、腹围；心肺检查注意心界扩大及心衰啰音；腹部听诊有无血管杂音（肾动脉狭窄）；眼底检查评估视网膜病变分级（Keith-Wagener分级）；颈动脉杂音；外周动脉搏动（桡动脉、股动脉、足背动脉）；神经系统检查有无卒中后遗体征；甲状腺检查（甲亢所致继发性高血压）；下肢有无水肿。","辅助检查":"【必做】血压测量（规范测量诊室血压，并予家庭自测（连续7天，早晚各1次）或24小时动态血压监测，用于评估白大衣高血压及隐匿性高血压，此项重要）、血常规、尿常规（评估蛋白尿及肾损害）、肾功能（肌酐、肾小球滤过率）、电解质（血钾，低钾提示原发性醛固酮增多症等继发线索）、血糖及糖化血红蛋白（筛查糖尿病）、血脂（总胆固醇、甘油三酯、低密度脂蛋白、高密度脂蛋白）、尿酸、肝功能；【靶器官评估】心电图（左室肥厚、缺血）、超声心动图（左室肥厚、心功能、瓣膜）、颈动脉超声（内膜中层厚度、斑块）、眼底检查（视网膜病变）、蛋白尿定量（尿白蛋白/肌酐比值）、睡眠呼吸暂停筛查（打鼾者评估OSA）；【继发因素排除】用于年轻或难治性高血压者：肾动脉超声或CTA（肾动脉狭窄）、醛固酮/肾素比值（筛查原醛，适用于低钾及难治者）、尿儿茶酚胺（嗜铬细胞瘤，适用于阵发性症状者）、皮质醇（库欣综合征）、肾脏超声；【综合评估】危险分层（参照SCORE或中国模型，依危险因素及靶器官损害评估心血管总体风险，用于指导治疗决策，此项重要）。","初步诊断":"1. 高血压病3级（诊室血压186/112mmHg，已行家庭及动态血压评估；危险分层为极高危；已评估心、脑、肾、眼、血管等靶器官损害；已排除继发性高血压）\n（注：治疗强调长期综合管理，降压达标以防靶器官损害：①生活方式干预（所有患者的基础治疗）：限盐（<5~6g/日，此项重要）、限酒戒烟、减重（BMI<24kg/m²并控制腹围）、运动（有氧运动，每周≥150分钟，如快走）、DASH饮食（多蔬菜水果、低脂）、减压及保证睡眠。②药物治疗：起始指征为1级低中危者经生活方式干预3~6个月血压仍>140/90mmHg时用药，高危者立即用药并可联合治疗；常用五大类药物为血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂（普利类或沙坦类）、钙通道阻滞剂（地平类）、噻嗪类利尿剂（氢氯噻嗪）、β受体阻滞剂（洛尔类，适用于心率快或合并冠心病者）；起始可单药小剂量或联合，2级及以上者起始即联合，可选单片复方制剂以提高依从性；常用组合为ACEI/ARB加CCB、ACEI/ARB加噻嗪类；单片复方制剂（如缬沙坦氨氯地平、氯沙坦氢氯噻嗪）依从性好，此项重要；降压目标一般为<140/90mmHg，年轻、糖尿病、肾病或冠心病等高危患者强化至<130/80mmHg，65~79岁老年患者<140~150/90mmHg，80岁以上<150/90mmHg并个体化缓慢降压；达标时间4~12周，选用长效药物平稳降压；血压不达标时递增剂量或联合用药，已用3种药物（含利尿剂）仍不达标者为难治性高血压，需排查继发原因（原醛、肾动脉狭窄）、依从性及白大衣效应。③靶器官损害治疗：合并冠心病或心衰者用β受体阻滞剂及ACEI（心梗后）；脑卒中者用ACEI或利尿剂行二级预防；糖尿病肾病者首选ACEI/ARB（有蛋白尿时）；心衰者按四联方案治疗。④随访：血压达标后每1~3个月随访，家庭自测并记录；每年评估靶器官（肾功能、心电图、超声）；关注药物不良反应（ACEI所致咳嗽、CCB所致踝部水肿、利尿剂所致低钾）并调整；强调长期服药依从性，勿自行停药以防血压反弹及卒中风险；开展健康教育，指导自我监测并记录，就诊时携带血压记录。由心内科及社区长期综合管理，降压达标以防心、脑、肾并发症，此项重要。）","处理方案":"【药物治疗】\n1. 钙通道阻滞剂（CCB，首选基础用药）：苯磺酸氨氯地平片 5mg qd 晨服，2-4周血压未达标可增至10mg qd，长期维持；或硝苯地平控释片30mg qd。\n2. 血管紧张素Ⅱ受体拮抗剂（ARB，与CCB联用强化降压）：缬沙坦胶囊80mg qd，或厄贝沙坦片150mg qd；3级高血压起始即推荐\"CCB+ARB\"两药联合（如氨氯地平5mg+缬沙坦80mg qd），2-4周未达标者再加第3种药物。\n3. 噻嗪类利尿剂（联合方案第三药）：氢氯噻嗪片12.5mg qd，尤其适用于盐敏感型、老年或伴容量负荷者，与上述药物联用；长期使用注意监测血钾、血钠。\n4. β受体阻滞剂（合并冠心病或静息心率＞80次/分者选用）：琥珀酸美托洛尔缓释片47.5mg qd，心率偏快者起始，逐步调整至静息心率55-60次/分，不可骤停。\n\n【一般治疗及生活指导】\n1. 严格低盐饮食：每日食盐摄入＜5g，减少酱油、咸菜、腌制品及加工食品，炒菜出锅前放盐，警惕\"隐形盐\"。\n2. 戒烟限酒（男性酒精＜25g/d、女性＜15g/d），避免浓茶、咖啡及人参等升压补品；规律作息，保证7-8小时睡眠，避免熬夜、情绪激动、用力排便及屏气动作。\n3. 适度有氧运动：血压平稳后行快走、慢跑、游泳、太极拳等，每周5次、每次30-40分钟，运动时心率控制在（170-年龄）次/分以内；血压未控制达标或伴心脑血管并发症者暂避免剧烈及等长抗阻运动。\n4. 自我监测血压：每日晨起服药前、睡前各测1次并记录血压日记；控制体重（BMI＜24kg/m²，男性腰围＜90cm、女性＜85cm），超重者减重5%-10%。\n\n【随诊要求】\n1. 建议2-4周门诊复诊1次，评估血压控制达标情况、药物疗效及不良反应，未达标者每2周复诊并调整方案；达标后每1-3个月复诊。\n2. 每3-6个月复查血常规、尿常规、肝肾功能、电解质、血脂、血糖；每年至少1次心电图、心脏彩超、眼底检查及颈动脉超声，评估心脑肾靶器官损害。\n3. 家庭自测血压持续≥180/110mmHg，或出现剧烈头痛、恶心呕吐、视物模糊、胸闷胸痛、呼吸困难、言语不清、肢体麻木无力等急症表现时，立即急诊就诊，不可自行调药或停药；出现干咳、头晕、低血压、踝部水肿等药物不良反应应及时复诊调整。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":775,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"29d66f3a40f605ea4b60cb2a12d1839a9fa9a61097492908b8705ecc2b6cce76","pinyin":"gaoxueyabing3ji","initials":"gxyb3j","setting":"out","caseName":"门诊病历643","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历643",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b0c32ddccda677674b95","key":"v1-c9ccc21dfe2a3058|templates-b0c32ddccda677674b95","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高血压危象","category":"门诊病历模板","raw":{"name":"高血压危象","category":"门诊病历模板","case":{"case_name":"门诊病历644","templates":{"主诉":"血压升高伴头痛、呕吐2小时","现病史":"患者有高血压病史，既往血压控制差，此次因自行停用降压药而发病。诱因包括情绪激动紧张、突然停用降压药（血压反跳，此项重要）、摄盐过多、使用非甾体抗炎药或激素、嗜铬细胞瘤（阵发性血压骤升，伴头痛、心悸、大汗）、肾动脉狭窄、子痫、交感兴奋（如可卡因）。于2小时前突发下列表现：血压急剧升高（≥180/120mmHg，符合高血压危象定义）。分型上，高血压急症指伴急性靶器官损害，需立即静脉降压并住院（ICU）；高血压亚急症指无急性靶器官损害，可口服降压并于门诊观察。急症表现包括：高血压脑病（剧烈头痛、恶心呕吐、意识障碍、抽搐，由脑水肿所致）、脑出血或脑梗死（卒中，表现为偏瘫、失语）、急性左心衰或肺水肿（呼吸困难、端坐呼吸、咳粉红色泡沫痰）、急性冠脉综合征（胸痛、心梗）、主动脉夹层（胸背部撕裂样剧痛并向远处放射，为最危险的急症，收缩压显著升高）、急进性肾损害（蛋白尿、血尿、肾衰）、视网膜病变（视物模糊、出血、视盘水肿）、子痫（妊娠期）、嗜铬细胞瘤危象。需重点询问有无胸痛（鉴别夹层及心梗，此项重要）、头痛及意识障碍或抽搐（脑受累）、呼吸困难（心衰或肺水肿）、视力改变、肢体无力或麻木（卒中）、腹痛，以及既往降压药依从性和诱因。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P96次/分，R24次/分，BP208/126mmHg（双上肢血压对比，夹层时双上肢压差>20mmHg，并测上下肢血压）。神志评估有无意识障碍（脑病或卒中）；神经系统检查有无定位体征（卒中）、抽搐；眼底检查（出血、渗出、视盘水肿，提示急进性高血压）；心肺听诊有无啰音（肺水肿、心衰）、心音异常（心梗或主动脉瓣关闭不全杂音，提示夹层）；脉搏是否对称（夹层时脉搏减弱或缺失，需对比）；腹部有无压痛；肢体有无无力；妊娠者考虑子痫；全身有无出汗、面色苍白（嗜铬细胞瘤）。","辅助检查":"【必做】血压（双侧上肢重复测量确认）、心电图（评估心梗、左室肥厚、缺血及夹层）、血常规、电解质（血钾，低钾提示原醛）、肾功能（肌酐，评估肾衰）、血糖、心肌肌钙蛋白（心梗及夹层）、血沉及D-二聚体（夹层时D-二聚体阴性有排除价值）、尿常规（蛋白及血尿，提示肾损害）；【影像】疑主动脉夹层者行CT血管成像（增强，属急症关键检查）、超声心动图（评估左室肥厚、心功能、瓣膜及主动脉根部，排查夹层）、头颅CT（排查脑出血及卒中，用于意识障碍者，属急症）、胸片（评估心衰、肺水肿及纵隔增宽，提示夹层）、眼底检查（视网膜病变）；【妊娠】妊娠试验及产科评估（子痫）；疑嗜铬细胞瘤且有阵发症状者查儿茶酚胺代谢产物；【分型】评估心、脑、肾、眼、血管等靶器官，确定属急症或亚急症，以指导治疗强度，此项重要。","初步诊断":"1. 高血压危象（血压≥180/120mmHg，属高血压急症：伴急性靶器官损害（高血压脑病、急性左心衰、急性冠脉综合征、主动脉夹层、急性肾损害），需住院静脉降压；已评估靶器官受累及诱因）\n（注：治疗原则为紧急静脉降压并于ICU监护，降压须适度，防止过快过低致灌注不足，此项重要：①高血压急症：予静脉降压，第1小时平均动脉压下降幅度<25%（此项重要，勿过快），随后2~6小时降至160/100~110mmHg，24~48小时逐渐降至正常，须缓慢降压以保护脑灌注自动调节，过快可致脑缺血及梗死，老年及卒中患者尤须注意。药物可选硝普钠（静脉滴注，需监护，长期使用注意氰化物蓄积）、硝酸甘油（用于心衰及缺血）、拉贝洛尔（静脉注射或滴注，适用于夹层，可与β受体阻滞剂配合）、尼卡地平或乌拉地尔静脉滴注；按靶器官选择：主动脉夹层须快速降压（收缩压<120mmHg，10分钟内达标）并加用β受体阻滞剂，同时急诊手术或介入，最为紧急；高血压脑病须缓慢降压并予甘露醇减轻脑水肿；急性心衰或肺水肿予静脉硝酸甘油或硝普钠加利尿剂；卒中者（出血性降压至<180mmHg，缺血性溶栓要求≤185/110mmHg）需平衡脑灌注；嗜铬细胞瘤危象先用酚妥拉明行α受体阻滞（勿先单用β受体阻滞剂，以免诱发α危象）。②高血压亚急症：予口服降压（门诊加量或加药，可用卡托普利等短效药物），门诊观察数小时并复测血压，使血压渐降，无需急症静脉用药；注意休息并复查，调整长期治疗方案（评估依从性，改用长效制剂）。③诱因及依从性处理：恢复服药，评估继发原因（嗜铬细胞瘤、原醛、肾动脉狭窄）、摄盐、情绪及睡眠。④监测：静脉用药期间持续监护血压（每5~15分钟测1次至稳定）、观察神志及神经体征（降压过程中防脑缺血症状加重）、监测尿量及肾功能（降压影响肾灌注）、心电图（监测缺血）。⑤随访：血压达标后由静脉改为口服（重叠用药以防血压反跳），开展长期管理及依从性教育，控制血压以防危象再发，此项重要；随访心、脑、肾靶器官并处理诱因。由急诊、心内科诊治，急症者予静脉适度降压并按靶器官分别处理，主动脉夹层最为紧急，须防止降压过快，此项重要。）","处理方案":"【药物治疗】\n1. 降压药物（静脉、首选）：α1受体阻滞剂乌拉地尔注射液（压宁定）25mg加入0.9%氯化钠注射液20ml缓慢静脉注射（5分钟内），必要时5分钟后重复1次；或25mg加入0.9%氯化钠注射液250ml静脉滴注，起始滴速2mg/min，根据血压每10-15分钟调整滴速至血压达标，病情稳定后改口服降压药维持。\n2. 降压药物（静脉、备选）：二氢吡啶类钙通道阻滞剂尼卡地平注射液静脉泵入，起始0.5μg/(kg·min)，每5-10分钟递增0.5-1μg/(kg·min)，最大10μg/(kg·min)，血压控制后逐渐减量并换用口服制剂。\n3. 口服过渡及长期维持：卡托普利片12.5mg口服 tid，待血压平稳（<160/100mmHg）后改为氨氯地平片5mg qd联合缬沙坦胶囊80mg qd长期维持，每1-2周依据血压调整剂量。\n4. 合并靶器官损害（急性脑卒中、急性左心衰、急性冠脉综合征、主动脉夹层等）者：立即收入院或转急诊抢救，不宜在门诊单纯降压，以免延误病情。\n\n【一般治疗及生活指导】\n1. 绝对卧床休息，取半卧位，保持环境安静、光线柔和，避免情绪激动、剧烈活动及用力排便，密切监测血压，每15-30分钟复测并记录。\n2. 低盐低脂饮食，每日食盐摄入<5g，戒烟限酒，避免浓茶、咖啡等兴奋性饮品。\n3. 保持大便通畅，便秘者可予乳果糖口服溶液15ml qd，切忌屏气用力排便。\n4. 规律作息、保证充足睡眠，避免熬夜与过度劳累；如出现剧烈头痛、视物模糊、胸痛、气促、肢体麻木或言语不清等立即就医。\n\n【随诊要求】\n1. 血压未稳定者每日复测血压并门诊随诊；血压稳定后1-2周门诊复诊1次，评估并调整口服降压方案。\n2. 复诊时复查心电图、肾功能、血电解质、尿常规及眼底检查，动态评估靶器官损害及降压药物不良反应。\n3. 长期规律服药，不得擅自停药或减量；血压平稳后每1-3个月复测血压，每3-6个月门诊复诊1次，出现血压明显波动或不适随时复诊。\n"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":776,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f2702e575e5f34781b40547a252692e22bcbeac8904e9c35f2f2d7a16825d03c","pinyin":"gaoxueyaweixiang","initials":"gxywx","setting":"out","caseName":"门诊病历644","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历644",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c39b0884c8fd860e1ca6","key":"v1-c9ccc21dfe2a3058|templates-c39b0884c8fd860e1ca6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高血压脑病","category":"门诊病历模板","raw":{"name":"高血压脑病","category":"门诊病历模板","case":{"case_name":"门诊病历645","templates":{"主诉":"剧烈头痛、恶心呕吐伴意识障碍6小时","现病史":"患者有高血压病史，既往血压未控制。其发病机制为慢性高血压患者血压急骤升高，超过脑血流自动调节上限，致脑过度灌注及脑水肿。诱因包括停用降压药、肾性高血压（急进性肾小球肾炎、血管炎）、嗜铬细胞瘤、子痫（妊娠期抽搐）、药物因素。于6小时前血压骤升后出现下列表现：头痛（剧烈，全头胀痛，进行性加重）、恶心呕吐（颅内压增高所致）、视力障碍（视物模糊、黑矇、皮层盲）、意识障碍（嗜睡、昏睡、昏迷、谵妄，降压后可恢复，为脑病的可逆性特征，可与卒中鉴别，符合可逆性后部白质脑病综合征（PRES），影像可支持）、抽搐（全面性或局灶性）、局灶神经体征（多不恒定，如偏瘫、失语，可为一过性）、眼底改变（高血压视网膜病变Ⅳ级，可见视盘水肿、出血、渗出，此项重要）。需与卒中鉴别（脑出血或脑梗死，其头痛、意识障碍及局灶体征可与脑病相似，但脑病经降压后症状迅速缓解，具可逆性，此项重要）、脑肿瘤及脑膜炎相鉴别。还需了解血压水平（舒张压常>130mmHg）、既往血压控制情况、肾功能（可能并存急进性高血压肾损害）及妊娠情况。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P88次/分，R20次/分，BP212/134mmHg（显著升高，舒张压>130mmHg）。神志评估（嗜睡或昏迷，记录GCS评分）；眼底检查（视盘水肿、出血、渗出，符合恶性高血压视网膜病变Ⅳ级，为核心体征）；瞳孔（不等大提示脑疝）；神经系统检查有无局灶体征（多可逆）、有无抽搐（需观察）；颈强直（提示脑膜刺激征，用于鉴别）；心肺检查；妊娠者考虑子痫；皮肤及全身检查。","辅助检查":"【必做】血压（反复测量）、头颅CT（核心，用于排除脑出血（颅内出血与脑病鉴别重要，因两者降压目标不同）、评估脑水肿；PRES在CT或MRI上表现为后部白质低密度，MRI可见后循环白质水肿，以顶枕叶为主，支持诊断）、心电图及心肌肌钙蛋白（评估靶器官缺血）、肾功能及尿常规（评估急进性肾损害）、电解质、眼底检查、血常规及血小板（排查血栓性血小板减少性紫癜：高血压加神经症状加血小板减少需鉴别）、血气分析；【影像】头颅MRI（用于确认PRES，显示可逆性白质水肿）、脑血管检查（疑血管炎者，年轻女性产后少见）；心脏超声（评估靶器官）；妊娠者行产科评估（子痫）。","初步诊断":"1. 高血压脑病（血压急剧升高伴脑水肿，表现为头痛、意识障碍、抽搐及PRES；已排除脑出血及卒中；病变具可逆性；属急症，需静脉降压）\n（注：治疗原则为急诊（ICU）立即静脉降压，逆转脑水肿，防止脑损伤：①降压：立即予静脉降压药，可选拉贝洛尔、尼卡地平、硝普钠或乌拉地尔，首选拉贝洛尔或尼卡地平（不增加颅内压）。目标为第1小时平均动脉压下降20~25%（勿过快过低，以防脑缺血），2~6小时血压降至160~170/100~105mmHg（高血压脑病使收缩压降至160~170mmHg或首日下降20~25%），24~48小时逐渐降至基础水平，缓慢降压重要。应避免过快降压（首小时<25%）致脑灌注不足及梗死，老年患者尤须注意；硝普钠可增高颅内压，须慎选，宜用尼卡地平或拉贝洛尔。②对症治疗：抽搐者予地西泮止痉（降压后多可缓解）、颅内压增高者予甘露醇减轻脑水肿（脑水肿多随血压下降而缓解）、恶心呕吐予对症处理；监测神志、瞳孔及神经体征，降压过程中记录变化（症状改善支持脑病诊断），持续监护血压。③病因治疗：继发性高血压（肾性、嗜铬细胞瘤、子痫）须治疗原发病；妊娠子痫予硫酸镁预防抽搐（与产科协作）。④随访：血压控制后转为口服长效降压药（与静脉用药重叠以防血压反跳）并长期达标管理；随访神经症状恢复情况（降压后数小时至数日恢复，多数可逆、无后遗，符合PRES可逆特点）、眼底、肾及心脏等靶器官评估与治疗；开展依从性教育以防再发；继发病因须治疗并随访。由急诊、心内科及ICU诊治，立即静脉适度降压，先行头颅CT排除出血，抽搐及颅压增高者对症处理，防止降压过快，此项重要。）","处理方案":"【药物治疗】\n1. 降压治疗（首选，尽快达标）：乌拉地尔注射液25mg加入0.9%氯化钠注射液250ml中缓慢静脉滴注，起始滴速1～2mg/min，每10～15分钟监测血压，首小时内平均动脉压下降不超过25%，目标2～6小时内将血压降至160/100mmHg左右，维持1～3天，病情稳定后改为口服降压药维持。\n2. 口服降压维持：硝苯地平控释片30mg qd晨服，联合缬沙坦胶囊80mg qd口服，长期维持血压<140/90mmHg；若血压控制欠佳，可加用氢氯噻嗪片12.5mg qd口服。\n3. 降颅压、减轻脑水肿：20%甘露醇注射液125ml静脉快速滴注（30分钟内滴完），q8h，连用3～5天，联合呋塞米片20mg bid口服×3天，注意补钾并监测电解质。\n4. 对症支持：头痛明显者予布洛芬缓释胶囊0.3g bid口服；烦躁不安、精神紧张者予地西泮片2.5～5mg睡前口服，必要时4～6小时后可重复1次。\n\n【一般治疗及生活指导】\n1. 绝对卧床休息，床头抬高15°～30°，保持环境安静、光线柔和，避免情绪激动、用力屏气及用力排便，防止血压骤升加重脑水肿。\n2. 低盐低脂饮食，每日食盐摄入<3g，限制动物脂肪及高胆固醇食物，戒烟限酒，避免浓茶、咖啡等刺激性饮品；适量饮水，保持大便通畅。\n3. 每日早、中、晚及出现头晕、头痛时自测血压并记录，避免剧烈活动及重体力劳动，保证充足睡眠，保持情绪平稳。\n4. 严格遵医嘱服药，不得擅自停药、减量或漏服降压药；若出现剧烈头痛、视物模糊、恶心呕吐、肢体麻木或抽搐，应立即急诊就诊。\n\n【随诊要求】\n1. 症状缓解、血压稳定后3～5天内复诊，评估头痛、头晕等神经系统症状缓解情况及血压控制水平，必要时调整降压方案。\n2. 1周内复查血常规、肾功能、电解质、心电图及眼底检查，评估高血压靶器官损害情况；此后长期每1～3个月门诊复诊，监测血压、血糖、血脂，维持血压<140/90mmHg。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":777,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"462fcc6bfc00eda366b28e13c414278fc1e7c9e085089d32d8d6190a3f392414","pinyin":"gaoxueyanaobing","initials":"gxynb","setting":"out","caseName":"门诊病历645","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历645",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9413ae922d3c47823a0e","key":"v1-c9ccc21dfe2a3058|templates-9413ae922d3c47823a0e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高血压性心脏病","category":"门诊病历模板","raw":{"name":"高血压性心脏病","category":"门诊病历模板","case":{"case_name":"门诊病历646","templates":{"主诉":"活动后气短、乏力伴心悸1年","现病史":"患者有高血压病史，长期（数年）血压未控制或控制不佳。其病理过程为左室压力负荷增加→心肌肥厚（向心性重构）→舒张功能障碍（早期表现为射血分数保留的心衰，即HFpEF）→后期心脏扩张及收缩功能下降（射血分数降低）。并发症包括冠心病（高血压加速动脉粥样硬化，可合并心绞痛、心梗）及脑、肾、血管等靶器官损害并存。于高血压多年后出现下列表现：早期多无症状，左室肥厚经心电图或超声发现；劳力性气短（舒张功能不全所致，活动后气促，符合HFpEF）、乏力、心悸（房颤，因左房增大，为常见并发症）、心衰（夜间阵发性呼吸困难、端坐呼吸，提示进展为左心衰）、心绞痛（合并冠脉病变）、心律失常（房颤，有栓塞风险，需抗凝）、晕厥。还需了解血压控制史（用药依从性、血压水平及是否达标）、超声所见（左室肥厚、室壁厚度）、NYHA分级、诱因（感染、摄盐过多、停药）及靶器官（肾、脑）评估情况。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P88次/分，R20次/分，BP158/96mmHg（血压未控制）。心尖搏动向左下移位、呈抬举样（左室增大）；心界向左下扩大；S4（左室肥厚所致舒张期奔马律）；S3（提示心衰）；主动脉瓣第二心音亢进；肺部闻及湿啰音（心衰）；颈静脉怒张及下肢水肿（晚期右心衰）；眼底检查（高血压视网膜病变）；监测体重。","辅助检查":"【必做】心电图（左室肥厚，可见电压增高伴ST-T劳损，符合Sokolow-Lyon标准，并可发现房颤及缺血）、超声心动图（核心，评估左室肥厚（室间隔或后壁厚度≥12mm，呈向心性）、射血分数（保留或降低，用于分型）、舒张功能（E/e′升高提示舒张障碍）、左房增大（房颤风险）、室壁运动（合并缺血时异常））、胸片（心影呈左室增大、靴形心，可见肺淤血）、BNP/NT-proBNP（评估心衰）、肾功能及尿常规（评估高血压肾损害等靶器官）、电解质（血钾，注意利尿剂及醛固酮影响）、血糖及血脂（代谢评估）、动态心电图（Holter，监测房颤及室性心律失常）。","初步诊断":"1. 高血压性心脏病（长期高血压致左室肥厚，呈向心性肥厚（室壁≥12mm）；射血分数保留（HFpEF）；合并左房增大及心房颤动；NYHA分级Ⅱ级；合并冠心病及靶器官损害待评估）\n（注：治疗以控制血压为根本核心，以逆转肥厚、防止心衰：①降压治疗：血压达标（<130/80mmHg，高危者强化），选用长效药物并联合用药，优先选择肾素-血管紧张素系统阻滞剂（血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂，有逆转左室肥厚的证据，此项重要），可联合钙通道阻滞剂、利尿剂或β受体阻滞剂（用于冠心病或心率快者），并提高依从性（可用单片复方制剂）。②左室肥厚：通过严格降压逆转，ACEI/ARB效果最佳（可逆转肥厚、降低事件），随访超声观察室壁厚度。③心衰管理：射血分数保留（HFpEF）者予利尿剂（减轻肺淤血及容量负荷）、SGLT2抑制剂（恩格列净或达格列净，近年已获批用于HFpEF，可降低住院率，此项重要），并控制血压、治疗房颤（控制心室率或复律）、减重；射血分数降低（HFrEF）者按四联方案治疗（ARNI、β受体阻滞剂、螺内酯、SGLT2抑制剂）。④心房颤动：依CHA2DS2-VASc评分行抗凝（高血压合并房颤卒中风险高，予华法林或NOAC，此项重要），并控制心室率（β受体阻滞剂或地高辛）。⑤合并冠心病：予抗血小板及他汀行二级预防，评估血运重建指征。⑥随访：家庭自测血压并评估达标情况；每年复查心电图及超声（评估肥厚逆转及心功能）；监测肾功能及电解质（药物安全性）、BNP（心衰指标）、房颤及栓塞风险；随访肾、脑、眼底等靶器官；开展依从性教育，强调长期坚持，此项重要；管理体重并限盐，稳定期适当运动。由心内科诊治，严格降压、逆转肥厚、按分型治疗心衰、房颤抗凝并规律随访，此项重要。）","处理方案":"【药物治疗】\n1.血管紧张素转换酶抑制剂（ACEI）或血管紧张素II受体拮抗剂（ARB）：培哚普利叔丁胺片4mg qd晨服（或缬沙坦胶囊80mg qd），2-4周血压未达标可加倍，长期维持治疗；出现干咳不耐受者换用ARB。\n2.钙通道阻滞剂（CCB）：苯磺酸氨氯地平片5mg qd晨服，2-4周血压不达标可增至10mg qd，长期维持。\n3.β受体阻滞剂：琥珀酸美托洛尔缓释片23.75mg qd口服，根据静息心率（目标55-60次/分）及耐受性每1-2周调整，最大剂量95mg qd，心率<55次/分或出现乏力、头晕时减量。\n4.噻嗪类利尿剂：合并心力衰竭或容量负荷过重时加用氢氯噻嗪片12.5mg qd口服，长期服用者定期监测血钾、血钠及肾功能。\n\n【一般治疗及生活指导】\n1.低盐低脂饮食：每日食盐摄入<5g，减少酱油、咸菜、腌制及加工食品；控制总热量，超重/肥胖者积极减重，目标BMI<24kg/m²。\n2.戒烟限酒：严格戒烟并避免二手烟；男性每日酒精摄入<25g，女性<15g，建议戒酒。\n3.规律运动：血压控制平稳后每周5次、每次30分钟中等强度有氧运动（快走、慢跑、游泳、骑车）；血压未达标或合并心功能不全者避免剧烈及等长运动（如举重、憋气用力）。\n4.保证充足睡眠，避免熬夜、情绪激动、过度劳累及寒冷刺激；注意保暖，监测血压，避免因血压剧烈波动加重心脏负荷。\n\n【随诊要求】\n1.血压未达标者每2-4周门诊复诊调整降压方案；血压达标且稳定后每1-3个月复诊1次，定期家庭自测血压并记录。\n2.每3-6个月复查心电图、超声心动图，评估左心室肥厚程度及心功能变化；每年复查血脂、空腹血糖、肾功能、电解质及尿微量白蛋白，评估靶器官损害。\n3.建议定期行24小时动态血压监测，评估昼夜血压节律及降压疗效。\n4.如出现胸闷、胸痛、心悸、呼吸困难、夜间阵发性呼吸困难、端坐呼吸或双下肢水肿等，提示心功能恶化，立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":778,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"39a458d987a4c53e2a43a89bd34e5234e58b027569a1a055c924dd4e02c22535","pinyin":"gaoxueyaxingxinzangbing","initials":"gxyxxzb","setting":"out","caseName":"门诊病历646","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历646",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a1195db040964e03293e","key":"v1-c9ccc21dfe2a3058|templates-a1195db040964e03293e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高血压肾损害","category":"门诊病历模板","raw":{"name":"高血压肾损害","category":"门诊病历模板","case":{"case_name":"门诊病历647","templates":{"主诉":"乏力1天","现病史":"患者1周前无明显诱因出现高血压肾损害相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以乏力1天就诊而初步诊断高血压肾损害，提示长期血压控制不佳已累及肾脏，入院即刻完善血常规检查排除贫血所致乏力，并注意有无感染；完善生化全项检查，其中肾功能检查明确血肌酐、尿素氮及估算肾小球滤过率，评估肾损害程度并指导降压药物剂量，肝功能检查排除肝功能障碍影响用药，电解质检查排除高钾、低钾等电解质紊乱，血糖、血脂检查了解代谢危险因素；患者乏力明显，查心肌酶谱及肌钙蛋白排除急性心肌损伤；查心电图及心脏超声了解有无左室肥厚、心肌缺血及心功能状态，评估高血压心脏损害；查胸部X线片了解心脏大小及主动脉形态；完善 BNP/NT-proBNP 检查明确有无心功能不全；完善动态心电图及动态血压监测观察血压节律与心律失常；必要时完善冠脉CTA检查排除冠状动脉病变，同时完善尿常规及尿微量白蛋白检查明确蛋白尿程度。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 高血压肾损害\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.血管紧张素Ⅱ受体拮抗剂（ARB）类（首选，降压并降尿蛋白、延缓肾损害进展）：缬沙坦胶囊 80mg po qd×长期；服药2-4周后复查血肌酐、血钾，若肌酐较基线升高<30%可增至160mg qd，若升高>30%或血钾>5.5mmol/L应减量或停用并就诊。\n2.钙通道阻滞剂（CCB）类：苯磺酸氨氯地平片 5mg po qd×长期，血压未达标可增至10mg qd（注意足踝水肿不良反应）。\n3.噻嗪类利尿剂：氢氯噻嗪片 12.5mg po qd×长期，晨服，定期复查电解质；若eGFR<30ml/min/1.73m²改用袢利尿剂呋塞米片 20mg po qd。\n4.SGLT2抑制剂（eGFR≥25ml/min/1.73m²、无禁忌时加用，进一步延缓肾功能恶化）：达格列净片 10mg po qd×长期，用药期间注意泌尿系感染及血容量不足风险。\n\n【一般治疗及生活指导】\n1.饮食：低盐低脂优质低蛋白饮食，每日食盐摄入<5g，蛋白质0.8g/kg/d，肾功能不全者0.6g/kg/d并以鸡蛋、牛奶、瘦肉等优质蛋白为主，避免动物内脏、浓汤及高嘌呤食物。\n2.休息与活动：避免熬夜及过度劳累，保证充足睡眠，注意保暖、预防感冒及泌尿系感染；血压平稳后可规律进行快走、太极拳等中等强度有氧运动，每周≥5次、每次30分钟，避免剧烈及竞技性运动。\n3.禁忌：戒烟限酒；禁用或慎用肾毒性药物（非甾体抗炎药如布洛芬、氨基糖苷类抗生素、含马兜铃酸的中草药），避免未经评估使用含碘造影剂。\n4.自我监测：家庭自备血压计，每日晨起及睡前各测血压1次并记录，监测有无眼睑及双下肢水肿、尿量减少、泡沫尿增多等变化。\n\n【随诊要求】\n1.调整药物初期每1-2周门诊复诊1次，复查血压、血肌酐、血钾及eGFR，评估用药反应及安全性。\n2.此后每1-3个月复诊1次，每3个月复查尿常规、尿微量白蛋白/肌酐比值（UACR）、血肌酐、eGFR及电解质。\n3.每6个月行肾脏彩色多普勒超声检查；若出现血压持续不达标、水肿加重、尿量明显减少、恶心呕吐、胸闷气促等，应及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":779,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0b3c08186ea88e40e418c10f6e4eee992db77adf63d05818241a0f0b1205f4ee","pinyin":"gaoxueyashensunhai","initials":"gxyssh","setting":"out","caseName":"门诊病历647","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历647",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e295703896983ae008f8","key":"v1-c9ccc21dfe2a3058|templates-e295703896983ae008f8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"妊娠高血压","category":"门诊病历模板","raw":{"name":"妊娠高血压","category":"门诊病历模板","case":{"case_name":"门诊病历648","templates":{"主诉":"乏力1天","现病史":"患者1周前无明显诱因出现妊娠高血压相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以乏力1天就诊而初步诊断妊娠高血压，需同时兼顾孕妇安全与胎儿状况，即刻完善血常规检查排除贫血、感染并了解血小板计数，警惕HELLP综合征；完善生化全项检查，肝肾功能检查排除肝肾功能不全并评估病情严重程度，电解质检查排除电解质紊乱，血糖、血脂检查了解代谢状况；患者乏力、妊娠期心脏负荷加重，查心肌酶谱及肌钙蛋白排除急性心肌损伤；查心电图了解有无心肌缺血及心律失常，查心脏超声了解心脏结构及功能；查胸部X线片了解心肺情况；完善 BNP/NT-proBNP 检查明确有无心功能不全；完善动态心电图观察心律变化；必要时完善冠脉CTA检查前须严格评估胎儿安全性，故仅在母体获益明确时进行；同时完善尿常规及24小时尿蛋白定量检查明确有无子痫前期，完善产科超声及胎心监护评估胎儿生长发育与宫内状况，并完善眼底检查了解有无视网膜病变。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 妊娠高血压\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 拉贝洛尔片（α、β受体阻滞剂，妊娠期一线降压药）：50mg po tid起始，每2-3天根据血压调整剂量，可增至100-200mg tid，最大日剂量2400mg，血压控制达标（130-150/80-95mmHg）后维持至分娩及产后血压稳定。\n2. 硝苯地平控释片（二氢吡啶类钙通道阻滞剂）：30mg po qd，最大日剂量90mg；血压控制不佳时与拉贝洛尔联合，或单用于不能耐受拉贝洛尔者。\n3. 甲基多巴片（中枢性α2受体激动剂，备选药物）：250mg po bid-tid起始，最大日剂量2000mg，适用于拉贝洛尔禁忌或疗效不佳者。\n4. 钙剂（辅助预防子痫前期）：碳酸钙D3片0.6g（含元素钙600mg）po qd-bid，或钙尔奇D600mg po qd，与降压药同用，降低子痫前期发生风险。\n注：仅用于轻度妊娠期高血压门诊治疗；若血压≥160/110mmHg、出现蛋白尿或子痫前期表现，需住院行硫酸镁解痉等综合治疗，门诊不宜单用硫酸镁口服降压。\n\n【一般治疗及生活指导】\n1. 休息与体位：保证每日睡眠≥8-10小时，以左侧卧位为主，减轻子宫对下腔静脉压迫、改善胎盘血流灌注；避免久站、久坐及重体力劳动，工作与活动强度以不感疲劳为度。\n2. 饮食：低盐饮食，每日食盐摄入<5g，少食腌制、加工食品；保证优质蛋白（鱼、禽、蛋、奶、豆制品）摄入，适量进食新鲜蔬果；控制孕期体重增长（正常体重者整个孕期增重11-16kg为宜），超重或肥胖者适当减量。\n3. 自我监测与症状警戒：每日早晚固定时间自测血压并记录；注意有无头痛、眼花、视物模糊、上腹不适、胸闷、恶心呕吐及胎动异常（12小时胎动<10次或较平时减少50%），出现上述任一症状立即就医。\n4. 禁忌：戒烟、戒酒，避免情绪激动、精神紧张、剧烈运动及快速起身等体位突变；暂停性生活及盆浴，避免诱发血压骤升。\n\n【随诊要求】\n1. 轻度妊娠期高血压每周复诊1次，复诊时监测血压、体重、水肿情况及尿常规（蛋白尿）；若血压控制不佳、出现蛋白尿或自觉症状加重，缩短为每2-3天复诊或转住院治疗。\n2. 按产科高危妊娠管理定期产检：每月复查尿常规、血常规、肝肾功能、凝血功能，每2-4周行产科B超监测胎儿生长发育、羊水量及胎盘功能，孕32周后每周行胎心监护；若发展为重度子痫前期或子痫，立即住院综合治疗。\n3. 产后随访：产后6周复查血压、尿常规及肝肾功能，多数患者产后12周内血压恢复正常；产后持续高血压者转心内科/肾内科进一步诊治，并评估远期心脑血管风险。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":780,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cf65de7eb2561dff6558b87175089739992e9afe91a3a852eca4af9a1d795e48","pinyin":"renshengaoxueya","initials":"rsgxy","setting":"out","caseName":"门诊病历648","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历648",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2777a9161a4d9f701fb2","key":"v1-c9ccc21dfe2a3058|templates-2777a9161a4d9f701fb2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"更年期高血压","category":"门诊病历模板","raw":{"name":"更年期高血压","category":"门诊病历模板","case":{"case_name":"门诊病历649","templates":{"主诉":"乏力1天","现病史":"患者1周前无明显诱因出现更年期高血压相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者围绝经期女性，1周前无明显诱因出现血压相关症状并进行性加重，今日以乏力1天就诊，既往体健、否认高血压等慢性病史，首先完善血常规检查排除贫血、感染所致乏力；拟长期口服降压药物治疗，药物需经肝肾代谢，完善生化全项（肝肾功能）检查排除肝肾功能不全，为选药及调整剂量提供依据；完善生化全项中电解质检查排除电解质紊乱所致血压波动，并筛查原发性醛固酮增多症等继发性高血压线索；完善生化全项中血糖、血脂检查了解糖脂代谢水平，评估围绝经期代谢综合征及动脉粥样硬化危险因素；患者乏力伴血压升高，需警惕心肌缺血，完善心肌酶谱、肌钙蛋白检查排除急性心肌损伤；入院即刻完善心电图检查明确有无 ST-T 改变、左心室肥厚及心律失常，作为后续对比基线；完善心脏超声检查（含左心功能测定）了解心脏结构、室壁运动及射血分数，评估高血压所致靶器官损害程度；完善胸部X线片检查了解主动脉形态及心肺情况，排除肺部疾患所致气短；患者症状逐渐加重，完善动态心电图检查了解有无阵发性心律失常及隐匿性心肌缺血；完善 BNP/NT-proBNP 检查明确有无心功能衰竭；必要时完善冠脉CTA检查明确冠状动脉有无狭窄，进一步明确诊断并鉴别原发性高血压与冠心病所致症状。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 更年期高血压\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 钙通道阻滞剂（CCB）为更年期高血压一线首选：苯磺酸氨氯地平片5mg qd晨服，1周后血压未达标（≥140/90mmHg）可增至10mg qd；或硝苯地平控释片30mg qd。疗程：长期服用，平稳降压，不可自行停药。\n2. 若静息心率≥80次/分或伴心悸、潮热、烦躁等交感兴奋表现，联合β受体阻滞剂：琥珀酸美托洛尔缓释片47.5mg qd，或酒石酸美托洛尔片25mg bid；目标静息心率55～60次/分。\n3. 单药或二联治疗后血压仍不达标，加用血管紧张素Ⅱ受体拮抗剂（ARB）：缬沙坦胶囊80mg qd，或氯沙坦钾片50mg qd。\n4. 更年期症状明显（潮热汗出、失眠、情绪波动、自主神经功能紊乱）者，辅以谷维素片10mg tid；症状严重且血压控制平稳者，可转妇科评估激素补充治疗指征。\n\n【一般治疗及生活指导】\n1. 饮食：低盐饮食，每日食盐摄入<5g，减少腌制食品、高脂高糖食物；增加豆制品、奶制品、新鲜蔬菜水果及富钾富钙食物摄入；戒烟限酒，避免浓茶、咖啡等刺激性饮品。\n2. 运动：坚持规律中等强度有氧运动，如快走、慢跑、游泳、太极拳，每周至少5次、每次30分钟，以运动时心率不超过（170－年龄）为度；避免剧烈运动及清晨空腹或起床后立即剧烈活动。\n3. 作息与情志：保证每晚7～8小时睡眠，避免熬夜、过度劳累；学会情绪管理，通过冥想、听音乐、与家人倾诉等缓解焦虑紧张，保持心态平和，避免情绪激动诱发血压骤升。\n4. 自我监测与注意事项：每日晨起及睡前自测血压并记录，避免用力排便、憋气、突然改变体位；冬季注意保暖，减少冷热刺激；未经医师指导不得自行加药、减药或停药。\n\n【随诊要求】\n治疗初期每2～4周门诊复诊1次，监测血压、心率及更年期症状变化，直至血压平稳达标（<140/90mmHg）；血压达标稳定后每1～3个月复诊1次，复查血压、心率、血脂、血糖、血尿酸及肝肾功能；每年行心电图、心脏彩超评估靶器官损害。如出现血压明显波动、持续头痛、胸闷胸痛、视物模糊、肢体麻木或更年期症状加重，应及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":781,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"158101b55607a24604834793b0924dae08d7ddd9fa77d813c0646528baf99151","pinyin":"gengnianqigaoxueya","initials":"gnqgxy","setting":"out","caseName":"门诊病历649","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历649",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-488b2d6ca220b0dbef2e","key":"v1-c9ccc21dfe2a3058|templates-488b2d6ca220b0dbef2e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"稳定型心绞痛","category":"门诊病历模板","raw":{"name":"稳定型心绞痛","category":"门诊病历模板","case":{"case_name":"门诊病历650","templates":{"主诉":"劳力性胸痛3个月","现病史":"患者存在危险因素：吸烟、高血压、糖尿病、血脂异常、冠心病家族史、肥胖、缺乏运动，并有既往冠心病史（心梗史、PCI或搭桥史）。诱因多为劳力（上楼、快走、提重物）、情绪激动、饱餐、寒冷及晨起。于3个月前出现下列表现：胸痛或不适（胸骨后压榨样、闷痛或紧缩感，如胸部压石头感），可放射至左肩臂（尺侧）、颈部、下颌及背部；持续时间3~5分钟，多在10分钟以内；由诱因（活动达到一定量、运动耐量固定于同一阈值）诱发，即相同劳力引起相同程度的疼痛，为稳定型特征；休息或含服硝酸甘油后1~3分钟缓解；发作频率、强度及运动耐量（数周内无变化，符合稳定型）；可伴活动后气短、乏力，不典型者见于老年人、女性及糖尿病（无痛性心肌缺血，仅表现为气短，此项重要）。需鉴别：不稳定型心绞痛（静息发作、程度加重、硝酸甘油效果差，属急症，需评估）、心肌梗死（胸痛持续>20分钟，含服硝酸甘油不缓解）、非心源性胸痛（胃食管反流，有烧心感并与进食、卧位相关；肋间神经痛，有压痛并与呼吸相关；焦虑；胆囊疾病）。还需了解运动耐量变化（下降提示不稳定，为警示）及含服硝酸甘油的效果。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP142/86mmHg（评估血压及血脂控制状态）。体重及BMI；心肺检查注意心音及杂音（瓣膜病变）、有无啰音（心衰体征）、颈静脉充盈及下肢水肿（心衰）；周围血管检查（血管杂音、足背动脉搏动）；眼底检查（动脉硬化）；评估危险因素（腹部肥胖）。静息时体征多正常，发作时需评估并记录，发作时心电图对诊断帮助大。","辅助检查":"【必做】静息心电图（多正常，发作时可见ST段压低，应记录，发作时心电图诊断价值高；可见陈旧心梗Q波及左室肥厚）、运动负荷心电图（核心诊断手段，平板运动诱发胸痛并见ST段压低≥1mm为阳性，提示缺血；禁忌证为不稳定型心绞痛、心梗及心衰）、动态心电图（Holter，捕捉日常发作时的ST段变化）、超声心动图（评估室壁运动及心功能，静息节段性运动异常提示陈旧心梗；负荷超声通过运动或药物诱发节段性运动异常提示缺血）、冠脉CTA（用于低中危患者，无创评估冠脉狭窄及钙化，对排除冠心病有价值）、冠状动脉造影（金标准，用于确诊及决策血运重建，适用于高危、症状明显或负荷试验阳性者）；【血液】血糖及糖化血红蛋白、血脂（关注低密度脂蛋白目标值）、肝肾功能、血常规、心肌肌钙蛋白（稳定型者正常，升高提示急性冠脉综合征）、甲状腺功能。","初步诊断":"1. 稳定型心绞痛（冠心病，劳力性心绞痛；发作频率及运动耐量稳定；冠脉狭窄程度待造影或CTA评估；危险分层依据左室功能、负荷试验及病变范围；需评估二级预防）\n（注：治疗为抗缺血加二级预防加血运重建的综合方案：①急性发作处理：立即停止活动并休息，舌下含服硝酸甘油0.5mg；5分钟不缓解可再含1片，最多3片（每5分钟1片），15分钟仍不缓解须急诊（可能为心梗）；预防性用药可在预期劳力前含服。②抗缺血药物：β受体阻滞剂为一线首选（减慢心率、降低心肌耗氧，目标静息心率55~60次/分以控制心绞痛）；硝酸酯类（长效单硝酸异山梨酯，用于预防发作，须留出空白间期以防耐药）；钙通道阻滞剂（二线用药或用于β受体阻滞剂禁忌者，如地尔硫卓（适用于心率偏慢者）或维拉帕米，或二氢吡啶类氨氯地平（适用于心率正常者））；曲美他嗪及尼可地尔可作辅助用药。③二级预防（核心，防心梗及死亡）：抗血小板（阿司匹林75~100mg qd，终身服用，不能耐受者改用氯吡格雷）；他汀（强效，如阿托伐他汀20~40mg或瑞舒伐他汀10mg，使低密度脂蛋白<1.8mmol/L，此项重要，可稳定斑块、降低事件）；血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂（用于糖尿病、心衰或高血压者，具心脏保护作用）；控制危险因素（戒烟最为重要且为可改变因素、血压<130/80mmHg、血糖HbA1c<7%、控制体重、运动并予心脏康复运动处方、合理饮食）。④血运重建：指征为药物不能满意控制症状，或存在高危冠脉病变（左主干、多支病变、前降支近段病变）及负荷试验提示高危（大面积缺血）者；方式为经皮冠状动脉介入（置入支架，多用药物洗脱支架）或冠状动脉搭桥（适用于多支病变、糖尿病及左主干病变，其与经皮冠状动脉介入的获益需讨论）；血运重建可缓解症状，对高危者可改善生存。⑤随访：观察症状发作变化（加重提示不稳定，须就诊）、硝酸甘油疗效及运动耐量（下降为警示）；强调二级预防用药依从性（终身服用，此项重要）；每3~6个月评估危险因素并复查心电图；开展心脏康复运动训练以改善预后；搭桥或支架术后需复查，症状再发时评估再狭窄或桥血管病变。由心内科诊治，先评估（负荷试验或造影），予抗缺血加二级预防加血运重建，戒烟及他汀治疗重要。）","处理方案":"【药物治疗】\n1. 抗血小板：阿司匹林肠溶片 100mg qd 晨起空腹口服，长期服用（出血风险高者改氯吡格雷75mg qd）。\n2. 调脂稳定斑块：阿托伐他汀钙片 20mg qn 睡前口服，长期服用，目标LDL-C<1.8mmol/L，服药期间监测肝功能及肌酸激酶。\n3. 抗心绞痛（β受体阻滞剂）：琥珀酸美托洛尔缓释片 47.5mg qd 口服，静息心率控制在55~60次/分，逐周调整。\n4. 心绞痛发作时急救：硝酸甘油片 0.5mg 舌下含服，每5分钟可重复1次，最多含服3次，含服后症状不缓解或血压明显下降应立即急诊就医。\n\n【一般治疗及生活指导】\n1. 休息与活动：急性期或心绞痛频繁发作时卧床休息，缓解期坚持规律有氧运动（如快走、太极拳），每次30分钟、每周5次，运动强度以不诱发胸闷为宜，避免剧烈及竞技性运动。\n2. 饮食：低盐低脂低糖饮食，每日食盐<5g，控制总热量，戒烟、限酒、避免浓茶咖啡，保持大便通畅，避免用力排便。\n3. 禁忌：避免过度劳累、情绪激动、饱餐后立即活动、寒冷刺激及熬夜，随身携带硝酸甘油备用；合并高血压、糖尿病者严格控压、控糖。\n4. 体重管理：超重或肥胖者（BMI≥24kg/m²）减重，目标BMI<24kg/m²，注意防寒保暖，天气骤变时减少外出。\n\n【随诊要求】\n1. 用药后1个月门诊复诊，复查血脂、肝肾功能、心肌酶及心电图，评估心率、血压及药物耐受性。\n2. 症状稳定者每3~6个月复诊1次；若心绞痛发作频率、持续时间或严重程度增加，或静息状态下发作，应立即就诊，必要时行冠脉CTA或冠脉造影评估。\n3. 长期规律随访，动态复查血脂达标情况及肝肾功能，监测出血倾向，不适随诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":782,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2988910100c79d687367b1cda22466b7c112ddbb07c7588dc4e7bfc03c83a262","pinyin":"wendingxingxinjiaotong","initials":"wdxxjt","setting":"out","caseName":"门诊病历650","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历650",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0be1a94ad37d5d6061eb","key":"v1-c9ccc21dfe2a3058|templates-0be1a94ad37d5d6061eb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"不稳定型心绞痛","category":"门诊病历模板","raw":{"name":"不稳定型心绞痛","category":"门诊病历模板","case":{"case_name":"门诊病历651","templates":{"主诉":"胸痛伴出汗、气短6小时","现病史":"患者存在冠心病危险因素：吸烟、高血压、糖尿病、血脂异常及家族史，既往有稳定型心绞痛史，此次病情恶化，表现为发作频率增加、程度加重、诱发阈值降低（轻微活动即发作）、持续时间延长（>20分钟）、静息时发作（休息或夜间新出现）、含服硝酸甘油效果差或需加量，符合不稳定型心绞痛，属急性冠脉综合征，与稳定型心绞痛鉴别重要，其机制为斑块不稳定（破裂或糜烂）继发血栓（非闭塞性），可进展为心梗，须急症评估。于静息状态（诱因可不明显）出现下列表现：胸痛（胸骨后压榨样或闷痛，性质同稳定型，但发作特点为不稳定，即静息发作、程度加重、时间延长、硝酸甘油效果差），放射至左臂、颈、下颌，伴出汗、气短、恶心。心绞痛类型包括：静息型（休息时发作，持续>20分钟）、新发型（病程<2个月，中度以上活动即发作）、恶化型（原稳定型加重，频率增加、阈值降低）、梗死后型（心梗后早期，>24小时，属不稳定）、变异型（冠脉痉挛所致，静息发作伴ST段一过性抬高，钙通道阻滞剂有效）。心电图可见ST段压低及T波倒置（发作时出现、动态变化并可恢复）；心肌肌钙蛋白正常（不稳定型心绞痛不升高，若升高则为NSTEMI，此区别重要，需动态复查）；按GRACE评分行危险分层，高危（肌钙蛋白升高、ST段改变、血流动力学不稳定、恶性心律失常）者需紧急经皮冠状动脉介入，中低危者可先药物治疗并择期造影。今日来我院急诊/心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P92次/分，R20次/分，BP148/90mmHg。发作时可见痛苦面容、出汗，心率及血压可升高；心肺检查注意双肺有无啰音（提示心衰，属高危）、心脏有无S3或S4（心功能不全）、有无杂音（急性二尖瓣反流）、颈静脉有无怒张（右心衰）；全身评估有无灌注不足及休克；发作间期体征可正常，体征有限，需评估危险因素（血压、血脂、体重、腰围）。","辅助检查":"【必做】心电图（核心：静息时可见ST段压低及T波倒置，为不稳定型心绞痛特征；发作时动态对比ST改变可支持诊断）、动态心电图（捕捉发作时缺血，尤其静息及夜间发作）、心肌肌钙蛋白（动态检测（0、1、3小时），正常可排除心肌坏死，升高则为NSTEMI，按心梗处理）、肌酸激酶同工酶、BNP（评估心衰）、血糖及血脂（评估危险因素）、肾功能（为造影做准备）；【影像】超声心动图（可见节段性室壁运动异常（缺血，可逆）、左室射血分数评估泵功能，并排除其他病因如主动脉瓣狭窄）、冠脉CTA（用于低中危患者，门诊排除冠脉狭窄）、冠状动脉造影（金标准，用于决策经皮冠状动脉介入）；【危险分层】GRACE及TIMI评分（评估风险，指导治疗强度）；【负荷试验】病情稳定后行运动或药物负荷试验，评估缺血（低危者出院前必要时进行）。","初步诊断":"1. 不稳定型心绞痛（急性冠脉综合征，属不稳定型心绞痛，NSTEMI待肌钙蛋白分层；分型：恶化型；GRACE风险评分为中危；冠脉病变待评估）\n（注：治疗按急性冠脉综合征处理，住院观察，予药物加血运重建，依危险分层决策：①抗栓治疗：双联抗血小板（阿司匹林300mg负荷量加氯吡格雷300~600mg或替格瑞洛180mg，随后双抗维持1年）、抗凝（低分子肝素，依诺肝素1mg/kg q12h，用于急性期），高危或经皮冠状动脉介入者可考虑GPⅡb/Ⅲa抑制剂（现已少用）。②抗心肌缺血：硝酸酯类（硝酸甘油含服或静脉滴注，扩张冠脉、缓解症状）、β受体阻滞剂（美托洛尔，减慢心率、降低心肌耗氧，防止进展为心梗，目标心率55~60次/分）、钙通道阻滞剂（用于β受体阻滞剂禁忌或变异型心绞痛者，如地尔硫卓）、他汀（阿托伐他汀40~80mg，稳定斑块、抗炎，应早期使用，此项重要）。③介入治疗：高危者（肌钙蛋白升高、ST段改变、血流动力学不稳定或心律失常）行急诊冠脉造影加经皮冠状动脉介入（24小时内，此项重要）；中危者早期造影（48~72小时）；低危者经药物稳定后行负荷试验，异常者再造影。④并发症处理：进展为心梗（胸痛持续、肌钙蛋白升高，按心梗行再灌注治疗）、心衰及心律失常。⑤二级预防：双联抗血小板（1年，阿司匹林终身服用）、他汀（低密度脂蛋白<1.4mmol/L）、β受体阻滞剂、血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂（用于心衰或糖尿病者）、控制危险因素（血压、血糖、血脂及戒烟，为核心措施，防斑块进展）、心脏康复。⑥随访：观察症状（再发不稳定须急诊）、强调抗栓用药依从性（勿自行停药，支架置入后双抗治疗尤为重要，停药可致支架内血栓）、每3~6个月评估危险因素控制情况、支架术后必要时复查。由心内科及急诊诊治，按急性冠脉综合征评估，以肌钙蛋白分层，高危者早期行经皮冠状动脉介入，予双抗及他汀并落实二级预防，此项重要。）","处理方案":"【药物治疗】\n1. 抗血小板：阿司匹林肠溶片100mg qd晨起空腹口服，长期服用；联合氯吡格雷片75mg qd（双联抗血小板治疗），至少维持1个月，后根据缺血及出血风险评估调整。\n2. 调脂稳定斑块：阿托伐他汀钙片20mg qn（或瑞舒伐他汀钙片10mg qn）睡前口服，长期服用，目标LDL-C＜1.8mmol/L或较基线降低≥50%。\n3. 抗心绞痛：美托洛尔缓释片23.75~47.5mg qd口服（或酒石酸美托洛尔片25mg bid），根据心率调整，目标静息心率55~60次/分；单硝酸异山梨酯缓释片40mg qd口服（每日留出8~12小时无药间期）；心绞痛急性发作时予硝酸甘油片0.5mg舌下含服，5分钟无效可重复含服，最多连续3次，若仍不缓解立即急诊。\n4. 钙通道阻滞剂：地尔硫䓬片30mg tid口服（β受体阻滞剂禁忌或疗效不佳时选用，注意监测心率及血压）。\n【一般治疗及生活指导】\n1. 休息：发作期卧床休息，减少活动，避免劳累及熬夜，保持情绪稳定。\n2. 饮食：低盐低脂、清淡饮食，少食多餐，避免过饱，戒烟限酒，控制体重及血糖。\n3. 活动：缓解期可进行散步等中等强度有氧运动，避免剧烈运动、饱餐后立即活动及寒冷天气外出运动。\n4. 禁忌：避免情绪激动、用力排便、突然用力及寒冷刺激等诱发因素，保持大便通畅。\n【随诊要求】\n1. 服药1个月后复诊，复查血常规、凝血功能、肝肾功能，评估双联抗血小板出血风险。\n2. 服用他汀类药物1~3个月后复查血脂、肝功能及肌酸激酶，评估疗效与安全性。\n3. 若胸痛发作频率增加、静息或夜间发作、发作时间延长或含服硝酸甘油无效，应立即急诊就诊，切勿拖延。\n4. 症状稳定者建议尽早完善冠脉CTA或冠脉造影评估冠脉病变，根据患者具体情况制定个体化方案行血运重建治疗，术后按医嘱长期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":783,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"34494ee60df3a4e4a3274705688137d930843ba9be2d142953c98635ef66567d","pinyin":"buwendingxingxinjiaotong","initials":"bwdxxjt","setting":"out","caseName":"门诊病历651","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历651",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-92599605c9192adec961","key":"v1-c9ccc21dfe2a3058|templates-92599605c9192adec961","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"变异型心绞痛","category":"门诊病历模板","raw":{"name":"变异型心绞痛","category":"门诊病历模板","case":{"case_name":"门诊病历652","templates":{"主诉":"反复静息性胸痛2个月，多于夜间发作。","现病史":"患者（冠脉痉挛所致变异型心绞痛，即Prinzmetal心绞痛，为大冠脉局灶性痉挛引起透壁性缺血，发作时心电图ST段抬高，多于静息时发作，可在正常或狭窄冠脉基础上发生；吸烟为最重要危险因素及诱因，戒烟对减少痉挛发作有效而重要；其他诱因包括寒冷、情绪紧张、过度通气、可卡因、饮酒、镁缺乏；阿司匹林及NSAIDs可抑制前列环素，可能诱发冠脉痉挛，须注意；过敏反应亦可诱发；自主神经功能紊乱（迷走与交感神经昼夜节律变化）与午夜至清晨发作的特征有关）于夜间或凌晨（多为0~6时发作）出现：静息性胸痛（胸骨后压榨样，程度剧烈，休息时发作，与劳力无关，为变异型心绞痛的特征性表现；发作呈定时性，每天同一时间发作，以午夜至凌晨为著；每次持续数分钟，多为5~15分钟；含服硝酸甘油后迅速缓解，为痉挛解除的特征；发作时心电图ST段一过性抬高，患者急性心肌梗死鉴别，缓解后ST段即恢复，而心梗时持续抬高；可并发室性心律失常、晕厥或心肌梗死，痉挛持久者可进展为心肌梗死，故须重视）。既往有吸烟史，曾有类似发作，当时未能记录心电图（发作时心电图诊断价值高，急诊心电图或动态心电图可捕捉）。评估心肌梗死风险（痉挛可继发血栓形成）。今日来我院心内科就诊。患者为中老年男性，既往无高血压、糖尿病及冠心病史，起病以来精神紧张、夜间睡眠差，发作间期无明显胸痛，活动耐量尚可，无发热、无咯血。本次就诊前曾自行含服硝酸甘油，胸痛可于数分钟内缓解，为进一步明确胸痛性质及发作时心电图改变而就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP126/78mmHg。发作时行心电监护（可捕捉ST段抬高，必要时急诊或CCU监护）；心肺检查（注意心音变化及心律失常，痉挛发作时可出现；同时监测血压）；缓解期查体多正常；评估吸烟状态及危险因素。神志清楚，发育正常，营养中等，自主体位，查体合作。皮肤黏膜无黄染及出血点，浅表淋巴结未触及肿大。颈静脉无怒张，气管居中，甲状腺未触及肿大。胸廓对称，双肺呼吸音清，未闻及干湿性啰音。心前区无隆起，心界不大，心率78次/分，律齐，各瓣膜听诊区未闻及病理性杂音，无心包摩擦音。腹平软，无压痛，肝脾肋下未触及。双下肢无水肿。","辅助检查":"【必做】发作时心电图（核心检查，发作时可见ST段抬高，缓解后恢复，为诊断关键，强调发作时记录心电图；动态心电图或Holter可捕捉发作）、动态心电图（Holter可捕捉夜间发作时ST段抬高，价值重要）、心电图（缓解期多正常）、运动试验（可诱发，但变异型心绞痛多于静息时发作，运动多不诱发，故不可靠）；【确诊】冠脉造影（可于发作时行诱发试验，如乙酰胆碱或麦角新碱激发试验，以诱发痉挛；药物激发冠脉痉挛需在造影时备好硝酸甘油以便缓解，为确诊手段，患者导管室进行；造影同时评估冠脉有无狭窄或病变）；【其他】心肌肌钙蛋白（发作持久者提示心肌梗死时可升高）、超声心动图（发作时可见节段性室壁运动异常）、血镁及血钾（低镁可诱发冠脉痉挛，须检测并补充）、甲状腺功能、吸烟相关评估。上述检查以发作时心电图及冠脉激发试验为确诊依据，缓解期心电图多无异常，不能据此排除本病；若发作时未能记录心电图，患者症状反复发作时重复检查或行Holter监测，以免漏诊。","初步诊断":"1. 变异型心绞痛（冠脉痉挛性心绞痛；静息或夜间定时发作，心电图ST段一过性抬高，含服硝酸甘油后迅速缓解；需行冠脉造影及激发试验，并评估心肌梗死风险）\n（注：治疗原则为解除痉挛加预防复发（以钙通道阻滞剂为核心），并预防心肌梗死：①急性发作：舌下含服或静脉滴注硝酸甘油以缓解痉挛；反复发作者持续静脉滴注硝酸甘油；同时行心电监护，评估心律失常及心肌梗死风险；②预防复发：以钙通道阻滞剂为核心，为一线首选，可选用地尔硫卓或维拉帕米（适用于心率偏快者）或氨氯地平（长效制剂），常需高剂量、足量用药以控制痉挛，此点重要；必要时联合β受体阻滞剂（存在争议，β受体阻滞剂可加重痉挛，因α受体占优势致血管收缩，部分患者可加重，故须慎用，一般以钙通道阻滞剂为主加硝酸酯，不加β受体阻滞剂）、硝酸酯（长效制剂用于预防）、α受体阻滞剂或尼可地尔（用于难治性病例）、补充镁剂（适用于低镁者）；戒烟为最重要措施（吸烟可诱发痉挛，戒烟可显著减少发作，此点重要）；避免寒冷、情绪激动、过度通气及可卡因等诱因；③抗血小板及他汀治疗：可用阿司匹林（冠脉痉挛可与动脉粥样硬化并存，用于预防血栓及心肌梗死，但须注意个别患者阿司匹林可加重痉挛，应权衡利弊，多数主张使用）、他汀（改善内皮功能，降低事件风险）；④血运重建：适用于痉挛合并固定狭窄者，即造影发现狭窄病变时可行经皮冠状动脉介入及支架植入（支架治疗对痉挛节段部分有效，但痉挛可在支架处再发，须评估）；单纯痉挛而无狭窄者以药物治疗为主，即钙通道阻滞剂；⑤随访：观察发作情况（钙通道阻滞剂足量后是否缓解、停发并记录）、动态心电图（随访ST段抬高发作是否消失以评估疗效）、心肌梗死风险（痉挛持久可致心肌梗死，症状持续超过20分钟须急诊，此点重要）、钙通道阻滞剂需长期维持，勿自行停药（停药可致反跳性痉挛，此点重要）、坚持戒烟；心内科随诊，以钙通道阻滞剂为核心，配合硝酸酯、戒烟、Holter随访，重视心肌梗死风险。本病为冠脉痉挛所致，发作多集中于夜间及凌晨，长期规范服用钙通道阻滞剂可显著减少发作；治疗目标为解除痉挛、预防复发并防止心肌梗死，患者应随身携带硝酸甘油，发作时及时含服，症状持续不缓解时立即急诊就诊。","处理方案":"【药物治疗】\n1. 钙通道阻滞剂（控制冠脉痉挛的首选药物）：地尔硫䓬缓释胶囊90mg qd口服，或地尔硫䓬片30mg tid口服；痉挛发作频繁者可联合硝苯地平控释片30mg qd口服。疗程：长期维持治疗，症状缓解后仍需维持用药，停药医师指导下缓慢减量，不可骤停。\n2. 硝酸酯类（缓解急性发作）：硝酸甘油片0.5mg舌下含服，发作时立即含服，每5分钟可重复1次，最多连续3次；发作频繁者予硝酸异山梨酯片5mg tid口服预防发作。\n3. 抗血小板（降低血栓及心肌梗死风险）：阿司匹林肠溶片100mg qd口服，长期服用。\n4. 他汀类调脂（稳定斑块）：阿托伐他汀钙片20mg qn口服，长期服用，定期复查血脂及肝功能；注意变异型心绞痛患者应避免使用β受体阻滞剂，以免加重冠脉痉挛。\n【一般治疗及生活指导】\n1. 戒烟限酒，避免寒冷刺激、情绪激动、精神紧张及过度劳累等诱发冠脉痉挛的因素，冬季注意保暖，避免清晨冷空气下外出。\n2. 低盐低脂饮食，规律进餐，保证充足睡眠，避免熬夜及长时间伏案劳累。\n3. 适度有氧运动（如散步、慢走、太极拳），以不诱发胸痛为度，避免剧烈运动及突然用力。\n4. 避免自行使用β受体阻滞剂、拟交感神经类药物及可诱发血管痉挛的药物，如确需加用其他药物，医师指导下进行。\n【随诊要求】\n1. 治疗后2~4周门诊复诊，评估胸痛发作频率、持续时间及程度改善情况，必要时调整药物剂量。\n2. 每1~3个月定期门诊随访，监测血压、心率、血脂及肝肾功能，观察药物不良反应（头痛、面部潮红、踝部水肿、牙龈增生、低血压等）。\n3. 定期复查心电图及24小时动态心电图，评估心肌缺血发作及心律失常情况；每年复查心脏超声，必要时复查冠脉CTA或冠状动脉造影。\n4. 如出现胸痛发作时间延长、程度加重、发作频率增多，或伴晕厥、呼吸困难、血压下降等表现，须立即急诊就医，不可延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":784,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9ff8527bf24b696d37331a16d86c054e01145e612d6ba9e3459d5ae6ab6eca52","pinyin":"bianyixingxinjiaotong","initials":"byxxjt","setting":"out","caseName":"门诊病历652","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历652",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-dcb71d905e03e3020b5f","key":"v1-c9ccc21dfe2a3058|templates-dcb71d905e03e3020b5f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"卧位型心绞痛","category":"门诊病历模板","raw":{"name":"卧位型心绞痛","category":"门诊病历模板","case":{"case_name":"门诊病历653","templates":{"主诉":"胸痛1天","现病史":"患者1周前无明显诱因出现卧位型心绞痛相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者1周前无明显诱因出现卧位型心绞痛相关症状并进行性加重，今日以胸痛1天就诊，卧位型心绞痛多于平卧安静时发作，提示冠状动脉储备功能明显下降，入院即刻完善心电图检查明确有无 ST 段压低、T 波倒置等心肌缺血改变；完善心肌酶谱、肌钙蛋白检查排除急性心肌梗死及心肌损伤；完善血常规检查排除贫血、感染所致心肌氧供不足；拟使用抗血小板、调脂及扩冠药物治疗，完善生化全项（肝肾功能）检查排除肝肾功能不全，为用药安全提供依据；完善生化全项中电解质检查排除电解质紊乱所致心律失常及血管痉挛；完善生化全项中血糖、血脂检查了解血脂水平及糖代谢状态，指导调脂、抗动脉粥样硬化方案；完善心脏超声检查（含左心功能测定）了解室壁运动、射血分数及瓣膜情况，评估心功能与缺血性心肌损害；完善胸部X线片检查了解心脏大小、主动脉情况及肺部情况，排除肺部疾患所致胸痛；胸痛发作与体位相关，完善动态心电图检查了解夜间及静息状态下的心肌缺血与心律失常；完善 BNP/NT-proBNP 检查明确有无心功能衰竭；必要时完善冠脉CTA检查明确冠状动脉狭窄部位及程度，进一步明确诊断并评估血运重建指征。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 卧位型心绞痛\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗血小板治疗：阿司匹林肠溶片100mg qd口服（无禁忌者）；急性期可与氯吡格雷片75mg qd口服联合双联抗血小板治疗。\n2. 抗心肌缺血治疗：发作时立即硝酸甘油片0.5mg舌下含服，5分钟不缓解可重复1次，最多连续3次，含服后取坐位防跌倒；缓解期予单硝酸异山梨酯缓释片40mg qd晨服，长期用药留出夜间无硝酸酯间歇期以防耐药。\n3. β受体阻滞剂：琥珀酸美托洛尔缓释片23.75~47.5mg qd口服，逐渐滴定至静息心率55~60次/分；心率<55次/分、低血压或房室传导阻滞者减量或慎用。\n4. 调脂稳定斑块：阿托伐他汀钙片20mg qn口服（或瑞舒伐他汀钙片10mg qn），长期服用，定期监测肝功能与肌酸激酶。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息，采取半卧位或坐位，避免完全平卧；夜间入睡时抬高床头15°~30°，减少静脉回心血量、降低室壁张力与心肌耗氧。\n2. 低盐低脂饮食（每日食盐<5g），少食多餐，晚餐宜清淡少量，避免饱餐及睡前进食；戒烟限酒，控制体重。\n3. 避免诱发因素：情绪激动、过度劳累、用力排便、寒冷刺激；保持大便通畅，便秘者可用乳果糖口服溶液10ml qd通便。\n4. 症状稳定后循序渐进进行有氧运动（慢走、太极拳等），每次20~30分钟，以不诱发胸闷为度；静息状态下仍有不适或发作频繁时暂停活动。\n\n【随诊要求】\n1. 卧位型心绞痛属不稳定型心绞痛高危类型，建议尽快收住院行冠脉造影评估血运重建；若门诊观察，2周内复诊并复测血压、心率、心电图。\n2. 复诊复查血常规、肝肾功能、血脂、空腹血糖、肌钙蛋白I及心脏彩超，评估疗效及药物不良反应（出血、肝功能异常、肌病等）。\n3. 若胸痛发作更频繁、持续时间延长、含服硝酸甘油效果变差，或伴出汗、呼吸困难、黑矇、晕厥，立即急诊就医；服药期间出现牙龈出血、黑便、皮下瘀斑、肌痛等及时就诊调整用药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":785,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"34ae67d9815794af1550ef55645956360b419c55b4f070a8b1a5212877c90d20","pinyin":"woweixingxinjiaotong","initials":"wwxxjt","setting":"out","caseName":"门诊病历653","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历653",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9929588a3f74c0da1ab8","key":"v1-c9ccc21dfe2a3058|templates-9929588a3f74c0da1ab8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"梗死后心绞痛","category":"门诊病历模板","raw":{"name":"梗死后心绞痛","category":"门诊病历模板","case":{"case_name":"门诊病历654","templates":{"主诉":"胸痛1天","现病史":"患者1周前无明显诱因出现梗死后心绞痛相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者有心肌梗死病史，1周前无明显诱因出现梗死后心绞痛相关症状并进行性加重，今日以胸痛1天就诊，提示梗死相关血管区域存在存活心肌缺血，入院即刻完善心电图检查并与既往心电图对比，明确有无新发 ST-T 动态演变；完善心肌酶谱、肌钙蛋白检查排除再发急性心肌梗死；完善血常规检查排除贫血、感染所致心肌氧供不足；完善生化全项（肝肾功能）检查排除肝肾功能不全，为抗血小板、调脂药物安全使用提供依据；完善生化全项中电解质检查排除电解质紊乱所致心律失常及冠状动脉痉挛；完善生化全项中血糖、血脂检查了解血脂水平，指导二级预防调脂方案；完善心脏超声检查（含左心功能测定）了解梗死节段室壁运动、射血分数及有无室壁瘤形成，评估心功能及预后；完善胸部X线片检查了解心脏大小及肺部情况，排除肺淤血及肺部疾患；完善 BNP/NT-proBNP 检查明确有无心功能衰竭并进行心功能分级；完善动态心电图检查了解有无发作性心肌缺血及恶性心律失常；必要时完善冠脉CTA检查明确梗死后冠状动脉残余狭窄及血管病变情况，评估血运重建指征。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 梗死后心绞痛\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗血小板治疗：阿司匹林肠溶片100mg qd晨服，联合氯吡格雷片75mg qd，双联抗血小板治疗持续≥12个月；\n2. 调脂稳定斑块：阿托伐他汀钙片20mg qn（或瑞舒伐他汀钙片10mg qn），长期服用，LDL-C目标<1.4mmol/L或较基线降低≥50%；\n3. 抗心肌缺血：琥珀酸美托洛尔缓释片47.5mg qd，静息心率目标55~60次/分；若仍有心绞痛发作，加用单硝酸异山梨酯缓释片40mg qd晨服；\n4. 改善预后：培哚普利叔丁胺片4mg qd（无禁忌证时），血压控制目标<130/80mmHg。\n\n【一般治疗及生活指导】\n1. 发病后4周内避免劳累及剧烈活动，保证充分休息，避免情绪激动及用力排便，保持大便通畅；\n2. 低盐低脂饮食，每日食盐<5g，戒烟限酒，控制体重（BMI<24kg/m²），规律作息；\n3. 每日监测血压、心率并记录；胸痛发作时立即舌下含服硝酸甘油0.5mg，若15~20分钟不缓解或反复发作，立即就近急诊就医；\n4. 循序渐进恢复活动，如平地散步，以不诱发胸闷胸痛为度，避免饱餐后、寒冷及清晨剧烈活动。\n\n【随诊要求】\n1. 1~2周内门诊复诊，评估心绞痛发作频率、血压心率控制情况及药物耐受性；\n2. 每月复查心电图、血脂、肝肾功能及心肌酶谱；心脏超声每3~6个月复查，动态评估心功能及室壁运动；\n3. 若心绞痛频繁发作、出现静息或夜间发作、发作时间延长或含服硝酸甘油疗效下降，提示高危，需立即复诊，必要时住院行冠脉造影评估残余狭窄；\n4. 长期坚持二级预防用药，切勿自行停药或减量。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":786,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"610c0a9d0900652bee4ae56e434a0859a2784698b7f7a0c253ddb1de9966d094","pinyin":"gengsihouxinjiaotong","initials":"gshxjt","setting":"out","caseName":"门诊病历654","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历654",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-09df6528b18e5b39bfe0","key":"v1-c9ccc21dfe2a3058|templates-09df6528b18e5b39bfe0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性心肌梗死","category":"门诊病历模板","raw":{"name":"急性心肌梗死","category":"门诊病历模板","case":{"case_name":"门诊病历655","templates":{"主诉":"突发胸骨后压榨性剧痛1小时。","现病史":"患者（危险因素：吸烟、高血压、糖尿病、血脂异常、冠心病家族史；既往有冠心病、心绞痛、心肌梗死、支架植入或搭桥史）于静息或活动时（诱因可为劳累、情绪激动、饱餐、寒冷，亦多见于晨起）出现：胸痛（胸骨后压榨样，范围大，可超过手掌大小，程度剧烈，持续超过30分钟；心绞痛多短于20~30分钟且含服硝酸甘油可缓解，而心梗时疼痛持续，含服硝酸甘油不缓解，为重要鉴别点）、放射痛（可放射至左肩、左臂、下颌或背部）、大汗（明显，皮肤湿冷）、濒死感及恐惧、恶心呕吐（下壁梗死时迷走神经张力增高，较常见）、气短（提示心衰或肺水肿等泵衰竭表现）、心悸（提示心律失常）、晕厥（提示严重心律失常或心源性休克）、烦躁不安；不典型表现（老年人或糖尿病患者可无胸痛，即无痛性心梗，仅表现为气短、乏力、意识模糊或上腹痛，须警惕，尤其糖尿病患者因神经病变致感觉减退，此点重要；女性症状亦可不典型；上腹痛易误认为胃病，下壁梗死时尤须注意）。发病时间须精确记录症状开始时间，对再灌注时间窗的判定至关重要；记录院前是否嚼服阿司匹林、是否含服硝酸甘油及是否呼救。今日来我院急诊胸痛中心就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P98次/分（可增快或减慢，取决于有无心律失常），R22次/分，BP108/68mmHg（可降低见于心源性休克；亦可升高见于应激状态）。神志（清楚、烦躁或淡漠，淡漠提示休克）。面色苍白、大汗、皮肤湿冷（提示休克）、肺部（可闻及湿啰音，提示肺水肿及泵衰竭，须行Killip分级评估）、心脏（心音低钝、奔马律即S3，提示泵衰竭；心包摩擦音提示梗死后心包炎，多见于2~4天；注意心律失常，如心动过速或心动过缓；闻及杂音提示乳头肌功能不全致二尖瓣反流，新出现杂音提示并发症）、腹部（注意上腹部，下壁梗死时可出现上腹压痛）、颈静脉（右室梗死时可怒张，伴低血压构成三联征，提示右室梗死）、四肢（评估灌注，休克时肢体冰冷）。","辅助检查":"【必做】心电图（核心检查，须立即进行并在10分钟内完成：ST段抬高，呈弓背向上，见于STEMI，须有至少2个相邻导联抬高；新发左束支传导阻滞属STEMI等同表现；ST段压低或T波倒置见于NSTEMI；须动态观察演变，包括ST段回落、T波倒置及Q波形成，以评估再灌注效果；同时持续心电监护）；【血液】心肌肌钙蛋白（患者肌钙蛋白为核心指标，发病3~4小时开始升高，12~24小时达峰，须动态复查，可于0、1、3小时检测以排除心梗）、肌酸激酶同工酶、血常规、凝血功能、血糖（注意应激性高血糖及糖尿病）、电解质、肝肾功能、血脂（入院基线）、BNP或NT-proBNP（评估心衰及泵衰竭）；【影像】床旁超声心动图（观察节段性室壁运动异常，有助于急性期定位；测定左室射血分数以评估泵功能；评估并发症，如室间隔穿孔、乳头肌断裂、心包积液及室壁瘤；对心包情况及急症评估关键）；【再灌注评估】冠状动脉造影（可急诊行经皮冠状动脉介入即PCI，为再灌注的金标准）、冠状动脉CTA（少用，不适用于急诊）；【其他】胸片（评估肺水肿及心脏大小）、血气分析。","初步诊断":"1. 急性心肌梗死（分型：STEMI或NSTEMI；部位：前壁、下壁或后壁，依心电图导联判断；Killip分级：Ⅰ~Ⅳ级；记录发病小时数，据此决定再灌注策略）\n（注：急性心肌梗死属急症，时间就是心肌，再灌注时间窗为救治核心：①急诊处理：立即行心电监护，持续监测；低氧者吸氧；阿司匹林300mg嚼服，须立即给予，联合替格瑞洛180mg或氯吡格雷600mg行双抗负荷；吗啡2~4mg静脉注射镇痛，适用于剧痛者，低血压者慎用；硝酸甘油含服或静脉滴注，但下壁或右室梗死时慎用（因低血压，右室梗死依赖前负荷，故不用，此点重要）；他汀类药物（阿托伐他汀80mg，早期给予）；②再灌注治疗：STEMI为核心，须把握时间窗，首选急诊经皮冠状动脉介入，适用于发病12小时内（超过12小时但仍有持续缺血或心源性休克者仍可进行），要求球囊扩张时间少于90分钟（自首次医疗接触算起，此点重要）；不能行经皮冠状动脉介入者可溶栓，用rt-PA，要求发病30分钟内开始（院内），适用于胸痛发作12小时内且无禁忌者，溶栓后3~24小时行冠状动脉造影，必要时补救性经皮冠状动脉介入；NSTEMI以抗栓加危险分层为主，肌钙蛋白升高或属高危者应早期行经皮冠状动脉介入（24小时内），病情稳定者择期造影；③抗栓治疗：阿司匹林联合替格瑞洛或氯吡格雷行双抗，持续1年，适用于急性冠脉综合征；肝素或比伐卢定抗凝，用于经皮冠状动脉介入期间及急性期；替罗非班用于高危患者经皮冠状动脉介入术前，较少使用；④并发症处理：泵衰竭或心源性休克者予利尿（呋塞米）及血管活性药（多巴胺或去甲肾上腺素，用于休克），可行主动脉内球囊反搏（用于泵衰竭或休克的机械辅助，此点重要）；机械并发症如室间隔穿孔或乳头肌断裂须急诊手术；心律失常方面，室颤予除颤，室速用胺碘酮或电复律，房室传导阻滞（下壁梗死所致者多可逆，可观察）必要时起搏；右室梗死者予扩容（生理盐水，以维持前负荷，此点重要，不用硝酸酯类及利尿剂）；心包炎者相应处理；⑤二级预防：双抗治疗1年后改为单抗；他汀强化治疗，目标低密度脂蛋白低于1.4mmol/L；β受体阻滞剂（美托洛尔，早期使用以防猝死，心衰者亦适用）；血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂（适用于心衰或射血分数降低者，可改善预后）；螺内酯（适用于心衰）；控制血压、血糖并戒烟；行心脏康复，制定运动处方以防复发；⑥随访：复查心电图及超声以评估心功能恢复、随访心衰、注意再发缺血（出现症状及时急诊）、康复方面于4~6周内循序渐进活动，于心内科门诊随诊；由急诊胸痛中心、心内科及导管室协作，尽快再灌注，启动绿色通道，牢记时间就是心肌，此点重要。","处理方案":"【药物治疗】\n1.抗血小板：阿司匹林肠溶片100mg qd晨服，联合氯吡格雷片75mg qd，双联抗血小板治疗持续12个月（若行支架植入按医嘱延长），注意观察牙龈、皮肤及消化道出血。\n2.调脂稳定斑块：阿托伐他汀钙片20mg qn口服（或瑞舒伐他汀钙片10mg qn），长期服用，LDL-C目标＜1.4mmol/L或较基线降幅≥50%，定期复查肝功能及肌酸激酶。\n3.β受体阻滞剂：琥珀酸美托洛尔缓释片23.75mg qd口服，根据心率调整至47.5mg qd，目标静息心率55～60次/分，心率＜50次/分或伴低血压时减量并随诊。\n4.如合并左心功能不全/心力衰竭：培哚普利片4mg qd口服（或缬沙坦胶囊80mg qd），注意监测血压、肾功能及血钾；胸痛发作时舌下含服硝酸甘油片0.5mg，5分钟不缓解可重复1次，最多3次。\n【一般治疗及生活指导】\n1.休息：急性期卧床休息1～3天，避免劳累及情绪激动，保持大便通畅，避免用力排便，必要时予乳果糖口服液通便。\n2.饮食：低盐低脂清淡饮食，每日食盐＜5g，减少饱和脂肪酸及胆固醇摄入，少食多餐、避免饱餐，戒烟限酒，控制体重。\n3.活动：病情稳定后循序渐进开展心脏康复活动，从床上活动、坐位过渡至平地慢走，逐步增加活动量，避免剧烈运动、屏气动作及寒冷刺激。\n4.禁忌：禁用西地那非等PDE5抑制剂（与硝酸酯类药物同用可致严重低血压），避免突然停药、熬夜及竞技性活动，随身携带硝酸甘油。\n【随诊要求】\n1.门诊复诊：出院后1、3、6、12个月定期复诊，复查心电图、心肌损伤标志物、血脂、肝肾功能、凝血功能及血常规。\n2.心功能评估：3～6个月内行心脏彩色多普勒超声评估左室射血分数及室壁运动，支架术后患者遵医嘱复查冠脉造影或负荷试验。\n3.危险信号：若再发胸痛、胸闷、呼吸困难、晕厥或黑便，立即舌下含服硝酸甘油，5分钟不缓解立即拨打120急诊就医，切勿自行驾车。\n4.危险因素控制：长期监测并控制血压＜130/80mmHg、空腹血糖及LDL-C达标，合并房颤患者按医嘱评估抗凝治疗，规律复诊调整用药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":787,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b05de06f6b75d5cbfe11faf433b8c1fcf807d89c682d91a5145bbb89be7e6c48","pinyin":"jixingxinjigengsi","initials":"jxxjgs","setting":"out","caseName":"门诊病历655","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历655",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-143b228c80ca91fc3b6d","key":"v1-c9ccc21dfe2a3058|templates-143b228c80ca91fc3b6d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"陈旧性心肌梗死","category":"门诊病历模板","raw":{"name":"陈旧性心肌梗死","category":"门诊病历模板","case":{"case_name":"门诊病历656","templates":{"主诉":"胸闷1天","现病史":"患者1周前无明显诱因出现陈旧性心肌梗死相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者有陈旧性心肌梗死病史，1周前无明显诱因出现胸闷相关症状并进行性加重，今日以胸闷1天就诊，重点评估梗死后左室重构、心功能状态及缺血复发风险；完善心电图检查明确有无病理性 Q 波、ST-T 改变及新发缺血动态演变；完善心肌酶谱、肌钙蛋白检查排除新的急性心肌梗死及心肌损伤；完善血常规检查排除贫血、感染所致胸闷及心肌氧供不足；完善生化全项（肝肾功能）检查排除肝肾功能不全，为二级预防用药提供依据；完善生化全项中电解质检查排除电解质紊乱所致心律失常及心肌兴奋性异常；完善生化全项中血糖、血脂检查了解血脂水平，指导强化调脂治疗；完善心脏超声检查（含左心功能测定）了解梗死节段室壁运动、射血分数及有无室壁瘤、附壁血栓，评估心功能与预后；完善胸部X线片检查了解心脏大小及肺部情况，排除肺部疾患所致胸闷；完善 BNP/NT-proBNP 检查明确有无心功能衰竭；完善动态心电图检查了解有无发作性心肌缺血与心律失常；必要时完善冠脉CTA检查明确冠状动脉病变及残余狭窄情况，进一步明确诊断。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 陈旧性心肌梗死\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗血小板治疗：阿司匹林肠溶片100mg qd，晨起空腹口服，长期维持；若不能耐受或过敏，改用氯吡格雷片75mg qd。\n2. 调脂稳定斑块：阿托伐他汀钙片20mg qn（或瑞舒伐他汀钙片10mg qn），睡前口服，长期服用，使LDL-C降至<1.8mmol/L或较基线下降≥50%，定期复查肝功能及肌酶。\n3. β受体阻滞剂：琥珀酸美托洛尔缓释片23.75mg qd（或酒石酸美托洛尔片12.5mg bid），根据心率及血压调整剂量，静息心率控制在55~60次/分，长期服用，注意心率不低于50次/分。\n4. 血管紧张素转换酶抑制剂：培哚普利片4mg qd（或缬沙坦胶囊80mg qd），长期服用以改善心室重构，注意监测血压、肾功能及血钾；如有心绞痛发作，可临时含服硝酸甘油片0.5mg，间隔5分钟可重复，最多3次，无效立即急诊就诊。\n\n【一般治疗及生活指导】\n1. 生活方式：绝对戒烟、限酒（最好戒酒），规律作息，保证充足睡眠，避免劳累、熬夜及情绪激动。\n2. 饮食：低盐低脂饮食（每日食盐<6g），减少饱和脂肪及反式脂肪摄入，多食新鲜蔬菜、水果及全谷物，控制体重（BMI<24kg/m²）。\n3. 活动：病情稳定后循序渐进进行有氧运动（如快走、慢骑车），每周3~5次、每次30分钟左右，以运动后不感胸闷气促为度；避免剧烈运动、屏气用力及提重物。\n4. 禁忌及防护：避免用力排便（可预防性使用乳果糖或开塞露），寒冷天气注意保暖，避免饱餐后立即运动，防止诱发心绞痛或再梗死。\n\n【随诊要求】\n1. 每1~3个月门诊复诊，复查心电图、血压、心率，评估心功能（心脏彩超每6~12个月复查一次）。\n2. 每3~6个月复查血脂、肝肾功能、血糖及心肌酶谱，根据结果调整他汀及降糖、降压药物。\n3. 长期规范服药，不可自行停药或减量；如出现胸痛、胸闷、气促加重、心悸、晕厥或黑便等情况，立即就近急诊就诊；支架或搭桥术后患者遵医嘱定期行冠脉复查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":788,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0bc5e02b39ba2962d10e97649174d2479435c8b05a717303bd85b63ac10a062b","pinyin":"chenjiuxingxinjigengsi","initials":"cjxxjgs","setting":"out","caseName":"门诊病历656","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历656",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e08009700fd5d625e2ce","key":"v1-c9ccc21dfe2a3058|templates-e08009700fd5d625e2ce","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心房扑动","category":"门诊病历模板","raw":{"name":"心房扑动","category":"门诊病历模板","case":{"case_name":"门诊病历657","templates":{"主诉":"阵发性心悸伴胸闷、气短1年，加重3天。","现病史":"患者（多见于器质性心脏病，如冠心病、高血压性心脏病、瓣膜病（二尖瓣病变致左房扩大）、心力衰竭、肺病（肺心病伴低氧可致房扑）、甲状腺功能亢进、先天性心脏病修补术后、心脏手术（术后房扑与心房切口瘢痕有关）、饮酒（阵发性发作，即所谓假日心脏综合征，饮酒可诱发房扑或房颤），亦可见特发性者）于阵发、持续或持久发作时出现：心悸（发作时自觉心悸，感心脏乱跳或快速匀齐；房扑时心房率250~350次/分，心室率依房室传导比例而定，2:1传导时心室率约150次/分且匀齐，最为常见；3:1或4:1传导时心室率约75~100次/分，相对较慢；1:1传导少见，心室率极快可达300次/分，可致晕厥，血流动力学严重障碍，属急症；房室传导比例变化时心律可不齐）、胸闷、气短、乏力、头晕、颈静脉扑动波（房扑时心房收缩可在颈静脉见到扑动波）、多尿、心衰加重（原有心衰者可因房扑而加重）、心绞痛（冠心病患者心率增快可致缺血）、血栓栓塞（房扑时心房内可形成血栓，虽较房颤发生率低，但仍有栓塞风险，左心耳血栓可致卒中，故抗凝重要，房扑与房颤在栓塞处理上类似）。鉴别诊断包括心房颤动（心室率绝对不齐，房颤与2:1传导的房扑易混淆，需心电图鉴别：房扑可见锯齿状F波，Ⅱ、Ⅲ、aVF导联为负向锯齿波，心房率250~350次/分且规则；房颤为f波且节律不齐）、窦性心动过速及室上性心动过速的鉴别。诱因包括饮酒、劳累、感染及手术等。今日来我院急诊或心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P146次/分（心室率可快可慢，脉律在2:1传导时规则，传导比例变化时不齐）、BP118/76mmHg。心率（快，2:1传导时约150次/分，或心律不规则，取决于传导比例变化）、心音（S1可恒定，见于传导规则时；亦可强弱变化）、颈静脉（可见扑动波，为心房收缩经房室传导形成的快速扑动波，为特征性表现，颈静脉可见快速节律性搏动）、肺部（可闻及湿啰音，提示心衰）、血压（1:1传导时可降低，甚至休克）、甲状腺（注意有无甲亢体征）、基础心脏病体征（注意心脏杂音提示瓣膜病变及心衰体征）。","辅助检查":"【必做】心电图（核心检查，用于诊断房扑：P波消失，代之以F波即锯齿状扑动波，在Ⅱ、Ⅲ、aVF导联明显，心房率250~350次/分且规则；房室传导以2:1最常见，心室率约150次/分且匀齐，此时按压颈动脉窦或给予腺苷可减慢房室传导、显示F波，从而明确诊断，为重要诊断技巧；QRS波窄，属室上性）、动态心电图（用于阵发性发作的捕捉）、Holter；【血液】电解质（评估低钾）、甲状腺功能（甲亢可致房扑，此点重要）、血常规、心肌肌钙蛋白（评估缺血）、肝肾功能；【影像】超声心动图（评估基础心脏病，包括左房大小、瓣膜及心功能，为核心检查；并注意左心耳血栓，可经食管超声检查，于电复律或消融前排除血栓，此点重要，即复律前需抗凝3周或经食管超声排除血栓）；【其他】心电生理检查及房扑消融（典型房扑可行三尖瓣峡部消融，可根治，此点重要）；动态监测发作频率。","初步诊断":"1. 心房扑动（分型：典型（峡部依赖、逆钟向，常见）或非典型；病程：阵发性、持续性或持久性；心室率（房室传导比例如2:1等）；评估基础心脏病（左房大、瓣膜病变、心衰）及栓塞风险（CHA₂DS₂-VASc评分））\n（注：治疗以控制心室率或转复加抗凝为主，依血流动力学状态及病程决定：①急性期血流动力学不稳定者（低血压、休克、心衰或1:1快速传导）行同步电复律（50~100J，所需能量低，房扑对电复律敏感且有效，此点重要）；②控制心室率（适用于稳定者）：β受体阻滞剂（美托洛尔或艾司洛尔，可减慢房室传导，目标心室率低于100~110次/分）、钙通道阻滞剂（地尔硫卓，静脉或口服，可延长房室结不应期）、洋地黄（地高辛，适用于心衰合并房扑，为二线用药）、胺碘酮（用于难以控制或合并心衰的房扑）；③转复窦性心律：可行电复律（同步，50~100J，房扑复律成功率高）、药物复律（伊布利特或普罗帕酮，可转复房扑，但须监护，注意尖端扭转型室速及QT间期延长；氟卡尼适用于阵发性房扑且心脏正常者）、导管消融（可根治，行三尖瓣峡部消融，对典型房扑成功率超过95%，应首选根治，尤其适用于反复发作或药物治疗效果不佳者，此点重要，属微创治疗）；④抗凝：房扑的栓塞风险与房颤相同，应评估CHA₂DS₂-VASc评分（包括心衰、高血压、年龄不低于75岁计2分、糖尿病、卒中史计2分、血管病、女性），男性不低于2分、女性不低于3分者应抗凝（可用华法林或新型口服抗凝药，如利伐沙班或达比加群，NOAC应首选，用药简便）；房扑转复时，若持续时间超过48小时，患者转复前抗凝3周或经食管超声排除左心耳血栓后再复律，或直接行消融（消融可根治，但转复的抗凝原则同房颤）；复律后须继续抗凝至少4周，并依CHA₂DS₂-VASc评分决定是否长期抗凝；⑤处理诱因及基础病：甲亢者治疗甲亢、饮酒者戒酒、心衰者控制心衰、肺病伴低氧者纠正低氧；⑥随访：随访心律（复查心电图，评估复律或消融后窦性心律能否维持）、心室率（评估控制是否达标）、抗凝（监测出血及栓塞，NOAC须注意依从性）、复发（房扑复发者再次评估消融）、基础病随访；由心内科处理，以控制心室率、抗凝及复律为主，典型房扑可行消融根治，并重视预防栓塞，此点重要。","处理方案":"【药物治疗】\n1. 控制心室率：首选β受体阻滞剂，琥珀酸美托洛尔缓释片47.5mg qd口服；若不耐受或合并心衰，可选用地尔硫䓬片30mg tid口服（心衰及低血压者禁用），目标静息心室率60～80次/分。\n2. 转复并维持窦律：胺碘酮片0.2g tid口服×7天，之后减为0.2g qd维持（用药前及用药期间监测心电图QT间期、甲状腺功能、肝功能）；无结构性心脏病者可选用普罗帕酮片150mg tid口服。\n3. 预防血栓栓塞：根据CHA₂DS₂-VASc评分≥2分者（男性）或≥3分者（女性）启动抗凝，利伐沙班片20mg qd口服（CrCl 15～49ml/min者减为15mg qd）；或华法林钠片2.5mg qd起始，维持INR 2.0～3.0。\n【一般治疗及生活指导】\n1. 休息：急性发作期及心室率未控制时卧床休息，避免劳累、剧烈运动及情绪激动，保证充足睡眠。\n2. 饮食：低盐低脂清淡饮食，戒烟限酒，避免浓茶、咖啡、酒精等兴奋性饮品，避免暴饮暴食。\n3. 活动：症状控制后可进行散步、慢跑、太极拳等中等强度有氧运动，每次30分钟左右，以不诱发心悸、气短为度；避免竞技性及屏气用力的运动。\n4. 监测与禁忌：教会患者每日自测脉搏（注意脉搏不规则或明显增快/减慢），未经医师评估勿自行停药或改量；出现黑矇、晕厥、胸痛、呼吸困难时立即就医。\n【随诊要求】\n1. 用药后2周复诊，复查心电图及24小时动态心电图，评估心室率控制及心律转复情况，据此调整药物剂量。\n2. 服用胺碘酮者每3～6个月复查心电图（QT间期）、甲状腺功能、肝功能及胸部X线；服用华法林者开始每周复查INR，稳定后每2～4周复查。\n3. 建议完成超声心动图及甲状腺功能等病因筛查，并视情况评估导管射频消融治疗（典型房扑消融成功率>95%）。\n4. 若出现心悸加重、脉搏>120次/分或<50次/分、胸闷胸痛、黑矇晕厥等，随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":789,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4f3c35f3b0bc3d214ea4093f9c499ca8401c6fcc30dfa58a40e5ce59baa7f51d","pinyin":"xinfangpudong","initials":"xfpd","setting":"out","caseName":"门诊病历657","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历657",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a15935352cefc0164ad3","key":"v1-c9ccc21dfe2a3058|templates-a15935352cefc0164ad3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"室上性心动过速","category":"门诊病历模板","raw":{"name":"室上性心动过速","category":"门诊病历模板","case":{"case_name":"门诊病历658","templates":{"主诉":"突发突止的心悸3小时，伴头晕、胸闷。","现病史":"患者（多见于无器质性心脏病的年轻人，因旁路或房室结双径路形成折返，为阵发性室上性心动过速，是最常见的心律失常之一；诱因包括情绪激动、劳累、饮酒、咖啡、茶、运动，或无明显诱因自发发作）于突发骤止、呈阵发性、持续数秒至数小时后出现：心悸（突发，自觉心跳极快，150~250次/分，节律规则匀齐，为室上速特征，脉搏快而规则）、突发突止（发作与终止均突然，为阵发性室上速的特征，此点重要）、头晕（血压偏低致脑供血不足）、胸闷、气短、乏力、多尿（发作时心房利钠肽分泌增多致排尿，为特征性表现之一，较少见）、恶心、出汗、黑矇或晕厥（严重快速心率致低血压时少见）、心绞痛（冠心病患者心率增快可致缺血）。分型包括房室结折返性心动过速（最常见，由房室结双径路所致）、房室折返性心动过速（与预激综合征即Wolff-Parkinson-White综合征的旁路有关，心电图可见delta波，特征性改变，详见预激综合征）、心房颤动或心房扑动（心室率快且不规则，房颤时心律绝对不齐，可与室上速的规则心律相区别）、窦性心动过速（节律规则，但起止逐渐而非突发突止，常有发热、贫血、甲亢等诱因）、心房扑动（2:1传导时心室率约150次/分且规则，颈静脉可见扑动波）。记录终止方法（刺激迷走神经，如Valsalva动作、屏气用力、咳嗽、冷水洗脸、含冰，压迫眼球因有视网膜损伤风险禁用；颈动脉窦按摩需由医生操作）及是否有效终止；记录发作频率、持续时间及耐受情况。今日来我院急诊或心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P186次/分（增快，超过150次/分，脉律规则），R20次/分，BP104/66mmHg（发作时可偏低，但多数尚可维持）。发作时（心悸，皮肤潮红或苍白，出汗，心率快而规则；颈静脉可见搏动，房室分离少见）、心音（S1恒定，符合室上速特点）、血流动力学（评估稳定或不稳定，出现低血压或休克属急症，需电复律）、发作间期（查体多正常；预激患者心电图可见delta波）、心脏（注意有无杂音，评估器质性心脏病）、甲状腺（注意甲亢，甲亢所致心动过速需鉴别）。","辅助检查":"【必做】心电图（发作时为核心检查：室上速频率150~250次/分，QRS窄，属室上性，时限小于120ms，为正常传导；心律规则，RR间期匀齐；P波为逆行性，房室结折返时P波常隐藏于QRS波内或紧随其后，不易辨认；可见继发性ST段压低，由频率过快所致，并非缺血）、发作间期心电图（多正常；若为预激，可见delta波、PR间期缩短，支持预激诊断）、动态心电图（可捕捉阵发性发作，记录起止及类型）；【血液】血常规、电解质（低钾可致心律失常）、甲状腺功能（用于甲亢与窦性心动过速或房颤的鉴别，重要）、心肌肌钙蛋白（伴胸痛时排除缺血）；【影像】超声心动图（评估器质性心脏病，如瓣膜及心肌结构性病变，并评估心功能以指导治疗）；【电生理】发作频繁、合并预激或药物治疗无效者，行心电生理检查及射频消融（可根治，能定位折返环并消融，治愈率高，此点重要）；【其他】记录刺激迷走神经终止发作的方法及其有效性。","初步诊断":"1. 阵发性室上性心动过速（分型：房室结折返性心动过速或房室折返性心动过速（与预激相关）或其他类型；记录发作频率；评估血流动力学状态；排除器质性心脏病）\n（注：治疗原则为终止发作加预防复发，依血流动力学状态决定：①急性终止：血流动力学稳定者先刺激迷走神经，为一线措施，如Valsalva动作（屏气用力15秒，仰卧抬腿可提高成功率）、冷水面部浸没（潜水反射）、咳嗽；药物首选腺苷6mg快速静推，随后以生理盐水冲管，无效可予12mg并重复1~2次，终止率高（超过90%），须注意可致短暂心脏停搏、胸痛及喘息（均短暂），应告知患者；预激或哮喘者慎用；腺苷无效可用维拉帕米5mg静脉注射，但预激合并房颤者禁用（可加速旁路传导，有室颤风险，此点重要，预激患者不用钙通道阻滞剂），亦可用β受体阻滞剂如艾司洛尔；血流动力学不稳定者（低血压、休克、心衰、心绞痛）立即行同步电复律（100~200J），属急症处理，此点重要；②预防复发：频繁发作或症状明显者可用药物，如β受体阻滞剂或非二氢吡啶类钙通道阻滞剂（地尔硫卓，作用于房室结折返）、普罗帕酮（阻滞钠通道，适用于预激及房室折返），长期服用；亦可选择导管射频消融，为根治性治疗，应首选，尤其适用于年轻、频繁发作或合并预激者（旁路消融可消除预激所致的猝死风险，房颤经旁路下传虽罕见但可致室颤，此点重要），根治率超过95%，属微创，推荐患者，此点重要；③发作自我管理：教会患者Valsalva动作等迷走神经刺激方法，以便早期终止发作、减少急诊就诊；记录发作频率、持续时间及诱因，便于就诊评估；④随访：消融后复查心电图及动态心电图，评估有无复发（复发率低于5%，可再次消融）；药物治疗者评估疗效及副作用并调整用药；合并预激者定期评估，必要时消融；由心内科及电生理专业随诊，室上速急性期可用腺苷或迷走神经刺激，血流动力学不稳定时电复律，根治首选射频消融，此点重要。","处理方案":"【药物治疗】\n1. 终止急性发作：腺苷注射液6mg经上肢静脉1-2秒内快速推注，随后立即推注生理盐水10ml冲洗，无效者间隔1-2分钟后重复12mg，患者心电监护下进行；或维拉帕米注射液5mg缓慢静注（5-10分钟内），伴低血压、心功能不全者禁用。\n2. 预防发作（口服首选）：普罗帕酮片150mg po tid，维持期可减至100mg tid，用药前行心电图及超声心动图排除器质性心脏病、房室传导阻滞及心功能不全。\n3. 或维拉帕米片40mg po tid，可增至80mg tid，伴心力衰竭、病态窦房结综合征、Ⅱ度以上房室传导阻滞者禁用。\n4. 或琥珀酸美托洛尔缓释片47.5mg po qd，服药期间监测静息心率及血压，静息心率<55次/分或血压偏低时复诊调整剂量。\n\n【一般治疗及生活指导】\n1. 保证充足睡眠，生活规律，避免熬夜、劳累、精神紧张及剧烈运动，保持情绪平稳。\n2. 避免饮用浓茶、咖啡、酒精及含兴奋成分的功能饮料，戒烟，减少辛辣刺激性饮食。\n3. 心悸发作时立即停止活动，取坐位或卧位安静休息，可试行Valsalva动作（深吸气后屏气用力做呼气动作10-15秒）或冷水浸面刺激迷走神经终止发作。\n4. 发作频繁或症状明显影响生活者，建议心内科门诊评估行心内电生理检查及导管射频消融术根治。\n\n【随诊要求】\n1. 服药期间每周复诊监测心率、血压及心电图，若出现心悸加重、黑矇、晕厥、胸痛或呼吸困难，立即急诊就诊。\n2. 发作频繁（≥1次/月）或抗心律失常药物疗效不佳者，转心内科专科门诊评估射频消融适应证。\n3. 长期服药者每3-6个月复查常规心电图及动态心电图，评估心律失常控制情况及药物不良反应。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":790,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b2adef4fd2d3d5830c06d7aa07f087611a033d51dc3a64865a9b0815b7ec3fd8","pinyin":"shishangxingxindongguosu","initials":"ssxxdgs","setting":"out","caseName":"门诊病历658","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历658",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6ab79faede272eccb8e2","key":"v1-c9ccc21dfe2a3058|templates-6ab79faede272eccb8e2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"室性心动过速","category":"门诊病历模板","raw":{"name":"室性心动过速","category":"门诊病历模板","case":{"case_name":"门诊病历659","templates":{"主诉":"心悸伴头晕、黑矇、晕厥、血压降低3小时。","现病史":"患者（器质性心脏病：冠心病或心肌梗死瘢痕，为最常见病因，陈旧性心梗后室速多由瘢痕折返所致，此点重要；心肌病，包括扩张型、肥厚型及致心律失常性右室心肌病（ARVC），后者多见于年轻运动员，可致室速及猝死，此点重要；心力衰竭、瓣膜病；离子通道病，如长QT综合征可致尖端扭转型室速（多形性），诱因包括低钾及延长QT间期的药物（抗心律失常药、抗生素、抗组胺药等），此点重要；Brugada综合征；电解质紊乱，如低钾、低镁可致尖端扭转型室速，此点重要；药物因素，如洋地黄中毒可致室速，儿茶酚胺及运动亦可诱发；特发性室速，即无器质性心脏病者，如右室流出道室速，多与运动相关，预后良好）。诱因包括运动（ARVC及儿茶酚胺相关）、情绪激动、缺血及电解质紊乱。患者于突发或运动后出现：心悸（心率快，QRS宽，150~200次/分，可规则或不规则）、头晕、黑矇、晕厥（血流动力学障碍，室速时心排血量下降致脑缺血，出现晕厥须重视；器质性心脏病患者发生室速伴晕厥提示猝死高风险，属急症）、低血压或休克（不稳定性室速属急症，须电复律）、胸闷胸痛（提示缺血）、呼吸困难（提示心衰）、濒死感、心室颤动（可由室速进展而来，即室速转为室颤，可致猝死，最为严重）、无脉（无脉室速应按心搏骤停处理，立即心肺复苏并除颤）。记录持续时间及血流动力学状态：稳定者血压可维持，发作短暂，可用药物终止；不稳定者出现低血压、休克、晕厥或肺水肿，须立即电复律，此点重要且时间紧迫。今日来我院急诊或心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P172次/分（增快，脉律可规则或不规则，血压低时脉细弱），R22次/分，BP86/54mmHg（血压降低，提示血流动力学不稳定）。神志（清楚、晕厥或意识丧失）、皮肤（苍白、湿冷，提示低灌注）、心率（快，150~200次/分）、心音（S1强弱变化，因房室分离致S1强弱不等，为室速特征，可与S1恒定的室上速相鉴别）、颈静脉（可见间歇性大炮波，由房室分离所致，为室速特征）、肺部（可闻及湿啰音，提示心衰）、四肢（评估灌注）、心电图（监护可见宽QRS心律，确认室速后立即处理）、血流动力学（持续监测血压）。","辅助检查":"【必做】心电图及心电监护（核心检查：室速表现为宽QRS波，时限超过120ms，患者室上速伴差异性传导鉴别，鉴别依据为Brugada标准及有无房室分离，房室分离支持室速；频率150~200次/分，节律规则或不规则，尖端扭转型室速为多形性，QRS波围绕基线扭转；同时评估血流动力学状态）；【血液】电解质（低钾、低镁须纠正，为尖端扭转型室速的处理关键）、心肌肌钙蛋白（评估缺血及心肌梗死）、血气分析（评估低氧及酸中毒）、药物浓度（如洋地黄，评估中毒）、甲状腺功能；【影像】超声心动图（评估器质性心脏病，如心肌梗死瘢痕、心肌病及心功能，为评估室速基础病的核心，并观察节段性室壁运动异常）；【评估】动态心电图或植入式循环记录仪（捕捉发作，明确频率及类型）、冠状动脉造影（评估缺血）、心脏MRI（评估心肌纤维化即瘢痕等室速基质，以及致心律失常性右室心肌病的右室脂肪浸润，有助诊断）、心电生理检查（可诱发室速、定位并消融，兼具治疗作用）、基因检测（适用于年轻患者及有家族史者，筛查离子通道病或心肌病）、QT间期测定（评估长QT综合征及尖端扭转型室速）。","初步诊断":"1. 室性心动过速（分型：单形性或多形性（尖端扭转型）；病因分型：器质性（冠心病瘢痕、心肌病）、离子通道病或特发性；血流动力学状态（稳定或不稳定）；评估基础心脏病）\n（注：治疗原则为不稳定者立即电复律，稳定者予药物或消融，核心是预防猝死：①血流动力学不稳定者（低血压、休克、晕厥、肺水肿、心绞痛）行同步电复律（100~200J），须立即实施，属急症，此点重要；无脉室速按心搏骤停处理，行心肺复苏及除颤，详见心室颤动；②稳定的室速：药物治疗首选胺碘酮150mg静脉注射（10分钟内推注，继以静脉滴注，为广谱抗心律失常药，适用于器质性室速，须注意低血压及QT间期延长）、利多卡因（适用于缺血性室速及急性心肌梗死，为备选）、镁剂（硫酸镁2g，用于尖端扭转型室速，尤其合并低镁者，为关键处理，同时补钾）；尖端扭转型室速须停用延长QT间期的药物，补钾补镁，并提高心率（用异丙肾上腺素或起搏），以缩短QT间期并终止发作；③病因及基质处理：缺血者行血运重建（冠状动脉造影及经皮冠状动脉介入，适用于缺血性室速）、纠正电解质紊乱（低钾、低镁）、停用致心律失常药物（延长QT间期者）、治疗心衰；④长期预防猝死（核心）：植入式心律转复除颤器（ICD）的指征包括器质性心脏病患者室速或室颤复苏后（二级预防），以及射血分数低于35%的心衰患者（一级预防，防猝死，此点重要，有SCD-HeFT及MADIT等研究证据支持），致心律失常性右室心肌病及长QT综合征等高危患者亦为ICD指征；导管射频消融适用于瘢痕相关室速（心肌梗死后室速消融可减少发作，作为ICD的补充以减少放电）及特发性室速（如流出道室速，消融可根治，无需ICD，因属良性）；药物（胺碘酮及β受体阻滞剂）作为辅助，用于减少发作；⑤随访：管理基础病（心衰及冠心病）、ICD程控并评估放电情况、消融后监测有无复发、记录心律失常发作并评估，再发时及时急诊；由心内科及电生理专业处理，不稳定者电复律，尖端扭转型室速补镁补钾，器质性心脏病者植入ICD防猝死，并可行消融治疗，此点重要。","处理方案":"【药物治疗】\n1. β受体阻滞剂：琥珀酸美托洛尔缓释片47.5mg qd，或酒石酸美托洛尔片12.5～25mg bid，根据静息心率（目标55～60次/分）及血压调整剂量，长期口服维持，用于缺血性心脏病、心肌病等结构性心脏病所致室速的二级预防。\n2. Ⅲ类抗心律失常药：盐酸胺碘酮片，负荷量200mg tid×7天，继以200mg bid×7天，再减为200mg qd长期维持；用药期间监测QT间期、甲状腺功能、肝功能及胸片（肺纤维化筛查），不可与延长QT间期的药物联用。\n3. 钠通道阻滞剂：盐酸美西律片150～200mg tid，口服，用于室性早搏诱发或特发性室速的抑制，肾功能不全者减量；与胺碘酮联用时美西律减量。\n4. 病因及诱因处理：合并电解质紊乱者口服/静脉补充钾镁（如门冬氨酸钾镁片1～2片 tid）；伴心功能不全者联合沙库巴曲缬沙坦或血管紧张素转换酶抑制剂（如培哚普利片4mg qd）及他汀类药物（如阿托伐他汀钙片20mg qn）改善心脏重构。\n\n【一般治疗及生活指导】\n1. 急性发作伴心悸、黑矇或血流动力学不稳定者立即就地平卧，呼叫急救转运至急诊；症状缓解期避免剧烈活动及重体力劳动，注意休息。\n2. 戒除烟酒，避免咖啡、浓茶及功能性饮料等兴奋性饮品；避免熬夜、过度劳累及情绪激动等诱发因素。\n3. 低盐低脂、清淡易消化饮食，避免暴饮暴食；保持大便通畅，避免用力排便诱发心动过速。\n4. 严格遵医嘱服药，不得自行停药、减量或更改药物；随身携带病历及急救卡（注明诊断、所用药物及紧急联系人）。\n\n【随诊要求】\n1. 2周内复诊，评估心悸、晕厥等症状及药物耐受情况；此后每1～3个月门诊复查心电图及24小时动态心电图，评估室速发作负荷及QT间期。\n2. 每3～6个月复查心脏彩色多普勒超声，评估心功能及心脏结构变化；合并冠心病、心肌病者同时复查心衰相关指标。\n3. 服用胺碘酮者每3～6个月复查甲状腺功能、肝功能及胸片；服用美西律者注意监测心电图及血药浓度相关不良反应。\n4. 有晕厥、猝死家族史或心功能降低（LVEF≤35%）者，尽早心内科专科评估，明确有无射频消融或植入式心律转复除颤器（ICD）指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":791,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"df45a4fdcfa5ce4513cf99911bc5482894c339ab3603e26ea0f89f79346a110f","pinyin":"shixingxindongguosu","initials":"sxxdgs","setting":"out","caseName":"门诊病历659","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历659",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1e01f3a9b5f775f07d05","key":"v1-c9ccc21dfe2a3058|templates-1e01f3a9b5f775f07d05","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心室颤动","category":"门诊病历模板","raw":{"name":"心室颤动","category":"门诊病历模板","case":{"case_name":"门诊病历660","templates":{"主诉":"突发意识丧失伴抽搐1小时。","现病史":"患者于冠心病、急性心肌梗死（最常见病因，心梗后室颤可致猝死，此点重要）、心肌病、长QT综合征或遗传性心律失常（多见于年轻人，常由运动或情绪诱发，可致晕厥及猝死；Brugada综合征及长QT综合征者家族史为重点）、电解质紊乱（低钾、低镁，此点重要）、药物中毒（抗心律失常药、洋地黄）、电击伤、心肌炎、严重缺氧或酸中毒等诱因下，或无明确诱因（特发性）突发：意识丧失（突然发生，呼之不应，倒地）、抽搐（心搏骤停致脑缺氧，数秒至数十秒后出现全身抽搐，即阿斯综合征，患者癫痫鉴别，后者非心搏停止所致，心电图可确诊室颤，此点重要）、呼吸停止（或呈叹气样、濒死呼吸）、大动脉搏动消失（颈动脉摸不到，为确诊关键）、发绀（迅速出现，见于皮肤黏膜）、瞳孔散大（晚期出现，提示脑缺氧超过4~6分钟可致不可逆脑损伤，故有黄金4分钟之说，此点重要）。心搏骤停时室颤为最常见心律（超过80%的院外猝死由心律失常所致，属可除颤心律，心肺复苏联合电除颤是存活关键，时间至关重要，每延迟1分钟除颤存活率下降7~10%，此点重要）。记录目击情况（是否被目击，旁观者是否立即开始心肺复苏，此点重要，并应立即呼救120）、除颤仪是否可用（公共场所的自动体外除颤器AED）；既往史（心脏病史，如冠心病或心衰，属猝死高危，需评估植入式心律转复除颤器即ICD行二级预防；晕厥史，尤其是劳力性或情绪性晕厥，需考虑遗传性心律失常；家族猝死史，尤其50岁以下猝死，为重点，应行家属筛查）。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.0℃（可测不出），P0次/分（颈动脉及股动脉搏动均不可触及），R0次/分（呼吸停止，或呈濒死叹息样），BP0/0mmHg（测不出）。神志（意识丧失，呼之不应）、瞳孔（散大，对光反射消失；早期可存在，其变化可反映脑缺氧时间）、呼吸（停止或呈叹气样）、心音（听不到）、发绀、抽搐（注意观察）、心电图监护（可见室颤波形，为关键依据，应立即连接监护仪）。复苏过程中持续评估意识状态、瞳孔及自主循环是否恢复，记录心肺复苏开始时间、除颤次数及用药情况。复苏成功后注意监测体温、尿量、血糖及血气，警惕再灌注心律失常及多器官功能障碍。","辅助检查":"【必做】心电监护及心电图（核心检查：室颤表现为无规律的颤动波，无QRS波，据此确认并立即行电除颤，为除颤指征，须即刻监护；除颤后观察是否转复为窦性心律或其他心律并评估；复苏后行12导联心电图以查找病因，如心肌梗死可见ST段抬高，须急诊行经皮冠状动脉介入；并注意长QT综合征或Brugada综合征等遗传性心律失常的心电图改变）；【血液】血气分析（复苏过程中评估酸中毒）、电解质（低钾、低镁为诱因，须纠正，此点重要）、心肌肌钙蛋白（评估心肌梗死）、血糖、乳酸；【影像】超声心动图（复苏后评估心功能及病因，如心肌病；床旁超声在复苏中可判断心脏是否停搏，即无收缩，并评估有无室颤）、胸片（复苏后确认气管插管位置并评估肺水肿）；【其他】复苏后行脑功能评估（瞳孔及格拉斯哥昏迷评分）、监测核心体温（复苏后行亚低温即目标温度管理，可改善神经预后，此点重要，目标32~36℃并维持24小时）；病因评估包括冠状动脉造影（疑心肌梗死时急诊进行）、基因检测（遗传性心律失常者及其家族评估）。血气分析须动态复查以评估复苏效果，注意维持氧合与二氧化碳分压正常范围；电解质应重点监测血钾及血镁，低钾、低镁为室颤常见诱因，须及时纠正。抢救过程中应持续心电监护、每2分钟评估心律及脉搏，记录除颤次数与能量、肾上腺素及胺碘酮用量、自主循环恢复时间，以便后续评估脑功能及预后。","初步诊断":"1. 心室颤动（心搏骤停；分型：院外或院内，目击或非目击，并记录旁观者是否行心肺复苏及除颤时间；病因：急性心肌梗死或遗传性心律失常待查）\n（注：心室颤动为心搏骤停，须立即行心肺复苏，分秒必争，黄金4分钟内的除颤是存活关键：①立即呼救并开始心肺复苏：发现后立即呼救（拨打120并取AED），随即行胸外按压，强调高质量按压，频率100~120次/分，深度5~6cm，保证充分回弹并尽量减少中断；配合人工呼吸，按压与通气比为30:2，儿童或窒息所致者优先开放气道；持续复苏，在AED到达前不得停止；②电除颤（关键措施）：室颤属可除颤心律，须尽早除颤，使用AED或除颤仪，双相波200J或单向波360J，除颤1次后立即继续心肺复苏2分钟，再评估心律，必要时重复除颤；每延迟除颤1分钟，存活率下降7~10%，时间为核心，此点重要；③高级生命支持：由医护人员建立高级气道（气管插管）及静脉通路，给予肾上腺素1mg，每3~5分钟1次，可在除颤前给药；胺碘酮300mg静脉注射，用于室颤或无脉室速在除颤无效后给药，必要时可再追加150mg；纠正诱因，如低钾者补钾、低镁者予硫酸镁（尖端扭转型室速者2g）及纠正酸碱失衡；④复苏后处理：自主循环恢复后行综合管理，包括目标温度管理（亚低温32~36℃维持24小时，有神经保护作用，此点重要，随后缓慢复温）、机械通气（管理氧合及二氧化碳）、血流动力学支持（用血管活性药维持灌注，设定目标平均动脉压）、早期冠状动脉造影及经皮冠状动脉介入（疑急性心肌梗死者复苏后急诊进行，此点重要，可改善预后）、病因治疗（纠正电解质紊乱、处理药物因素及遗传性心律失常）、脑保护（避免高热、低氧、低血压及低血糖，并监测神经功能）；⑤二级预防：植入ICD，指征为室颤复苏存活者（除可逆病因外，可行一级或二级预防，此点重要，以防再发猝死）；遗传性心律失常经基因确诊者行ICD或药物治疗（长QT综合征用β受体阻滞剂）；心肌梗死者行血运重建并给予抗血小板、他汀及β受体阻滞剂等药物以防再梗死；⑥家属筛查：遗传性心律失常（长QT综合征、Brugada综合征、肥厚型心肌病）及有家族猝死史者，其家属应行心电图及基因筛查，以防猝死，此点重要；由急诊、心内科及ICU处理，核心为心肺复苏加除颤、把握黄金时间、复苏后综合管理，并以ICD行二级预防，重视生存链（早期呼救、早期心肺复苏、早期除颤、早期复苏后治疗），此点重要。","处理方案":"【药物治疗】\n1. 抗心律失常药（复律成功后长期二级预防首选）：盐酸胺碘酮片0.2g po tid×1周，继以0.2g po bid×1周，之后0.2g po qd长期维持；用药前及用药期间每3个月复查心电图（QTc）、甲状腺功能、肝功能及胸部影像（警惕肺间质纤维化）。\n2. β受体阻滞剂：琥珀酸美托洛尔缓释片47.5mg po qd（或富马酸比索洛尔片5mg po qd），按静息心率、血压调整剂量，目标静息心率55～60次/分。\n3. 电解质及基础病药物：门冬氨酸钾镁片（潘南金）2片 po tid，维持血钾4.0～5.0mmol/L、血清镁≥0.82mmol/L；合并缺血性心脏病者加用阿司匹林肠溶片0.1g po qd＋阿托伐他汀钙片20mg po qn。\n4. 急性发作抢救用药（非门诊常规，一旦发生立即执行）：肾上腺素注射液1mg iv推注，每3～5分钟重复1次；室颤反复或难转复时予盐酸胺碘酮注射液300mg iv推注，必要时追加150mg，继以1mg/min维持6小时；同步实施电除颤（双相波120～200J，无效递增），电除颤为根本救治措施。\n\n【一般治疗及生活指导】\n1. 心室颤动属恶性室性心律失常，发作即致心脏骤停，须立即呼救并实施高质量心肺复苏及电除颤，随即转入急诊/CCU监护治疗，门诊不予单独留观。\n2. 休息与活动：保证充足睡眠，避免熬夜、过度劳累及剧烈运动；复苏后3～6个月内禁止驾驶机动车，避免竞技体育、桑拿、热水浴等交感神经兴奋性活动。\n3. 饮食：低盐低脂饮食，戒烟限酒，避免浓茶、咖啡等刺激性饮品；合并心衰者限制每日液体入量＜1500ml、钠盐＜2g。\n4. 家庭急救准备：建议家中配备自动体外除颤器（AED），家属接受心肺复苏培训；遵嘱规律服药，禁止自行停药、减量或更换药物；出现心悸、黑矇、晕厥先兆立即就近就医。\n\n【随诊要求】\n出院（或急救处置后）1、3、6个月心内科门诊复诊，此后每6个月1次；每次复查心电图、24小时动态心电图、超声心动图、血钾镁及肝肾功能，服用胺碘酮者加查甲状腺功能与QTc。植入埋藏式心律转复除颤器（ICD）者，术后1个月、3个月及此后每6个月行程控随访。期间出现心悸、晕厥、黑矇、胸痛等症状随时就诊，勿等待预约；有长QT综合征、Brugada综合征等家族史者，建议直系亲属行心电图及基因筛查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":792,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4bf7f3adb81d73aca4dbd42b6e283a3f8b25f14d4ad40973b690c98a746f6cb3","pinyin":"xinshichandong","initials":"xscd","setting":"out","caseName":"门诊病历660","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历660",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-85ddbe9c43d6ea4c1544","key":"v1-c9ccc21dfe2a3058|templates-85ddbe9c43d6ea4c1544","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"房室传导阻滞","category":"门诊病历模板","raw":{"name":"房室传导阻滞","category":"门诊病历模板","case":{"case_name":"门诊病历661","templates":{"主诉":"乏力、头晕、黑矇伴晕厥1天。","现病史":"患者（病因：特发性传导系统退行性变，多见于老年人，为最常见病因，与纤维化有关，即Lenegre病及Lev病；冠心病，因心肌缺血或心肌梗死致病，下壁心梗多累及房室结，阻滞常为暂时性；心肌病；药物，如β受体阻滞剂、钙通道阻滞剂、地高辛及胺碘酮可抑制房室传导，此点重要，停药后多可逆；电解质紊乱，如高钾；甲状腺功能减退；感染，如心肌炎（莱姆病可致房室传导阻滞，多见于年轻人，经蜱传播，此点重要，病变可逆，抗生素治疗有效）、风湿热、心内膜炎（可致瓣周脓肿）；先天性因素，如先天性完全性房室传导阻滞，与母体狼疮（抗SSA抗体）有关，可致胎儿房室传导阻滞；心脏手术或消融损伤）于起病后出现：Ⅰ度房室传导阻滞（PR间期延长超过0.20秒，多无症状，常于体检时发现，属良性，可观察）、Ⅱ度房室传导阻滞（莫氏Ⅰ型即文氏型，PR间期逐渐延长直至QRS波脱落，阻滞部位多在房室结，属良性，可观察；莫氏Ⅱ型，PR间期恒定而QRS波突然脱落，阻滞部位多在希氏束下，易进展为高度阻滞，可致晕厥，须起搏器治疗，此点重要；2:1传导或高度阻滞，QRS波成比例脱落，心室率慢）、Ⅲ度房室传导阻滞（完全性，心房与心室完全分离，各自按自身节律搏动，心室率取决于逸搏心律，交界区逸搏40~60次/分，室性逸搏20~40次/分，心率缓慢，可致晕厥）。症状包括乏力（心室率慢致心排血量下降）、头晕、黑矇、晕厥（高度或完全性阻滞时心室率极慢或心脏停搏，可致阿斯综合征，出现晕厥甚至抽搐，此点重要，并有猝死风险）、心悸（因心律脱落而自觉不适）、气短（活动后因慢心率、低心排血量出现心衰表现）、心绞痛（冠心病患者因心率慢可加重）。鉴别包括迷走性因素（运动员或睡眠时出现Ⅰ度阻滞多属生理性，预后良好）、药物性因素（停药后恢复）、可逆性因素（心肌梗死、电解质紊乱、莱姆病等，处理原发病后可恢复）、持续性退行性变（需植入永久起搏器，应评估起搏指征）。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.4℃，P48次/分（缓慢，Ⅲ度阻滞时常低于40~60次/分；Ⅰ度阻滞时心率可正常），R18次/分，BP112/68mmHg（可偏低，与心率慢有关）。心率（慢而规则，Ⅲ度阻滞时为固定频率的逸搏心律）、心律（可不齐，Ⅱ度阻滞时有脱落）、S1（强弱不等，Ⅲ度阻滞时因房室分离，心房与心室同时收缩时S1增强，即大炮音，为特征性表现）、颈静脉（可见大炮波，由房室分离所致，为Ⅲ度阻滞的特征）、心衰体征（注意肺部啰音，慢心率低心排血量可致心衰）、血压及灌注（晕厥发作后注意神志）、基础病体征（注意心脏瓣膜病变及心肌梗死体征）、甲状腺、全身情况。","辅助检查":"【必做】心电图（核心检查：PR间期，Ⅰ度阻滞时超过0.20秒；Ⅱ度阻滞时莫氏Ⅰ型PR间期逐渐延长直至脱落，莫氏Ⅱ型PR间期恒定而脱落；Ⅲ度阻滞时P波与QRS波完全无关，心房率正常而心室率慢，可见逸搏心律；QRS波宽窄可提示逸搏起源，交界性逸搏QRS窄，40~60次/分，室性逸搏QRS宽，低于40次/分，后者预后较差）、动态心电图（可捕捉发作性阻滞及晕厥，评估价值关键，阵发性高度阻滞可用Holter或植入式循环记录仪）、运动心电图（观察运动前后阻滞变化，以助评估）；【血液】电解质（高钾需校正，并复查心电图）、心肌肌钙蛋白（提示心肌梗死）、甲状腺功能、药物浓度（如地高辛）、莱姆抗体（年轻人、有蜱接触史或疫区居住者疑诊莱姆病时应检测，病变可逆，此点重要）；【影像】超声心动图（评估基础心脏病，如心肌梗死、心肌病及瓣膜病，并评估心功能）；【电生理】希氏束电图可明确阻滞部位（房室结或希氏束下），影响预后及起搏决策，适用于难治或疑难病例；无创检查如阿托品试验及运动试验可用于鉴别迷走性因素，Ⅰ度或文氏型阻滞若为迷走性，阿托品可改善，可评估房室结功能。","初步诊断":"1. 房室传导阻滞（分度：Ⅰ度、Ⅱ度（莫氏Ⅰ型即文氏型、莫氏Ⅱ型、2:1）或Ⅲ度（完全性）；阻滞部位：房室结或希氏束下；病因：退行性变、药物、缺血、莱姆病等；症状为晕厥、阿斯综合征；评估起搏器指征）\n（注：治疗依据阻滞程度、部位、症状及可逆性决定：①可逆病因处理：药物所致者停用β受体阻滞剂、钙通道阻滞剂、地高辛及胺碘酮，多可恢复；纠正电解质紊乱（如高钾）；心肌梗死所致者，下壁心梗多累及房室结致缺血性阻滞，常为暂时性，可观察约2周；莱姆病者予抗生素（头孢曲松或多西环素），房室传导多可恢复，此点重要，年轻患者及疫区居住者勿漏诊；甲减者予甲状腺素替代；②临时起搏：指征为高度或Ⅲ度阻滞伴血流动力学不稳定、晕厥或心衰，以及可逆病因需等待恢复者，可行经静脉或经皮临时起搏，属急症生命支持措施，此点重要；③永久起搏器：植入指征包括Ⅲ度房室传导阻滞（有症状者为明确指征，此点重要；无症状但伴宽QRS逸搏、停搏超过3秒或心室率低于40次/分者亦为指征，以防猝死）、Ⅱ度莫氏Ⅱ型（有症状或有高度阻滞进展风险，应起搏）、莫氏Ⅰ型（多属良性，无症状者可观察，但症状明显或阻滞进展至房室结以下者须评估）、运动相关阻滞（Ⅲ度者应起搏）、因病情必须使用某种药物而不能停用者（如心衰必须使用β受体阻滞剂但引起症状性阻滞，可先起搏后再用药，以保用药安全）；起搏器类型包括双腔起搏器（DDD，保持房室同步，更符合生理，为多数患者的选择）、单腔起搏器（适用于心房颤动合并房室传导阻滞者，VVI）及无导线起搏器（新型，如Micra）；④随访：起搏器程控（评估起搏阈值及感知，每3~6个月复查并可行远程监测，起搏依赖者评估电池寿命）、注意起搏器综合征（VVI起搏因房室不同步可致乏力及低血压，必要时升级为双腔起搏）、注意感染（囊袋感染）；无症状的Ⅰ度或文氏型阻滞可观察随访（每年复查心电图，监测是否进展，并注意避免使用加重房室传导阻滞的药物）；未起搏而有晕厥者应评估复发并行动态监测；由心内科处理，症状性高度阻滞应植入永久起搏器，可逆病因须积极处理，以防阿斯综合征及猝死，此点重要。","处理方案":"【药物治疗】\n1. 阿托品：适用于症状性房室传导阻滞（头晕、黑矇、乏力、晕厥），阿托品注射液0.5～1mg皮下或静脉注射，必要时可间隔5分钟重复1次（总量不超过3mg，需在医疗机构内患者）；症状轻微者予阿托品片0.3mg tid口服，根据心率调整。\n2. 异丙肾上腺素：阿托品无效或有禁忌（青光眼、前列腺肥大、快速性心律失常倾向）时，异丙肾上腺素1～4μg/min静脉滴注，将心室率维持在50～60次/分，需心电监护下患者。\n3. 沙丁胺醇片：症状轻微、心室率轻度减慢者，沙丁胺醇2.4mg tid口服，可提高心室率、改善症状。\n4. 病因处理：停用或减量致传导阻滞的药物（β受体阻滞剂、地高辛、维拉帕米、地尔硫䓬、胺碘酮等）；急性心肌炎、急性心肌梗死所致者予抗炎、抗缺血及营养心肌治疗，并监测血钾、血镁等电解质。\n\n【一般治疗及生活指导】\n1. 休息：有头晕、乏力、胸闷、黑矇等症状者应卧床休息或减少活动，避免劳累、熬夜，保证充足睡眠；症状明显者建议住院或心电监护观察。\n2. 活动：无症状或症状轻微者可日常活动，但避免剧烈运动、竞技性体育运动和重体力劳动；有晕厥发作史者严禁驾车、高空作业、操作危险机械及游泳等，以防晕厥致意外伤害。\n3. 饮食：均衡饮食，低盐低脂，戒烟限酒，避免浓茶、咖啡等刺激性饮品；多食富含膳食纤维食物，保持大便通畅，避免用力排便诱发症状。\n4. 禁忌：慎用或避免使用减慢心率及加重传导阻滞的药物（β受体阻滞剂、非二氢吡啶类钙拮抗剂、地高辛、胺碘酮等），确需使用者患者医生指导下评估；避免一次性大量饮酒。\n\n【随诊要求】\n1. 门诊复诊：症状稳定者每1～3个月复诊1次，每次复查心电图；症状反复或心率波动明显者缩短复诊间隔。\n2. 动态心电图：疑为一过性、间歇性传导阻滞或症状与心电图不符者，建议行24小时动态心电图（Holter）检查以明确阻滞程度与频率。\n3. 起搏器随访：已植入永久起搏器者，术后1、3、6个月各程控随访1次，此后每6～12个月常规程控，电池耗竭前适时复查。\n4. 急诊指征：再次出现晕厥、抽搐、黑矇频繁发作、胸闷胸痛、呼吸困难或心率显著减慢（<40次/分）者，应立即急诊就诊，勿延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":793,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3d7a808168651e60d1dfeeb02ec4e110dc5617e12fd5857f035f658a441fe375","pinyin":"fangshichuandaozuzhi","initials":"fscdzz","setting":"out","caseName":"门诊病历661","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历661",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f273487c9c096884a1d0","key":"v1-c9ccc21dfe2a3058|templates-f273487c9c096884a1d0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"束支传导阻滞","category":"门诊病历模板","raw":{"name":"束支传导阻滞","category":"门诊病历模板","case":{"case_name":"门诊病历662","templates":{"主诉":"心悸1天","现病史":"患者1周前无明显诱因出现束支传导阻滞相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者1周前无明显诱因出现束支传导阻滞相关症状并进行性加重，今日以心悸1天就诊，需明确传导阻滞类型、程度及其病因；完善心电图检查明确系左束支还是右束支传导阻滞、有无分支阻滞及房室传导异常；完善血常规、尿常规、便常规检查排除贫血、感染及消化道隐匿性出血所致心肌缺血；完善肝肾功能检查排除肝肾功能不全；完善电解质检查排除电解质紊乱所致传导异常，并筛查有无高钾血症等病因；完善血糖、血脂检查了解有无糖尿病、血脂异常等动脉粥样硬化危险因素；完善胸部X线片检查了解心脏大小、形态及肺循环情况，排除肺部疾患及心脏扩大；完善腹部超声检查排除肾脏病变等继发因素；患者心悸症状逐渐加重，完善动态心电图检查了解有无间歇性传导阻滞进展及发作性心律失常；完善心脏超声检查（含左心功能测定）了解心脏结构、室壁运动及射血分数，评估有无器质性心脏病基础；根据病情需要选择相应检查，必要时完善冠脉CTA、心肌酶谱、肌钙蛋白及甲状腺功能检查，以排除心肌炎、心肌缺血及甲状腺功能异常所致传导阻滞。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 束支传导阻滞\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 无症状、无基础心脏病的单纯束支传导阻滞：无需特殊抗心律失常药物治疗，定期随访观察即可；避免自行使用影响心脏传导的药物。\n2. 合并冠心病者：阿司匹林肠溶片100mg qd 长期口服；阿托伐他汀钙片20mg qn 长期口服（目标LDL-C＜1.8mmol/L）。\n3. 合并慢性心力衰竭（射血分数降低型）者：沙库巴曲缬沙坦钠片50mg bid 起始，每2-4周滴定至目标剂量；琥珀酸美托洛尔缓释片23.75mg qd 起始，每2周滴定一次至耐受剂量（静息心率维持≥55次/分）。\n4. 合并症状性室性心律失常者：盐酸美西律片150mg tid，根据疗效与耐受性调整剂量（日剂量≤900mg）；或盐酸胺碘酮片0.2g tid×1周，继以0.2g bid×1周，此后0.2g qd 维持。用药期间监测心电图QT间期、肝肾功能及甲状腺功能。\n\n【一般治疗及生活指导】\n1. 规律作息，避免熬夜、过度劳累及情绪激动，保证充足睡眠，戒烟限酒。\n2. 适度活动：可进行散步、太极拳、慢走等低中强度有氧运动，避免剧烈运动及竞技性运动；运动中出现头晕、黑矇、心悸时应立即停止并休息。\n3. 低盐低脂饮食，控制体重；合并高血压、糖尿病者严格监测并控制血压、血糖。\n4. 就诊时主动告知医生心电图存在束支传导阻滞，避免使用延长QT间期或抑制房室传导的药物（如奎尼丁、普罗帕酮、三环类抗抑郁药等）。\n\n【随诊要求】\n1. 无症状者每6-12个月复查心电图1次，动态观察传导阻滞有无进展（如进展为双束支或三束支阻滞、PR间期延长）。\n2. 出现黑矇、晕厥、头晕、心悸、活动后气促等症状，或复查提示传导阻滞进展者，应立即就诊，完善动态心电图、心脏超声及必要时电生理检查，评估永久起搏器植入指征。\n3. 合并基础心脏病（冠心病、心衰、心肌病等）者遵医嘱定期复诊原发病，每3-6个月复查心电图及心脏超声。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":794,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3313011d22f13635f6fbcf6483a084cd63e56c3b8a4d946efde58a5cf11bcc33","pinyin":"shuzhichuandaozuzhi","initials":"szcdzz","setting":"out","caseName":"门诊病历662","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历662",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-701482132c0b67e51371","key":"v1-c9ccc21dfe2a3058|templates-701482132c0b67e51371","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"病态窦房结综合征","category":"门诊病历模板","raw":{"name":"病态窦房结综合征","category":"门诊病历模板","case":{"case_name":"门诊病历663","templates":{"主诉":"反复头晕、黑矇伴心悸3年，加重1周。","现病史":"患者（老年患者多见，窦房结退行性变及纤维化为最常见原因，与年龄相关的特发性改变有关；冠心病致窦房结动脉缺血；心肌病或心肌炎；浸润性病变，如淀粉样变、结节病；药物，如β受体阻滞剂、钙通道阻滞剂、胺碘酮及地高辛可抑制窦房结，此点重要，多为可逆，停药后需评估；甲状腺功能减退；迷走神经张力过高，如运动员可出现生理性窦性心动过缓，须鉴别；心脏手术可损伤窦房结）于起病后渐进出现：窦性心动过缓（显著，心率低于40次/分，为窦性心动过缓最常见的表现）、窦性停搏（停搏时间超过3秒）、窦房传导阻滞、快慢综合征（心动过缓与阵发性心房颤动、心房扑动或室上性心动过速交替出现，即慢快综合征，快速心律终止后出现长间歇甚至停搏，可致晕厥）。症状包括头晕、乏力、疲劳（低心排血量所致）、黑矇或晕厥（停搏超过3秒或显著窦性心动过缓时发生）、心悸（快慢交替，如心房颤动发作时）、心衰或心绞痛加重（慢心率时加重）、活动耐量下降。需评估：药物因素（抗心律失常药及β受体阻滞剂可加重窦性心动过缓，须评估）、阵发性心房颤动（用药需谨慎，快慢综合征者须先植入起搏器后才能使用抗心律失常药物，此点重要）、颈动脉窦（按压可致心率变化，提示窦房结敏感）、迷走神经因素、甲状腺功能（甲减可致窦性心动过缓）、运动反应（窦性心动过缓者运动时心率不能相应升高，提示变时功能不全）、运动员（生理性窦性心动过缓）、晕厥（需评估起搏器指征，此点重要）；晕厥多在心率骤慢或心脏停搏时发生，发作前可有头晕、黑矇等先兆，发作后可自行恢复，患者血管迷走性晕厥、体位性低血压及癫痫相鉴别。患者病程中症状呈渐进性加重，活动耐量逐渐下降，时有夜间心悸及憋醒，为进一步明确窦房结功能并评估起搏治疗指征而就诊。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.3℃，P46次/分（显著缓慢，可低于40次/分，亦可呈快慢交替）、R17次/分，BP118/70mmHg。心率（缓慢，节律可规则或不齐，可见停搏及窦房传导阻滞；发作时呈快慢交替，如心房颤动发作时）、心肺（注意心衰体征）、颈动脉窦（按压时心率可骤降，提示敏感或迷走神经张力高）、甲状腺（注意甲减体征）、神经（晕厥发作后评估神志）、直立位血压。神志清楚，精神尚可，发育正常，营养中等，自主体位，查体合作。皮肤黏膜无黄染及出血点，浅表淋巴结未触及肿大。颈静脉无怒张，气管居中，甲状腺未触及肿大。胸廓对称，双肺呼吸音清，未闻及干湿性啰音。心前区无隆起，心界不大，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛及反跳痛，肝脾肋下未触及，双下肢无水肿。颈动脉窦按压试验患者心电监护下谨慎进行。","辅助检查":"【必做】心电图（可见窦性心动过缓，心率低于50次/分，白天为著；窦性停搏超过3秒，此点重要，与晕厥相关；窦房传导阻滞；快慢综合征，即窦性心动过缓合并心房颤动）、动态心电图（核心检查，可行24~48小时或更长监测，晕厥发作不频繁者可用植入式循环记录仪行长程监测以捕捉发作，此点重要；记录最慢心率、停搏及快慢交替情况）、阿托品试验（静脉注射阿托品后心率仍低于90次/分，支持窦房结功能不全）、运动试验（评估窦房结变时功能，变时功能不全者运动时心率不能相应增快）、心电生理检查（测定窦房结恢复时间，用于评估窦房结功能，属有创检查，适用于起搏前评估或诊断不明者，必要时进行）；【排除】药物（停用β受体阻滞剂、钙拮抗剂及胺碘酮后复查，判断可否逆）、甲状腺功能（排除甲减）、电解质（钾、钙）、心肌肌钙蛋白及缺血评估（评估冠心病）、睡眠呼吸监测（排除阻塞性睡眠呼吸暂停，其可致夜间窦性心动过缓）；【评估】症状（晕厥、黑矇，为起搏器决策的关键）、直立倾斜试验（HUTT，用于鉴别血管迷走性晕厥）。对夜间心率明显减慢者应结合睡眠呼吸监测结果综合判断，排除阻塞性睡眠呼吸暂停所致者；对晕厥反复发作者可行动态心电图延长监测或植入式循环记录仪，以明确症状与心律失常的相关性。","初步诊断":"1. 病态窦房结综合征（窦房结功能障碍；类型：严重窦性心动过缓、窦性停搏、窦房传导阻滞或快慢综合征；症状为头晕、黑矇、晕厥、心悸；存在变时功能不全；已排除药物及可逆病因；评估起搏器指征）\n（注：对有症状者，植入永久起搏器为核心治疗：①起搏器植入：指征为有症状者（晕厥、黑矇或症状性窦性心动过缓，及停搏超过3秒且与症状相关），为永久起搏器的明确指征，此点重要，可防晕厥及摔伤；无症状者（窦性心动过缓或停搏）可观察随访，但停搏超过3秒者即使症状不典型，多数亦倾向于起搏，以防意外晕厥；快慢综合征者应先植入起搏器，之后才能安全使用抗心律失常药物控制心房颤动（快速心律），因未起搏时使用β受体阻滞剂或胺碘酮会抑制窦房结、加重停搏，此点重要，即先起搏再用药；起搏器类型宜选双腔起搏器（DDD），以保持房室同步、更符合生理，因单腔心室起搏可诱发起搏器综合征（房室不同步）；②药物治疗：急性有症状的窦性心动过缓可用阿托品或异丙肾上腺素，作为临时起搏前的过渡，起搏为最终治疗；停用可加重窦性心动过缓的药物（如β受体阻滞剂、钙拮抗剂、地高辛、胺碘酮），并评估其必要性（如心房颤动需控制心室率者，可在起搏后使用）；茶碱对部分患者有兴奋窦房结作用，但效果有限，现已少用；③诱因处理：甲状腺功能减退者予替代治疗；缺血者评估冠状动脉；药物所致者停药；运动员的生理性窦性心动过缓可观察，不需起搏；④随访：起搏器程控（评估起搏比例及功能，每3~6个月复查并可行远程监测）、评估症状（晕厥是否消失）、快慢综合征者观察心房颤动发作并在起搏后患者抗心律失常药物控制发作、监测电极及电池寿命；未起搏者随访观察停搏是否进展，可用Holter监测，一旦出现起搏指征即再评估；由心内科处理，有症状者植入起搏器，快慢综合征者先起搏再用药，以预防晕厥及摔伤，此点重要。本病多见于老年人，病程多呈渐进性，早期可仅表现为轻度窦性心动过缓而被忽视，随病情进展可出现窦性停搏、窦房传导阻滞及快慢综合征。","处理方案":"【药物治疗】\n1. 提高心率（茶碱类）：氨茶碱片0.1g，tid，口服，连用2周为一疗程，复诊评估疗效后调整。\n2. 提高心率（中成药）：心宝丸2粒（或参仙升脉口服液20ml），tid，口服，疗程4周。\n3. 慢快综合征抗凝（新型口服抗凝药）：合并阵发性房颤/房扑且CHA₂DS₂-VASc评分≥2分者，予利伐沙班片15mg，qd，长期口服，定期监测肾功能，注意出血风险。\n4. 改善心肌代谢：辅酶Q10胶囊10mg，tid，口服，疗程1-3个月，缓解乏力、胸闷等伴随症状。\n【一般治疗及生活指导】\n1. 休息：有头晕、黑矇、乏力、心慌等症状期间注意休息，避免熬夜及过度劳累；症状明显者建议卧床休息。\n2. 活动：活动量力而行、循序渐进，避免剧烈运动和长时间憋气动作；出现一过性黑矇、晕厥先兆时立即就地平卧、抬高下肢，并尽快就医。\n3. 饮食：低盐低脂、营养均衡饮食，规律进食、避免暴饮暴食，戒烟限酒，避免浓茶、咖啡等兴奋性饮品。\n4. 禁忌：避免自行服用减慢心率药物（β受体阻滞剂、非二氢吡啶类钙拮抗剂、胺碘酮、地高辛、普罗帕酮等）及影响窦房结功能的中成药；避免用力排便、突然站立等诱发体位性低血压的行为。\n【随诊要求】\n1. 用药2周后复诊，复查心电图及24小时动态心电图，评估心率改善及药物疗效。\n2. 反复晕厥、晕厥先兆或药物治疗无效的症状性心动过缓者，建议心内科住院评估，行永久性心脏起搏器植入治疗。\n3. 合并房颤/房扑并服用抗凝药者，每3-6个月门诊复诊，复查凝血功能、肝肾功能，评估出血及血栓风险；出现黑便、牙龈出血、皮肤瘀斑等出血征象随时就诊。\n4. 无症状或症状稳定者每3-6个月门诊复查心电图及动态心电图，监测窦房结功能变化及病情进展，动态评估起搏器植入指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":795,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ba1539d12d8375c36ca1c702a6ae4c05d9cdeb4a63d9519b0d7914fd5b967b12","pinyin":"bingtaidoufangjiezonghezheng","initials":"btdfjzhz","setting":"out","caseName":"门诊病历663","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历663",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-98bf57ff08e102d4385e","key":"v1-c9ccc21dfe2a3058|templates-98bf57ff08e102d4385e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"窦性心动过速","category":"门诊病历模板","raw":{"name":"窦性心动过速","category":"门诊病历模板","case":{"case_name":"门诊病历664","templates":{"主诉":"阵发性心悸3天。","现病史":"患者于起病后出现心悸：心率增快（超过100次/分，为窦性心律，P波正常，起搏点位于窦房结）。诱因包括生理性因素（运动、情绪激动或紧张、焦虑、饮酒、咖啡、茶或浓茶等含咖啡因饮品、吸烟）、发热（体温每升高1℃，心率约增快10次/分，见于感染）、贫血（代偿性心率增快）、脱水、失血或休克、甲状腺功能亢进（表现为心悸、怕热、多汗、消瘦、手抖，此点重要，须查甲状腺功能）、心力衰竭或低血压、低氧、肺栓塞、药物（如阿托品、沙丁胺醇、甲状腺素、茶碱）、妊娠。需鉴别：持续性窦性心动过速（心悸持续存在）、体位性心动过速综合征（POTS，多见于年轻女性，站立后心率增快超过30次/分，伴头晕）、不适当窦性心动过速（静息时心率快而无明确原因）、阵发性发作（须判断是否突发突止，室上速为突发突止，而窦性心动过速多逐渐起止，此点重要）；心率方面，窦性心动过速多低于160次/分（运动时可更高），室上速为150~250次/分且突发突止，心房颤动则心律绝对不齐。伴随症状包括胸痛、气短、晕厥（提示心衰、缺血或休克，须评估）及焦虑。既往史应注意贫血、出血、脱水、甲亢、心衰及肺病。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.2℃，P112次/分（超过100次/分，心率增快）、R20次/分，BP106/68mmHg（可偏低，见于休克或脱水）。神志清楚，注意有无贫血貌，甲状腺（注意有无肿大及震颤，提示甲亢）、心肺（注意肺部啰音提示心衰，有无心脏杂音）、下肢有无水肿（提示心衰）、皮肤（湿冷提示休克或发热）、有无发热、体位变化（直立后心率变化，用于评估POTS）、脱水征（注意皮肤弹性）。","辅助检查":"【必做】心电图（核心检查：窦性心动过速，P波正常，Ⅰ、Ⅱ、aVF导联直立，符合窦性心律，据此与异位心动过速如房速或室上速相鉴别；心率超过100次/分，须捕捉发作时图形）、动态心电图（用于阵发性发作，记录全天心率，明确最快与最慢心率，窦性心动过速多呈渐起渐止）、记录发作与症状的相关性（心悸）；【病因】血常规（排除贫血）、甲状腺功能（排除甲亢，为必查项目，此点重要）、电解质、血糖、肝肾功能、感染指标（血常规及CRP，适用于发热者）、心电图及超声心动图（评估心衰及心脏结构）、胸片（评估肺部及心衰）；【体位】直立倾斜试验（用于POTS，站立后心率增快超过30次/分，多见于年轻人）、Holter（评估心率变异性）；【其他】心肌肌钙蛋白及BNP（评估心衰及缺血）、血容量评估（脱水）、药物及毒物筛查。对心悸发作频繁者应重复动态心电图检查，明确发作时心律类型，排除阵发性房性心动过速、心房扑动及心房颤动；如心率持续增快且病因不明，可行心电生理检查进一步评估。","初步诊断":"1. 窦性心动过速（心率超过100次/分，窦性心律，P波正常；分型：生理性（运动、情绪、咖啡因）、病理性（发热、贫血、甲亢、心衰、脱水）或药物性；持续性或阵发性，伴心悸相关症状；病因待查）\n（注：治疗以针对病因为核心，窦性心动过速多为继发表现，应处理原发病：①生理性者去除诱因即可，如停饮咖啡、酒，戒烟，注意休息放松，运动后心率可自行恢复，不需治疗；②病因治疗：发热或感染者予抗感染及退热；贫血者予补铁并治疗贫血；甲亢者予抗甲状腺药物（甲巯咪唑），必要时用β受体阻滞剂控制心率及症状；心衰者予利尿及规范抗心衰四联治疗；脱水或失血者补液或输血；肺栓塞者抗凝；焦虑者予心理疏导，必要时抗焦虑治疗；停用致病药物；③对症治疗：症状明显、心悸影响生活者可用β受体阻滞剂（美托洛尔）控制症状，但窦性心动过速仍以病因治疗为主，β受体阻滞剂仅作对症处理，勿掩盖病因，如甲亢者须先抗甲亢，此点重要；④不适当窦性心动过速及体位性心动过速综合征（POTS）：POTS者增加盐及水的摄入以扩充血容量，行运动训练以增强下肢肌肉泵，必要时用β受体阻滞剂或氟氢可的松，并请专科评估；不适当窦性心动过速可用β受体阻滞剂或伊伐布雷定（窦房结If电流抑制剂，可降低心率而不降低血压，属新药，须评估）；⑤随访：随访心率（评估病因治疗后的恢复情况）、评估心悸症状是否缓解、甲亢者随访甲状腺功能、贫血者复查血红蛋白、对复发或持续者再次评估病因，行动态心电图排除异位心动过速，必要时复查Holter；由心内科处理，病因治疗优先，β受体阻滞剂用于对症，注意排除甲亢、贫血、心衰及室上速，此点重要。本病多为继发性表现，临床以查明并处理原发病因为主，对心悸症状明显、影响日常生活者可在病因治疗基础上短期对症处理。","处理方案":"【药物治疗】窦性心动过速以病因处理为核心，β受体阻滞剂为控制心率的首选药物，门诊成人常规方案如下：\n1. β受体阻滞剂（首选）：酒石酸美托洛尔片25mg bid口服，或琥珀酸美托洛尔缓释片47.5mg qd晨服，根据静息心率调整，目标静息心率60～80次/分；若心率<55次/分或血压下降，减量或停药。\n2. 甲状腺功能亢进相关窦速：在抗甲状腺药物治疗基础上，加用普萘洛尔片10mg tid口服，心率控制后逐渐减量。\n3. 合并焦虑、紧张情绪者：可短期联用劳拉西泮片0.5mg bid或地西泮片2.5mg tid，疗程1～2周，症状缓解后停用。\n【一般治疗及生活指导】\n1. 避免饮用浓茶、咖啡及含酒精饮料，戒烟，减少辛辣等刺激性食物摄入。\n2. 规律作息，保证每日7～8小时睡眠，避免熬夜、过度劳累及长时间精神紧张。\n3. 症状控制稳定后可进行散步、慢跑等中等强度有氧运动，每次30分钟、每周3～5次，避免剧烈运动和竞技性体育活动。\n4. 保持情绪平稳，学习深呼吸、冥想等放松训练，必要时进行心理疏导。\n【随诊要求】\n1. 服药后1～2周复诊，评估心悸等症状缓解情况及心率、血压变化，据此调整β受体阻滞剂剂量。\n2. 建议完善24小时动态心电图，明确心率波动规律并排除阵发性室上速、房颤等其他心律失常。\n3. 复查血常规、甲状腺功能、电解质等，针对贫血、甲亢、感染、低血容量等病因进行治疗。\n4. 若出现心悸明显加重、胸闷胸痛、头晕黑矇或晕厥，应立即就诊，不可自行调整药物。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":796,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d75541561d907b1fda1cfef32bbf3b531e35a021c8c202a21516cb243fbe6fa9","pinyin":"douxingxindongguosu","initials":"dxxdgs","setting":"out","caseName":"门诊病历664","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历664",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e9590adf1b45f596b090","key":"v1-c9ccc21dfe2a3058|templates-e9590adf1b45f596b090","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"窦性心动过缓","category":"门诊病历模板","raw":{"name":"窦性心动过缓","category":"门诊病历模板","case":{"case_name":"门诊病历665","templates":{"主诉":"体检发现心率慢1日。","现病史":"患者于体检发现或出现症状后发现心率慢：心率低于60次/分（为窦性心律，P波正常）。生理性因素（运动员或长期锻炼者迷走神经张力高，静息心率可低至40~50次/分，因每搏量增大、心排血量可维持正常，故无症状，属良性，此点重要；睡眠时心率生理性降低；年轻人亦可见）。病理性因素（甲状腺功能减退，表现为怕冷、乏力、便秘、皮肤干燥及黏液性水肿；药物，如β受体阻滞剂、钙通道阻滞剂、胺碘酮及地高辛，为最常见原因且多可逆；窦房结功能障碍，即病态窦房结综合征，多见于老年人，详见相关专项；缺血，如下壁心肌梗死累及窦房结动脉；心肌炎或心肌病；颅内压增高；黄疸；低温；高钾血症）。需注意：症状方面，多数无症状（心率高于45~50次/分者多属良性）、头晕及乏力（低心排血量所致）、黑矇或晕厥（心率显著减慢低于40次/分，或出现停搏，提示病态窦房结综合征，须警示，此点重要）、活动耐量下降、心绞痛或心衰加重（慢心率时）、迷走性因素（呕吐、疼痛或排尿等迷走反射可致阵发性窦性心动过缓）、颈动脉窦敏感、睡眠呼吸暂停（阻塞性睡眠呼吸暂停可致夜间心率下降）、运动反应（运动时心率能否增快，正常者变时功能良好）、甲状腺功能（排除甲减）、用药史及运动员史。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.2℃，P54次/分（低于60次/分，心率缓慢）、R16次/分，BP116/72mmHg。心率（缓慢，节律规则）、心肺（注意心衰体征）、甲状腺（注意甲减体征）、黏液性水肿（甲减体征）、黄疸、体温（低温）、神经（注意晕厥及颅内压增高体征）、直立位血压、运动后心率反应（评估变时功能）、用药情况（评估药物影响）。","辅助检查":"【必做】心电图（窦性心动过缓，P波正常，注意P波与QRS波的关系，据此与房室传导阻滞鉴别；心率低于60次/分）、动态心电图（24小时监测，记录平均心率、最低心率及有无停搏，停搏超过3秒提示病态窦房结综合征，须警示，此点重要；同时评估运动时变时功能及睡眠时最低心率）、阿托品试验（评估窦房结功能，注射后心率仍低于90次/分支持窦房结功能不全）；【病因】甲状腺功能（排除甲减，为必查项目）、电解质（排除高钾）、药物（停用β受体阻滞剂及钙通道阻滞剂后复查，心率恢复者提示药物性）、心肌肌钙蛋白及缺血评估（冠心病致窦房结缺血）、睡眠呼吸监测（打鼾者行多导睡眠图，排除阻塞性睡眠呼吸暂停）、超声心动图（评估心脏功能与结构）、肝肾功能。","初步诊断":"1. 窦性心动过缓（心率低于60次/分，窦性心律；分型：生理性（运动员、睡眠）或病理性（甲减、药物、窦房结功能障碍、缺血）；评估症状（头晕、乏力、黑矇、晕厥）及运动变时功能；评估有无停搏及病态窦房结综合征）\n（注：治疗依据病因及症状决定，生理性者不需治疗：①生理性者（运动员或睡眠时）无症状属良性，因心排血量可代偿，告知患者无需治疗，此点重要，勿过度治疗；②药物性者减量或停用β受体阻滞剂、钙通道阻滞剂、胺碘酮及地高辛，并作评估（如心衰确实需要β受体阻滞剂者，心率高于50次/分可继续使用，低于50次/分且有症状者应减量或停用），药物调整须结合基础病；③病因治疗：甲减者予左甲状腺素替代，心率可恢复；阻塞性睡眠呼吸暂停者予CPAP治疗，夜间窦性心动过缓可改善；缺血者评估冠脉并治疗；高钾者予纠正；④有症状者（头晕、晕厥、活动耐量下降，或属病态窦房结综合征及停搏者）应植入永久起搏器，指征参见病态窦房结综合征（症状性窦性心动过缓或停搏超过3秒）；急性有症状的窦性心动过缓可用阿托品静脉注射或异丙肾上腺素，作为临时起搏前的过渡，适用于急诊；出现晕厥者应评估起搏指征，以防摔伤，此点重要；⑤随访：随访心率及运动时心率反应、复查Holter监测停搏是否进展、评估症状以决定起搏指征、药物调整后复查、随访甲状腺及基础病；由心内科处理，生理性者观察，药物性者减量或停药，症状性或伴停搏者植入起搏器，并治疗甲减及阻塞性睡眠呼吸暂停，此点重要。","处理方案":"【药物治疗】\n1. 无症状或心率≥50次/分者：无需抗心律失常药物治疗，重点是查找并纠正病因，如停用或减量β受体阻滞剂、非二氢吡啶类钙拮抗剂（地尔硫䓬、维拉帕米）、胺碘酮、地高辛等减慢心率的药物，同时排查甲状腺功能减退、电解质紊乱、阻塞性黄疸等基础疾病。\n2. 有症状（头晕、乏力、胸闷）且心率<50次/分者：硫酸阿托品片0.3mg，口服，每日3～4次，据心率调整，短期患者；若效果不佳可加用硫酸沙丁胺醇片2.4mg（或缓释茶碱0.1～0.2g），口服，每日2次。\n3. 中医辨证属心肾阳虚、心阳不振者：心宝丸2～6粒，口服，每日3次，2～4周为一疗程；或参仙升脉口服液10ml，每日3次。\n4. 出现晕厥、黑矇或心率持续<40次/分经药物治疗无效者，属急诊危重情况，应转急诊或心内科住院，予以异丙肾上腺素静滴或临时起搏，并评估永久起搏器植入指征，门诊不常规长期口服异丙肾上腺素。\n\n【一般治疗及生活指导】\n1. 规律作息，保证充足睡眠，避免熬夜、过度劳累及精神紧张；心率<50次/分或症状明显者应适当休息，减少日常活动量。\n2. 合理饮食，均衡营养，避免暴饮暴食；戒烟限酒，避免大量饮用浓茶、咖啡等刺激性饮品。\n3. 无症状且心率≥50次/分者可进行散步、太极拳等中低强度有氧运动，避免剧烈运动、竞技性运动及长时间屏气动作（如负重憋气、潜水）。\n4. 注意监测心率变化，如出现头晕、眼前发黑、乏力加重或晕厥前兆时，立即就地平卧、抬高下肢，避免跌倒受伤，并及时就医。\n\n【随诊要求】\n1. 无症状者建议每6～12个月复查心电图1次，必要时行动态心电图（24小时Holter）检查。\n2. 有症状或服药治疗者2～4周复诊，复查心电图，评估症状与心率改善情况，据此调整药物剂量或疗程。\n3. 曾发生晕厥、黑矇或Holter提示长RR间期（>3秒）者，应1～2周内复诊，完善动态心电图、心脏超声等检查，并转诊心内科评估永久起搏器植入指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":797,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"74e1f6b2c8aa0c87b777907d7db94213e1c71f416239c3bb0c14628fbb0a5bf1","pinyin":"douxingxindongguohuan","initials":"dxxdgh","setting":"out","caseName":"门诊病历665","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历665",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c806585734482ad76da8","key":"v1-c9ccc21dfe2a3058|templates-c806585734482ad76da8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"窦性心律不齐","category":"门诊病历模板","raw":{"name":"窦性心律不齐","category":"门诊病历模板","case":{"case_name":"门诊病历666","templates":{"主诉":"心悸1天","现病史":"患者1周前无明显诱因出现窦性心律不齐相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者1周前无明显诱因出现窦性心律不齐相关症状并进行性加重，今日以心悸1天就诊，入院即刻完善心电图检查明确心律不齐的具体类型、心率及有无传导异常；完善血常规检查排除贫血、感染所致心悸；完善生化全项（肝肾功能）检查排除肝肾功能不全；完善生化全项中电解质检查排除电解质紊乱所致心律失常；完善生化全项中血糖、血脂检查了解代谢状况，评估动脉粥样硬化危险因素；完善心肌酶谱、肌钙蛋白检查排除心肌损伤及心肌炎所致心律异常；完善心脏超声检查（含左心功能测定）了解心脏结构、室壁运动及射血分数，评估有无器质性心脏病；完善胸部X线片检查了解心脏大小及肺部情况，排除肺部疾患所致心悸；完善动态心电图检查了解全天心率变化、有无发作性心律失常及最长 RR 间期；完善 BNP/NT-proBNP 检查明确有无心功能衰竭；必要时完善冠脉CTA检查明确冠状动脉有无狭窄，排除缺血性因素所致心律不齐。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 窦性心律不齐\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 无症状或症状轻微者无需药物治疗，定期随访观察即可。\n2. 自觉心悸、胸闷不适且与情绪紧张、劳累相关者：谷维素片10mg po tid，维生素B1片10mg po tid，均连用2周，以调节自主神经功能。\n3. 若静息心率偏快（>90次/分）伴明显心悸、胸闷：酒石酸美托洛尔片12.5mg po bid，服药期间监测心率及血压，心率<55次/分或血压<90/60mmHg时减量或停药，疗程2~4周。\n\n【一般治疗及生活指导】\n1. 保证充足睡眠，避免熬夜、过度劳累，保持作息规律；儿童及青少年呼吸性窦性心律不齐属常见生理现象，随年龄增长多可自行改善，无需恐慌。\n2. 避免浓茶、咖啡、酒精及功能性饮料等刺激性饮品，戒烟。\n3. 坚持适度有氧运动（如快走、慢跑、游泳），避免剧烈运动及长时间屏气动作；运动中出现头晕、黑矇时应立即停止并休息。\n4. 保持情绪平稳，进行深呼吸放松训练（吸气时心率根据患者具体情况制定个体化方案增快、呼气时减慢属正常生理反应）。\n\n【随诊要求】\n1. 无症状者建议6~12个月复查常规心电图1次。\n2. 若出现心悸加重、胸闷、头晕、黑矇或晕厥，或静息心率持续>100次/分、<50次/分，应及时就诊，完善24小时动态心电图、心脏彩超及甲状腺功能检查，除外病态窦房结综合征、心肌炎、甲亢等病因。\n3. 服用美托洛尔者，用药后2~4周复诊，评估症状缓解情况并复查心电图及心率、血压。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":798,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2b1d1081c7b9448d0bd4592157220a233587903f8f37c6226efef2e0c31acd53","pinyin":"douxingxinlvbuqi","initials":"dxxlbq","setting":"out","caseName":"门诊病历666","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历666",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-01f353f237a17dd84b0c","key":"v1-c9ccc21dfe2a3058|templates-01f353f237a17dd84b0c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"期前收缩","category":"门诊病历模板","raw":{"name":"期前收缩","category":"门诊病历模板","case":{"case_name":"门诊病历667","templates":{"主诉":"阵发性心悸、心脏停搏感2年。","现病史":"患者于起病后出现心悸：早搏即期前收缩，为提前出现的心搏。类型包括室性早搏（室早，QRS波宽大畸形，最常见）、房性早搏（房早，P波提前出现）、交界性早搏。症状包括心悸（自觉心跳停一下或漏跳，因代偿间歇所致）、心搏强而有力（早搏后第一个正常心搏增强）、可无症状（于体检或心电图检查时发现，多数无症状，健康人偶发者常见）、频发者（24小时超过10000次、连发或多源者，需评估室早负荷）、活动可诱发或使早搏消失。需评估良性或器质性：室早分层方面，无器质性心脏病者为良性，预后良好，不增加死亡风险，此点重要，勿过度治疗并避免加重焦虑；器质性心脏病者（心肌梗死后、心肌病、心衰）室早可诱发室速或室颤，猝死风险增加，尤其射血分数降低者，须评估；频发室早（负荷超过10%~20%）可致心肌病，即室早诱导性心肌病，经治疗后可逆，此点重要；房早频发者可为阵发性房颤的前兆，须评估。诱因包括咖啡因、酒精、茶、睡眠不足、焦虑、压力、运动，电解质紊乱（低钾、低镁），药物（洋地黄中毒），甲亢、贫血、感染。另需注意晕厥（连发室早可致室速，须评估，属严重情况）、家族史（猝死及遗传性心律失常，如早期复极综合征、长QT综合征）、运动试验反应（运动诱发或加重室早提示器质性，须警示；运动后早搏消失多提示良性）。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分（早搏时脉律不齐）、R18次/分，BP120/74mmHg。脉搏（可闻及间歇，早搏时漏搏）、心率及节律（听诊可发现早搏，注意心音提前或增强）、心肺（注意有无杂音提示瓣膜病变或心衰）、甲状腺（注意甲亢）、有无贫血貌、有无水肿（提示心衰）、运动或活动后心率变化、直立位血压。","辅助检查":"【必做】心电图（核心检查，明确早搏类型：室早为宽大QRS波且无P波，房早为P波提前出现；室早形态分单源或多源；连发者即成对或成串，为非持续性室速）、动态心电图（24~48小时监测，评估早搏负荷即数量与百分比、频率分布、有无连发或多形，以及与运动、睡眠的关系，为评估负荷及室早诱发心肌病风险的核心）、活动平板试验（观察运动诱发或抑制室早，运动诱发者须警惕器质性心脏病，此点重要）；【器质性评估】超声心动图（评估结构与功能，尤其射血分数，低于40%者室早致猝死风险显著升高，需评估ICD指征，此点重要；并注意心肌病、瓣膜病变及缺血性室壁运动异常）、心肌肌钙蛋白（评估缺血）、冠状动脉评估（疑冠心病等高危者）、心脏MRI（疑心肌病或心肌纤维化等复杂室早者）；【电解质】血钾及血镁（降低者须纠正）、甲状腺功能、血常规（评估贫血）、药物浓度（洋地黄）；【遗传】有家族猝死史或年轻晕厥者，注意长QT综合征、Brugada综合征及早期复极综合征，可行心电图评估及基因筛查。","初步诊断":"1. 期前收缩（早搏；分型：室性（室早，单源、多源或连发，并评估负荷）或房性（房早）；伴心悸症状；有无器质性心脏病（射血分数）；评估室早负荷及恶性心律失常（室速）风险；评估诱因）\n（注：治疗依据症状、有无器质性心脏病及负荷决定，良性者以观察为主，勿过度治疗，此点重要：①良性者（无器质性心脏病、负荷低、无症状）可观察，告知患者属良性、预后良好，以消除焦虑，此点重要；去除诱因（咖啡因、酒精、茶、睡眠不足、压力）；定期随访；无症状者不需治疗，因过度使用抗心律失常药物的副作用大于获益，此点重要；②有症状者（影响生活）在去除诱因后可用β受体阻滞剂（一线用药，如美托洛尔，控制心悸症状），亦可用普罗帕酮或美西律（适用于无器质性心脏病且β受体阻滞剂无效者），但须注意器质性心脏病患者禁用Ⅰc类抗心律失常药（普罗帕酮），因可增加死亡率（CAST研究结论，此点重要）；③器质性心脏病或心衰伴室早者应治疗基础病（心肌梗死后用β受体阻滞剂以防猝死；心衰者予规范心衰药物治疗），射血分数降低伴室早者应评估ICD指征（射血分数低于35%的心衰患者可行一级预防，参见心衰及ICD相关内容）；频发室早致心肌病者可行射频消融（负荷超过10%~20%且室早诱导心肌病者，经消融或药物控制后射血分数可恢复，此点重要，须评估，即室早负荷高、射血分数降低且无其他病因者可考虑消融）；④症状性频发室早或连发者应评估射频消融（可定位起源，如右室流出道室速为常见且良性；消融成功率高，适用于症状性或负荷高者），亦可用药物（β受体阻滞剂或胺碘酮，适用于器质性心脏病者）；⑤随访：Holter评估治疗后的早搏负荷是否减少、随访射血分数（频发室早者监测有无心肌病，治疗后可见恢复）、评估心悸症状控制情况、室速或晕厥发作时及时急诊评估（尤其器质性心脏病患者）、控制诱因；由心内科处理，做好风险分层，良性者观察或用β受体阻滞剂，器质性心脏病或高负荷者治疗基础病并考虑消融，勿过度治疗，此点重要。","处理方案":"【药物治疗】\n1.β受体阻滞剂（首选，适用于症状性房性/室性期前收缩，尤其心率偏快者）：酒石酸美托洛尔片 12.5~25mg bid 口服，疗程1~3个月，据心率调整剂量，静息心率不低于55次/分；或琥珀酸美托洛尔缓释片 47.5mg qd 口服。\n2.无器质性心脏病、症状明显的室性期前收缩：盐酸普罗帕酮片 150mg tid 口服，疗程2~4周，症状缓解后可减至150mg bid 维持，用药期间复查心电图，禁用于病态窦房结综合征及明显心功能不全者。\n3.器质性心脏病（心肌梗死、心力衰竭等）合并室性期前收缩：胺碘酮片 200mg tid×1周→200mg bid×1周→200mg qd 维持，长期服用需监测QT间期、血钾、甲状腺功能及肝功能。\n4.症状性房性期前收缩：可选用非二氢吡啶类钙通道阻滞剂，如盐酸维拉帕米片 40mg tid 或盐酸地尔硫卓片 30mg tid 口服，疗程2~4周；禁用于二度以上房室传导阻滞及严重心动过缓者。\n\n【一般治疗及生活指导】\n1.休息与睡眠：保证充足睡眠，避免熬夜及过度劳累；心悸症状明显者适当卧床休息，减少诱发因素。\n2.饮食：低盐低脂清淡饮食，戒烟戒酒，避免浓茶、咖啡及含咖啡因的功能性饮料。\n3.活动：病情稳定期可进行散步、慢跑等中等强度有氧运动，每次30分钟左右，避免剧烈运动及竞技性活动；运动中如出现心悸、头晕、黑矇应立即停止并休息。\n4.情绪与禁忌：保持情绪稳定，避免精神紧张、焦虑；慎用含麻黄碱等拟交感成分的感冒药及减肥药；注意防治感染、腹泻所致电解质紊乱，避免自行突然停药或改量。\n\n【随诊要求】\n1.用药后2~4周复诊，复查心电图，评估期前收缩频次及症状改善情况，据此调整药物剂量。\n2.治疗1~3个月复查24小时动态心电图（Holter），动态评估期前收缩负荷及有无短阵室速、成对期前收缩等恶性心律失常。\n3.长期服药者每1~3个月复查心电图及血电解质（血钾），服用胺碘酮者每3~6个月复查甲状腺功能、肝功能及胸片；原发器质性心脏病者定期心内科门诊随访，评估心功能及药物耐受性。\n4.如出现心悸加重伴头晕、黑矇、晕厥、胸痛或持续性心动过速，应立即急诊就诊，警惕恶性心律失常。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":799,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2c9929e878118efa86e48f40c18b569f82feaa64225e565d400661a3305a8bd3","pinyin":"qiqianshousuo","initials":"qqss","setting":"out","caseName":"门诊病历667","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历667",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ea25c20861afee24bf17","key":"v1-c9ccc21dfe2a3058|templates-ea25c20861afee24bf17","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"预激综合征","category":"门诊病历模板","raw":{"name":"预激综合征","category":"门诊病历模板","case":{"case_name":"门诊病历668","templates":{"主诉":"阵发性心悸2年，体检发现心电图异常1周。","现病史":"患者（预激综合征即WPW综合征，为Wolff-Parkinson-White综合征，心电图上PR间期缩短小于0.12秒并可见delta波，即QRS波起始部粗钝，伴宽QRS波；因存在旁路即Kent束，冲动经旁路提前激动心室，形成心室预激；旁路为房室间的异常通道；可无症状，仅于体检或心电图检查时发现，预激心电图在人群中约占0.1%~0.3%；症状性者表现为室上速，即房室折返性心动过速（AVRT），由旁路与房室结构成折返环，多突发突止，表现为心悸；亦可合并心房颤动，预激合并房颤时冲动经旁路传导，心室率极快，可超过300次/分，因旁路不应期短，有诱发室颤及猝死的风险，虽罕见但须重视，并可致晕厥或黑矇）。家族中可有预激患者（预激可为家族性）；注意有无心脏结构异常（如Ebstein畸形，即三尖瓣下移畸形，可伴右束支预激；心肌病）。需记录诱因、发作频率、心率及症状，既往有无室上速发作及急诊终止方法（腺苷或刺激迷走神经）、有无射频消融史；运动员体检时发现者亦不少见。高危因素包括心电图呈间歇性预激（delta波时有时无）、多旁路、症状性房颤伴旁路不应期短及年轻患者。患者于体检或发作时发现上述表现。今日来我院心内科或电生理门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP118/72mmHg。心率及节律（发作时可见室上速或心房颤动）、心肺（注意有无杂音，评估Ebstein畸形或其他结构性心脏病体征）、血压（发作时可降低）、发绀、神志、一般情况（静息心电图可见预激图形）。","辅助检查":"【必做】心电图（核心检查：静息时PR间期小于0.12秒伴delta波，QRS波起始部粗钝，QRS波增宽，并可见继发性ST-T改变，符合预激；注意Ⅱ型预激或间歇性预激）、间歇性预激（delta波间歇出现）、动态心电图（可捕捉发作，明确为室上速或心房颤动；预激合并房颤时心室率快，QRS波宽窄多变，因冲动经旁路下传）、旁路定位（依心电图delta波向量初步判断旁路部位，如左侧、右侧或间隔部）、运动试验（预激图形消失提示旁路不应期长，属低危）、心内电生理检查（用于确诊及评估，可定位旁路、测定不应期、诱发心动过速或房颤并测定最高心室率，以行风险分层，旁路不应期短者室颤风险升高，同时可行消融治疗）；【结构】超声心动图（排除Ebstein畸形即三尖瓣下移畸形及其他结构性心脏病）、家族心电图筛查。","初步诊断":"1. 预激综合征（WPW；旁路（Kent束）；心电图表现（PR间期缩短伴delta波）；间歇性或持续性；症状（无症状、室上速或心房颤动）；旁路不应期及猝死风险评估；评估射频消融指征）\n（注：治疗依据症状及风险决定，无症状者需评估，必要时消融以预防：①无症状预激：应行风险分层，可行心电生理检查评估，高危者（旁路不应期短于250ms，或可诱发心房颤动且心室率极快）及有症状性心动过速者，推荐预防性射频消融；无症状但属高危者（年轻、运动员或从事高风险职业如飞行员、驾驶员）亦应考虑消融；电生理检查评估为低危者（不应期长、呈间歇性预激）可观察随访，并告知一旦出现心悸或晕厥应及时就诊评估；②有症状者：室上速发作时先终止发作，可刺激迷走神经（Valsalva动作）或用腺苷静脉注射（通过阻滞房室结终止折返，适用于房室折返性心动过速）；但预激合并心房颤动时禁用腺苷、维拉帕米及地高辛，因其阻滞房室结可加快旁路传导、使心室率升高，增加室颤风险，此点重要，预激合并房颤只能使用普鲁卡因胺、伊布利特或胺碘酮，血流动力学不稳定者行电复律；射频消融可根治，旁路消融成功率超过95%，应首选，适用于症状性预激，可根治并免于长期服药；亦可手术治疗，但旁路消融的并发症包括房室传导阻滞（间隔旁路邻近房室结时）及心包或血管损伤（少见）；③预防：消融前可用药物预防，如普罗帕酮（适用于无器质性心脏病者，可阻滞旁路）、β受体阻滞剂或钙通道阻滞剂（作用于房室结，预防折返），但合并房颤者禁用钙通道阻滞剂及地高辛（可加速旁路传导）；胺碘酮适用于器质性心脏病者；④随访：消融后评估是否成功（delta波消失即治愈），注意有无复发（旁路再通，较少见，复查心电图及Holter）；无症状观察者定期随访，出现症状即评估；高危职业者应告知限制（如驾驶或飞行，直至消融成功或确认低危）；有家族史者建议筛查；由心内科及电生理专业处理，症状性者首选消融，无症状高危者评估后可行消融预防，预激合并房颤禁用维拉帕米及地高辛，此点重要。","处理方案":"【药物治疗】\n1. 预防房室折返性心动过速（阵发性室上速）复发：盐酸普罗帕酮片（心律平）150mg tid，餐后口服，疗程4周；发作控制良好者可减至100mg tid长期维持，服药期间定期复查心电图，若QRS时限增宽≥25%或出现明显窦性心动过缓，应减量或停药。\n2. 窦性心律下预防发作（不合并心房颤动者）：酒石酸美托洛尔缓释片（倍他乐克）47.5mg qd，晨起口服，维持静息心率≥55次/分，疗程4-8周后门诊评估疗效，必要时调整剂量。\n3. 注意：预激综合征合并心房颤动/心房扑动或表现为宽QRS心动过速时，禁用维拉帕米、地高辛、β受体阻滞剂及腺苷（可缩短旁路不应期、加速心室率，有诱发心室颤动风险）；此类患者应住院行电复律或静脉患者伊布利特/普鲁卡因胺/胺碘酮，并尽早行射频消融根治。\n\n【一般治疗及生活指导】\n1. 避免诱因：熬夜、情绪激动、精神紧张、过度劳累、饮酒及浓茶、咖啡等兴奋性饮品。\n2. 避免剧烈运动及竞技性体育活动（如长跑、篮球、游泳比赛等），日常活动以不诱发心悸为度。\n3. 发作时立即停止活动，取坐位或半卧位，尝试Valsalva动作（深吸气后屏气用力呼气15-20秒）或冷水面部刺激，可终止部分发作；持续不缓解或伴头晕、黑矇、晕厥、胸痛者立即急诊就诊。\n4. 规律作息，清淡饮食，戒烟限酒，保持情绪平稳及大便通畅。\n\n【随诊要求】\n1. 用药后2-4周门诊复诊，复查心电图评估疗效及药物不良反应；长期服药者每3-6个月复查心电图、肝肾功能及电解质。\n2. 心动过速发作≥1次/月，或发作伴晕厥、血流动力学不稳定者，建议尽早行心内电生理检查及射频消融术（根治性治疗，成功率90%以上）。\n3. 出现心悸持续不缓解、胸痛、气促、黑矇或晕厥等，立即急诊就医，切勿自行增减药物。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":800,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b54e3adc8f2054b0372111cdf9aab42d81f101606f1974a5a66ab03fca1507aa","pinyin":"yujizonghezheng","initials":"yjzhz","setting":"out","caseName":"门诊病历668","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历668",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cbe185d31e493ada58aa","key":"v1-c9ccc21dfe2a3058|templates-cbe185d31e493ada58aa","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性心力衰竭","category":"门诊病历模板","raw":{"name":"急性心力衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历669","templates":{"主诉":"突发呼吸困难伴咳粉红色泡沫痰1天。","现病史":"患者（基础心脏病：冠心病或心肌梗死，急性心肌梗死致泵衰竭为急性心衰最常见的病因；高血压，血压急进性升高可致左心衰；瓣膜病，如急性腱索断裂或感染性心内膜炎致急性关闭不全；心肌病，如扩张型心肌病失代偿；心律失常，如快速心房颤动或室速可诱发；有心衰史者可为慢性心衰急性加重，常因依从性差或自行停药诱发）。诱因包括感染（肺炎为最常见诱因，此点重要）、心肌缺血或心肌梗死、心律失常、血压控制不佳、液体及盐摄入过多（依从性差）、贫血、肺栓塞、甲状腺功能亢进、药物（非甾体抗炎药致水钠潴留，或自行停用利尿剂）。患者于突发或数小时至数日内出现：急性呼吸困难（突发，进行性加重，呈静息性；端坐呼吸，平卧时加重、坐起后缓解，故不能平卧；夜间阵发性呼吸困难，夜间憋醒；咳粉红色泡沫痰，为肺泡水肿的特征，提示急性肺水肿；烦躁不安，由低氧所致；大汗，因交感兴奋；皮肤湿冷，提示灌注不足；发绀；心悸；血压可升高（高血压性肺水肿，因交感兴奋）或降低（心源性休克、泵衰竭，最为严重，属急症）；意识模糊（低氧或低灌注致脑功能障碍）；少尿（肾灌注下降）。分型方面，左心衰以肺淤血及肺水肿为主，表现如上；右心衰表现为颈静脉怒张、肝大、下肢水肿及腹水；全心衰常以急性左心为主。心源性休克指血压低于90mmHg并持续低灌注致器官衰竭，属急症，死亡率高，需循环支持。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.0℃，P118次/分（增快），R30次/分（增快，呼吸窘迫），BP156/92mmHg（可升高或降低）、SpO2 88%（降低）。神志（清楚、烦躁或嗜睡，与低氧有关）、体位（端坐位或半坐位，不能平卧）、大汗及皮肤湿冷（提示低灌注）或皮肤温暖（高心排血量者少见）、发绀、颈静脉（怒张，提示右心衰；肺水肿时左房压升高亦可致）、肺部（可闻及湿啰音，双肺大量细湿啰音提示肺水肿，自肺底向上弥漫；可闻及哮鸣音，即心源性哮喘，由支气管痉挛所致，患者支气管哮喘鉴别，两者治疗不同）、心脏（S3奔马律为心衰特征；心动过速；闻及杂音提示新发急性瓣膜病变或乳头肌功能不全）、呼吸（超过30次/分，窘迫）、腹部（肝大伴压痛，提示右心衰）、下肢（水肿，提示慢性基础病变）、灌注（末梢冰冷，提示休克）。","辅助检查":"【必做】心电图（评估缺血、心律失常及心肌梗死等诱因）、心肌肌钙蛋白（排除心肌梗死所致心肌损伤）、BNP或NT-proBNP（核心检查，急性心衰时升高，超过300pg/ml支持心衰诊断，阴性有助于排除，对呼吸困难的鉴别诊断重要）、胸部X线（可见肺淤血或肺水肿，肺门蝶翼影为肺泡水肿的特征；心影增大；可有胸腔积液）、血常规（评估感染及贫血）、电解质（利尿治疗时须监测）、肾功能（评估肾衰及指导利尿治疗）、血气分析（评估低氧）、肝功能、血糖；【影像】超声心动图（核心检查，评估左室射血分数即收缩功能，据此分为射血分数降低的心衰与射血分数保留的心衰；评估节段性室壁运动异常提示缺血、瓣膜病变如急性反流或狭窄、心包情况，明确心功能及病因，属急症床旁检查）；【其他】肺栓塞相关检查（疑诊时查D-二聚体或CTPA）、感染相关检查（血培养及降钙素原）、尿量监测（必要时导尿，评估利尿效果）。","初步诊断":"1. 急性心力衰竭（急性左心衰或急性肺水肿；分型：高血压性、缺血性、瓣膜性等；评估有无心源性休克；左室射血分数（HFrEF/HFpEF）；BNP升高）\n（注：治疗为急症处理，须立即稳定血流动力学并减轻肺水肿，在急诊、CCU或ICU进行：①体位及氧疗：取端坐位或半坐位，双腿下垂以减少静脉回流；吸氧，低氧者予高流量面罩，目标SpO2超过90%，严重者予无创通气；无创正压通气（CPAP或BiPAP）对肺水肿改善显著，可降低插管率，此点重要，意识清楚者首选；无创通气失败、意识障碍或呼吸衰竭者行气管插管；②利尿：静脉注射呋塞米20~40mg，首剂给予负荷量，通过利尿减轻肺水肿，为核心治疗，须监测尿量、电解质及肾功能，避免利尿过度致低灌注，并评估疗效；顽固者袢利尿剂可持续静脉滴注；③血管扩张剂：硝酸甘油静脉滴注，适用于高血压性或缺血性肺水肿，通过扩张静脉减轻前负荷，收缩压超过110mmHg者可用，此点重要，低血压者不用；硝普钠适用于重度高血压性肺水肿，需持续监测，注意氰化物中毒；重组人脑利钠肽（奈西立肽）兼具利尿及扩血管作用，为肺水肿的治疗选择，须注意血压；收缩压低于90mmHg者禁用扩血管药，心源性休克者应改用升压药；④吗啡：2~4mg静脉注射，适用于烦躁或疼痛者，可减轻前负荷，但须注意呼吸抑制，慎用，行无创通气时少用并密切监测；⑤正性肌力药及血管活性药：心源性休克或低血压者用去甲肾上腺素或多巴胺升压以维持灌注，多巴酚丁胺适用于低心排血量及正性肌力支持，收缩压超过90mmHg的心衰泵衰竭者可用，此点重要；主动脉内球囊反搏可用于心源性休克的机械辅助，尤其缺血性者；⑥病因及诱因处理：急性心肌梗死行再灌注治疗（经皮冠状动脉介入）；快速心房颤动予控制心室率或复律（胺碘酮或电复律，血流动力学不稳定者电复律）；高血压者降压；感染者用抗生素；急性瓣膜病变者考虑手术；⑦心衰长期管理：稳定后给予血管紧张素转换酶抑制剂、血管紧张素Ⅱ受体拮抗剂或ARNI，β受体阻滞剂（稳定后起始）、螺内酯、SGLT2抑制剂（达格列净，无论射血分数如何均可获益，为近年标准治疗）、利尿剂（口服维持），并限盐限水，监测体重以防再发，此点重要；⑧随访：评估心功能（超声复查左室射血分数是否恢复）、症状（呼吸困难及NYHA分级）、体重（每日监测，早期发现水潴留以防失代偿）、用药依从性（此点重要）、预防再入院（多学科心衰管理及随访门诊，此点重要）；由急诊、心内科及CCU处理，以利尿、扩血管及无创通气为主，积极处理病因，心源性休克者予循环支持，并做好长期管理，此点重要。","处理方案":"【药物治疗】\n1. 利尿剂（减轻肺淤血与水钠潴留）：呋塞米片20mg po qd～bid，根据每日尿量与体重调整，维持尿量1500ml/d以上；水肿明显者联合螺内酯片20mg po qd，用药期间监测血钾、肌酐。\n2. 血管扩张剂（缓解急性肺淤血症状）：硝酸甘油片0.5mg舌下含服，5分钟未缓解可重复含服，间隔≥5分钟、连续不超过3次，用药期间收缩压不低于90mmHg；血压偏高者可加服单硝酸异山梨酯缓释片20mg po bid。\n3. 神经内分泌拮抗剂（改善远期预后，症状稳定后启用）：沙库巴曲缬沙坦钠片50mg po bid起始，收缩压≥100mmHg者每2～4周递增至100mg po bid，目标剂量200mg bid；配合美托洛尔缓释片23.75mg po qd，静息心率≥55次/分时逐渐加量至47.5～95mg qd。\n4. 合并心房颤动或栓塞高危者：依诺肝素4000IU皮下注射 q12h，疗程3～5天，注意观察牙龈、皮肤及消化道出血倾向。\n\n【一般治疗及生活指导】\n1. 休息体位：急性期绝对卧床休息，取半卧位或坐位、双下肢下垂以减少回心血量、减轻肺淤血；症状缓解后逐渐增加床上活动，避免劳累及情绪激动。\n2. 饮食管理：严格低盐饮食（每日食盐<3g），控制液体入量1500～2000ml/d（或\"量出为入\"），少食多餐，避免饱餐及浓茶、咖啡等刺激性饮品。\n3. 自我监测：每日晨起空腹称体重并记录出入量，3天内体重增加>2kg或尿量明显减少提示心衰加重，应及时复诊调整利尿剂。\n4. 禁忌事项：戒烟限酒，保持大便通畅，避免用力排便（必要时乳果糖口服10ml qd通便），预防呼吸道感染、冬季注意保暖，避免受凉诱发急性发作。\n\n【随诊要求】\n1. 复诊时间：症状缓解后1周内门诊复诊，其后每1～3个月定期随访，复查心电图、超声心动图、BNP/NT-proBNP、血电解质、肾功能及肝功能。\n2. 药物调整：随访时评估NYHA心功能分级及血压心率，逐步将沙库巴曲缬沙坦、美托洛尔、螺内酯滴定至目标剂量；利尿剂按体重与症状个体化调整，定期复查血钾、肌酐，防止低钾及肾损伤。\n3. 预警信号：出现静息性呼吸困难、夜间阵发性憋醒、不能平卧、下肢水肿加重、体重快速增加、血压过低（<90/60mmHg）或晕厥时，立即就近急诊就诊，勿等待预约复诊。\n4. 依从性教育：规律服药，不可自行停药或减量（尤其β受体阻滞剂），遵医嘱进行6分钟步行试验评估运动耐力并循序渐进康复锻炼，建议接种流感疫苗及肺炎疫苗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":801,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4db8fd9622ca6f80169c341115dd7a2ac92dd4c2e172fbc6322cae34e2444b5e","pinyin":"jixingxinlishuaijie","initials":"jxxlsj","setting":"out","caseName":"门诊病历669","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历669",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f152d39aef3da604f2b3","key":"v1-c9ccc21dfe2a3058|templates-f152d39aef3da604f2b3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"左心衰竭","category":"门诊病历模板","raw":{"name":"左心衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历670","templates":{"主诉":"呼吸困难3月，加重伴夜间憋醒1周。","现病史":"患者（病因：缺血性心肌病，如冠心病或心肌梗死，为最常见病因；高血压致左室肥厚；瓣膜病，如主动脉瓣狭窄或关闭不全、二尖瓣反流；心肌病，如扩张型心肌病；心律失常；心肌炎；酒精性心肌病；糖尿病；既往有心肌梗死、经皮冠状动脉介入或搭桥史）。诱因及加重因素包括感染（肺炎为最常见诱因）、心肌缺血、心律失常（如快速心房颤动）、盐及液体摄入过多或依从性差、血压升高、贫血、甲状腺功能亢进、肺栓塞、药物（非甾体抗炎药致水钠潴留）。患者于慢性渐进或急性加重过程中出现左心衰症状：呼吸困难（劳力性呼吸困难，早期表现为活动后气促，并呈进行性加重；夜间阵发性呼吸困难，入睡后憋醒，坐起后缓解，为特征性表现；端坐呼吸，不能平卧，需高枕或坐位；静息时气短）、乏力（心排血量下降）、咳嗽（肺淤血刺激所致，多为干咳或咳泡沫痰；咳粉红色泡沫痰提示急性肺水肿，属急症，其呼吸困难表现详见急性心力衰竭）、活动耐量下降。需评估纽约心脏病协会（NYHA）心功能分级：Ⅰ级活动不受限，Ⅱ级轻度受限，Ⅲ级明显受限、轻微活动即出现症状，Ⅳ级静息时即有症状；并明确射血分数分型：射血分数降低的心衰（射血分数低于40%）、射血分数保留的心衰（射血分数不低于50%，多为舒张功能障碍，常见于老年人、女性及高血压患者）、射血分数轻度降低的心衰（40%~49%）；同时了解利尿剂反应、依从性及夜间阵发性呼吸困难的发生频率。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P102次/分（增快）、R24次/分（增快，呼吸困难）、BP142/86mmHg（可升高提示容量负荷增加，可降低提示泵衰竭）、SpO2 92%。体位（端坐位，不能平卧）、呼吸（急促）、肺部（可闻及湿啰音，早期局限于肺底，加重时波及全肺提示肺水肿；可闻及哮鸣音，即心源性哮喘）、颈静脉（单纯左心衰时可正常，合并右心衰时可怒张）、心脏（心界扩大，S3奔马律为心衰的重要体征，可有杂音提示瓣膜病变，心率增快）、下肢水肿或肝大（合并右心衰或晚期时出现）、皮肤灌注（湿冷提示低心排血量）、体重（液体潴留时可增加）。","辅助检查":"【必做】BNP或NT-proBNP（核心检查，心衰时升高，慢性者超过35pg/ml、急性者超过300~450pg/ml支持心衰诊断，阴性有助于排除，对呼吸困难的鉴别诊断重要；利钠肽亦可用于随访及疗效评估）、超声心动图（核心检查，评估射血分数以明确分型即射血分数降低或保留、左室大小、室壁运动异常提示缺血、瓣膜狭窄或反流、舒张功能（射血分数保留者测E/e′）及心包情况）、胸部X线（可见肺淤血，肺门增大呈蝶翼影提示急性肺水肿，可见Kerley B线提示间质水肿；心影增大；可有胸腔积液）、心电图（评估缺血、心房颤动及左室肥厚）、血常规（评估贫血）、肾功能及电解质（利尿剂治疗时监测）、血糖及糖化血红蛋白、血脂、甲状腺功能（排除甲亢或甲减）、心肌肌钙蛋白（评估缺血及心肌炎）、肝功能（评估肝淤血）；【其他】冠状动脉造影（缺血性病因者评估血运重建）、Holter（评估心房颤动及室性心律失常）、动态血压监测、睡眠呼吸监测（阻塞性睡眠呼吸暂停为心衰常见共病，可加重病情）、铁蛋白及转铁蛋白饱和度（铁缺乏为心衰常见共病，补铁可获益）、6分钟步行试验（评估心功能）。","初步诊断":"1. 左心衰竭（射血分数降低（HFrEF，低于40%）、射血分数轻度降低或射血分数保留（HFpEF，不低于50%）；NYHA分级（Ⅰ~Ⅳ级）；BNP升高；病因（缺血、高血压、瓣膜病、心肌病）；肺淤血程度；评估急性加重诱因）\n（注：治疗以药物四联为核心（适用于射血分数降低的心衰），并处理诱因及并发症：①射血分数降低的心衰：采用新四联药物以改善预后，可显著降低死亡及住院风险，包括血管紧张素受体脑啡肽酶抑制剂（ARNI，沙库巴曲缬沙坦，起始或替代血管紧张素转换酶抑制剂，为一线用药）、β受体阻滞剂（美托洛尔、比索洛尔或卡维地洛，小剂量起始并逐渐加量至靶剂量，目标心率55~60次/分，急性期不用，待稳定后使用）、醛固酮受体拮抗剂（螺内酯或依普利酮，须监测血钾及肌酐）、SGLT2抑制剂（达格列净或恩格列净，无论有无糖尿病均可获益，为心衰四联的近年标准治疗，此点重要）；四联药物须滴定达标，随访中逐渐加量至靶剂量，此点关键；同时使用利尿剂（呋塞米，用于缓解肺淤血及水肿症状，重在容量管理，此点重要）、地高辛（适用于合并心房颤动或症状持续者，宜小剂量并监测）；②射血分数保留的心衰：以利尿剂缓解容量负荷及症状为主，SGLT2抑制剂对射血分数保留的心衰近年已获批，可降低住院风险，此点重要；并积极治疗基础病（控制高血压、处理心房颤动及冠心病、减重、治疗阻塞性睡眠呼吸暂停），本病无特效药物，以症状管理加基础病治疗为主；③诱因及合并症处理：感染者抗感染；心房颤动予控制心室率或复律并抗凝；贫血者纠正贫血；铁缺乏者予静脉补铁；缺血者行血运重建；控制血压；限盐限水（盐低于5g/d，水1.5~2L/d）；每日监测体重（3天内增加2kg为警示信号，须调整利尿剂，此点重要）；改善依从性；睡眠呼吸暂停者予CPAP治疗；④随访：评估症状、NYHA分级及体重（每周或每月）、BNP（评估疗效）、超声心动图（评估射血分数改善情况）、肾功能及电解质（利尿剂及醛固酮拮抗剂须监测）、四联药物滴定至靶剂量（随访关键）、心衰教育（自我监测体重与症状、低盐饮食、依从用药、稳定后行心脏康复，此点重要）、预防再入院、晚期患者行姑息治疗讨论（此点重要）；由心内科或心衰中心随诊，以四联加利尿剂为基础，积极管理诱因并随访滴定，此点重要。","处理方案":"【药物治疗】\n1. 利尿剂（减轻肺淤血及水肿）：呋塞米片20mg qd晨服（水肿明显或气促较重时20~40mg qd~bid，疗程视症状及体重而定），联合螺内酯片20mg qd，用药期间监测体重、出入量及血钾、肾功能。\n2. ACEI/ARB（逆转心室重构）：培哚普利片4mg qd（或缬沙坦胶囊80mg qd），起始小剂量，每2周按血压、肾功能及血钾逐步滴定至目标剂量（培哚普利8~10mg/d），长期维持。\n3. β受体阻滞剂（抑制交感激活、改善预后）：琥珀酸美托洛尔缓释片23.75mg qd起始，每2~4周按心率（静息55~60次/分）及耐受性上调至47.5~95mg qd，长期维持；心率＜50次/分或低血压时减量并复诊。\n4. SGLT2抑制剂（进一步降低心衰住院及心血管死亡风险）：达格列净片10mg qd，长期口服，注意会阴卫生、监测血糖及有无泌尿生殖道感染。\n【一般治疗及生活指导】\n1. 休息与活动：急性加重期或气促明显时卧床休息、取半卧位或高枕位；症状稳定后循序渐进进行低强度有氧运动（如步行、太极拳），以不诱发胸闷气短为度，避免剧烈及屏气用力活动。\n2. 饮食与限盐限水：低盐饮食（每日食盐＜2~3g），避免腌制食品；控制液体摄入（每日总量约1500~2000ml），轻中度心衰一般无需严格限水，但应避免大量饮水。\n3. 体重监测：每日晨起排尿后空腹称体重并记录，3天内体重增加＞2kg或下肢水肿、气促加重提示容量超负荷，应及时就诊调整利尿剂。\n4. 禁忌与防护：严格戒烟限酒，避免受凉感冒及呼吸道感染（可接种流感和肺炎疫苗），避免情绪激动、饱餐及用力排便，避免自行停用或加量药物，尤其是β受体阻滞剂不可骤停。\n【随诊要求】\n用药调整期每1~2周复诊1次，病情稳定后每1~3个月复诊1次；每次复诊监测血压、心率、体重、血电解质、肾功能及NT-proBNP/BNP，定期复查心电图及心脏彩超评估心功能；如出现夜间阵发性呼吸困难、端坐呼吸、静息时气促加重、咳粉红色泡沫痰、下肢水肿加重或体重短期内明显增加，应立即就诊，必要时急诊处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":802,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"760deafde3416182aab46613729b878e6da360731f6905e5c311f43d60c59a73","pinyin":"zuoxinshuaijie","initials":"zxsj","setting":"out","caseName":"门诊病历670","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历670",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-412bf9bb91cec2a6e746","key":"v1-c9ccc21dfe2a3058|templates-412bf9bb91cec2a6e746","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"右心衰竭","category":"门诊病历模板","raw":{"name":"右心衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历671","templates":{"主诉":"双下肢水肿、腹胀纳差伴乏力半年","现病史":"患者因右心衰竭的病因（以左心衰最为常见，左心衰进展可致右心衰乃至全心衰；亦可见于肺源性者，如慢性肺病、肺动脉高压、肺心病（以COPD或间质性肺病多见）；肺动脉高压（原发性或继发性）；瓣膜病变（三尖瓣或肺动脉瓣病变累及右心）；右室心肌病或右室梗死（如下壁心梗）；心包病变（缩窄性心包炎或心包压塞致右心回流受阻）；先天性者（房间隔缺损、艾森曼格综合征）；肺栓塞（急性右心衰）；全身高输出量状态（甲亢、贫血、脚气病））于半年前起病，呈慢性渐进过程，出现以下表现：体循环淤血症状，包括下肢凹陷性水肿（晨轻暮重，为最早且最常见的表现）、腹胀纳差（胃肠淤血所致，可表现为早饱、食欲下降，易被误认为消化系统疾病，此点重要）、肝大胀痛（淤血性肝大）、颈静脉怒张（肝颈静脉回流征阳性）、腹水（晚期出现）、胸腔积液（以右侧多见，由淤血所致）、尿少（肾淤血，可有夜尿增多）、体重增加（液体潴留所致）、乏力及活动耐量下降（低心排所致）；呼吸困难多因左心衰或肺病基础疾病引起。\n既往基础病方面：肺心病者可见咳喘及肺气肿体征；左心衰者以肺淤血症状为主；另有肺动脉高压相关表现。\n诱因方面：急性起病者需考虑肺栓塞（突发气促、低血压）或心包压塞。\n心排血量下降明显者可出现休克表现（严重低灌注）。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P96次/分，R22次/分，BP112/70mmHg。颈静脉怒张（半坐位45°时明显，为核心体征），肝颈静脉回流征阳性；肝大（肋下可及、有压痛，边缘钝）；腹水征（移动性浊音阳性）；双下肢凹陷性水肿（程度达膝以上）；胸腔积液征（呼吸音降低、叩诊浊音，以右侧为著）；心脏听诊：右室抬举样搏动（提示肺动脉高压）、三尖瓣反流杂音（吸气时增强）、肺动脉瓣区第二心音亢进（提示肺动脉高压）、心音遥远（提示心包病变）；肺部可闻及肺心病相关的啰音或哮鸣音及肺气肿体征；可见发绀、杵状指（肺心病所致）、黄疸（淤血性肝损害）。监测体重及腹围（评估液体潴留）。","辅助检查":"【必做】BNP或NT-proBNP（升高，支持心衰及右心衰，但肺心病者可仅轻至中度升高）；超声心动图（核心检查：右室大小及功能、三尖瓣反流程度、估测肺动脉压及右房压、左心射血分数（了解左心衰基础）、心包有无缩窄或积液、瓣膜情况）；心电图（右室肥厚（肺型P波）、右束支阻滞、下壁心梗（提示右室心梗）、房颤）；胸片（肺心病表现：肺过度充气、肺动脉段凸出；胸腔积液；心影改变）；肝功能（淤血性肝损害，转氨酶升高）；肾功能；血常规（有无贫血）；血气分析（肺心病者可见低氧）；D-二聚体（评估肺栓塞）；下肢静脉超声（深静脉血栓，为肺栓塞来源）。\n【其他】CTPA（疑肺栓塞时）；右心导管（确诊肺动脉高压，测量肺动脉压，见肺动脉高压章节；并可行心包缩窄评估）；甲状腺功能；铁及转铁蛋白。","初步诊断":"1. 右心衰竭（体循环淤血：颈静脉怒张、肝大、水肿、腹水；心功能分级为NYHAⅢ级）：继发于左心衰、肺心病（肺动脉高压）、肺栓塞、心包病变或瓣膜病变等；右心大小、功能及肺动脉压经超声评估；并行心排血量及灌注评估。\n（注：治疗以病因治疗为核心，同时利尿减轻淤血、对症支持）\n①利尿（核心措施，用于体循环淤血）：呋塞米20~40mg，用于水肿、腹水及肝淤血者以缓解症状；螺内酯联合患者（肺心病或肝淤血者兼具保钾作用）；目标为体重每日下降0.5~1kg（水肿者）；监测电解质及肾功能（警惕利尿过度致低钾及肾灌注下降）；顽固性腹水者需限盐、加量利尿剂，低蛋白者补充白蛋白；大量腹水者可行穿刺减压。\n②病因治疗：左心衰者按四联方案治疗（见左心衰章节）；肺心病者予氧疗（长期家庭氧疗为肺心病核心治疗）、支气管扩张剂或激素（COPD者）、控制感染；肺动脉高压者予靶向药物（见肺动脉高压章节）；肺栓塞者予抗凝或溶栓；三尖瓣反流严重者考虑手术；心包缩窄者行心包切除、压塞者行穿刺；右室心梗者需扩容（补充前负荷，予生理盐水；右室梗死需保证前负荷，不用硝酸酯类及利尿剂，此点重要）；房间隔缺损者可行修补。\n③低心排或休克（严重右心衰、心排血量下降）：予正性肌力药（多巴酚丁胺）；容量管理需谨慎（右房压已升高者并非低容量状态）；监测器官灌注；极少需机械支持。\n④一般治疗：限盐（每日食盐<5g）、严重水肿者限制液体入量、抬高下肢利于利尿、每日监测体重、低氧者氧疗（SpO2<90%，肺心病者）、避免加重因素（预防肺栓塞，活动、弹力袜、高危者抗凝；避免酒精，防心肌病）。\n⑤随访：每周监测体重、腹围及水肿；监测电解质、肾功能及肝功能（利尿及肝淤血者）；复查BNP及超声（评估右心功能、肺动脉压及治疗反应）；随访基础病因；预防再入院；依据容量状态调整利尿剂（以体重为关键指标）；做好患者教育（自我监测）。心内科或呼吸科共同管理病因治疗、利尿减轻淤血、氧疗（肺心病）及随访，此点重要。","处理方案":"【处置提示】本病属危重/需急诊处理范畴：首诊即应转急诊或收入院，不得在门诊留观拖延；以下方案为住院/急诊条件下的参考，门诊不得据此长期用药。\n\n【药物治疗】\n1. 利尿剂：呋塞米片20mg qd口服，晨起顿服，视水肿及体重变化可加量至20-40mg bid，疗程2-4周后依据淤血消退情况逐渐减量至最小有效剂量维持；服药期间每日晨起空腹测体重，每周监测血钾、血钠及肾功能，防止低钾及容量不足。\n2. 醛固酮受体拮抗剂：螺内酯片20mg qd口服（与呋塞米联用利尿兼保钾、拮抗右室重构），长期维持；用药期间监测血钾及肾功能，血钾＞5.5mmol/L或肌酐明显升高时减量或停药。\n3. 强心及心率控制（合并心房颤动或右心功能明显减退时）：地高辛片0.125mg qd口服，维持5-7天后复查血药浓度，监测心率及消化道症状，防地高辛中毒；若以房颤心室率快为主要表现，可加用美托洛尔缓释片23.75mg qd口服，根据心率（静息目标60-80次/分）调整。\n4. 针对病因治疗：若为肺栓塞所致急性右心衰竭，予利伐沙班片15mg bid×21天后改为20mg qd维持抗凝至少3个月；若合并肺部感染，加用抗感染治疗；如为慢性肺部疾病所致，积极治疗原发病并持续低流量吸氧（1-2L/min，每日≥15小时）。\n\n【一般治疗及生活指导】\n1. 休息与体位：急性期卧床休息，取半卧位或坐位，双下肢抬高以利静脉回流、减轻下肢水肿；病情稳定后循序渐进恢复日常活动，避免剧烈运动、负重及长时间站立或久坐。\n2. 饮食管理：严格低盐饮食（每日食盐＜3g），限制液体入量（每日＜1500-2000ml），少食多餐、易消化饮食，避免过饱增加心脏负荷；戒烟限酒，避免咖啡、浓茶等兴奋性饮品。\n3. 体重监测与诱因规避：每日晨起空腹称体重并记录，3天内体重增加＞2kg提示液体潴留加重需及时调整利尿剂；注意保暖预防呼吸道感染，避免劳累、情绪激动，慎用非甾体抗炎药及可能加重心衰的药物。\n4. 氧疗：有低氧血症者家庭氧疗，保持血氧饱和度≥90%，缓解右室负荷。\n\n【随诊要求】\n1. 每周复诊1次评估水肿、颈静脉怒张、体重及利尿剂反应，直至淤血体征基本消退；稳定期每月复诊1次。\n2. 每2周复查血电解质、肾功能及肝功能，每1-3个月复查BNP或NT-proBNP、心电图、超声心动图评估右心室大小及功能变化。\n3. 出现以下情况需及时就诊：呼吸困难进行性加重、夜间不能平卧、3天内体重增加＞2kg、尿量明显减少、下肢水肿加重或出现胸腹水、晕厥、心悸或消化道出血等，不可自行加量或停药利尿剂及地高辛。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":803,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7e9dc92692bfb5f0ed7e621bea77ceee61b3bbeca8ee855aa0dbd5f5f15f3772","pinyin":"youxinshuaijie","initials":"yxsj","setting":"out","caseName":"门诊病历671","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历671",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9ef093aa0098dc5620af","key":"v1-c9ccc21dfe2a3058|templates-9ef093aa0098dc5620af","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"全心衰竭","category":"门诊病历模板","raw":{"name":"全心衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历672","templates":{"主诉":"气短1天","现病史":"患者1周前无明显诱因出现全心衰竭相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者1周前无明显诱因出现全心衰竭相关症状并进行性加重，今日以气短1天就诊，重点评估心功能状态并明确心衰病因；完善 BNP/NT-proBNP 检查明确心功能衰竭及其严重程度，指导利尿、扩血管治疗；完善心脏超声检查（含左心功能测定）了解心脏是否扩大、室壁运动、射血分数及瓣膜情况，明确心衰类型与病因；完善胸部X线片检查了解心脏增大及肺淤血情况，评估肺部情况与气短的相关性；入院即刻完善心电图检查明确有无心律失常、心肌缺血及心室肥厚改变；完善血常规检查排除贫血、感染等心衰加重诱因；完善生化全项（肝肾功能）检查排除肝肾功能不全，为利尿剂、强心药物安全使用提供依据；完善生化全项中电解质检查排除电解质紊乱所致心律失常及心衰加重；完善生化全项中血糖、血脂检查了解代谢与血脂水平，指导病因治疗；完善心肌酶谱、肌钙蛋白检查排除急性心肌损伤及缺血性心肌病；完善动态心电图检查了解有无阵发性心律失常；必要时完善冠脉CTA检查排除缺血性心肌病所致心功能衰竭。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 全心衰竭\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【处置提示】本病属危重/需急诊处理范畴：首诊即应转急诊或收入院，不得在门诊留观拖延；以下方案为住院/急诊条件下的参考，门诊不得据此长期用药。\n\n【药物治疗】\n1. 利尿剂：呋塞米片20mg qd口服，晨起顿服，据每日尿量、体重及水肿消退情况调整剂量（最大可至40mg qd），利尿期间注意补钾并监测电解质。\n2. RAAS抑制剂：沙库巴曲缬沙坦钠片（诺欣妥）50mg bid口服起始，2~4周后逐渐递增至100mg~200mg bid，未耐受者可用缬沙坦胶囊40mg bid替代；联合螺内酯片20mg qd口服，注意监测血钾及肾功能，血钾>5.5mmol/L或eGFR<30ml/min/1.73m²时减量或停用。\n3. β受体阻滞剂：琥珀酸美托洛尔缓释片23.75mg qd口服起始，每2周加倍，逐步增至47.5~95mg qd，以静息心率55~60次/分为目标，慢性稳定期加用，急性加重期暂缓。\n4. SGLT2抑制剂：达格列净片10mg qd口服，晨服，用于射血分数降低或保留的全心衰竭患者，注意外阴生殖道感染及容量不足风险。\n\n【一般治疗及生活指导】\n1. 休息与体位：急性加重期卧床休息，取半卧位或端坐位以减轻回心血量及肺淤血；症状稳定后适当下床活动，以不诱发气促、胸闷为度，避免剧烈运动及重体力劳动。\n2. 饮食与饮水：严格限盐（每日食盐<5g，避免腌制食品及加工食品）、限水（每日液体入量1500~2000ml），少食多餐，进食易消化、富含维生素食物，避免过饱。\n3. 体重与容量监测：每日晨起排尿后空腹称体重并记录，3天内体重增加>2kg或出现双下肢水肿、夜间阵发性呼吸困难时提示液体潴留，应及时复诊或自行加用利尿剂（遵医嘱）。\n4. 禁忌事项：戒烟、限酒，避免受凉感冒及呼吸道感染（可接种流感及肺炎疫苗），避免情绪激动、用力排便及长时间站立，避免擅自使用非甾体抗炎药（如布洛芬、双氯芬酸）及含麻黄碱类感冒药。\n\n【随诊要求】\n1. 首次用药后2周复诊，复查血电解质（尤其血钾）、肾功能、肝功能、BNP/NT-proBNP及心电图，评估利尿剂及RAS抑制剂耐受性；病情稳定后每2~4周复诊1次，据血压、心率、体重及心衰症状调整药物剂量。\n2. 每3~6个月复查超声心动图、BNP/NT-proBNP、血常规、肝肾功能及电解质，评估心功能分级及心室重构逆转情况。\n3. 如出现呼吸困难加重、端坐呼吸、咳粉红色泡沫痰、心悸、晕厥、少尿或水肿明显加重等，须立即就医，不可等待预约复诊；服用利尿剂期间出现乏力、食欲下降、肌痉挛等低钾表现时应提前就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":804,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"13616d2d6b1399b08537bac9c4665601922cec18cfc9342c3068c37c058204a3","pinyin":"quanxinshuaijie","initials":"qxsj","setting":"out","caseName":"门诊病历672","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历672",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4ecb279e34694092f210","key":"v1-c9ccc21dfe2a3058|templates-4ecb279e34694092f210","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"舒张性心力衰竭","category":"门诊病历模板","raw":{"name":"舒张性心力衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历673","templates":{"主诉":"气短1天","现病史":"患者1周前无明显诱因出现舒张性心力衰竭相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者1周前无明显诱因出现舒张性心力衰竭相关症状并进行性加重，今日以气短1天就诊，重点评估左室舒张功能及射血分数保留的心衰诊断依据；完善 BNP/NT-proBNP 检查明确心功能衰竭；完善心脏超声检查（含左心功能测定）了解左室肥厚、舒张功能、射血分数及瓣膜情况，明确舒张性心衰诊断；完善胸部X线片检查了解心脏大小及肺部情况，排除肺部疾患所致气短；入院即刻完善心电图检查明确有无左室肥厚、心肌缺血及心律失常；完善血常规检查排除贫血、感染所致气短；完善生化全项（肝肾功能）检查排除肝肾功能不全，为利尿及降压药物使用提供依据；完善生化全项中电解质检查排除电解质紊乱所致心律失常；完善生化全项中血糖、血脂检查了解代谢与血脂水平，指导控制危险因素；完善心肌酶谱、肌钙蛋白检查排除急性心肌损伤；完善动态心电图检查了解有无发作性心律失常及心肌缺血；必要时完善冠脉CTA检查排除冠状动脉病变所致心功能异常。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 舒张性心力衰竭\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.利尿剂（减轻肺循环及体循环淤血）：呋塞米片20mg qd晨服，根据体重变化及水肿消退情况调整剂量，症状缓解后改最小有效剂量维持或间歇服用，疗程一般1~2周。\n2.SGLT2抑制剂（HFpEF首选，改善预后）：达格列净片10mg qd口服，长期服用，注意泌尿系感染及容量不足。\n3.血管紧张素Ⅱ受体拮抗剂/血管紧张素受体脑啡肽酶抑制剂（降压、逆转左室肥厚、改善舒张功能）：缬沙坦胶囊80mg qd口服；血压可耐受者换用沙库巴曲缬沙坦钠片50mg bid口服，长期服用，定期监测血压及血肌酐、血钾。\n4.醛固酮受体拮抗剂：螺内酯片20mg qd口服，长期维持，用药后1周及每月复查血钾、肾功能，高钾血症或肾功能不全者慎用。\n【一般治疗及生活指导】\n1.休息与活动：急性加重期或症状明显时卧床或半卧位休息，避免劳累；病情稳定后循序渐进进行有氧运动（步行、太极拳等），每周3~5次、每次20~30分钟，以运动后不出现胸闷气促为宜。\n2.饮食：低盐低脂易消化饮食，每日食盐摄入<5g，控制每日饮水量1500~2000ml，避免饱餐；每日晨起空腹称体重并记录，3天内体重增加>2kg提示体液潴留，应及时就诊。\n3.禁忌与诱因规避：戒烟限酒，保持情绪平稳，避免用力排便、剧烈运动及快速大量输液；注意保暖，预防呼吸道感染，及时治疗高血压、房颤、冠心病等基础疾病。\n4.自我监测：坚持规律服药，家庭自测血压及心率，目标血压<130/80mmHg、静息心率60~80次/分；合并房颤者遵医嘱规范抗凝，预防血栓栓塞。\n【随诊要求】\n1.每2~4周门诊复诊1次，评估气促、水肿、体重、血压及心率变化，据此调整利尿剂及降压药物剂量。\n2.每3~6个月复查心电图、超声心动图、血常规、电解质、肝肾功能及BNP/NT-proBNP；每年至少全面评估1次心脏结构与功能。\n3.若出现静息时呼吸困难加重、夜间阵发性呼吸困难、端坐呼吸、双下肢水肿加重或体重短期内明显增加、血压心率明显异常，应立即就诊或急诊处理，切勿自行调整药物。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":805,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"156a8210f9a5a77770a58d0526e16996d579cc0a16efae73f619c467113668c1","pinyin":"shuzhangxingxinlishuaijie","initials":"szxxlsj","setting":"out","caseName":"门诊病历673","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历673",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bf1f8f1e34faefdeb9dc","key":"v1-c9ccc21dfe2a3058|templates-bf1f8f1e34faefdeb9dc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"收缩性心力衰竭","category":"门诊病历模板","raw":{"name":"收缩性心力衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历674","templates":{"主诉":"气短1天","现病史":"患者1周前无明显诱因出现收缩性心力衰竭相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以气短1天为主诉，1周来症状逐渐加重并伴乏力，自服药物效果欠佳，本次入院需系统评估心功能不全的程度与病因。入院即刻完善血常规检查排除感染、贫血所致气短加重；完善心肌酶谱及肌钙蛋白检查排除急性心肌损伤、急性心肌梗死；完善BNP/NT-proBNP检查明确有无心力衰竭及其严重程度，并作为疗效随访的基线指标；完善生化全项（肝肾功能、电解质、血糖、血脂）检查了解肝肾功能与电解质水平，排除电解质紊乱所致乏力，同时为利尿剂、血管紧张素受体脑啡肽酶抑制剂等药物的安全使用提供依据；完善心电图检查了解心律、心率及有无心肌缺血、心肌梗死图形，入院即刻完成；完善心脏超声检查了解心脏各腔室内径、室壁运动、左室射血分数及瓣膜情况，明确心衰的收缩功能受损程度与病因分型；完善胸部X线片检查了解心影大小及有无肺淤血、胸腔积液；患者气短伴乏力、需评估有无阵发性心律失常及心动过速相关心肌病，完善动态心电图检查了解24小时心律变化；患者否认高血压、糖尿病、冠心病等慢性病史，需鉴别缺血性心肌病所致心功能下降，必要时完善冠脉CTA检查明确冠状动脉有无狭窄，为病因诊断与治疗方案选择提供依据。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 收缩性心力衰竭\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 血管紧张素受体脑啡肽酶抑制剂（ARNI）：沙库巴曲缬沙坦钠片 50mg po bid，根据血压、血钾及肾功能每2-4周滴定至目标剂量（200mg bid）；不耐受者可选缬沙坦胶囊 80mg qd起始，长期维持。\n2. β受体阻滞剂：琥珀酸美托洛尔缓释片 23.75mg po qd起始，每2周滴定一次，逐步增至目标剂量95-190mg qd（静息心率55-60次/分）；或富马酸比索洛尔片 1.25mg po qd起始，目标剂量10mg qd。\n3. 钠-葡萄糖共转运蛋白2抑制剂（SGLT2i）：达格列净片 10mg po qd，或恩格列净片 10mg po qd，晨服，长期服用（eGFR<20ml/min/1.73m²慎用）。\n4. 利尿剂及醛固酮受体拮抗剂：呋塞米片 20mg po qd（晨服，据体重及水肿情况调整，必要时qod或加量），水肿消退后以最小有效量维持；螺内酯片 20mg po qd，与呋塞米合用可增效保钾（需定期复查血钾及肾功能，肌酐升高或高钾血症者慎用）。\n\n【一般治疗及生活指导】\n1. 休息与活动：症状加重期或急性期卧床休息、取半卧位减轻肺淤血，避免劳累；病情稳定后循序渐进进行低强度有氧运动（如散步、太极拳），以不引起胸闷气促为度，避免剧烈及等长运动。\n2. 饮食管理：低盐饮食，每日食盐摄入<5g，少食多餐避免过饱；限制液体摄入，每日总量1500-2000ml，重度心衰者<1500ml，监测体重变化。\n3. 自我监测与禁忌：每日晨起排空后称体重，3日内体重增加超过2kg提示液体潴留，应及时复诊或调整利尿剂；戒烟限酒，预防呼吸道感染（建议接种流感疫苗和肺炎球菌疫苗），避免情绪激动，禁用非甾体抗炎药及Ⅰ类抗心律失常药等加重心衰的药物。\n\n【随诊要求】\n用药后2周复诊，评估症状、血压、心率、血钾、肾功能及药物耐受性并调整剂量；此后每1-3个月门诊随访1次，复查BNP/NT-proBNP、心电图、心脏超声、电解质及肝肾功能，评估心功能分级及达标情况；若出现静息时呼吸困难加重、夜间阵发性呼吸困难、端坐呼吸、双下肢水肿明显加重、体重短期内快速增加、心悸或晕厥，应随时急诊就诊，不可等待常规复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":806,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a2e128405350171d56eaa0b39eb7081e4c1aba215b068161a820ce48409b986d","pinyin":"shousuoxingxinlishuaijie","initials":"ssxxlsj","setting":"out","caseName":"门诊病历674","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历674",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3bc2be81ac6d8137f585","key":"v1-c9ccc21dfe2a3058|templates-3bc2be81ac6d8137f585","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高输出量性心力衰竭","category":"门诊病历模板","raw":{"name":"高输出量性心力衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历675","templates":{"主诉":"气短1天","现病史":"患者1周前无明显诱因出现高输出量性心力衰竭相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以气短1天为主诉，1周来症状逐渐加重伴乏力，自服药物效果欠佳，高输出量性心力衰竭多继发于贫血、甲状腺功能亢进、动静脉瘘、维生素B1缺乏等高动力循环状态，故检查需兼顾心功能评估与原发病筛查。入院即刻完善血常规检查排除贫血所致高动力循环及心衰加重；完善心肌酶谱及肌钙蛋白检查排除急性心肌损伤、急性心肌梗死；完善BNP/NT-proBNP检查明确有无心力衰竭及其严重程度，并作为疗效观察基线；完善生化全项（肝肾功能、电解质、血糖、血脂）检查了解肝肾功能与电解质水平，排除电解质紊乱所致乏力，并指导利尿剂等药物安全使用；完善心电图检查了解心律、心率及有无心肌缺血改变；完善心脏超声检查了解心腔大小、室壁运动、左室射血分数及瓣膜情况，明确心输出量增高的血流动力学依据；完善胸部X线片检查了解心影大小、肺淤血及有无胸腔积液；患者乏力明显、需评估有无阵发性心律失常与心率增快，完善动态心电图检查了解24小时心律变化；必要时完善冠脉CTA检查明确冠状动脉有无狭窄，排除缺血性因素参与心功能下降。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 高输出量性心力衰竭\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 呋塞米片20mg qd，晨起口服，据尿量及体重调整（可渐增至40mg qd），减轻容量负荷、缓解肺淤血及下肢水肿，疗程至淤血体征消退后以最小有效量维持。\n2. 美托洛尔缓释片（倍他乐克）23.75mg qd起始，血流动力学稳定后根据静息心率、血压每2周调整剂量，目标静息心率60～70次/分，抑制交感过度激活、降低高排血量状态及心肌耗氧；慢速滴定，避免骤停。\n3. 病因治疗（本病的核心）：甲状腺功能亢进致心衰者予甲巯咪唑片10mg tid起始，定期监测血常规、肝功能及甲状腺功能；贫血致心衰者予琥珀酸亚铁片0.1g tid餐后服（必要时加用促红细胞生成素）；维生素B1缺乏（脚气病）致心衰者予维生素B1片100mg tid，连用至心功能改善后维持。\n4. 经利尿剂及病因治疗仍容量控制不佳、合并左室收缩功能障碍者，加用血管紧张素转换酶抑制剂如培哚普利片4mg qd，监测血压、血钾及肾功能。\n【一般治疗及生活指导】\n1. 休息与活动：急性期卧床休息，取半卧位减轻呼吸困难，保持情绪稳定、避免过度劳累；病情稳定后循序渐进恢复日常活动量，避免剧烈运动和长时间负重诱发心衰加重。\n2. 饮食：低盐饮食，每日食盐摄入<5g，避免咸菜、腌制品等高钠食物；同时保证充足热量、优质蛋白及多种维生素摄入，纠正贫血和营养不良等原发病。\n3. 体重与症状监测：每日晨起排尿后测体重并记录，若3天内体重增加>2kg，或出现双下肢水肿加重、夜间阵发性呼吸困难、端坐呼吸，提示容量超负荷，及时就诊调整利尿剂。\n4. 禁忌：戒烟限酒，避免自行服用含钠制剂、糖皮质激素及非甾体抗炎药；妊娠期、甲亢未控制者严格避孕并规范专科治疗原发病。\n【随诊要求】\n1. 每1～2周复诊1次：评估呼吸困难、水肿等症状及NYHA心功能分级，监测血压、心率、体重、24小时出入量，复查电解质、肾功能，据此调整利尿剂及β受体阻滞剂剂量。\n2. 每1～3个月复查心脏超声（LVEF、心排血量）、BNP/NT-proBNP，评估疗效与心功能演变；同时按原发病（甲亢、贫血、维生素B1缺乏等）要求定期复查甲状腺功能、血常规等相关指标，并转相应专科长期管理。\n3. 如出现静息状态下呼吸困难明显加重、端坐呼吸、咳粉红色泡沫样痰、心悸晕厥或神志改变，提示急性心衰发作，应立即急诊就诊，不得等待门诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":807,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e4337e6fb3b3349abbee5b94a16b98e690fc05eb268ae33d99bcb3a63a50d66c","pinyin":"gaoshuchuliangxingxinlishuaijie","initials":"gsclxxlsj","setting":"out","caseName":"门诊病历675","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历675",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cc694d19323a839f8606","key":"v1-c9ccc21dfe2a3058|templates-cc694d19323a839f8606","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"低输出量性心力衰竭","category":"门诊病历模板","raw":{"name":"低输出量性心力衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历676","templates":{"主诉":"乏力1天","现病史":"患者1周前无明显诱因出现低输出量性心力衰竭相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以乏力1天为主诉，1周来症状逐渐加重伴气短，自服药物效果欠佳，低输出量性心力衰竭以组织灌注不足为主要表现，需重点评估心排血量下降程度及器官灌注情况。入院即刻完善血常规检查排除贫血所致乏力、气短；完善心肌酶谱及肌钙蛋白检查排除急性心肌损伤、急性心肌梗死；完善BNP/NT-proBNP检查明确有无心力衰竭及其严重程度，并作为疗效随访基线；完善生化全项（肝肾功能、电解质、血糖、血脂）检查了解肝肾功能与电解质水平，评估低灌注所致肝肾损伤并排除电解质紊乱所致乏力，为血管活性药物与利尿剂使用提供依据；完善心电图检查了解心律、心率及有无心肌缺血、心肌梗死图形；完善心脏超声检查了解心脏各腔室内径、室壁运动、左室射血分数及瓣膜情况，明确心排血量下降的机制；完善胸部X线片检查了解心影大小及有无肺淤血、胸腔积液；患者乏力明显、需评估有无心动过缓、房室传导阻滞等缓慢性心律失常，完善动态心电图检查了解24小时心律与心率变化；必要时完善冠脉CTA检查明确冠状动脉有无狭窄，排除缺血性心肌病所致低心排状态。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 低输出量性心力衰竭\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.利尿剂：呋塞米片 20mg qd 口服，晨服，根据每日体重及水肿情况调整剂量（每日体重减轻0.5～1.0kg为宜），注意监测血钾。\n2.肾素-血管紧张素系统抑制剂：缬沙坦胶囊 80mg qd 口服（或培哚普利片 2mg qd 口服），小剂量起始，每2周根据患者具体情况制定个体化方案加倍至目标剂量，长期维持。\n3.β受体阻滞剂：琥珀酸美托洛尔缓释片 23.75mg qd 口服，心功能稳定（NYHA Ⅱ～Ⅲ级、LVEF≤40%）后小剂量起始，每2～4周加倍1次，目标心率55～60次/分，长期维持。\n4.醛固酮受体拮抗剂：螺内酯片 20mg qd 口服（适用于LVEF≤35%或NYHA Ⅲ～Ⅳ级患者），用药后第1周及第1个月复查血钾、肌酐，血钾>5.0mmol/L或肌酐>221μmol/L时停用。\n\n【一般治疗及生活指导】\n1.休息与活动：症状明显期卧床休息或半卧位，下肢抬高，限制活动量；病情稳定后循序渐进进行步行、太极拳等有氧运动，每周3～5次、每次20～30分钟，以不出现气促为宜，避免剧烈运动和重体力劳动。\n2.饮食：严格低盐饮食，每日食盐<5g，减少腌制食品及酱油摄入；液体入量每日1500～2000ml（夏季可适当增加），少量多餐、避免饱餐。\n3.自我监测：每日晨起空腹、排尿后称体重并记录尿量，如3日内体重增加超过2kg或出现下肢水肿加重、夜间阵发性呼吸困难，提示容量负荷加重，应及时就诊。\n4.禁忌与预防：戒烟限酒，避免劳累、情绪激动、感染（感冒、腹泻）及不规律服药等诱发因素；未经医师许可不得自行停药或加药，避免使用非甾体抗炎药及含钠制剂。\n\n【随诊要求】\n1.用药调整期每1～2周门诊复诊1次，评估症状、血压、心率、体重及药物不良反应；病情稳定后每1～3个月复诊1次。\n2.每次复诊复查血压、心率、血电解质（尤其血钾）、肾功能及BNP/NT-proBNP；每3～6个月复查心电图、心脏彩超评估心功能及左室重构。\n3.如出现静息呼吸困难、夜间不能平卧、咳粉红色泡沫痰、水肿进行性加重、心悸晕厥等病情加重表现，需随时急诊就诊，不可等待常规复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":808,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"96004b03ceb1a75e961ea74453857f771418ad90be8ac37cbb2e1b98ca89050b","pinyin":"dishuchuliangxingxinlishuaijie","initials":"dsclxxlsj","setting":"out","caseName":"门诊病历676","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历676",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-250b54b8f72b67282323","key":"v1-c9ccc21dfe2a3058|templates-250b54b8f72b67282323","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"难治性心力衰竭","category":"门诊病历模板","raw":{"name":"难治性心力衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历677","templates":{"主诉":"气短1天","现病史":"患者1周前无明显诱因出现难治性心力衰竭相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以气短1天为主诉，1周来症状逐渐加重伴乏力，自服药物效果欠佳，需按难治性心力衰竭评估心功能受损程度、明确可纠正的加重因素与病因。入院即刻完善血常规检查排除感染、贫血等心衰加重诱因；完善心肌酶谱及肌钙蛋白检查排除急性心肌损伤、急性心肌梗死；完善BNP/NT-proBNP检查明确心力衰竭严重程度及治疗效果，作为调整方案的依据；完善生化全项（肝肾功能、电解质、血糖、血脂）检查了解肝肾功能与电解质水平，排除电解质紊乱、肾功能恶化所致利尿剂抵抗，并指导正性肌力药物等安全使用；完善心电图检查了解心律、心率及有无心肌缺血、心肌梗死图形；完善心脏超声检查了解心腔大小、室壁运动、左室射血分数及瓣膜情况，明确心衰病因与收缩功能受损程度；完善胸部X线片检查了解心影大小及有无肺淤血、胸腔积液，评估容量负荷；患者症状反复、口服药物效果欠佳，完善动态心电图检查了解有无阵发性快速性心律失常或缓慢性心律失常影响心功能；必要时完善冠脉CTA检查明确冠状动脉有无狭窄，排除缺血性心肌病等可干预病因，为进一步血运重建评估提供依据。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 难治性心力衰竭\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 袢利尿剂（首选，缓解充血症状）：呋塞米片20mg qd-bid口服，根据24小时尿量及每日体重调整剂量，维持每日净出量约500-1000ml，同时联用螺内酯片20mg qd以拮抗醛固酮、保钾及改善预后（需监测血钾及肾功能）。\n2. 血管紧张素受体脑啡肽酶抑制剂（ARNI，改善预后）：沙库巴曲缬沙坦钠片50mg bid起始，每2-4周滴定1次，逐渐加量至目标剂量100-200mg bid（用药前及用药期间监测血压、血钾、肾功能，禁与ACEI联用，换用ACEI需停药36小时以上）。\n3. SGLT2抑制剂（减少心衰住院及死亡）：达格列净片10mg qd或恩格列净片10mg qd，晨服，长期维持；用药期间注意泌尿生殖道感染及容量不足风险。\n4. β受体阻滞剂（血流动力学稳定后小剂量起始、缓慢滴定）：琥珀酸美托洛尔缓释片11.875mg qd起始，每2周递增1次，逐渐加至最大耐受剂量（可至190mg qd），心率维持在55-60次/分，血压偏低或急性失代偿期暂缓加量。\n【一般治疗及生活指导】\n1. 休息与活动：心功能IV级及急性加重期卧床休息，取半卧位以减轻肺淤血；症状缓解后循序渐进恢复日常活动（如室内缓步行走），避免剧烈运动、负重及情绪激动，保证充足睡眠。\n2. 饮食与饮水：严格限钠，每日食盐摄入<2g（约合钠<800mg）；限制液体入量，每日1500-2000ml（严重水肿或低钠血症时减至1000-1500ml）；少量多餐，避免饱餐增加心脏负荷。\n3. 每日自我监测：每日清晨排尿后空腹测体重，3日内体重增加超过2kg提示液体潴留，需及时复诊调整利尿剂；同时记录每日出入量、血压、心率及水肿变化。\n4. 禁忌：戒烟戒酒，预防感冒及呼吸道感染（可接种流感及肺炎疫苗）；避免使用非甾体抗炎药（NSAIDs）、含伪麻黄碱类感冒药及自行加用其他药物；不得自行停药、减量或更改用药方案。\n【随诊要求】\n每1-2周门诊复诊1次，复查血压、心率、体重、血电解质（尤其血钾）、肾功能及BNP/NT-proBNP，评估呼吸困难、水肿、尿量变化及药物耐受性，据此动态调整利尿剂及神经内分泌拮抗剂（ARNI、β受体阻滞剂）剂量；若出现静息呼吸困难、端坐呼吸、体重3日内增加>2kg、尿量明显减少、血压<90/60mmHg或晕厥、不能耐受药物等情况，应立即就近急诊就诊，不可等待预约复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":809,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9a065a93acd5af3b57afdf4a2d6761b3eb17a77f929e4f53b03d5a89fac7442b","pinyin":"nanzhixingxinlishuaijie","initials":"nzxxlsj","setting":"out","caseName":"门诊病历677","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历677",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c18990bd9742f5a36fc2","key":"v1-c9ccc21dfe2a3058|templates-c18990bd9742f5a36fc2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"细菌性心肌炎","category":"门诊病历模板","raw":{"name":"细菌性心肌炎","category":"门诊病历模板","case":{"case_name":"门诊病历678","templates":{"主诉":"胸闷1天","现病史":"患者1周前无明显诱因出现细菌性心肌炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以胸闷1天为主诉，1周来症状逐渐加重伴乏力，拟诊细菌性心肌炎，需从感染、心肌损伤、心功能与心律失常四个方面系统评估。入院即刻完善血常规检查了解白细胞及中性粒细胞水平，明确有无细菌感染及其程度；完善心肌酶谱及肌钙蛋白检查明确有无心肌损伤及其程度，动态复查评估病情演变；完善BNP/NT-proBNP检查评估心脏负荷与心功能状态，明确有无心力衰竭；完善生化全项（肝肾功能、电解质、血糖、血脂）检查了解肝肾功能与电解质水平，排除电解质紊乱所致胸闷、乏力，并指导抗菌药物选择与剂量调整；完善心电图检查了解有无ST-T改变、传导阻滞及心律失常，入院即刻完成；完善心脏超声检查了解心腔大小、室壁运动、左室射血分数及瓣膜情况，明确心肌受累范围与心功能受损程度；完善胸部X线片检查了解心影大小、肺淤血及有无肺部感染灶；患者胸闷伴乏力、心肌炎易并发心律失常，完善动态心电图检查了解有无频发早搏、传导阻滞等心律失常；必要时完善冠脉CTA检查排除冠状动脉狭窄所致心肌缺血，与急性冠脉综合征相鉴别；感染病原未明时完善血培养检查明确致病菌并指导抗菌药物选择。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 细菌性心肌炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染治疗（病因治疗）：首选阿莫西林胶囊0.5g po tid×10～14天（覆盖链球菌、葡萄球菌等常见致病菌）；或阿莫西林克拉维酸钾片0.625g po bid×10～14天。青霉素过敏者选用阿奇霉素片0.5g po qd×5天，或左氧氟沙星片0.5g po qd×7～14天（同时覆盖非典型病原体）。\n2. 心肌营养与保护：辅酶Q10胶囊10mg po tid×4周；维生素C片0.2g po tid×4周；曲美他嗪片20mg po tid×4周，改善心肌能量代谢。\n3. 心率控制与心脏保护（静息心率＞70次/分且无心动过缓、房室传导阻滞时）：琥珀酸美托洛尔缓释片23.75mg po qd，根据心率、血压调整，病情稳定后逐渐减量，疗程一般3～6个月。\n【一般治疗及生活指导】\n1. 休息：急性期严格卧床休息以减少心脏做功，至少休息至发热、胸痛等症状消失且心电图、心肌酶恢复正常（一般2～4周）；恢复期3～6个月内避免剧烈运动和重体力劳动，逐步恢复日常活动。\n2. 饮食：清淡、易消化、富含高蛋白及维生素饮食，适当限盐（每日＜5g），少量多餐避免饱餐加重心脏负担；戒烟、忌酒，避免咖啡、浓茶等刺激性饮品。\n3. 预防再感染：注意保暖，勤洗手，避免前往人群密集场所；如出现上呼吸道感染等急性感染应及时就医，防止感染复发加重心肌损害。\n4. 禁忌：急性期及恢复期禁止剧烈运动（长跑、球类、游泳等）、熬夜及情绪激动；避免自行加用其他药物，尤其非甾体抗炎药。\n【随诊要求】\n1. 治疗期间每周门诊复诊1次，复查心电图、心肌酶谱（CK-MB、cTnI）及炎症指标（血常规、CRP、ESR）直至恢复正常；病情稳定后每2～4周复诊1次。\n2. 抗生素疗程结束后1周内复诊，评估感染控制及心肌恢复情况，必要时调整后续治疗方案。\n3. 停药后第3个月、第6个月各复查心电图和超声心动图，评估心肌恢复与心功能；期间若出现胸痛、心悸加重、呼吸困难或晕厥，应立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":810,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a3708d181630e90573228b40a7d616084396cf17435e9dda22a94e8f998ff6e7","pinyin":"xijunxingxinjiyan","initials":"xjxxjy","setting":"out","caseName":"门诊病历678","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历678",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0ceacae8112bdeba00f8","key":"v1-c9ccc21dfe2a3058|templates-0ceacae8112bdeba00f8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"真菌性心肌炎","category":"门诊病历模板","raw":{"name":"真菌性心肌炎","category":"门诊病历模板","case":{"case_name":"门诊病历679","templates":{"主诉":"胸闷1天","现病史":"患者1周前无明显诱因出现真菌性心肌炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以胸闷1天为主诉，1周来症状逐渐加重伴乏力，拟诊真菌性心肌炎，多见于免疫功能低下或长期应用广谱抗菌药物、免疫抑制剂者，需兼顾感染证据、心肌损伤与心功能评估。入院即刻完善血常规检查了解白细胞及中性粒细胞水平，评估感染与免疫状态；完善心肌酶谱及肌钙蛋白检查明确有无心肌损伤及其程度，动态复查判断病情进展；完善BNP/NT-proBNP检查评估心脏负荷与心功能状态，明确有无心力衰竭；完善生化全项（肝肾功能、电解质、血糖、血脂）检查了解肝肾功能与电解质水平，排除电解质紊乱所致胸闷、乏力，并为抗真菌药物剂量调整提供依据；完善心电图检查了解有无ST-T改变、传导阻滞及心律失常；完善心脏超声检查了解心腔大小、室壁运动、左室射血分数及瓣膜情况，注意有无赘生物或心腔内占位，明确心肌受累程度；完善胸部X线片检查了解心影大小、肺淤血及有无肺部真菌感染灶；患者胸闷伴乏力、真菌性心肌炎易并发心律失常，完善动态心电图检查了解24小时心律变化；必要时完善冠脉CTA检查排除冠状动脉狭窄所致心肌缺血；必要时完善血培养及真菌G试验、GM试验检查明确真菌感染证据，指导抗真菌治疗。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 真菌性心肌炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 首选氟康唑胶囊（大扶康）400mg qd口服，首日负荷剂量，此后200mg qd，疗程至少4周（念珠菌属所致心肌炎），直至发热、胸痛等临床症状消失且心电图、心肌损伤标志物恢复正常后再巩固2周。\n2. 曲霉菌属感染或氟康唑耐药者，换用伏立康唑片200mg bid口服（首日负荷剂量400mg bid），餐前1小时或餐后1小时服用，疗程6~12周，有条件者监测血药浓度维持谷浓度1~5.5mg/L。\n3. 隐球菌性心肌炎或重症混合感染者，可在抗真菌基础上加用氟胞嘧啶片1.0g qid口服（按体重50~150mg/kg/d分4次），与氟康唑或两性霉素B联合，疗程2~6周；门诊治疗期间每周复查血常规及肝肾功能。\n【一般治疗及生活指导】\n1. 急性期绝对卧床休息，避免体力劳动和剧烈运动，待心电图、心肌损伤标志物恢复正常后逐渐恢复日常活动，3个月内避免剧烈运动。\n2. 给予高蛋白、高维生素、易消化饮食，保证充足饮水和热量摄入，忌烟酒及辛辣刺激食物；注意口腔、皮肤卫生，勤洗手，避免进入潮湿霉变环境以防真菌再感染。\n3. 严格遵医嘱规律服药，不可自行减量或停药；服用伏立康唑、伊曲康唑期间避免日光暴晒（光敏反应），并避免与西沙必利、特非那定等可致QT间期延长药物合用。\n【随诊要求】\n1. 每1~2周门诊复诊，监测临床症状、心电图、心肌损伤标志物（肌钙蛋白、CK-MB）及超声心动图变化。\n2. 抗真菌药物肝毒性明显，每2周复查肝功能、肾功能及血常规；使用伏立康唑者视条件监测血药浓度。\n3. 疗程结束、病情稳定后第1、3、6个月复查超声心动图及心肌损伤标志物，评估心功能恢复情况；若出现胸痛加重、呼吸困难、心悸、晕厥或新发发热，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":811,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"46abbacf1430fb97c27abccdd123279ee3cbf1ff17ce1fd92b20f31440ab4434","pinyin":"zhenjunxingxinjiyan","initials":"zjxxjy","setting":"out","caseName":"门诊病历679","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历679",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c874c98c2a9b16a86da7","key":"v1-c9ccc21dfe2a3058|templates-c874c98c2a9b16a86da7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"寄生虫性心肌炎","category":"门诊病历模板","raw":{"name":"寄生虫性心肌炎","category":"门诊病历模板","case":{"case_name":"门诊病历680","templates":{"主诉":"胸闷1天","现病史":"患者1周前无明显诱因出现寄生虫性心肌炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以胸闷1天为主诉，1周来症状逐渐加重伴乏力，拟诊寄生虫性心肌炎，需结合流行病学接触史评估感染证据、心肌损伤与心功能状态。入院即刻完善血常规检查了解嗜酸性粒细胞及白细胞水平，为寄生虫感染提供线索并排除贫血；完善心肌酶谱及肌钙蛋白检查明确有无心肌损伤及其程度，动态复查评估病情演变；完善BNP/NT-proBNP检查评估心脏负荷与心功能状态，明确有无心力衰竭；完善生化全项（肝肾功能、电解质、血糖、血脂）检查了解肝肾功能与电解质水平，排除电解质紊乱所致胸闷、乏力，并指导抗寄生虫药物安全使用；完善心电图检查了解有无ST-T改变、传导阻滞及心律失常；完善心脏超声检查了解心腔大小、室壁运动、左室射血分数及瓣膜情况，注意有无心腔内占位，明确心肌受累程度；完善胸部X线片检查了解心影大小、肺淤血及有无肺部病变；患者胸闷伴乏力、心肌受累易并发心律失常，完善动态心电图检查了解24小时心律变化；必要时完善冠脉CTA检查排除冠状动脉狭窄所致心肌缺血；必要时完善寄生虫相关血清学抗体检查明确病原，指导针对性治疗。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 寄生虫性心肌炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 病因治疗（抗寄生虫）：阿苯达唑片0.4g口服bid，连服10～14天，为旋毛虫、弓形虫等所致心肌炎首选方案；若确诊美洲锥虫病（克氏锥虫感染），改予苄硝唑片按5mg/kg/d分2次口服，疗程60天，需专科医师处方并定期监测血象及肝功能。\n2. 抗心力衰竭及心室重构：螺内酯片20mg qd；培哚普利片4mg qd（或缬沙坦胶囊80mg qd），据血压及肾功能调整剂量；心功能稳定后加用琥珀酸美托洛尔缓释片23.75mg qd，据心率血压缓慢递增，防止快速加重心衰。\n3. 心肌营养支持：辅酶Q10片10mg tid口服，疗程2～4周，辅助改善心肌代谢。\n【一般治疗及生活指导】\n1. 急性期绝对卧床休息，减少心肌耗氧；症状缓解后渐进恢复日常活动，3～6个月内避免剧烈运动及重体力劳动，防止诱发心律失常或加重心肌损伤。\n2. 高蛋白、高维生素、易消化饮食；肉类彻底煮熟后食用，生熟食案板、刀具分开，禁食生或半生肉制品及生鱼片，防止寄生虫再感染。\n3. 戒烟限酒，避免浓茶、咖啡及辛辣刺激饮食；保持情绪稳定、大便通畅，避免用力排便诱发心律失常。\n4. 注意饮食及个人卫生，饭前便后洗手；家中饲养猫犬者避免接触猫粪及犬排泄物，定期为宠物驱虫。\n【随诊要求】\n1. 治疗期间每周复诊1次，监测血常规、肝功能及心电图，抗寄生虫疗程结束后复查嗜酸性粒细胞计数及寄生虫病原学指标，评估虫体清除情况。\n2. 疗程结束后2周复查心电图、心肌酶谱及超声心动图，评估心功能与心脏结构恢复情况。\n3. 病情稳定后每1～3个月复查心电图及超声心动图，随访至少6～12个月；期间出现胸痛、心悸、气促加重或晕厥，随时急诊就诊。\n4. 遗留慢性心肌损害者长期心内科随诊，定期评估心功能，防治心力衰竭、心律失常及扩张型心肌病等远期并发症。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":812,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"25187aa8094ef15a86a7f1093cae390f7375ca9510fd2e7011f36a627c487b55","pinyin":"jishengchongxingxinjiyan","initials":"jscxxjy","setting":"out","caseName":"门诊病历680","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历680",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-06cce545c38cfab49348","key":"v1-c9ccc21dfe2a3058|templates-06cce545c38cfab49348","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"中毒性心肌炎","category":"门诊病历模板","raw":{"name":"中毒性心肌炎","category":"门诊病历模板","case":{"case_name":"门诊病历681","templates":{"主诉":"胸闷1天","现病史":"患者1周前无明显诱因出现中毒性心肌炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以胸闷1天为主诉，1周来症状逐渐加重伴乏力，拟诊中毒性心肌炎，多有药物、化学毒物或生物毒素接触史，需评估毒物所致心肌损伤、心功能与心律失常风险。入院即刻完善血常规检查排除感染、贫血所致胸闷、乏力，并了解有无血液系统毒性损害；完善心肌酶谱及肌钙蛋白检查明确有无心肌损伤及其程度，动态复查评估毒物对心肌的持续损害；完善BNP/NT-proBNP检查评估心脏负荷与心功能状态，明确有无心力衰竭；完善生化全项（肝肾功能、电解质、血糖、血脂）检查了解肝肾功能与电解质水平，评估毒物所致肝肾损害并排除电解质紊乱所致心律失常，为解毒及保护治疗提供依据；完善心电图检查了解有无ST-T改变、QT间期延长、传导阻滞及心律失常；完善心脏超声检查了解心腔大小、室壁运动、左室射血分数及瓣膜情况，明确心肌收缩功能受损程度；完善胸部X线片检查了解心影大小及有无肺淤血、胸腔积液；患者胸闷伴乏力、中毒性心肌炎易并发恶性心律失常，完善动态心电图检查了解24小时心律变化；必要时完善冠脉CTA检查排除冠状动脉狭窄所致心肌缺血；如明确毒物接触史，完善血、尿毒物浓度检测明确中毒程度，指导解毒治疗。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 中毒性心肌炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 营养心肌、改善心肌代谢：辅酶Q10片10mg tid×4周，联用曲美他嗪片20mg tid×4周，或维生素C片0.2g tid×4周。\n2. 病因治疗（抗感染）：若由细菌毒素（白喉、猩红热、伤寒等）所致，予阿莫西林胶囊0.5g tid×7天；青霉素过敏者改用左氧氟沙星片0.5g qd×7天。\n3. 糖皮质激素（适用于心肌损伤明显或伴心律失常者）：醋酸泼尼松片30mg qd晨起顿服，5～7天后每3～5天减量5mg，总疗程2～4周，用药期间监测血压、血糖及血钾。\n4. 对症治疗（合并频发室性早搏或窦性心动过速者）：琥珀酸美托洛尔缓释片23.75mg qd口服，心率<55次/分或出现低血压时减量或停用。\n\n【一般治疗及生活指导】\n1. 绝对卧床休息，直至体温、心电图及心肌酶恢复正常，一般需休息1～3个月；恢复期避免剧烈运动及重体力劳动，活动量循序渐进。\n2. 清淡易消化饮食、少量多餐，低盐低脂、富含优质蛋白及维生素（瘦肉、鱼、蛋、新鲜蔬果），忌烟酒、浓茶、咖啡及辛辣刺激食物，避免暴饮暴食。\n3. 立即停止接触并永久远离致病毒物（重金属、有机溶剂、农药及心肌毒性药物等），就诊时主动告知医师中毒史及药物过敏史，避免使用心脏毒性药物。\n4. 注意保暖、预防呼吸道感染，保持情绪平稳，避免紧张、焦虑及情绪激动。\n\n【随诊要求】\n1. 用药1周后门诊复诊，复查心电图、心肌酶谱（CK、CK-MB、cTnI）；2周后复查心脏彩色多普勒超声，评估心功能。\n2. 疗程结束后（约4周）复查心电图、心肌酶及心脏彩超；恢复期每2～4周随访1次，直至心电图及心肌酶完全恢复正常。\n3. 居家期间如出现胸闷、胸痛、心慌、气促、头晕或晕厥等表现，立即来院急诊或心内科就诊，不得自行加药。\n4. 建议休息3～6个月后再恢复正常活动，恢复期内避免剧烈运动及竞技性体育活动。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":813,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"51a36eea5dbe0315d447ec50b733ac2edfed54bd2be5a8445a5f7d4f6e45027d","pinyin":"zhongduxingxinjiyan","initials":"zdxxjy","setting":"out","caseName":"门诊病历681","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历681",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-89a248142d97bceeef52","key":"v1-c9ccc21dfe2a3058|templates-89a248142d97bceeef52","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"扩张型心肌病","category":"门诊病历模板","raw":{"name":"扩张型心肌病","category":"门诊病历模板","case":{"case_name":"门诊病历682","templates":{"主诉":"进行性气短、乏力伴水肿3年","现病史":"患者因扩张型心肌病的不同病因（特发性者最多，原因不明；遗传性者属家族性，与肌联蛋白、核纤层蛋白等基因相关，约20~30%为家族性，家族史筛查重要；心肌炎后，病毒性心肌炎可进展为心肌病；酒精性者与长期大量饮酒相关，酒精性心肌病可逆，戒酒后心功能可改善，此点重要，属可逆病因，必问饮酒史；围生期者见于妊娠末期及产后；药物或毒物所致者如蒽环类化疗药（阿霉素）的心肌毒性，与剂量相关；免疫性者如结节病心肌受累；代谢性者如甲减、血色病；心动过速性者因长期快速心律失常诱发，属可逆病因，控制心率后可改善）于3年前起病，呈隐匿渐进过程（数年），出现以下表现：\n心衰症状：左心衰者表现为劳力性呼吸困难（早期为活动后气短，渐进加重）、端坐呼吸、夜间阵发性呼吸困难、乏力、运动耐力下降；右心衰者表现为水肿（下肢或全身）、腹胀（肝淤血）、颈静脉怒张、少尿；临床上以全心衰多见。\n心律失常：心悸（房颤常见，因左房扩大所致）、室性早搏或室速（猝死风险，此点重要，扩张型心肌病以猝死为主要死亡方式）、传导阻滞。\n血栓栓塞：心腔内血栓（室壁运动差致血流淤滞，形成附壁血栓，可致脑、肺或外周栓塞，抗凝重要）；晕厥（心律失常所致）；猝死（室速或室颤所致，ICD可预防，此点重要）；胸痛（不典型，因心腔扩大致相对缺血）。\n体征：心脏扩大（心界向左下扩大）、S3奔马律、二尖瓣反流杂音（瓣环扩张所致功能性反流）、肺啰音、水肿。\n此外需询问饮酒史（评估酒精性病因）、家族史（心肌病或猝死家族史，重要）、化疗史及妊娠史（围生期心肌病）。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.4℃，P104次/分（增快，房颤时心律绝对不齐），R22次/分，BP98/64mmHg（可偏低，心衰所致）。心界向左下扩大（叩诊）、心尖搏动左下移位且弥散、心音低钝并可闻及S3奔马律（心衰）、S4；杂音为二尖瓣或三尖瓣收缩期反流性杂音（瓣环扩大所致功能性反流）；肺部可闻及湿啰音（左心衰）；颈静脉怒张；肝大伴压痛；腹水（右心衰晚期）；下肢凹陷性水肿；灌注偏低（晚期）；体重增加（水潴留）；心律失常（房颤，心律不齐）；恶病质（晚期）。","辅助检查":"【必做】超声心动图（核心检查：左室扩大，舒张末径>55mm（男）；室壁运动弥漫性减弱，收缩功能下降，左室射血分数<40%，为诊断核心；左室壁厚度正常或偏薄，以区别于肥厚型；瓣膜功能性反流；心腔血栓（位于室壁运动差区）；心功能评估）；心电图（左室肥大或非特异ST-T改变；心律失常如房颤、室早、传导阻滞；QRS增宽及左束支传导阻滞常见，与预后相关）；动态心电图（室性心律失常，用于猝死风险评估，重要）。\n【血液】BNP或NT-proBNP（心衰评估及随访）、心肌肌钙蛋白（心肌损伤及活动性）、肝肾功能及电解质（利尿监测）、铁蛋白及铁饱和度（血色病）、甲状腺功能（甲减，属可治病因）、HIV、酒精标志物（GGT，酒精性者）。\n【影像】心脏MRI（心肌纤维化，晚期钆增强提示瘢痕，用于猝死及预后评估；心肌炎性改变，水肿及T2序列提示活动性；心肌灌注）。\n【基因】基因检测（家族性者如肌联蛋白等基因，用于确诊、家族筛查及遗传咨询，重要）。\n【其他】心肌活检（心肌炎或浸润性疾病，诊断不明时，较少患者）、冠脉造影（排除缺血性心肌病，冠心病三支病变可致缺血性心肌病，鉴别重要；>40岁拟诊扩张型心肌病者应行冠脉评估以排除冠心病，因两者治疗不同）、心内膜心肌活检（用于结节病或巨细胞心肌炎等特定情况）。","初步诊断":"1. 扩张型心肌病（左室扩大，左室射血分数30%，心功能NYHAⅢ级）：病因考虑特发性、家族性、心肌炎后、酒精性或围生期；合并心衰（按NYHA分级）、心律失常或血栓；并行猝死风险评估。\n（注：治疗以心衰规范治疗、病因处理及猝死预防为综合方案，需长期管理）\n①病因及可逆因素处理：酒精性者戒酒（关键，戒酒后部分患者心功能可改善，重要）；围生期者予支持治疗（部分可恢复，再次妊娠属禁忌）；心动过速性者控制心率；心肌炎者予相应治疗；血色病者放血治疗；甲减者予替代治疗。\n②心衰药物治疗（射血分数降低心衰按金三角及新四联方案）：血管紧张素受体脑啡肽酶抑制剂（ARNI，沙库巴曲缬沙坦）可替代血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂，为一线用药；β受体阻滞剂（美托洛尔、比索洛尔或卡维地洛），可改善射血分数，需长期患者；醛固酮拮抗剂（螺内酯）可降低心衰死亡率；SGLT2抑制剂（达格列净或恩格列净）适用于心衰，无论射血分数如何，近年已成为标准治疗；利尿剂（呋塞米）缓解水肿及症状；地高辛用于房颤或症状顽固者。新四联可显著改善预后，重要。\n③猝死预防：ICD（植入式心律转复除颤器）指征为左室射血分数<35%、心衰NYHAⅡ~Ⅲ级、药物治疗3个月后射血分数仍<35%者，用于一级预防，可降低猝死风险，重要；有晕厥或室速史者为二级预防指征。心脏再同步化治疗（CRT）适用于左束支传导阻滞（QRS>130~150ms）合并心衰者，可再同步化、改善射血分数及症状、降低死亡率，适应证需评估，重要，可与ICD联合（CRT-D）。\n④抗凝：房颤者按CHA2DS2-VASc评分予抗凝（华法林或NOAC）；心腔血栓者予抗凝（华法林3~6个月后复查血栓是否消退）；有栓塞史者需抗凝，重要，室壁运动差并附壁血栓者应重视预防。\n⑤心律失常处理：房颤者控制心室率（β受体阻滞剂或地高辛），心衰患者使用抗心律失常药以胺碘酮较安全（心衰时其他药物有负性肌力作用，属禁用）；室速者予胺碘酮或ICD（防猝死）。\n⑥心脏移植：适用于终末期患者（难治性心衰、依赖静脉正性肌力药或机械支持者），左室辅助装置（LVAD）可作为桥接移植或终点治疗；移植需评估，适用于年轻且多器官功能良好者，重要。\n⑦随访：心功能（超声每6~12个月，观察射血分数变化）、症状（NYHA评估）、BNP（随访）、药物（滴定至靶剂量，依从性重要）、体重（每日监测，防水潴留）、依从性（与心衰反复住院及死亡相关，重要）、运动康复（稳定后行心脏康复，可改善预后）、家庭支持、ICD或CRT（程控及放电评估）。由心内科或心衰中心负责新四联治疗、ICD或CRT植入、病因处理、戒酒指导、猝死预防、移植评估及长期随访，重要。","处理方案":"【药物治疗】\n1.RAAS系统抑制剂：缬沙坦胶囊80mg qd口服，长期服用；若血压耐受（收缩压≥100mmHg），每2-4周可逐步加量至160mg qd，定期监测血压、血肌酐及血钾（血钾>5.5mmol/L或肌酐较基线升高>30%时减量或停药）。\n2.β受体阻滞剂：琥珀酸美托洛尔缓释片23.75mg qd口服起始，每2周递增一次剂量，逐步加量至47.5-95mg qd，目标静息心率55-60次/分，剂量调整期间注意心率不低于50次/分、血压及心衰症状变化，长期维持，不可突然停药。\n3.醛固酮受体拮抗剂：螺内酯片20mg qd口服（适用于NYHAⅡ-Ⅳ级且血钾<5.0mmol/L、肌酐≤221μmol/L的患者），用药1周及此后定期复查血钾、肾功能，出现男性乳房发育可换用依普利酮25mg qd。\n4.SGLT2抑制剂（心衰一线）：达格列净片10mg qd口服，晨服，长期服用，注意外阴及泌尿道感染风险；若存在明显淤血症状（下肢水肿、肺部湿啰音、颈静脉怒张），可短期加用呋塞米片20mg qd-bid口服，水肿消退后按需减量或停用。\n\n【一般治疗及生活指导】\n1.休息与活动：心功能Ⅰ-Ⅱ级（NYHA分级）可行散步、慢骑自行车等低中强度有氧运动，每次20-30分钟、每周3-5次，以不出现心悸气促为度；心功能Ⅲ-Ⅳ级或急性加重期应卧床休息，减少心脏耗氧，病情稳定后再逐步恢复活动。\n2.饮食：低盐低脂饮食，每日食盐摄入<5g（心衰期<3g），避免腌制食品、咸菜及酱料；控制每日液体入量在1500-2000ml（心衰期1500ml以内），少量多餐，避免饱餐；戒烟、戒酒，避免咖啡、浓茶及含酒精饮料。\n3.体重与感染管理：每日晨起排尿后空腹称体重并记录，3天内体重增加>2kg提示液体潴留，需及时复诊调整利尿剂；注意保暖，预防感冒及呼吸道感染，每年接种流感疫苗和肺炎球菌疫苗，感染后尽早就医。\n4.禁忌：避免剧烈运动、重体力劳动、提重物、情绪激动及屏气用力动作（如用力排便、搬重物），避免自行使用非甾体抗炎药（布洛芬、双氯芬酸等）及含麻黄碱类感冒药，以免诱发或加重心衰。\n\n【随诊要求】\n1.常规复诊：每1-3个月门诊复诊1次，评估血压、心率、体重、肺部啰音及下肢水肿情况，监测心电图、血常规、肝肾功能、电解质（尤其血钾）；每3-6个月复查超声心动图，评估左心室舒张末期内径、LVEF及瓣膜反流变化，据此调整用药。\n2.紧急就医指征：出现静息或夜间阵发性呼吸困难、端坐呼吸、咳嗽咳痰加重、双下肢水肿进行性加重、少尿、心悸伴晕厥或黑矇、胸痛等任一情况，应立即就近急诊就诊，勿等待常规复诊。\n3.用药管理：长期规律服药，不得自行停药、减量或更换药物，β受体阻滞剂、ACEI/ARB等均需缓慢调整剂量；合并心房颤动者需评估口服抗凝治疗（依据CHA₂DS₂-VASc评分），定期监测INR或肾功能。\n4.随访评估：有家族史者建议直系亲属行心电图及超声心动图筛查；拟妊娠或妊娠期女性需专科评估后再决定用药方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":814,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b5e1430e93df17803f1109888ed91e027bcf124fa69cd1b0a92df6e3221595d2","pinyin":"kuozhangxingxinjibing","initials":"kzxxjb","setting":"out","caseName":"门诊病历682","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历682",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e591300296ab79f51b5b","key":"v1-c9ccc21dfe2a3058|templates-e591300296ab79f51b5b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肥厚型心肌病","category":"门诊病历模板","raw":{"name":"肥厚型心肌病","category":"门诊病历模板","case":{"case_name":"门诊病历683","templates":{"主诉":"劳力性气短、胸痛伴运动后晕厥1年。","现病史":"患者因肥厚型心肌病的遗传背景（常染色体显性遗传，约50%有家族史，为肌节蛋白基因突变，如β肌球蛋白重链、肌球蛋白结合蛋白C等；家族筛查包括一级亲属基因检测及超声，重要；散发者为新发突变，无家族史）发病（可发生于任何年龄，青少年及青年运动猝死需警惕）于1年前起病（无症状者多为体检发现，如杂音、超声或心电图异常，或因家族筛查发现；亦可出现症状），出现以下表现：\n劳力性呼吸困难（最常见症状，因左室舒张功能障碍、充盈受限所致）、胸痛（心绞痛样，因心肌肥厚致需氧增加及冠脉相对供血不足，但冠脉正常）、晕厥或晕厥前兆（运动后或用力后出现，因流出道梗阻（梗阻性者左室流出道压差在运动或低前负荷时加重）或心律失常（室速或室颤）所致，为猝死风险，年轻人运动猝死最常见的遗传病因，重要）、心悸（心律失常如房颤，约占20~25%，多见于晚期，可致栓塞；亦可见室性心律失常）、猝死（可为首发表现，尤其运动员）、乏力头晕。\n此外：无肥厚型心肌病及猝死家族史（一级亲属35岁以下猝死者为重点询问内容）；既往超声及心电图曾异常（为就诊线索）；晕厥发作频率及诱因（运动相关，处理需评估）；无妊娠；运动习惯（运动员及竞技运动者风险较高）。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP116/72mmHg。心尖搏动左下移位（肥厚所致）；心界扩大（晚期）；心脏杂音（梗阻性肥厚型心肌病，即HOCM）：胸骨左缘收缩期喷射样杂音（为特征，与梗阻及LVOT压差相关，呈动态变化：Valsalva动作增加杂音（降低前负荷使梗阻加重）、立位杂音增强、蹲踞增加前负荷使杂音减弱、硝酸甘油使杂音增强）；二尖瓣反流杂音（收缩期，因SAM征即二尖瓣前叶收缩期前向运动致流出道梗阻及反流）；S4（心房收缩射血入肥厚心室所致）；S2分裂（流出道梗阻所致）；颈动脉可呈双峰脉（梗阻性特征，上升支陡峭后回落再上升）；无周围血管征（以区别于主动脉瓣狭窄，后者脉细迟、杂音向颈部放射、S2单一，此点重要）。","辅助检查":"【必做】超声心动图（确诊核心：左室壁不对称性肥厚，室间隔与左室后壁比值>1.3，舒张末室壁厚度≥15mm（成人）即可确诊；左室流出道压差（静息及激发，如Valsalva或运动，用于发现隐匿性梗阻，压差≥30mmHg为梗阻性）；SAM征（二尖瓣收缩期前移，为梗阻标志）；舒张功能受限（晚期）；心尖肥厚型者心电图可见巨大倒置T波，超声可观察心尖部，属变异型，注意日本及我国心尖型较多，需特别观察）；心电图（左室肥厚（电压增高）、ST-T改变（广泛深倒T波，心尖肥厚者具特征性）、异常Q波（间隔肥厚致假性梗死，见于Ⅱ、Ⅲ、aVF及V4~6）、心律失常（房颤、室早））。\n【危险分层】动态心电图（室性心律失常，24小时监测室速，用于猝死风险评估，重要）、运动负荷试验（激发流出道压差、评估症状，但晕厥或高危者应谨慎）、心脏MRI（心肌纤维化，晚期钆增强提示延迟强化，为猝死及心衰风险标志，评估重要；并精确评估肥厚分布）。\n【基因】基因检测（肌节蛋白基因突变，用于先证者确诊；阳性者可行家族成员筛查即级联检测，家族中未患病成员若基因阴性可排除，重要；并行遗传咨询）。\n【其他】心肺运动试验（功能评估）、血流动力学检查（心导管测压差，介入前评估，较少需要）。","初步诊断":"1. 肥厚型心肌病（梗阻性（HOCM，静息及激发压差阳性）或非梗阻性；室间隔肥厚型或心尖肥厚型；基因检测发现肌节蛋白基因突变；无肥厚型心肌病及猝死家族史；需行猝死风险分层评估）。\n（注：治疗为综合管理，目标为缓解症状及预防猝死，应由专科（心肌病中心）负责）\n①药物治疗（梗阻性者以降低心肌收缩力、减慢心率、改善流出道梗阻为原则）：β受体阻滞剂（一线用药，如普萘洛尔或美托洛尔，可减慢心率、延长舒张期充盈、降低压差、缓解气短胸痛及运动相关晕厥）；非二氢吡啶钙通道阻滞剂，即维拉帕米（用于β受体阻滞剂不耐受或无效者，但梗阻重合并低血压者慎用）；丙吡胺（用于难治性梗阻，具负性肌力作用，可与β阻滞剂联合）。避免使用加重梗阻的药物：硝酸酯类（扩血管、降低前负荷，可加重梗阻，应慎用或避免，心绞痛时禁用硝酸甘油，重要）、利尿剂（低血容量可加重梗阻，慎用）、地高辛及正性肌力药（增加梗阻，避免）、血管扩张剂（加重梗阻）。\n②流出道梗阻的介入或手术治疗（用于药物难治性重度梗阻，压差>50mmHg且伴症状者）：室间隔酒精消融（介入方法，向间隔支注射酒精造成局部梗死，减轻肥厚、降低压差，创伤小）；或室间隔心肌切除术（Morrow手术，外科方法，为金标准，可解除梗阻，需在有经验的中心开展）。\n③猝死预防：行风险评估，猝死危险因素包括心脏骤停或持续室速史（最高危，为ICD指征，属一级预防）、家族猝死史、不明原因晕厥（需评估）、左室壁厚度≥30mm、动态心电图发现非持续性室速、运动血压反应异常（低血压）；危险因素≥1个者应评估植入式心律转复除颤器（ICD）以预防猝死，重要，适用于高危者。并限制运动（竞技性运动属禁忌，因有猝死风险，应防止剧烈运动，重要，运动员需筛查；避免脱水）。\n④心律失常处理：房颤者控制心室率（β受体阻滞剂）并抗凝（肥厚型心肌病合并房颤者栓塞风险高，应予抗凝，如华法林或NOAC，重要）；室性心律失常高危者予ICD。\n⑤心衰处理：终末期出现扩张期改变（由肥厚转为扩张）并心衰者，按心衰规范治疗（血管紧张素转换酶抑制剂、β受体阻滞剂或利尿剂；但梗阻未解除时血管紧张素转换酶抑制剂需慎用，应个体化）；终末期者可评估心脏移植。\n⑥家族管理：行级联筛查，对一级亲属（父母、子女、同胞）行超声及心电图检查（家族基因已知者行基因检测），以早期检出、早期管理、预防猝死，重要，并予遗传咨询。随访由专科负责，每6~12个月复查超声及心电图以评估进展；ICD随访（程控）；运动指导；妊娠者多数可耐受，但梗阻重或高危者需评估并与产科协作。由心内科（心肌病及遗传性心脏病专科）长期管理，以防猝死为重点，ICD可救命。","处理方案":"【药物治疗】\n1. β受体阻滞剂（梗阻性及非梗阻性肥厚型心肌病首选一线）：琥珀酸美托洛尔缓释片47.5mg qd，或酒石酸美托洛尔片25mg bid，口服，起始低剂量，每1-2周根据静息心率及症状递增，目标静息心率55-60次/分，长期维持，不可骤停。\n2. 非二氢吡啶类钙通道阻滞剂（β受体阻滞剂不耐受或疗效不佳时选用；伴流出道梗阻者慎用）：地尔硫䓬缓释胶囊90mg qd或维拉帕米缓释片120mg qd，口服，餐后服用，监测血压及心率，心率<50次/分或II-III度房室传导阻滞者禁用。\n3. 丙吡胺（伴流出道梗阻且β受体阻滞剂治疗后仍有明显静息梗阻症状者）：磷酸丙吡胺胶囊100mg tid，口服，从小剂量起始，注意监测QT间期及抗胆碱能不良反应（口干、尿潴留）。\n4. 合并心房颤动者：利伐沙班片20mg qd口服（按CHA2DS2-VASc评分≥1分者口服抗凝），目标预防血栓栓塞；β受体阻滞剂或维拉帕米控制心室率。\n\n【一般治疗及生活指导】\n1. 严格避免剧烈运动、竞技性体育及爆发性用力动作（如举重、冲刺跑、屏气发力），推荐散步、慢骑自行车等低-中强度有氧活动，运动前须经专科评估；晕厥或猝死家族史者禁止参加有风险活动。\n2. 避免脱水、饱餐、大量饮酒、情绪激动及体位骤然改变（梗阻性患者尤甚），发热、腹泻、呕吐等致体液丢失时及时就医补液，防止梗阻加重。\n3. 饮食清淡、低盐低脂，保证优质蛋白，戒烟限酒；避免使用硝酸酯类、正性肌力药物（如洋地黄）、利尿剂过量及拟交感药物，因可加重流出道梗阻。\n\n【随诊要求】\n每3-6个月门诊复诊1次，复查心电图及超声心动图，评估左室流出道压差、室壁厚度及左房大小；每年至少行1次24小时动态心电图，有心悸、晕厥或先兆晕厥者随时复查；有心脏性猝死高危因素（非持续室速、家族猝死史、极端室壁增厚≥30mm、不明原因晕厥）者，转诊心脏专科评估植入式心律转复除颤器（ICD）指征；妊娠、计划手术或拟剧烈运动前须先至专科门诊评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":815,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4c9580efa734b2f72dcf98b922112d3939363f550cafe24af8238eec12012cba","pinyin":"feihouxingxinjibing","initials":"fhxxjb","setting":"out","caseName":"门诊病历683","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历683",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-304ba05c974704ea93e5","key":"v1-c9ccc21dfe2a3058|templates-304ba05c974704ea93e5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"限制型心肌病","category":"门诊病历模板","raw":{"name":"限制型心肌病","category":"门诊病历模板","case":{"case_name":"门诊病历684","templates":{"主诉":"气短1天","现病史":"患者1周前无明显诱因出现限制型心肌病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以气短1天为主诉，1周来症状逐渐加重并伴乏力，初步诊断限制型心肌病，需先除外感染、贫血等常见诱因，完善血常规检查排除感染及贫血所致气短；心肌病诊断明确后需长期用药且药物多经肝肾代谢，完善生化全项检查了解肝肾功能、电解质、血糖、血脂水平，评估用药安全性并指导后续治疗；查心肌酶谱及肌钙蛋白排除急性心肌损伤及心肌炎所致心功能下降；入院即刻完善心电图检查了解心律、心率及有无传导阻滞、ST-T改变，限制型心肌病常合并房性心律失常；查心脏超声了解心室壁厚度、心室舒张功能受限程度、双心房大小及瓣膜情况，为分型提供依据；完善胸部X线片检查了解心影大小及有无肺淤血，与其他气短病因鉴别；患者症状呈持续性，完善动态心电图检查排除阵发性心律失常及心动过缓；查BNP/NT-proBNP评估心室充盈压升高程度、明确有无心功能衰竭；若上述检查提示心肌病变而病因仍不明确，必要时完善冠脉CTA检查排除冠状动脉粥样硬化性心脏病所致心肌缺血。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 限制型心肌病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 利尿剂：呋塞米片20mg qd晨服，根据体重及尿量增减（可加至20mg bid），减轻体、肺循环淤血；注意监测血钾、血钠，防止低钾及低血容量。\n2. 醛固酮受体拮抗剂：螺内酯片20mg qd，与呋塞米联用保钾利尿、抑制心肌纤维化；用药期间监测血钾及肾功能，血钾>5.5mmol/L或血肌酐明显升高时减量或停用。\n3. β受体阻滞剂：琥珀酸美托洛尔缓释片23.75mg qd口服，目标静息心率60~70次/分，降低心肌耗氧、改善舒张功能；心率过缓或血压偏低时调整剂量。\n4. 抗凝治疗：合并心房颤动、既往栓塞史或超声提示心腔内血栓者，予利伐沙班片15mg qd（肌酐清除率30~49ml/min者减为10mg qd）或华法林（维持INR 2.0~3.0）抗凝，预防血栓栓塞，注意出血风险。\n【一般治疗及生活指导】\n1. 低盐饮食：每日食盐摄入<2g，避免腌制、熏酱及含钠加工食品，减轻水钠潴留。\n2. 限液与体重监测：每日液体入量控制在1500~2000ml（心衰加重期减至1000~1500ml），每日晨起排尿后空腹称体重并记录，3天内体重增加>2kg提示液体潴留，应及时就诊。\n3. 活动与禁忌：避免剧烈运动、重体力劳动及快速大量饮水，可进行散步、太极拳等低强度有氧活动，以不引起胸闷气短为度；避免妊娠、情绪激动、感染及使用非甾体抗炎药等致水钠潴留药物。\n【随诊要求】\n1. 每1~3个月门诊复诊，复查心电图、超声心动图、血常规、电解质及肝肾功能，评估心功能及用药安全性。\n2. 每日自测血压、心率，观察有无呼吸困难、下肢水肿、腹胀等淤血症状；症状加重或体重骤增随时就诊，勿自行增减利尿剂及β受体阻滞剂。\n3. 服用抗凝药期间注意有无牙龈出血、皮下瘀斑、黑便、血尿等出血征象，出现心悸、晕厥、胸痛或出血表现应立即急诊就诊。\n4. 建议于心内科专科完善心内膜心肌活检及病因筛查（如心肌淀粉样变、结节病、血色病等），明确病因后针对性治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":816,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a8f42c42d59522a70de41797df5fbfa6dc8255d221f077bab05a9e2a8df276a8","pinyin":"xianzhixingxinjibing","initials":"xzxxjb","setting":"out","caseName":"门诊病历684","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历684",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-046703877764527a84f8","key":"v1-c9ccc21dfe2a3058|templates-046703877764527a84f8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"致心律失常性右室心肌病","category":"门诊病历模板","raw":{"name":"致心律失常性右室心肌病","category":"门诊病历模板","case":{"case_name":"门诊病历685","templates":{"主诉":"心悸1天","现病史":"患者1周前无明显诱因出现致心律失常性右室心肌病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以心悸1天为主诉，1周来症状逐渐加重，初步诊断致心律失常性右室心肌病，首先完善血常规检查排除感染、贫血所致心悸；本病属心律失常性心肌病，需长期抗心律失常药物治疗且药物多经肝肾代谢，完善生化全项检查了解肝肾功能、电解质、血糖、血脂水平，评估用药安全性；心悸需与急性心肌损伤鉴别，查心肌酶谱及肌钙蛋白排除急性心肌损伤及心肌炎；入院即刻完善心电图检查了解有无右胸导联T波倒置、Epsilon波及室性早搏等特征性改变；查心脏超声了解右心室大小、右室壁运动情况及流出道有无扩张，评估右心结构功能并与其他心肌病鉴别；完善胸部X线片检查了解心影形态及有无肺淤血；本病以室性心律失常为核心表现，完善动态心电图检查明确有无室性心动过速及心律失常负荷，必要时评估植入型心律转复除颤器指征；查BNP/NT-proBNP评估心功能状态，明确有无心功能衰竭；若右室结构改变不典型而需与缺血性心肌病鉴别时，必要时完善冠脉CTA检查排除冠状动脉病变。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 致心律失常性右室心肌病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. β受体阻滞剂（一线首选，控制运动诱发的室性心律失常）: 美托洛尔缓释片23.75mg qd起始，或比索洛尔2.5mg qd起始，每1-2周逐步加量至目标静息心率55-60次/分，长期维持。\n2. 抗心律失常药物（β受体阻滞剂单用效果不佳或室速反复发作时加用）: 胺碘酮200mg tid×1周、200mg bid×1周负荷后改为200mg qd维持，定期复查心电图（QTc）、甲状腺功能、肝功能及胸片；或索他洛尔80mg bid，用药期间监测QTc，低钾血症及肾功能不全时慎用。\n3. 醛固酮受体拮抗剂（合并右心功能不全或心衰时）: 螺内酯20mg qd，联用呋塞米20mg qd（水肿明显时临时加量），并加用血管紧张素转换酶抑制剂（如培哚普利2-4mg qd）延缓心室重构。\n4. 抗凝治疗（合并房性心律失常、房颤或既往血栓栓塞史时）: 利伐沙班15mg qd（CrCl≥50ml/min时20mg qd）或华法林口服维持INR 2.0-3.0。\n\n【一般治疗及生活指导】\n1. 严格限制竞技性及患者度运动（马拉松、长跑、自行车、球类、游泳比赛等），运动是ARVC室速及猝死的主要诱因；仅允许低强度休闲活动（散步、太极拳等），以不引起心悸、胸闷为宜。\n2. 规律作息，避免熬夜、过度劳累及情绪激动；戒烟戒酒，减少咖啡因摄入，避免暴饮暴食。\n3. 合并心功能不全时低盐饮食（每日钠盐<5g），每日监测体重及下肢水肿情况，体重短期骤增或水肿加重时及时就诊。\n4. 禁用拟交感类药物及延长QT间期的药物（如部分抗组胺药、大环内酯类抗生素等）；任何新用药物医师有ARVC病史。\n\n【随诊要求】\n1. 每3-6个月门诊复诊，复查12导联心电图及24小时动态心电图，评估室性早搏负荷及非持续性室速发作情况，必要时调整抗心律失常药物。\n2. 每1-2年复查超声心动图，动态监测右室大小、右室收缩功能及LVEF；初始评估及病情进展时行心脏MRI评估心肌纤维脂肪浸润范围。\n3. 如出现心悸、晕厥、先兆晕厥、持续性室速或右心衰竭症状加重，随时就诊，并评估植入式心律转复除颤器（ICD）植入指征（晕厥、持续性室速、致病性基因突变高危型等）。\n4. 告知患者及直系亲属（父母、同胞、子女）行心电图、超声心动图筛查，必要时基因检测，家系成员需在心血管专科长期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":817,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"adc20ea0593f67b5c5e8a12ddf79cb669a1164927c38e181823861d4ce5aa521","pinyin":"zhixinlvshichangxingyoushixinjibing","initials":"zxlscxysxjb","setting":"out","caseName":"门诊病历685","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历685",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-54c9432249205a79949d","key":"v1-c9ccc21dfe2a3058|templates-54c9432249205a79949d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"围生期心肌病","category":"门诊病历模板","raw":{"name":"围生期心肌病","category":"门诊病历模板","case":{"case_name":"门诊病历686","templates":{"主诉":"气短1天","现病史":"患者1周前无明显诱因出现围生期心肌病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以气短1天为主诉，1周来症状逐渐加重并伴乏力，初步诊断围生期心肌病，妊娠及产褥期女性出现气短须先除外贫血与感染，完善血常规检查排除贫血、感染所致气短；围生期心肌病治疗涉及抗心力衰竭及抗凝药物，完善生化全项检查了解肝肾功能、电解质、血糖、血脂水平，评估用药安全性；查心肌酶谱及肌钙蛋白排除急性心肌损伤及围生期心肌炎；入院即刻完善心电图检查了解心律、心率及有无ST-T改变、心律失常；查心脏超声了解左心室扩大程度、射血分数、室壁运动及有无心腔内血栓，为诊断与抗凝决策提供依据；完善胸部X线片检查了解心影大小及有无肺淤血、胸腔积液；近1周症状持续加重，完善动态心电图检查排除阵发性心律失常；查BNP/NT-proBNP评估心功能受损程度、明确有无心功能衰竭并指导利尿及抗心力衰竭治疗；妊娠相关高凝状态易致冠脉事件，必要时完善冠脉CTA检查排除冠状动脉粥样硬化性心脏病及冠脉夹层。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 围生期心肌病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 利尿剂：呋塞米片20mg po qd（晨服），依据体重及下肢水肿程度调整，水肿消退后减量至最小维持量，同时监测血钾、血钠，必要时联合螺内酯片20mg po qd。\n2. 血管紧张素转换酶抑制剂（产后停哺乳期）：培哚普利叔丁胺片2mg po qd起始，血压耐受后渐增至4mg po qd；哺乳期改予肼苯哒嗪片25mg po tid联合硝酸异山梨酯片10mg po tid。\n3. β受体阻滞剂（心衰症状稳定、无急性失代偿时起始，小剂量滴定）：琥珀酸美托洛尔缓释片23.75mg po qd起始，每2周根据患者具体情况制定个体化方案加量，目标心率55-60次/分。\n4. 抗凝治疗（LVEF≤35%或合并心房颤动时）：依诺肝素钠注射液4000U ih q12h，哺乳期及备孕安全，维持至LVEF恢复或分娩后3个月，注意监测出血倾向。\n【一般治疗及生活指导】\n1. 休息：急性期绝对卧床休息，保证充足睡眠，避免劳累及剧烈活动，以心率及呼吸困难改善为准逐步恢复日常活动。\n2. 饮食：低盐（<5g/d）低脂易消化饮食，适当限制液体入量，每日晨起空腹称体重，监测体重及尿量变化。\n3. 禁忌：绝对避免再次妊娠（复发率高、预后差），采用屏障避孕或宫内节育器避孕，禁用口服避孕药；戒除烟酒，避免受凉及呼吸道感染。\n4. 活动：心功能稳定（NYHA Ⅰ-Ⅱ级）后循序渐进进行散步等温和有氧活动，出现胸闷、气促即减少活动量。\n【随诊要求】\n1. 产后6个月内为高危期，每2周门诊复诊1次，监测血压、心率、体重、电解质及肝肾功能，评估心衰症状变化。\n2. 每3个月复查超声心动图评估左心室射血分数及左室大小恢复情况；LVEF恢复至≥50%后可考虑逐渐减停药物，减药过程需在医师指导下进行。\n3. 动态心电图随访，警惕室性心律失常及血栓栓塞事件；如出现进行性呼吸困难、夜间不能平卧、下肢水肿加重、晕厥或胸痛，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":818,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4fed93575884f56bbda9dad6bd3bd155718f8539189eb5a0d6a6f5fd9cde00fc","pinyin":"weishengqixinjibing","initials":"wsqxjb","setting":"out","caseName":"门诊病历686","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历686",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3d9b55282c4322568ac5","key":"v1-c9ccc21dfe2a3058|templates-3d9b55282c4322568ac5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性心包炎","category":"门诊病历模板","raw":{"name":"急性心包炎","category":"门诊病历模板","case":{"case_name":"门诊病历687","templates":{"主诉":"胸痛伴发热1周","现病史":"患者于1周前（上呼吸道感染后，多为病毒性，属最常见，特发性或病毒性心包炎在青壮年多见；或为其他病因：结核性（我国重要病因，结核性心包炎可有发热、盗汗、消瘦及心包积液）、肿瘤性（恶性，如肺癌或乳腺癌转移，多为血性积液）、尿毒症性（终末期肾病、透析不充分）、心肌梗死后（Dressler综合征，于梗死后数周出现，属免疫性）、自身免疫性（SLE、类风湿）、药物性（普鲁卡因胺、异烟肼）、细菌性（化脓性，少见但严重））出现以下表现：\n胸痛（为首发及主要症状，位于心前区或胸骨后，呈锐痛或刺痛；特征为平卧、深吸气、咳嗽、吞咽时加重（胸膜性，与呼吸相关）；坐起前倾位减轻（特征性，重要）；可放射至左肩及斜方肌（膈神经分布，为心包炎特征性放射）；发热（低至中度，见于病毒性或结核性）；心悸；乏力；呼吸困难（因心包积液压迫或炎症所致）。\n心包摩擦音（为特征性体征，位于胸骨左缘第3~4肋间，呈抓刮样，前倾位深吸气时明显，可为三相（收缩期加舒张期），间歇出现，闻及即可诊断，但并非必有）。\n心电图呈动态改变（急性心包炎可见弥漫性ST段抬高，呈弓背向下、凹面向上，以区别于心梗的弓背向上；PR段压低，见于Ⅱ、Ⅲ、aVF及V2~V6，累及广泛导联，呈非冠脉分布，可与心梗鉴别；数日后ST段回落并出现T波倒置）。\n无大量心包积液及心脏压塞表现（呼吸困难加重、端坐呼吸、血压下降、颈静脉怒张，属急症）；近期无心肌梗死及心脏手术史；无结核接触史、肿瘤病史及尿毒症透析史。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P96次/分（增快），R20次/分，BP118/72mmHg。神志清楚，急性病容（因胸痛取前倾坐位）。心包摩擦音（特征性体征，位于胸骨左缘3~4肋间，呈抓刮样，前倾及深吸气时明显，听诊呈间歇性，须反复听诊）；心音低钝（大量积液时）；心率增快；颈静脉怒张（提示压塞或大量积液）；奇脉（大量积液时）；肝大及下肢水肿（亚急性者提示缩窄或压塞）；肺部听诊清（可与肺炎或心梗鉴别）；可见原发病体征（结核者可有淋巴结肿大，肿瘤者可有恶病质）。","辅助检查":"【必做】心电图（弥漫性ST段弓背向下抬高，具特征性，累及多个导联，呈非冠脉分布；PR段压低；T波演变，数日至数周后倒置再恢复；大量积液时可见低电压；需动态复查）、血常规（白细胞升高提示感染）、CRP（升高提示炎症活动，用于治疗监测，为核心随访指标）、血沉、心肌肌钙蛋白（可轻度升高，因心外膜下心肌受累，用于与心梗鉴别，后者明显升高且呈冠脉分布）、胸部X线（心影正常（无积液时）或>250ml时呈烧瓶形增大；肺野清晰，可与心衰鉴别）。\n【确诊及评估】超声心动图（核心检查：心包积液（量及分布）、心脏压塞评估、心包增厚（提示缩窄性心包炎，属后期表现）、可在心包腔引导穿刺）、心脏MRI（心包增厚及炎症，晚期钆增强提示心包炎活动性，用于疑难病例）。\n【病因】心包穿刺（用于大量积液或压塞，兼具治疗及诊断作用：心包液常规生化可区分渗出（炎症、肿瘤、结核）与漏出（尿毒症、心衰）；细胞学检查（肿瘤，可确诊恶性积液）；抗酸涂片及培养、ADA（结核性者ADA升高，重要，我国结核多见）；细菌培养）、结核筛查（结核菌素试验或IGRA，用于结核性心包炎，我国结核病高发，需查痰及胸片）、肿瘤标志物及影像（恶性者行胸腹部CT）、自身抗体（自身免疫者，提示风湿病）、肾功能及透析情况（尿毒症者）。","初步诊断":"1. 急性心包炎（病因以特发性或病毒性最为常见，结核性、肿瘤性、尿毒症性待查；伴心包积液，量少）。\n（注：治疗依病因，以对症为主；特发性及病毒性者多自限，病程数天至数周）\n①抗炎止痛（核心治疗，用于特发性及病毒性者）：非甾体抗炎药（布洛芬600~800mg tid，或阿司匹林（心梗后Dressler综合征者选用阿司匹林），或吲哚美辛（注意透壁心梗后慎用）），疗程1~2周，症状缓解后逐渐减量，以防复发，疗程应足够；秋水仙碱（0.5mg bid，与NSAIDs联合，可显著降低复发率，属一线辅助用药，重要，适用于特发性或复发性心包炎，予推荐）；糖皮质激素（用于NSAIDs禁忌、无效或结核性者（抗结核同时使用）），予泼尼松0.5mg/kg/d，逐渐减量，但可增加复发风险，应尽量少用。\n②病因治疗：结核性者予抗结核治疗（四联方案，即HRZE，疗程6~12个月；结核性心包炎可同时予激素以防缩窄，重要）；化脓性者予抗生素加引流（必要时心包切开）；尿毒症者强化透析；肿瘤性者予心包内化疗或心包开窗；自身免疫性者予激素，必要时加免疫抑制剂；药物性者停药。\n③心包积液及压塞处理：大量积液或压塞者行心包穿刺引流（治疗措施，必要时留置导管）；反复出现大量积液者行心包开窗（经剑突下，以防复发）。\n④休息（急性期卧床，避免劳累）及随访：CRP（为活动指标，用于治疗随访，正常后可停药）、超声（观察积液消退及心包增厚或缩窄演变，需长期监测，缩窄性心包炎为后期并发症，反复炎症可致心包增厚钙化及右心衰，需行心包切除，随访中识别，重要）、复发监测（约15~30%复发，秋水仙碱可防复发，疗程3~6个月；复发性心包炎者予秋水仙碱，必要时联合激素，需专科处理）。由心内科管理，特发性者多预后良好，应明确病因，防复发、防缩窄并随访。","处理方案":"【药物治疗】\n1. 非甾体抗炎药（一线止痛抗炎）：布洛芬缓释胶囊0.3g po bid，或阿司匹林肠溶片750mg po q8h，餐后服用，疗程1-2周，胸痛及炎症缓解后逐渐减量至停药；同时联用奥美拉唑肠溶胶囊20mg po qd保护胃黏膜。\n2. 秋水仙碱（降低复发率）：0.5mg po bid（体重<70kg或胃肠不耐受者0.5mg qd），疗程3个月；注意监测肝功能及腹泻、恶心等不良反应，避免与克拉霉素、环孢素等CYP3A4抑制剂合用。\n3. 糖皮质激素（仅在NSAIDs/秋水仙碱禁忌或无效、或明确自身免疫性病因时使用）：泼尼松0.2-0.5mg/kg/d（成人一般20-30mg/d）晨起顿服，症状控制后每1-2周缓慢减量，疗程4-6周，减量期间联用秋水仙碱防止反跳；化脓性心包炎按病原学选用敏感抗生素并尽早心包引流，结核性心包炎行规范抗结核治疗。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息，减少活动以降低心脏负荷；待胸痛消失、心包积液消退后逐步恢复日常活动。\n2. 清淡低盐饮食，避免辛辣刺激及过饱；戒烟限酒，保证充足睡眠，避免情绪激动。\n3. 恢复期（症状缓解后至少4-6周）避免剧烈运动及竞技性体育活动，暂停马拉松、篮球等患者度运动，防止复发；注意保暖，预防呼吸道感染。\n4. 停用可能诱发心包炎的药物（如肼苯哒嗪、普鲁卡因胺、异烟肼等），避免劳累及受凉。\n\n【随诊要求】\n1. 用药1-2周后复诊，复查血常规、CRP/ESR、心电图及超声心动图，评估胸痛缓解程度及心包积液变化。\n2. 治疗期间若出现胸痛加重、呼吸困难、端坐呼吸、血压下降或奇脉等表现，须立即急诊就诊，警惕心脏压塞。\n3. 症状缓解、炎症指标恢复正常后，每1-3个月复查超声心动图随访6个月至1年，出现颈静脉怒张、肝大、腹水等表现及时复诊，警惕缩窄性心包炎。\n4. 停药后若胸痛复发，及时复诊，评估复发并调整秋水仙碱/糖皮质激素方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":819,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a425e452e946e5ffa931f761d8f8eb3eacf277a27f8d5176730053779f734774","pinyin":"jixingxinbaoyan","initials":"jxxby","setting":"out","caseName":"门诊病历687","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历687",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-48ef9af67abf9b0998e6","key":"v1-c9ccc21dfe2a3058|templates-48ef9af67abf9b0998e6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性心包炎","category":"门诊病历模板","raw":{"name":"慢性心包炎","category":"门诊病历模板","case":{"case_name":"门诊病历688","templates":{"主诉":"胸闷1天","现病史":"患者1周前无明显诱因出现慢性心包炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以胸闷1天为主诉，1周来症状逐渐加重并伴乏力，初步诊断慢性心包炎，需先除外感染及贫血所致胸闷，完善血常规检查排除感染、贫血；慢性心包炎常累及肝脏并引起低蛋白血症、电解质紊乱，完善生化全项检查了解肝肾功能、电解质、血糖、血脂水平，评估心包缩窄对肝脏淤血的影响并指导用药；查心肌酶谱及肌钙蛋白排除心包心肌炎合并心肌损伤；入院即刻完善心电图检查了解有无低电压、ST-T改变及心律失常；查心脏超声了解心包厚度、有无钙化、心包积液及心室舒张受限情况，为诊断缩窄性心包炎提供依据；完善胸部X线片检查了解心影大小、有无心包钙化及肺淤血；患者胸闷持续存在，完善动态心电图检查排除心律失常所致胸闷；查BNP/NT-proBNP评估心包受限引起的心室充盈压升高程度、明确有无心功能衰竭；若需与缺血性心肌病、陈旧性心肌梗死鉴别，必要时完善冠脉CTA检查排除冠状动脉粥样硬化性心脏病。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 慢性心包炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 病因治疗（结核性心包炎，我国慢性心包炎最常见病因）：异烟肼片0.3g qd＋利福平胶囊0.45g qd＋吡嗪酰胺片1.5g qd＋乙胺丁醇片0.75g qd，晨起空腹顿服，强化期2个月；后改为异烟肼0.3g qd＋利福平0.45g qd巩固治疗10个月，总疗程12个月，全程联合葡醛内酯片0.1g tid保肝。\n2. 缓解体循环淤血（伴呼吸困难、下肢水肿、腹水时）：呋塞米片20mg qd晨服，据体重及尿量调整，最大可加至40mg qd；联合螺内酯片20mg qd口服，用药期间每周复查电解质、肾功能及血压。\n3. 控制心室率（合并心房颤动者）：美托洛尔缓释片23.75mg qd口服，目标静息心室率60～80次/分；伴明显心功能不全者加用地高辛片0.125mg qd，定期监测地高辛血药浓度。\n【一般治疗及生活指导】\n1. 注意休息，避免劳累及剧烈活动，保证每日睡眠7～8小时，减轻心脏负荷。\n2. 低盐饮食（每日食盐<5g），适当限制液体摄入，少食多餐避免饱餐，保证优质蛋白摄入。\n3. 注意保暖、预防呼吸道感染；结核性心包炎活动期注意呼吸道隔离及痰液消毒，戒烟戒酒。\n4. 每日晨起自测体重并记录尿量，若2周内体重增加>2kg，或出现夜间阵发性呼吸困难、端坐呼吸、下肢水肿加重，立即就医。\n【随诊要求】\n1. 抗结核治疗期间每1～2个月复查肝功能、肾功能、血常规及血尿酸，出现肝损伤或药物不良反应及时调整方案。\n2. 每1～3个月复查心电图、胸部X线或CT及心脏彩超，评估心包积液、心包钙化程度及心功能变化。\n3. 若出现进行性加重的呼吸困难、颈静脉怒张、肝大、腹水、下肢水肿等心包缩窄表现，尽早复诊，评估心包切除术手术指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":820,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c0bd1e75e02c1954d8ef381c637f56ff90c4360443b27a5ebc0192154ecde6da","pinyin":"manxingxinbaoyan","initials":"mxxby","setting":"out","caseName":"门诊病历688","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历688",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e88735c1ce306dfef23a","key":"v1-c9ccc21dfe2a3058|templates-e88735c1ce306dfef23a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"缩窄性心包炎","category":"门诊病历模板","raw":{"name":"缩窄性心包炎","category":"门诊病历模板","case":{"case_name":"门诊病历689","templates":{"主诉":"乏力、气短、腹胀伴水肿2年","现病史":"患者因缩窄性心包炎的病因（结核性心包炎后，我国以结核最为常见，为心包缩窄的主要病因，结核性心包炎未充分治疗可致缩窄，此点重要，应重视抗结核以预防缩窄；病毒性或特发性心包炎后，反复发作可致缩窄；心脏手术后，术后心包缩窄较少见；放射性心包炎，纵隔放疗（如霍奇金淋巴瘤、乳腺癌放疗）后数年至数十年可出现缩窄；尿毒症者长期透析；风湿性；肿瘤（心包转移）；结缔组织病），并有既往心包炎史（结核性或急性心包炎，可发生于多年前，需追问治疗史）于2年前起病（呈隐匿渐进过程，数月至数年，心包炎后可潜伏数月至数十年），出现以下表现：\n体循环淤血（呈右心衰样表现，但由心源性缩窄所致，具以下特征）：下肢水肿（凹陷性）、腹胀（腹水明显，可先于下肢水肿出现，因肝淤血所致）、食欲减退（胃肠淤血）、乏力（心排血量下降）、劳力性气短（舒张受限、充盈下降、心排血量降低所致）、颈静脉怒张（明显，Kussmaul征阳性：吸气时颈静脉扩张，呈反常表现，为缩窄特征，重要）、心包叩击音（舒张早期出现，因心包限制所致，呈高调，为特征性听诊发现）、奇脉（可有，吸气时收缩压下降）、肝大（质硬，淤血所致，长期可致肝硬化）、胸腹水（漏出液）、低蛋白（因淤血性肝病或胃肠丢失）、恶病质（晚期）。\n鉴别方面：限制型心肌病（因心肌限制所致，临床表现相似，鉴别重要，两者治疗不同，如心内膜心肌纤维化、淀粉样变，可行超声、MRI及心肌活检鉴别）；肝硬化（可有腹水，但无心衰表现，颈静脉不怒张，缩窄者颈静脉怒张，可资鉴别）；心衰（右心衰亦可致淤血，但缩窄者以右心淤血为主，肺野相对清晰，为其特点）。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P92次/分，R20次/分，BP100/78mmHg（脉压差小）。奇脉（吸气时血压下降>10mmHg，需检查）；颈静脉怒张并Kussmaul征（吸气时怒张加重，为特征，吸气时颈静脉扩张，与右心衰时吸气塌陷相区别）；心脏：心音遥远、心包叩击音（舒张早期呈喀喇样，为心包缩窄特征，于心尖内侧听诊）、心率增快（代偿）；心界不大（因缩窄心包固定所致）；腹部：肝大（质硬）、腹水（明显，移动性浊音阳性）、脾大（淤血）；下肢水肿；全身消瘦（恶病质、低蛋白）；肺部相对清晰，啰音少，可与肺水肿相区别。","辅助检查":"【必做】超声心动图（核心检查：心包增厚（回声增强）、钙化（强回声）；室间隔异常运动，呈呼吸性室间隔抖动（舒张期矛盾运动，为缩窄特征）；二尖瓣及三尖瓣血流呈呼吸变异（吸气时二尖瓣E峰下降、三尖瓣E峰升高，为缩窄特征，呼气时相反）；下腔静脉扩张且固定；呈限制性充盈模式，可与限制型心肌病鉴别（缩窄者呼吸变异大，限制型者小，鉴别重要））；胸部X线（心包钙化（缩窄者钙化可呈蛋壳样位于心影边缘，为特征，但非必有）；心影不大或轻度增大；胸膜增厚；胸腔积液）；胸部CT或MRI（核心检查：心包增厚>3~4mm、钙化（CT敏感，便于评估）；并可鉴别心包积液与增厚，MRI可评估心包炎症及增厚，为手术前评估的重要依据）；心电图（低电压、非特异ST-T改变、房颤（常见）、P波增宽）。\n【血液】BNP或NT-proBNP（升高，但低于扩张型心衰者，可辅助鉴别）、肝功能（淤血性升高）、白蛋白（降低，因丢失）、结核相关（结核菌素试验或γ-干扰素释放试验，评估结核性）、炎症指标（血沉、CRP，评估活动性）。\n【确诊】心导管（左右心压力测定：舒张压在各心腔呈均衡化，为缩窄特征，左右心舒张压接近；右室舒张早期下陷并呈高原波，即平方根征、dip-plateau）、心内膜心肌活检（用于与限制型心肌病鉴别，必要时行此项以确诊）。\n【其他】腹部超声（评估肝淤血及腹水）、胸腔积液行胸水检查。","初步诊断":"1. 缩窄性心包炎（心包增厚钙化，经影像证实；病因为结核性、特发性、术后或放射性；症状为右心淤血，表现为腹水、水肿、颈静脉怒张；Kussmaul征及心包叩击音阳性；需与限制型心肌病鉴别；并行手术评估）。\n（注：治疗以心包切除术为根治手段，内科治疗为支持及术前准备）\n①病因治疗：活动性结核者予抗结核治疗（四联方案，疗程6~12个月，以防缩窄进展；早期结核性心包炎予抗结核加激素可防缩窄，重要）；活动性炎症者予非甾体抗炎药或秋水仙碱（用于特发性及复发性者，可减少炎症，但已形成缩窄即纤维化钙化者不可逆，抗炎不能逆转，主要仍靠手术）。\n②内科支持（用于手术前或不能手术者）：利尿（呋塞米加螺内酯，减轻水肿及腹水；但缩窄者心排血量低，利尿过度可致低灌注，应慎用并适度，监测颈静脉压，勿过度，重要）、限盐、洋地黄（房颤者用于控制心室率，可用β受体阻滞剂或地高辛）、抗凝（房颤者预防栓塞）、营养（低蛋白者予补充）、腹水穿刺（大量者减压，但可致蛋白丢失，反复穿刺需注意）、抗结核（结核性者手术前应充分用药，完成疗程）。\n③心包切除术（根治治疗）：即剥离心包，解除缩窄、改善心脏舒张，可有效缓解症状并改善血流动力学，重要。手术时机：确诊且症状明显者（NYHAⅡ级以上，功能受限）；结核者于抗结核稳定后手术（活动期应先抗结核，疗程部分为6~8周后再手术，需权衡）；早期手术（心包炎后缩窄进展者宜尽早手术，以防心肌萎缩，长期缩窄可致心肌废用性萎缩，术后低心排、恢复慢，重要）。手术风险：心包剥离可致心肌损伤及低心排综合征，术后需ICU及正性肌力药支持，重要，高龄或病情严重者风险更高。\n④术后处理：症状改善（水肿、腹水消退需数周至数月，心肌逐步恢复）、心功能随访（超声）、复发（心包切除不彻底者需再次评估）、并发症（术后早期低心排，需及时处理）。\n⑤随访：术前予内科治疗稳定病情，监测体重、出入量及电解质；术后评估心功能恢复情况；病因方面结核者应完成疗程；并注意与限制型心肌病鉴别，若误诊则手术无效，重要，术前需充分鉴别，可行心导管及心肌活检。由心内科及心外科协作，诊断依据Kussmaul征、钙化及呼吸变异，经超声或CT确认，与限制型心肌病鉴别后行心包切除根治，同时做好术前准备，结核病因重要。","处理方案":"【药物治疗】\n1. 利尿消肿：呋塞米片20mg qd（晨服），根据24小时尿量及体重增减调整剂量，最大可用至40mg qd；联合螺内酯片20mg qd以减少钾丢失，每周监测体重、电解质及肾功能，避免过度利尿诱发低血压及低心排。\n2. 病因治疗：我国以结核性缩窄性心包炎最常见，疑诊或确诊结核者予抗结核四联方案：异烟肼片0.3g qd+利福平胶囊0.45g qd+吡嗪酰胺片0.5g tid+乙胺丁醇片0.75g qd，强化期2个月，巩固期异烟肼+利福平继续4~10个月（总疗程6~12个月），全程联合水飞蓟宾胶囊70mg tid护肝，每月复查肝功能；非结核病因者按原发病（化脓性、肿瘤性、尿毒症性等）相应处理。\n3. 对症治疗：并发心房颤动、心室率快者，予地高辛片0.125mg qd+美托洛尔缓释片23.75mg qd控制心室率，用药期间监测心率（静息心率60~80次/分）及地高辛中毒表现（恶心、黄视、心律失常）；血压偏低者禁用或慎用扩血管药及ACEI/ARB类降压药。\n【一般治疗及生活指导】\n1. 休息：限制体力活动，避免剧烈运动、负重及屏气动作，保证充足睡眠，以减轻心脏负荷、缓解体循环淤血症状。\n2. 饮食：低盐饮食（每日食盐<3g），限制液体入量（每日<1500ml），给予高蛋白、高维生素、易消化饮食，少量多餐，避免过饱加重腹胀。\n3. 自我监测：每日晨起空腹测体重并记录24小时尿量，体重较前日增加>1kg或尿量明显减少提示淤血加重，应及时就诊调整利尿剂。\n4. 禁忌：避免劳累、受凉感冒及情绪激动等诱因；慎用非甾体抗炎药，勿自行停用或增减利尿剂剂量；戒烟酒。\n【随诊要求】\n1. 利尿消肿期每周门诊复诊1次，监测体重、血压、心率、颈静脉怒张程度、肝大及下肢水肿变化，复查血电解质、肝肾功能，及时调整利尿剂。\n2. 抗结核治疗者每月复查肝功能，每2~3个月复查胸部CT评估心包厚度、钙化及胸腔积液变化，抗结核方案调整患者专科医师指导下进行。\n3. 本病根治手段为心包剥离术，内科治疗仅能缓解症状，建议尽早就诊心外科评估手术指征及时机；随访期间如出现呼吸困难加重、胸痛、腹水增多、晕厥或下肢水肿急剧加重，需随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":821,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3097ab68f45f4ae22bccbd56fc7e9515bfcf4dc4bd512a503365ff45468b836d","pinyin":"suozhaixingxinbaoyan","initials":"szxxby","setting":"out","caseName":"门诊病历689","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历689",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f373f1e26ace7357fb1b","key":"v1-c9ccc21dfe2a3058|templates-f373f1e26ace7357fb1b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心包积液","category":"门诊病历模板","raw":{"name":"心包积液","category":"门诊病历模板","case":{"case_name":"门诊病历690","templates":{"主诉":"胸痛、呼吸困难伴乏力1个月","现病史":"患者因心包积液的病因（感染性者：结核性（我国重要，结核性心包炎可致积液，伴低热、盗汗）、病毒性或特发性（常见，多自限）、化脓性（少见，病情重，多继发于败血症或邻近感染）；心衰或尿毒症性（多为漏出液，如透析患者）；肿瘤性（转移所致，如肺癌、乳腺癌，恶性心包积液多为血性）；自身免疫性（如SLE、类风湿，属免疫性）；心肌梗死后；甲状腺功能减退（黏液水肿可致心包积液）；药物性（少见）；放射性；外伤）\n于1个月前发现或出现（体检或症状发现：小量者多无症状，常为超声偶然发现；中至大量者可有胸痛（闷痛，呼吸或平卧时加重）、呼吸困难（因压迫肺及心脏致心排血量下降）、咳嗽、吞咽困难、乏力及心包摩擦音；压迫症状明显时，大量积液可致心脏压塞（表现为低血压、颈静脉怒张、奇脉、心音遥远），属急症，详见心脏压塞章节。\n积液性质、量及速度：增长快者症状明显，即使量不大也可致压塞；增长慢者可耐受大量积液，甚至达数升。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P98次/分，R20次/分，BP110/70mmHg。心界向两侧扩大（大量积液时）、心音遥远低钝、心包摩擦音（早期或少量积液时）、颈静脉怒张（提示压塞或大量积液）、奇脉（吸气时收缩压下降>10mmHg，为压塞征象）、呼吸急促（端坐位）、肺部听诊清（与心衰不同，心包积液者肺多清晰，此点重要）、肝大及水肿（大量积液致右心回流受阻）、血压偏低（压塞时可致休克）、发热（感染或结核所致）、可见原发病体征（肿瘤、甲状腺疾病）、下肢水肿。","辅助检查":"【必做】超声心动图（核心检查：心包积液（液性暗区，可估测量为少、中、大量，并判断分布，如包裹性）；压塞征象（右房或右室舒张期塌陷（舒张期受压）、呼吸性跨瓣血流变异增大）；可引导心包穿刺）。\n【病因】胸片（心影呈烧瓶样增大，>250ml时明显；并可观察肺部情况，如结核或肿瘤）、血常规及CRP、血沉（评估感染及炎症）、结核相关（结核菌素试验、γ干扰素释放试验、胸片）、肿瘤标志物（寻找原发灶线索）、甲状腺功能（甲减）、肾功能（尿毒症）、自身抗体（SLE等风湿病）、心肌肌钙蛋白及病毒相关检查（心肌炎、心包炎）、心包穿刺（诊断性，用于中至大量积液者，穿刺送检：常规及生化（鉴别渗出与漏出）、细胞学（恶性者查肿瘤细胞）、ADA（结核者>40U/L支持诊断）、抗酸涂片、培养及聚合酶链反应（结核）、细菌培养，明确病因重要）。\n【影像】CT（评估心包增厚、钙化、积液分布（包裹性、积气、化脓），并观察邻近肺及纵隔，评估肿瘤）、磁共振（评估心包炎症及增厚）、心电图（低电压（大量积液时）、ST段改变（心包炎）、电交替）。","初步诊断":"1. 心包积液（中量，经超声证实；性质为渗出性、漏出性或血性；病因考虑结核性、病毒性、肿瘤性、尿毒症性或自身免疫性，待查；评估心脏压塞风险（依增长速度及积液量）；评估心包穿刺指征）。\n（注：治疗以病因治疗为核心，压塞者予引流，并防复发）\n①小量、无症状者：评估并治疗病因，随访超声观察积液吸收或进展；心包炎者予非甾体抗炎药或秋水仙碱（特发性及病毒性者予抗炎，促进吸收）；停用致病药物。\n②大量、有症状或压塞者：行心包穿刺引流（治疗性，可减压缓解症状；压塞属急症，应立即穿刺，详见心脏压塞章节，并送检心包液以明确诊断）；可留置导管持续引流，以防再次积聚。\n③病因治疗：结核性者予抗结核（四联方案，疗程6~12个月）加糖皮质激素（可减少粘连及缩窄，重要），大量积液者行穿刺引流；化脓性者予心包引流或切开加静脉广谱抗生素，属急症；肿瘤性者予心包内化疗（如顺铂或博来霉素注入，防复发）或心包开窗（用于反复大量恶性积液者）、心包置管引流；尿毒症性者强化透析（积液多可吸收）；自身免疫性者予激素或免疫抑制剂（依原发病）；心衰者治疗心衰（利尿）；甲减者予甲状腺素替代。\n④随访：超声（评估积液消退或复发）、心包（观察增厚及缩窄演变，需长期随访，钙化可发展为缩窄性心包炎，详见缩窄性心包炎章节，出现右心衰表现者应评估手术）、结核者完成疗程、肿瘤者随访原发病治疗、引流者待引流量减少后拔管。由心内科负责病因导向治疗（我国以结核为重点），压塞者急诊穿刺，大量或复发者行开窗，随访中重视缩窄，重要。","处理方案":"【药物治疗】\n1. 非甾体抗炎药（急性特发性/病毒感染性心包积液首选）：布洛芬缓释胶囊300mg po bid~tid（或阿司匹林0.5g po tid），餐后服，症状缓解后逐渐减量，疗程1~2周；用药期间监测消化道症状，必要时加用质子泵抑制剂（如奥美拉唑20mg po qd）保护胃黏膜。\n2. 秋水仙碱（防复发，推荐与NSAIDs联用）：0.5mg po bid（体重<70kg者0.5mg po qd），疗程3个月；肾功能不全或肝功能异常者减量，出现腹泻、恶心等不良反应时停药或减量。\n3. 对症利尿（中-大量积液伴胸闷、呼吸困难或下肢水肿者）：呋塞米片20mg po qd，晨服，根据尿量及症状调整剂量；注意监测血钾，根据患者具体情况制定个体化方案补钾（如氯化钾缓释片0.5g po tid）。若病因明确为结核性心包炎，应转诊并按规范全程抗结核化疗（如异烟肼0.3g qd+利福平0.45g qd+吡嗪酰胺1.5g qd×2个月，续以异烟肼+利福平4个月，需肝功能监测）；化脓性心包炎按药敏选用敏感抗生素静脉抗感染治疗。\n【一般治疗及生活指导】\n1. 急性期卧床休息，减少活动，避免剧烈运动及重体力劳动，以降低心脏负荷；症状缓解后逐渐恢复活动。\n2. 饮食宜清淡、易消化，中-大量积液或伴心功能不全者低盐饮食（每日食盐<5g），少量多餐，戒烟限酒，避免咖啡因及浓茶等刺激性饮品。\n3. 注意保暖，预防呼吸道感染；心包炎常与病毒感染相关，避免劳累、熬夜及受凉等诱因。\n4. 密切自我监测：如出现进行性加重的胸闷、呼吸困难、端坐呼吸、心悸、头晕或血压下降、颈静脉怒张等表现，警惕心脏压塞，需立即急诊就诊，勿自行加量利尿剂。\n【随诊要求】\n1. 1~2周内复查超声心动图评估积液量变化，以后根据积液吸收情况每2~4周复查1次，直至积液消退；大量积液或积液持续不吸收者建议心内科专科门诊随诊。\n2. 疗程结束后仍需随访3~6个月，观察有无积液复发及缩窄性心包炎发生；合并发热、胸痛者加做血常规、ESR、CRP、心肌损伤标志物及心电图等复查。\n3. 服用NSAIDs者每2~4周复查肝肾功能；服用秋水仙碱者注意监测血常规及肝肾功能；服用利尿剂者每周复查电解质。\n4. 出现心包填塞征象（气促加重、血压下降、发绀、意识改变）或经心包穿刺引流者，按医嘱定期复查，必要时复查心包积液相关病原学及脱落细胞学检查，明确病因后按病因专科随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":822,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8d0bc59d007f74bbb6fe38fe616217c36e992f476b3f60822905dd1b7820ef13","pinyin":"xinbaojiye","initials":"xbjy","setting":"out","caseName":"门诊病历690","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历690",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-eda851ed9d1bf7c9e092","key":"v1-c9ccc21dfe2a3058|templates-eda851ed9d1bf7c9e092","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心脏压塞","category":"门诊病历模板","raw":{"name":"心脏压塞","category":"门诊病历模板","case":{"case_name":"门诊病历691","templates":{"主诉":"呼吸困难、胸痛伴头晕乏力2天","现病史":"患者有明确病因（心包积液快速增多：心包炎（病毒性、结核性、尿毒症性或肿瘤性；恶性心包积液如肺癌、乳腺癌转移，为最常见病因之一）、心包积血（心脏外伤、心脏手术、主动脉夹层破裂（属急症，为血性心包）、抗凝治疗、心肌梗死后心脏破裂；心脏压塞可由任何原因导致心包积液快速或大量积聚引起）、近期心包穿刺或心脏手术史），于2天前起病（急性者见于外伤或主动脉夹层，数分钟至数小时，急剧进展至休克；亚急性者见于肿瘤、结核或尿毒症，数天至数周，逐渐加重），出现以下表现：\n呼吸困难（最常见，呈端坐呼吸，前倾位可减轻）、胸痛（心前区闷痛或锐痛）、心悸、头晕乏力。\n体征方面：低血压（收缩压下降，脉压差减小）、颈静脉怒张（右心充盈受阻）、心音遥远低钝（Beck三联征，为经典表现，但并非全部出现）、奇脉（吸气时脉搏减弱，动脉压吸气时下降>10mmHg，为特征性体征，重要）、心动过速（代偿）、肝大、腹水及水肿（亚急性者，右心衰所致）、烦躁或意识改变（心排血量骤降致休克、脑灌注不足，属急症）。\n心脏压塞属临床急症，一经怀疑应立即行超声检查及心包穿刺，时间关键。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P124次/分（增快），R26次/分（增快，呈窘迫），BP84/56mmHg（低血压），脉压差22mmHg（减小，<30mmHg）。神志清楚或烦躁、淡漠（低灌注所致）；颈静脉怒张（明显）；呼吸急促，端坐并前倾；心界扩大（心包积液所致）；心音遥远低钝；奇脉（测量时吸气收缩压下降>10mmHg，为特征）；心动过速；肝大、腹水及下肢水肿（右心衰所致）；发绀（低氧，晚期）；可见原发病体征（外伤伤口、肿瘤或尿毒症表现，需评估）。","辅助检查":"【必做】超声心动图（床旁检查，为核心及首选：心包积液（液性暗区）、心脏压塞征象（右房或右室舒张期塌陷（受压，为压塞特征）、呼吸性跨瓣血流变异增大、下腔静脉扩张固定、吸气塌陷消失（提示右房压升高）），可快速确诊，急诊同时可引导心包穿刺）。\n【影像】胸部X线（心影增大，呈烧瓶形，见于大量积液>250ml者，急性者可正常；肺野清晰，提示非心源性，可与心衰鉴别）、胸部CT（评估积液量及性质、病因、是否为包裹性）。\n【血液】血常规（感染或出血）、心肌肌钙蛋白（心肌损伤、心梗或夹层）、肝肾功能（尿毒症，为病因）、血培养（感染性心包炎）、肿瘤标志物（恶性，病因筛查）、凝血功能（抗凝或出血）。\n【心包液】心包穿刺液（常规及生化（鉴别渗出与漏出）、细胞学（肿瘤）、抗酸涂片及培养（结核）、肿瘤标志物；为病因确诊的重要检查）。\n【其他】心电图（低电压、电交替（大量积液时，为特征，较少见）、ST段改变（心包炎））、BNP（用于与心衰鉴别，心脏压塞者BNP不高）。","初步诊断":"1. 心脏压塞（心包积液（大量或快速增多）致心脏充盈受阻，引起血流动力学障碍；病因考虑心包炎、肿瘤或外伤，待查）。\n（注：心脏压塞属急症，可致死，因心排血量骤降，需紧急处理，时间关键）\n①心包穿刺引流（核心治疗，应立即进行）：紧急心包穿刺（超声引导，经剑突下或心尖入路）引流减压，缓解压塞，常可即刻显著改善症状并使血压回升；可留置导管持续引流以防复发；并送检心包液以明确病因。\n②紧急支持（同时进行，在穿刺准备期间）：静脉补液扩容，提高右心充盈压、维持心排血量，属暂时措施，重要；吸氧；避免使用利尿剂及扩血管药（可降低前负荷、加重压塞，属禁忌）。\n③病因治疗：抗凝相关者停用抗凝，予鱼精蛋白逆转（肝素）或维生素K及凝血因子（华法林）；主动脉夹层者应急诊外科手术（血性心包提示夹层，应手术，勿盲目穿刺，须先经影像明确，重要）；外伤性者行心包开窗或手术；肿瘤性者予引流加心包内化疗或心包开窗（防复发）；结核性者予抗结核；尿毒症者加强透析。\n④随访：心包积液（引流后复查超声，监测积液量及有无再次积聚）、明确病因并治疗（防复发的根本）、随访原发病。由急诊及心内科处理：心脏压塞应经床旁超声快速识别，重视Beck三联征及奇脉，对原因不明的休克伴颈静脉怒张者应想到心脏压塞，尽早超声并穿刺，分秒必争。","处理方案":"【药物治疗】\n1. 紧急扩容：0.9%氯化钠注射液500ml快速静脉滴注（15～30分钟内输完），收缩压仍<90mmHg可重复1次，总量≤1000ml，维持收缩压≥90mmHg，为心包穿刺引流争取时间。\n2. 升压支持：盐酸多巴胺注射液5～10μg/(kg·min)微量泵持续静脉泵入，据血压调整滴速，维持平均动脉压≥65mmHg，血压稳定后逐步减停。\n3. 病因治疗（心包积液送检明确病因后启用）：\n（1）结核性心包炎：异烟肼0.3g qd＋利福平0.45g qd＋吡嗪酰胺1.5g qd＋乙胺丁醇0.75g qd，强化期2个月；后改异烟肼＋利福平巩固4～10个月，总疗程6～12个月，每2周复查肝肾功能；\n（2）细菌性心包炎：万古霉素1g q12h＋头孢曲松2g qd静脉滴注，疗程4～6周，据培养及药敏结果调整；\n（3）肿瘤性心包积液：心包腔内注入顺铂30mg（每周1次，共2～3次），或按原发肿瘤病理类型制定全身化疗方案。\n【一般治疗及生活指导】\n1. 绝对卧床休息，取半卧位或坐位以减轻呼吸困难；持续心电、血压、血氧饱和度监测；避免用力、屏气、剧烈咳嗽及Valsalva动作，防止压塞加重。\n2. 确诊或高度疑诊心脏压塞应立即收住院/急诊行心包穿刺引流或心包开窗术，解除压塞是根本治疗，切勿在门诊延误。\n3. 饮食：高蛋白、高维生素、易消化软食；低盐（每日食盐<3g），适当限制液体摄入（每日1000～1500ml），减轻心包渗液；避免饱餐。\n4. 禁忌：绝对禁剧烈运动、重体力劳动及情绪激动；保持大便通畅，必要时乳果糖10ml qd通便；若正在服用华法林、利伐沙班、阿司匹林、氯吡格雷等抗凝/抗血小板药物须立即告知医师，评估停药以降低穿刺出血风险。\n【随诊要求】\n1. 心包穿刺引流术后24小时、1周、1个月复查超声心动图，评估心包积液消退及心功能恢复情况。\n2. 每周复查血常规、C反应蛋白、心电图1次；结核性者每月复查肝肾功能、胸片/胸部CT，疗程结束后继续随访2年，警惕缩窄性心包炎发生。\n3. 肿瘤性积液按肿瘤科方案定期复查随访；日常若再现胸闷、气促、端坐呼吸、血压下降或脉搏吸气时减弱（奇脉），立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":823,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a2374e615f31cb867a1a5db62f05bb32c7057184ddef667da451dc019d412b00","pinyin":"xinzangyasai","initials":"xzys","setting":"out","caseName":"门诊病历691","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历691",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0d429d76f0c2795c3e14","key":"v1-c9ccc21dfe2a3058|templates-0d429d76f0c2795c3e14","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"二尖瓣狭窄","category":"门诊病历模板","raw":{"name":"二尖瓣狭窄","category":"门诊病历模板","case":{"case_name":"门诊病历692","templates":{"主诉":"劳力性呼吸困难、心悸伴咯血8年","现病史":"患者有风湿热史（为最常见病因，我国多见，既往链球菌感染后可致风湿热，二尖瓣最常受累，潜伏10~20年后出现症状，中年女性多见；先天性者罕见，可致二尖瓣狭窄；瓣膜钙化者见于老年，属退行性变）于8年前渐出现以下表现：\n劳力性呼吸困难（为最早及最常见症状，活动后气促，进行性加重，可按NYHA行心功能分级）、乏力、心悸（房颤，因左房扩大致房性心律失常，约30~40%并发，为最常见心律失常，表现为心悸、脉搏绝对不齐，有栓塞风险）、咯血（为二尖瓣狭窄特征性表现：支气管静脉破裂可致大咯血（少见，属急症）；痰中带血因肺泡毛细血管破裂所致；粉红色泡沫痰提示急性肺水肿（属急症，因左房压骤升））、咳嗽（肺淤血所致）、声音嘶哑（因增大的左房或肺动脉压迫左喉返神经，即Ortner综合征，少见）、吞咽困难（食管受压所致）、端坐呼吸及夜间阵发性呼吸困难（肺淤血加重，多见于晚期；急性肺水肿属急症，诱因包括房颤伴快心室率、感染、妊娠、输液过快）、下肢水肿（右心衰，晚期出现）。\n此外：无风湿热史（关节痛、舞蹈病等既往史）；体检发现心尖区舒张期隆隆样杂音（为特征，常为首诊线索）；无妊娠（二尖瓣狭窄者妊娠时血容量增加，可致代偿失调及肺水肿风险，孕前应评估）。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P92次/分（房颤时脉搏短绌，心率>脉率），R20次/分，BP116/72mmHg。二尖瓣面容（重度狭窄者可见双颧绀红，为特征，因低心排及肺动脉高压所致）；心尖区舒张期隆隆样杂音（特征性，局限于心尖区，左侧卧位或运动后呼气末明显）；开瓣音（二尖瓣开放音，提示瓣叶活动度好，紧跟S2，为狭窄特征）；S1亢进（瓣膜增厚但活动度好，呈拍击样）；若S1减弱或开瓣音消失，提示瓣叶钙化僵硬，见于重度狭窄；肺动脉瓣第二心音亢进或分裂（肺动脉高压所致）；Graham-Steell杂音（肺动脉瓣相对关闭不全，因肺动脉高压所致，呈舒张期吹风样，位于胸骨左缘）；右心衰体征（肝大、颈静脉怒张、下肢水肿，晚期）；房颤（心律绝对不齐，心音强弱不等，脉搏短绌）；肺部可闻及湿啰音（肺淤血，急性肺水肿时）。","辅助检查":"【必做】超声心动图（确诊及评估的核心检查：二尖瓣口面积（正常4~6cm²，狭窄分级为轻度>1.5cm²、中度1.0~1.5cm²、重度<1.0cm²）、瓣膜形态（增厚、钙化及活动度，行Wilkins评分，用于选择介入或手术方式）、跨瓣压差、左房大小（扩大）、肺动脉压估测、有无血栓（左房及左心耳，房颤或有栓塞者应行经食管超声评估，重要）、是否合并其他瓣膜病变（主动脉瓣等，风湿性者常为多瓣膜受累））；心电图（左房肥大（P波增宽呈双峰，即二尖瓣P波）、房颤、右室肥大（晚期，肺动脉高压所致））；胸部X线（左房增大（心影呈梨形，即二尖瓣型心）、肺动脉段突出、Kerley B线（肺淤血、间质水肿）、双肺淤血）。\n【其他】心导管（用于介入前测量左房压及肺动脉压、评估瓣口面积，超声不清时患者）、冠状动脉造影（术前评估，>40岁者用于除外冠心病）。\n【评估】风湿活动（ASO、血沉，活动期影响治疗决策）、感染性心内膜炎预防（高危者于牙科操作前预防性使用抗生素）、妊娠（评估心功能，行孕前咨询）。","初步诊断":"1. 二尖瓣狭窄（风湿性，瓣口面积1.2cm²，属中度狭窄；评估并发症：房颤、栓塞、肺水肿及右心衰）。\n（注：治疗依狭窄程度、症状及并发症决定，包括内科、介入及外科治疗）\n①内科治疗（用于轻度及无症状者）：随访（定期超声评估进展）；预防风湿热复发（年轻或风湿性者予长效青霉素，即苄星青霉素，每月1次，至40岁或终身，重要，可防瓣膜进一步损害）；感染性心内膜炎预防（牙科或手术操作前予抗生素，用于高危患者）；对症治疗（房颤者控制心室率（β受体阻滞剂或地高辛）；快心室率致肺水肿属急症，予西地兰并控制心率；房颤或有栓塞史者予抗凝（华法林，维持INR2~3，或NOAC），以预防栓塞，脑栓塞风险重要，机械瓣者须用华法林；肺淤血或右心衰者予利尿剂（呋塞米），应适度；急性肺水肿属急症，予端坐位、吸氧、利尿（呋塞米静注）、吗啡（镇静、减少前负荷）、控制心率，避免使用扩血管药（二尖瓣狭窄者左室充盈依赖前负荷，扩血管降低前负荷可加重病情，应慎用，重要，其处理不同于左心衰））。\n②介入治疗：经皮二尖瓣球囊成形术（PBMV），适用于中重度单纯狭窄且瓣膜条件好（无钙化、无左房血栓、无严重关闭不全）者，为首选，适应证为症状性中度以上狭窄，或无症状重度狭窄但并发症风险高者；疗效好，创伤小。\n③外科治疗：二尖瓣置换术（MVR），适用于瓣膜条件差（钙化僵硬）、合并关闭不全、左房血栓或介入禁忌者，可选机械瓣（需终身抗凝，维持INR2.5~3.5，适用于年轻者）或生物瓣（无需长期抗凝，适用于老年、不愿抗凝或计划妊娠者）；二尖瓣成形术（条件合适者尽量保留自身瓣膜）；手术时机为症状明显、肺动脉高压或栓塞者，NYHA≥Ⅱ级。\n④并发症处理：栓塞（脑栓塞者予抗凝，急性期行溶栓或取栓，由神经科处理）、感染性心内膜炎（发热者行血培养并予抗生素）、右心衰（予利尿，晚期）。\n⑤随访：超声（定期复查，轻中度者每1~2年，重度者每6~12个月，评估进展）、症状（心功能变化）、抗凝监测（华法林者规律监测INR）、妊娠（重度狭窄者患者孕前行介入或手术，孕期加强管理，由心内科与产科协作）。由心内科及心外科多学科协作，个体化确定介入或手术时机。","处理方案":"【药物治疗】\n1. 苄星青霉素120万U，深部肌内注射，每4周1次，长期预防用药（风湿性二尖瓣狭窄者预防风湿热复发，至少持续10年或至40岁；青霉素过敏者改用红霉素250mg，每日2次口服）\n2. 华法林钠片2.5mg，每日1次口服，起始后根据INR调整剂量，维持INR 2.0~3.0（合并心房颤动或既往体循环栓塞史者需长期抗凝，初期每周监测INR，稳定后每月1次）\n3. 呋塞米片20mg，每日1次口服（活动后气促、肺淤血明显者可增至20~40mg每日1~2次），联用螺内酯片20mg每日1次以预防低钾；合并心房颤动心室率快者加用美托洛尔缓释片47.5mg，每日1次口服，或地高辛片0.125mg每日1次口服，控制静息心率<80次/分\n\n【一般治疗及生活指导】\n1. 休息与活动：根据心功能分级限制活动量，避免剧烈运动、重体力劳动及突然用力，以活动后不出现心悸、气促为度；心功能Ⅲ~Ⅳ级者以卧床休息为主，采取半卧位减轻肺淤血\n2. 饮食与生活：低盐饮食（每日食盐<5g），少量多餐，控制体重；戒烟限酒，注意保暖、避免呼吸道感染及链球菌感染；保持口腔卫生，拔牙、导尿等有创操作前患者心脏病情并评估抗感染用药；育龄期女性应严格避孕，妊娠将显著加重心脏负荷\n\n【随诊要求】\n每3~6个月门诊复查心脏超声心动图（动态评估瓣口面积及肺动脉压）、心电图（监测心律及心室率）、胸片；口服华法林者定期监测INR。若出现静息气促、咯血、心悸明显加重、发热、双下肢水肿或夜间不能平卧，应随时就诊。症状进行性加重、二尖瓣瓣口面积<1.5cm²或肺动脉压显著升高者，建议转心内科/心外科评估经皮二尖瓣球囊成形术（PBMV）或二尖瓣置换手术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":824,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ef35ce1f4e8b20f0f86cc4cad207874725832876daf7041a77cbe65a69566bc3","pinyin":"erjianbanxiazhai","initials":"ejbxz","setting":"out","caseName":"门诊病历692","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历692",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4af92a6b647470d22b51","key":"v1-c9ccc21dfe2a3058|templates-4af92a6b647470d22b51","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"二尖瓣关闭不全","category":"门诊病历模板","raw":{"name":"二尖瓣关闭不全","category":"门诊病历模板","case":{"case_name":"门诊病历693","templates":{"主诉":"劳力性气短、乏力伴心悸6个月","现病史":"患者因二尖瓣关闭不全的病因（退行性者可见瓣膜脱垂，即二尖瓣脱垂伴黏液样变性，为最常见病因，多见于发达国家中老年；腱索断裂（自发性或心内膜炎所致，可致急性关闭不全）；风湿性者（我国多见，风湿性心脏病可致二尖瓣关闭不全，常伴狭窄，有风湿热史）；缺血性者（冠心病致乳头肌功能不全或梗死，引起缺血性二尖瓣关闭不全，心梗后常见）；功能性者（左室扩大致瓣环扩张，多见于心衰，二尖瓣反流可加重心衰，形成恶性循环）；感染性心内膜炎（瓣膜破坏致急性关闭不全，属急症）；先天性（瓣叶裂，少见）；心肌病）\n呈慢性过程（渐进发展，数年，可代偿）或急性起病（腱索断裂或心内膜炎所致，突发急性肺水肿，属急症），于6个月前出现以下表现：\n慢性者：劳力性呼吸困难（早期为活动后气短，渐进加重）、乏力（低心排所致）、心悸（房颤，因左房扩大）、咳嗽；代偿期可无症状数年；后期出现端坐呼吸及肺水肿（左心衰所致）、右心衰（水肿）。\n急性者：突发严重呼吸困难及肺水肿（咳粉红色泡沫痰）、低血压（急性反流致心排血量下降，可致休克）。\n体征：心尖部全收缩期吹风样杂音（向左腋下传导，为特征，见于二尖瓣关闭不全）、S1减弱、S3（心衰所致）、肺动脉瓣第二心音亢进（肺动脉高压）、心界扩大（左心扩大）、房颤。\n诱因：感染（心内膜炎者可有发热及新出现杂音，应查血培养，属急症，需评估）、心梗（缺血性者因乳头肌受累）。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P88次/分，R20次/分，BP118/74mmHg。心尖搏动左下移位并呈抬举样（左室大所致）；心界向左下扩大；心尖部收缩期杂音（全收缩期，呈吹风样，向左腋下及左肩胛传导（反流束方向因前叶或后叶受累而异））；S1减弱（瓣膜病变所致）；S3奔马律（心衰）；肺动脉瓣第二心音亢进（肺动脉高压，晚期）；房颤（心律绝对不齐）；肺部可闻及湿啰音（左心衰）；颈静脉怒张、肝大及水肿（右心衰，晚期）；急性者可出现急性肺水肿表现（端坐呼吸、咳粉红色泡沫痰、低血压）。","辅助检查":"【必做】超声心动图（核心检查：二尖瓣反流（彩色多普勒评估反流程度，分轻、中、重度，可测反流束面积、反流口面积及反流分数）、病因（瓣膜脱垂（瓣叶收缩期脱入左房）、腱索断裂（连枷样瓣叶）、风湿性（瓣叶增厚钙化）、瓣环扩大）、左房及左室大小（扩大，容量负荷所致）、射血分数（为手术时机的核心指标）、肺动脉压、是否合并狭窄或其他瓣膜病变）；心电图（左房大（P波增宽）、左室大、房颤）；胸部X线（左房大（心影改变）、肺淤血（心衰））。\n【血液】BNP（心衰）、心肌肌钙蛋白（心梗，缺血性者）、血培养（心内膜炎，发热疑诊者重要，必查）。\n【其他】心脏MRI（反流定量，反流分数为金标准定量方法，用于手术决策及重度反流评估）、经食管超声（精细评估反流机制，用于术前及心内膜炎查赘生物）、心导管（术前评估，>40岁者行冠脉造影评估冠脉，缺血性者适用；并测血流动力学）。","初步诊断":"1. 二尖瓣关闭不全（慢性，病因为退行性、风湿性、缺血性或功能性；反流程度为中度（经彩色多普勒及MRI反流分数评估）；左室大小及射血分数60%；评估房颤及心衰情况）。\n（注：治疗依反流程度、症状及左室功能决定，包括内科及手术治疗）\n①内科治疗（用于轻中度无症状者）：随访（超声每1~2年复查，监测反流进展、左室大小及射血分数）；预防感染性心内膜炎（高危者于牙科操作前予抗生素）；房颤（控制心室率（β受体阻滞剂或地高辛）；按CHA2DS2-VASc评分予抗凝（华法林或NOAC），预防栓塞，重要）；心衰（予利尿剂；扩血管药（血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂）可降低后负荷、减少反流，重要，慢性重度且射血分数降低者按心衰金标准方案治疗）；急性者（应住院，予硝普钠降低后负荷以减少反流，待稳定后行急诊手术；腱索断裂或心内膜炎所致急性重度者属急症）。\n②手术治疗：指征为慢性重度伴症状（NYHAⅡ级以上）者应手术，术式以瓣膜修复为首选，优于置换（可保留自身瓣膜、功能好、免于抗凝）；无症状重度者若左室功能受损（射血分数<60%）或左室扩大（收缩末径≥40mm），或新发房颤、肺动脉高压，亦应手术，以防不可逆损伤，重要，时机上若射血分数<50%再手术则预后差；缺血性或功能性者予血运重建（经皮冠状动脉介入或搭桥）加瓣膜修复，需评估。手术方式包括二尖瓣修复术（成形，如瓣环成形或腱索重建，脱垂者修复率高，>90%，为首选，可保留瓣膜，优于置换）、置换术（用于修复失败或瓣膜严重破坏者，可选机械瓣（需终身抗凝，维持INR2.5~3.5，适用于年轻者）或生物瓣（适用于老年或抗凝禁忌者））、经导管缘对缘修复（MitraClip，以夹合方式治疗，适用于重度反流且不能手术或高危者，重要，属新兴技术）。\n③感染性心内膜炎所致急性关闭不全：予抗生素加急诊手术（瓣膜破坏致心衰者应手术，清除感染灶并置换瓣膜）。\n④随访：轻度者每年复查超声，中重度者每6~12个月复查，监测左室及射血分数，把握手术时机（接近临界者应密切随访）；术后随访（修复者评估有无残留或复发反流；置换者监测抗凝（机械瓣监测INR）、预防心内膜炎）；房颤者长期抗凝。由心内科及心外科协作，重度反流应把握手术时机（在左室功能不可逆前手术，重要），首选修复，急性者需急诊手术，重要。","处理方案":"【药物治疗】\n1. 缬沙坦胶囊（血管紧张素Ⅱ受体拮抗剂，降低后负荷、减轻反流、延缓左心室重构，伴高血压或无症状性中重度反流者均可选用）80mg qd 口服，长期服用，依据血压及耐受性调整剂量（亦可选依那普利片5mg bid）\n2. 琥珀酸美托洛尔缓释片（β受体阻滞剂，合并心房颤动或心功能不全者控制心室率）23.75mg qd 口服，长期服用，目标静息心率55~60次/分，逐渐加量\n3. 呋塞米片（袢利尿剂，出现活动后气促、肺淤血、下肢水肿等充血性心衰症状时加用）20mg qd 口服，症状缓解后减量或停用，疗程1~2周后评估；合并心房颤动者加用利伐沙班片20mg qd 抗凝，长期服用，定期评估出血风险\n\n【一般治疗及生活指导】\n1. 低盐饮食（每日食盐<5g）、限制液体摄入，戒烟限酒，避免剧烈运动、重体力劳动及屏气用力（如举重、用力排便），注意休息，预防呼吸道感染\n2. 积极控制高血压、糖尿病、冠心病等基础疾病；保持口腔卫生，牙科操作及有创诊疗前预防性使用抗生素（如阿莫西林胶囊2g，操作前1小时口服），预防感染性心内膜炎；出现发热、寒战等感染征象时及时就诊\n\n【随诊要求】\n每3~6个月复查心电图及超声心动图，动态监测左心室大小、射血分数与反流程度；出现气促加重、乏力、心悸、下肢水肿等新发症状时随时就诊；重度反流伴左心室扩大或射血分数下降者，转心脏外科评估瓣膜手术时机"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":825,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8eee3e2c6f6277e191317babb78bce53cfd627eb054d3fe582de74b3ce21aece","pinyin":"erjianbanguanbibuquan","initials":"ejbgbbq","setting":"out","caseName":"门诊病历693","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历693",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5b8796a34d85c521b5f5","key":"v1-c9ccc21dfe2a3058|templates-5b8796a34d85c521b5f5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"主动脉瓣关闭不全","category":"门诊病历模板","raw":{"name":"主动脉瓣关闭不全","category":"门诊病历模板","case":{"case_name":"门诊病历694","templates":{"主诉":"活动后气短、心悸伴胸痛3年","现病史":"患者因主动脉瓣关闭不全的病因（主动脉根部或瓣环扩张（高血压、主动脉夹层；Marfan综合征可致主动脉根部扩张及关闭不全，多见于青年，身材高瘦、指长等马凡体征）、主动脉炎（梅毒或大动脉炎）、瓣膜病变（风湿性者常合并狭窄、感染性心内膜炎（瓣膜破坏致急性关闭不全，属急症）、先天性（二叶主动脉瓣）、退行性变）），呈急性（感染性心内膜炎或主动脉夹层所致，突发急性左心衰，属急症，可致肺水肿及休克）或慢性过程（风湿性、退行性或根部扩张所致，渐进发展，长期无症状，处代偿期），于3年前起病（急性者病程数小时至数天，表现为呼吸困难、端坐呼吸及粉红色泡沫痰，属急症；慢性者病程数年，逐渐出现症状），出现以下表现：\n活动后气短（最早出现，进行性加重）、心悸（左室扩大、收缩力增强，自觉心跳感强）、劳力性心绞痛（主动脉瓣关闭不全者舒张压降低致冠脉灌注不足，为其特征，舒张压极低时即使无冠脉狭窄亦可出现心绞痛）、头晕或晕厥（脑灌注不足，因舒张压低所致）、晚期左心衰（夜间阵发性呼吸困难、端坐呼吸、肺水肿）、急性关闭不全（属急症，突发呼吸困难、胸痛及休克，可致心源性休克，需急诊手术）、感染性心内膜炎（发热、新出现杂音，应查血培养）。\n此外：有高血压病史；无Marfan综合征；无风湿热史；无心脏手术史；无静脉吸毒史（心内膜炎相关）。今日来我院心内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P86次/分（脉压大，呈水冲脉，收缩压高、舒张压低），R20次/分，BP152/56mmHg（脉压增大（收缩压升高、舒张压降低，>60~80mmHg，见于慢性重度者））；周围血管征（为主动脉瓣关闭不全特征：水冲脉（Corrigan脉，桡动脉骤起骤落）、枪击音（股动脉听诊，Duroziez征）、毛细血管搏动（轻压指甲可见红白交替，Quincke征）、点头征（De Musset征，颈动脉搏动致头部随心跳点动）、股动脉枪击音（Traube征））；心尖搏动左下移位并呈抬举样（左室扩大所致）；心界向左下扩大；主动脉瓣区及胸骨左缘第3肋间舒张期叹气样杂音（呈递减型，前倾位呼气末明显，为特征，向心尖传导（反流束方向））、Austin Flint杂音（重度反流者心尖部舒张期隆隆样杂音，为相对二尖瓣狭窄，因反流冲撞二尖瓣前叶所致）、S2减弱或单一（瓣膜病变所致）；肺部可闻及湿啰音（左心衰）；下肢水肿（晚期）。","辅助检查":"【必做】超声心动图（确诊及评估核心：主动脉瓣反流（彩色多普勒评估反流程度，可测反流束宽度及反流分数）、左室大小及功能（左室舒张末径扩大、收缩功能即射血分数，为手术时机的关键指标）、主动脉根部（有无扩张，Marfan或夹层相关）、瓣膜形态（二叶瓣或赘生物，心内膜炎相关）；急性者左室大小可正常，但舒张压急升，需评估）；心电图（左室肥大伴劳损、电轴左偏）；胸部X线（左室增大（呈靴形心）、主动脉增宽迂曲（升主动脉或根部病变）、肺淤血（心衰））。\n【其他】心脏MRI（反流定量，反流分数为金标准定量方法；并评估主动脉形态，用于疑难病例）、心导管及冠脉造影（术前评估，年龄>40岁者行冠脉评估；并测压力）、血培养（疑感染性心内膜炎者，急性者必查）、风湿活动（ASO、血沉）、Marfan相关基因及眼晶状体检查（评估马凡综合征）、梅毒血清学（主动脉炎，少见病因，应筛查）。","初步诊断":"1. 主动脉瓣关闭不全（反流程度为重度；属慢性；病因考虑风湿性、感染性心内膜炎或主动脉根部扩张（Marfan），待查）。\n（注：治疗依症状、反流程度及左室功能决定，包括内科及手术治疗）\n①内科治疗（用于慢性轻中度无症状者）：随访（超声每1~2年复查，监测左室大小及射血分数，以判断手术时机）；治疗基础病（高血压者控制血压，予扩血管药（硝苯地平或ACEI）以降低反流、减轻负荷，血管扩张剂适用于慢性重度有症状而不宜手术者，属重要内科治疗；预防感染性心内膜炎（高危者于牙科操作前予抗生素）、梅毒者驱梅治疗、Marfan者予β受体阻滞剂（可减慢主动脉扩张）、房颤者抗凝、左心衰者予利尿（呋塞米）加ACEI；急性失代偿者应住院，予静脉硝普钠降低后负荷以减少反流，待稳定；急性肺水肿属急症，应予处理（静脉扩血管加利尿；但主动脉夹层所致急性关闭不全者勿用扩血管药，需急诊手术））。\n②外科治疗：主动脉瓣置换术（AVR），手术指征为重度反流伴症状（NYHA≥Ⅱ级）者均应手术，不手术则预后差；无症状重度者若左室功能受损（射血分数<50%）或左室显著扩大（舒张末径>70mm或收缩末径>50mm），亦应手术，以防不可逆心衰；急性重度者属急症，应急诊手术（心内膜炎或夹层者明确病因后立即手术）。瓣膜可选机械瓣（需终身抗凝，适用于年轻者）或生物瓣（适用于老年或抗凝禁忌者）。主动脉根部扩张者（Marfan）若升主动脉>50mm或快速增大，应行根部置换加瓣膜手术（Bentall手术，即复合带瓣管道），以防夹层，重要。\n③病因手术：感染性心内膜炎伴严重反流、心衰或脓肿者应早期手术，予清创加瓣膜置换，并完成抗感染疗程。\n④随访：超声（术后评估瓣膜功能及置换情况；未手术的重度者每6~12个月复查，临界时缩短间隔）、抗凝监测（机械瓣者监测INR）、预防心内膜炎。由心内科及心外科协作，重度反流者手术时机关键（患者左室功能不可逆前手术，重要，射血分数<50%再手术则预后差，需早期识别）。","处理方案":"【药物治疗】\n1. 硝苯地平控释片30mg，每日1次口服，长期服用，为无症状重度主动脉瓣关闭不全伴左室扩大者的首选扩血管治疗，可降低左室后负荷、减少反流量，延缓左室扩大及手术时间；服药期间自测血压，警惕低血压及头痛、面部潮红等不良反应。\n2. 缬沙坦胶囊80mg每日1次口服（或培哚普利片4mg每日1次），为合并高血压者的首选ACEI或ARB类降压药，目标血压<130/80mmHg，以进一步减轻反流；长期服用，用药后1-2周复查肾功能、血钾，肌酐明显升高者复诊调整。\n3. 呋塞米片20mg每日1次加螺内酯片20mg每日1次，于出现活动后气促、双下肢水肿等心衰症状时口服利尿，症状缓解后遵医嘱减量或停用，每周复查电解质、肾功能；合并心房颤动心室率快者加用地高辛片0.125mg每日1次控制心室率。\n\n【一般治疗及生活指导】\n1. 活动：无症状轻、中度反流者可正常生活，避免举重、竞技性运动等爆发性等长运动及重体力劳动；宜行快走、游泳等中等强度有氧运动，以运动后不出现胸闷、心悸为度；重度反流或有症状者限制活动、注意休息。\n2. 饮食：低盐低脂饮食，每日食盐摄入<5g，合并心衰时<3g；戒烟限酒、避免饱餐，控制体重于正常范围。\n3. 预防感染：注意口腔卫生，早晚刷牙、饭后漱口，定期牙科检查；拔牙、口腔及泌尿生殖道有创操作前主动告知主动脉瓣病变史，人工瓣膜置换或既往感染性心内膜炎史等高危者于操作前1小时预防性口服阿莫西林2g（青霉素过敏者用克林霉素600mg）；每年接种流感疫苗，建议接种肺炎球菌疫苗；发热持续不退及时就医，排查感染性心内膜炎。\n4. 禁忌：遵医嘱规律服药，不可自行停药或减量；避免感冒受凉及过度劳累诱发心衰。\n\n【随诊要求】\n每3-6个月门诊复诊，复测血压、心电图、胸片；超声心动图每6-12个月复查（重度反流每6个月），重点监测左室舒张末期内径及射血分数；合并高血压者每月自测血压。出现活动后气促、心悸、心前区不适、晕厥，或超声提示左室进行性扩大、射血分数<50%时，及时就诊，评估主动脉瓣置换术时机。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":826,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ecb18139d30453b60acdc4f28b9793ceaf558a1b831214d481372e7311aac801","pinyin":"zhudongmaibanguanbibuquan","initials":"zdmbgbbq","setting":"out","caseName":"门诊病历694","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历694",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4dc379933aadaf6e4813","key":"v1-c9ccc21dfe2a3058|templates-4dc379933aadaf6e4813","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"三尖瓣狭窄","category":"门诊病历模板","raw":{"name":"三尖瓣狭窄","category":"门诊病历模板","case":{"case_name":"门诊病历695","templates":{"主诉":"腹胀1天","现病史":"患者1周前无明显诱因出现三尖瓣狭窄相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以腹胀1天为主诉，1周来症状逐渐加重并伴乏力，初步诊断三尖瓣狭窄，三尖瓣狭窄致右心房压力升高、体循环淤血，需评估贫血与感染状况，完善血常规检查排除感染、贫血；患者体循环淤血常累及肝肾功能并引起水钠潴留、电解质紊乱，完善尿常规检查了解有无蛋白尿及肾功能受损，完善便常规检查排除消化道出血及肠道感染，完善肝肾功能检查了解肝功能受损程度，完善血糖、血脂检查评估基础代谢状况及心血管危险因素，完善电解质检查排除电解质紊乱所致心律失常；入院即刻完善心电图检查了解有无右心房扩大、心房颤动及传导异常；完善胸部X线片检查了解心影大小、右心房增大及肺血情况；三尖瓣狭窄常合并肝脾淤血，完善腹部超声检查了解肝脾大小、有无腹水及肝静脉淤血，解释腹胀原因；必要时可进一步行心脏超声检查评估三尖瓣瓣口面积、跨瓣压差及合并的其他瓣膜病变；余根据病情需要选择相应检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 三尖瓣狭窄\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 呋塞米片20mg qd晨服（依据尿量、晨起体重及水肿程度调整，必要时增至20mg bid），联合螺内酯片20mg qd口服，疗程视右心淤血症状而定，减轻右心负荷、缓解颈静脉怒张及下肢水肿\n2. 合并心房颤动者：琥珀酸美托洛尔缓释片47.5mg qd口服，静息心室率控制在60~80次/分；同步予华法林钠片2.5mg qd起始口服抗凝（无禁忌证时），定期监测INR，维持于2.0~3.0\n3. 风湿性病因者：苄星青霉素120万U im，每月1次，长期预防风湿活动复发；并发右心衰竭时可加用洋地黄类药物，但须警惕右心衰竭时洋地患者感及毒性反应\n\n【一般治疗及生活指导】\n1. 低盐饮食（每日食盐<5g）、少食多餐、避免饱餐及短时间内大量饮水，减轻右心前负荷；戒烟限酒\n2. 注意休息、避免剧烈运动及重体力劳动，可进行散步等轻度活动；每日晨起空腹称体重并记录，3天内体重增加>2kg提示液体潴留；注意保暖、预防呼吸道感染，及时治疗链球菌感染（咽痛、发热时尽早就诊）\n\n【随诊要求】\n每1~3个月门诊复诊（心衰症状明显或调整利尿剂期间每2~4周复诊），复查心电图、胸部X线、超声心动图评估狭窄程度及右心大小；长期服利尿剂者定期复查血电解质、肝肾功能；服华法林者按医嘱定期监测INR；若出现呼吸困难进行性加重、下肢水肿加重、心悸、晕厥或咯血等，立即就诊；重度狭窄伴明显症状且药物控制不佳者，及时转心外科评估经皮球囊扩张术或三尖瓣置换术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":827,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dd21c9dadc3094325e61624d6d1b0ad5fbc4a35ab9f6173fe6b8cd8dc0a7d10d","pinyin":"sanjianbanxiazhai","initials":"sjbxz","setting":"out","caseName":"门诊病历695","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历695",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-530e958cc70011334bb8","key":"v1-c9ccc21dfe2a3058|templates-530e958cc70011334bb8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"三尖瓣关闭不全","category":"门诊病历模板","raw":{"name":"三尖瓣关闭不全","category":"门诊病历模板","case":{"case_name":"门诊病历696","templates":{"主诉":"腹胀1天","现病史":"患者1周前无明显诱因出现三尖瓣关闭不全相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以腹胀1天为主诉，1周来症状逐渐加重并伴乏力，初步诊断三尖瓣关闭不全，三尖瓣关闭不全引起右心室容量负荷增加与体循环淤血，完善血常规检查排除感染、贫血；患者体循环淤血常累及肝肾功能并伴水钠潴留，完善尿常规检查了解有无蛋白尿及肾功能受损，完善便常规检查排除消化道出血及肠道感染，完善肝肾功能检查了解肝淤血所致肝功能异常，完善血糖、血脂检查评估心血管基础危险因素，完善电解质检查排除电解质紊乱及利尿剂所致失衡；入院即刻完善心电图检查了解有无右心房扩大、心房颤动及不完全性右束支传导阻滞；完善胸部X线片检查了解心影大小、右心增大及肺血情况；查心脏超声了解三尖瓣反流程度、瓣环扩大、右心室大小及肺动脉压力，评估手术指征；三尖瓣关闭不全常合并肝脾淤血，完善腹部超声检查了解肝脾大小、下腔静脉宽度、有无腹水及肝静脉淤血，明确腹胀原因；余根据病情需要选择相应检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 三尖瓣关闭不全\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 呋塞米片20mg qd晨服，水肿明显时20mg bid，水肿消退后据体重间歇维持（如隔日1次），疗程视容量负荷情况调整，注意补钾并监测血钾，为三尖瓣反流伴右心衰竭容量负荷过重者的首选。\n2. 螺内酯片20mg qd，与呋塞米联合长期维持，保钾、拮抗心肌纤维化，每月复查血钾及肾功能\n3. 合并心房颤动者：琥珀酸美托洛尔缓释片47.5mg qd控制心室率（静息心率目标<80次/分），并予利伐沙班15mg qd抗凝（或华法林维持INR 2.0~3.0），房颤持续者长期服用\n\n【一般治疗及生活指导】\n1. 低盐饮食：每日食盐<5g，避免腌制及加工食品；监测体重，每日晨起空腹称重，3日内体重增加>2kg提示容量负荷加重，应复诊调药\n2. 避免剧烈运动、重体力劳动及久站久坐，病情稳定期可行散步等低强度有氧活动；戒烟限酒，避免妊娠\n3. 预防呼吸道感染（感冒可诱发右心衰竭急性加重）；注意口腔卫生，拔牙、内镜等有创操作前告知心脏病史\n\n【随诊要求】\n1. 每3~6个月门诊复查心脏彩超，动态评估三尖瓣反流程度、右心房室大小及右心功能\n2. 长期服利尿剂者每1~3个月复查电解质、肝肾功能；出现活动后气促加重、下肢及颜面水肿、腹胀、食欲减退等右心衰加重表现时立即就诊\n3. 重度三尖瓣反流伴明显症状或右心功能进行性减退者，建议心外科就诊评估三尖瓣成形术或置换术时机"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":828,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4390cf525975fa08caa34d03a8b1657e4b8e4ba0a90246356d91fc2ff8c8127d","pinyin":"sanjianbanguanbibuquan","initials":"sjbgbbq","setting":"out","caseName":"门诊病历696","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历696",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-00edcb25763046094a6d","key":"v1-c9ccc21dfe2a3058|templates-00edcb25763046094a6d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺动脉瓣狭窄","category":"门诊病历模板","raw":{"name":"肺动脉瓣狭窄","category":"门诊病历模板","case":{"case_name":"门诊病历697","templates":{"主诉":"气短1天","现病史":"患者1周前无明显诱因出现肺动脉瓣狭窄相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以气短1天为主诉，1周来症状逐渐加重并伴乏力，初步诊断肺动脉瓣狭窄，需先除外感染所致气短，完善血常规检查排除感染、贫血，完善CRP检查了解有无炎症反应，完善降钙素原检查鉴别细菌感染与肺动脉瓣狭窄所致右心功能不全表现；入院即刻完善胸部X线片检查了解心影大小、肺动脉段突出及肺血减少情况，胸部CT检查进一步了解右心室流出道、肺动脉发育及有无合并肺部疾病；完善心电图检查了解有无右心室肥厚、右心房扩大及电轴右偏；查心脏超声评估肺动脉瓣跨瓣压差、瓣口面积、右心室肥厚程度，明确狭窄严重程度并指导介入或手术时机；完善血气分析检查了解有无低氧血症及二氧化碳潴留，评估肺通气功能与右心功能不全程度；患者如合并咳嗽咳痰，完善痰培养+药敏检查明确病原菌并指导抗感染治疗；病情稳定后完善肺功能检查评估肺通气功能，与慢性肺部疾病所致肺动脉高压鉴别；据病情需要完善动态心电图检查排除心律失常。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 肺动脉瓣狭窄\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 预防感染性心内膜炎：牙科及有创操作（如内镜、拔牙等）前1小时口服阿莫西林胶囊2.0g单次顿服；青霉素过敏者改用克林霉素胶囊600mg单次顿服，以降低感染性心内膜炎风险。\n2. 右心功能不全（出现水肿、肝大、颈静脉怒张时）对症治疗：呋塞米片20mg qd口服，视水肿消退情况可增至40mg qd，联用螺内酯片20mg qd，疗程1~2周后依据症状、体重及电解质监测结果调整，症状缓解后渐减停。\n3. 合并心房颤动或难治性右心衰竭时加用地高辛片0.125~0.25mg qd口服，长期维持，用药期间定期监测血药浓度及心电图，警惕洋地黄中毒（恶心、黄视、室性心律失常）。\n4. 反复发生肺部感染、右心衰竭的严重狭窄患者，若跨瓣压差明显增大（>50mmHg）或出现晕厥、胸痛等症状，应转诊行经皮球囊肺动脉瓣成形术（PBPV）或外科瓣膜切开术治疗，药物治疗不能替代解除梗阻。\n\n【一般治疗及生活指导】\n1. 休息与活动：无症状或轻中度狭窄者可正常日常活动并从事一般体育锻炼，但应避免竞技性运动、剧烈体力活动和长时间憋气用力的项目；重度狭窄或有症状者注意休息、避免劳累，活动量以不诱发气促、心悸为度。\n2. 饮食：低盐低脂饮食，每日食盐摄入<5g，少食腌制及油炸食品，均衡营养，控制体重，多食富含维生素及膳食纤维的食物。\n3. 日常防护：注意保暖，预防呼吸道感染，戒烟并避免二手烟及酗酒；保持口腔卫生，定期牙科检查，避免不洁牙科操作诱发感染性心内膜炎。\n4. 自我监测：出现活动后气促、心悸、胸痛、黑矇、晕厥、下肢水肿等表现时及时就诊；育龄女性计划妊娠前应先行超声心动图评估狭窄程度及心功能。\n\n【随诊要求】\n1. 无症状轻中度狭窄患者每1~2年复查心电图及超声心动图，评估跨瓣压差及右室负荷变化；重度狭窄或跨瓣压差进行性增大者每3~6个月复查1次，动态评估介入或手术指征。\n2. 行PBPV或外科手术者，术后1、3、6、12个月各复查超声心动图1次，此后每年复查1次，评估残余狭窄及肺动脉瓣关闭不全情况。\n3. 随访期间一旦出现新发症状（晕厥、胸痛、明显气促、右心衰竭表现）或心电图新出现心律失常，应立即复诊，必要时行心导管检查明确血流动力学状态。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":829,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0d568b4ebe3d3b4780f5a9aa3bee03a6dfb85c14972876e715f65e354f52ebc4","pinyin":"feidongmaibanxiazhai","initials":"fdmbxz","setting":"out","caseName":"门诊病历697","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历697",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-af8fe51fc7c142fd672e","key":"v1-c9ccc21dfe2a3058|templates-af8fe51fc7c142fd672e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺动脉瓣关闭不全","category":"门诊病历模板","raw":{"name":"肺动脉瓣关闭不全","category":"门诊病历模板","case":{"case_name":"门诊病历698","templates":{"主诉":"气短1天","现病史":"患者1周前无明显诱因出现肺动脉瓣关闭不全相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以气短1天为主诉，1周来症状逐渐加重并伴乏力，初步诊断肺动脉瓣关闭不全，需先除外感染及贫血所致气短，完善血常规检查排除感染、贫血，完善CRP检查了解有无炎症反应，完善降钙素原检查鉴别细菌感染与右心功能不全所致气短；入院即刻完善胸部X线片检查了解心影大小、肺动脉段及肺血情况，胸部CT检查进一步了解肺动脉扩张程度、右心室大小及有无合并肺部基础疾病；完善心电图检查了解有无右心室肥厚、右束支传导阻滞及心律失常；查心脏超声评估肺动脉瓣反流程度、右心室容量负荷、肺动脉压力及有无合并肺动脉高压，指导随访与手术决策；完善血气分析检查了解有无低氧血症及通气功能障碍，评估右心功能不全程度；如患者咳痰，完善痰培养+药敏检查明确病原菌并指导抗感染治疗；病情稳定后完善肺功能检查评估肺通气功能，与慢性阻塞性肺疾病所致肺动脉高压鉴别；必要时完善动态心电图检查排除心律失常。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 肺动脉瓣关闭不全\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 血管紧张素转换酶抑制剂（减轻肺动脉瓣反流、降低右心前负荷）：培哚普利叔丁胺片4mg qd，晨起口服，连用4-12周后评估疗效；不耐受（干咳）者换用血管紧张素Ⅱ受体拮抗剂，如缬沙坦胶囊80mg qd。\n2. 利尿剂（右心衰竭伴外周水肿、肝大时使用）：呋塞米片20mg qd，晨服，若水肿消退不明显可增至20mg bid；同时口服螺内酯片20mg qd以保钾，连用至水肿消退后减量维持。\n3. β受体阻滞剂（心率快、伴心律失常或合并右心功能不全时）：琥珀酸美托洛尔缓释片23.75mg qd起始，如耐受且静息心率仍＞70次/分，2周后增至47.5mg qd维持，注意监测血压及心率。\n4. 感染性心内膜炎预防（有基础心脏病者行牙科、口腔、呼吸道有创操作前）：阿莫西林胶囊2.0g，术前1小时顿服；青霉素过敏者改用克林霉素600mg，术前1小时顿服。\n\n【一般治疗及生活指导】\n1. 限制活动量：避免剧烈运动、举重及长时间屏气用力的重体力劳动，可进行散步、太极拳等低强度有氧活动，以不出现心悸、气促为宜。\n2. 饮食管理：低盐饮食（每日食盐＜5g），合并右心衰竭时进一步限盐限水（每日入液量约1500ml），戒烟限酒，避免暴饮暴食。\n3. 预防感染：注意保暖，预防呼吸道感染；保持口腔卫生，牙科及有创操作前按医嘱预防性患者抗生素，防止感染性心内膜炎。\n4. 妊娠与用药禁忌：育龄期女性妊娠前应行心功能评估；避免自行使用非甾体抗炎药及增加右心负荷的药物。\n\n【随诊要求】\n1. 每3-6个月门诊复查，行心脏彩色多普勒超声心动图评估肺动脉瓣反流程度、右心室大小及肺动脉压力变化；每年复查心电图1次。\n2. 每6-12个月行血常规、肝肾功能、电解质及BNP/NT-proBNP检查，评估右心功能及用药安全。\n3. 若出现进行性呼吸困难、下肢水肿加重、腹胀纳差、晕厥或明显心悸，提示右心衰竭加重或并发心律失常，应立即来院就诊；妊娠期、拟行外科手术者需提前心内科门诊评估。","手术记录":"手术记录\n\n手术日期：（门诊病历未记载，请术者据实际填写）\n术前诊断：肺动脉瓣关闭不全\n术后诊断：同术前诊断\n手术名称：肺动脉瓣置换术（或肺动脉瓣成形术；门诊病历仅记载\"拟行外科手术\"，具体术式为瓣膜置换或瓣环成形、是否合并其他心脏畸形矫治，病历未记载，请术者据实际填写）\n术者：（病历未记载，请术者补充）　　助手：（病历未记载，请补充）\n麻醉方法：全身麻醉（气管内插管，常规；病历未记载，请补充），麻醉者：（病历未记载，请补充）\n体位：仰卧位，肩背部垫高（常规，请据实际填写）\n手术经过（要点，具体步骤请术者据实际操作补充）：\n1. 全身麻醉成功后取仰卧位，常规消毒铺巾。取胸骨正中切口，电锯劈开胸骨，骨蜡止血，撑开胸骨，切开心包并悬吊，探查心脏及大血管，见肺动脉主干扩张、肺动脉瓣反流（肺动脉瓣环大小及反流程度病历未记载，请据实际填写）。\n2. 全身肝素化（3mg/kg），经升主动脉及上、下腔静脉（或右心房）插管建立体外循环，降温，阻断升主动脉，经主动脉根部或冠状静脉窦灌注冷停跳液使心脏停搏。\n3. 于肺动脉主干前壁做纵行切口，显露肺动脉瓣，切除病变瓣叶（或行瓣环成形），测量瓣环直径，选用合适型号人工瓣膜（生物瓣或机械瓣，以实际使用为准）以间断褥式缝线固定，检查瓣叶开放关闭良好、无反流。\n4. 缝合肺动脉切口，充分排气，开放升主动脉阻断钳，心脏自动复跳或电击除颤复跳，辅助循环，逐步停止体外循环，拔除插管，鱼精蛋白中和肝素。\n5. 仔细检查各吻合口及切口无活动性出血，置心包及纵隔引流管，钢丝固定胸骨，分层缝合切口。\n（体外循环时间、主动脉阻断时间、术中经食管超声评估结果等病历未记载，请术者据实际填写）\n术中出血量：（病历未记载，请据实际填写）　　输血量：（病历未记载，请据实际填写；心脏手术常规备血，术中可能需要输注红细胞、血浆、血小板及自体血回输）\n切除标本：切除的病变肺动脉瓣叶组织送病理检查（常规，请据实填写）\n术中意外及处理：无（病历未记载；如出现心律失常、低心排、出血、瓣周漏、冠状动脉气栓等，请据实补充记录及处理措施）\n术后情况：术后转入监护病房，予呼吸机辅助通气、血管活性药物维持循环、抗感染及强心利尿治疗，监测心率、血压、中心静脉压、尿量、引流量及血气分析，观察有无心律失常、低心排综合征、出血及感染。待血流动力学稳定、引流减少后拔除气管插管及引流管，复查超声心动图评估瓣膜功能与右心功能，转回普通病房继续治疗（是否预防性使用抗生素及抗凝方案视所用瓣膜类型由心脏外科确定）。\n签名：术者________　　记录者________","手术知情同意书":"手术知情同意书\n\n患者姓名：（病历未记载，请补充）　　性别：（病历未记载）　　年龄：（病历未记载）\n科别：心脏外科　　住院号（门诊号）：门诊病历698　　就诊日期：（病历未记载，请补充）\n术前诊断：肺动脉瓣关闭不全\n拟定手术名称：肺动脉瓣置换术/肺动脉瓣成形术（以实际手术方案为准）\n拟定手术日期：（病历未记载，请补充）\n麻醉方式：全身麻醉（气管内插管，体外循环下手术）\n\n一、手术目的：纠正肺动脉瓣关闭不全，消除或减轻右心室容量负荷过重，防止右心室扩大及右心衰竭进展，改善活动后气促、乏力、心悸等症状，预防心律失常及右心功能失代偿。\n\n二、替代治疗方案（各有适应证与利弊）：\n1. 药物治疗：血管紧张素转换酶抑制剂（如培哚普利4mg每日1次）或血管紧张素Ⅱ受体拮抗剂（如缬沙坦80mg每日1次）减轻肺动脉瓣反流、降低右心前负荷；利尿剂（呋塞米20mg每日1次+螺内酯20mg每日1次）用于右心衰竭伴水肿、肝大者；β受体阻滞剂（美托洛尔）用于心率快或合并心律失常者。药物治疗可缓解症状，但不能纠正瓣膜结构异常，不能阻止右心室扩大。\n2. 经导管肺动脉瓣介入置换/成形术：创伤小、恢复快，适用于解剖条件合适者，但受瓣环大小、右室流出道形态及肺血管条件限制，费用较高，远期耐久性待观察。\n3. 继续观察随访（每3～6个月复查超声心动图）：适用于反流轻、右心室不大、无症状者，但病变可能进展。\n4. 不做手术：中重度反流者右心室可进行性扩大、右心衰竭加重，出现顽固性水肿、腹胀纳差、活动受限甚或晕厥、心律失常，危及生命。\n\n三、手术风险与并发症：\n1. 麻醉意外、体外循环相关并发症（脑卒中、认知功能障碍、全身炎症反应、凝血功能障碍）；\n2. 术中大出血、心包填塞，需大量输血或二次开胸止血；\n3. 心律失常（室性心律失常、房室传导阻滞，必要时需安置临时或永久起搏器）；\n4. 低心排综合征、右心功能不全，需长时间血管活性药物或机械辅助支持；\n5. 瓣周漏、人工瓣膜功能障碍（血栓形成、瓣叶衰败、感染性心内膜炎），远期可能需再次手术；\n6. 肺动脉主干或瓣环撕裂、冠状动脉损伤、气栓栓塞；\n7. 术后感染（切口感染、纵隔炎、肺部感染、败血症）；\n8. 呼吸功能不全、肺不张、胸腔积液；\n9. 术后出血、心包积液、下肢深静脉血栓形成；\n10. 机械瓣需终身抗凝，抗凝相关出血或血栓栓塞风险；生物瓣远期衰败；\n11. 其他不可预知的并发症。\n\n四、麻醉风险：麻醉药物过敏、气管插管困难、呼吸循环抑制、心律失常、心搏骤停、术中知晓、术后苏醒延迟等，由麻醉医师另行详细交代并签署麻醉知情同意书。\n\n五、输血及血制品：心脏手术出血量较大，术中、术后常需输注红细胞、血浆、血小板、冷沉淀及白蛋白等血制品，并使用自体血回输；输血可能传播肝炎、艾滋病等血源性疾病并可能发生发热、过敏、溶血、输血相关急性肺损伤等反应。已另行签署输血知情同意书。\n\n六、术中改变术式的可能：若术中发现瓣膜病变程度、瓣环大小与术前评估不符，或合并其他心脏畸形、冠状动脉病变，可能改行瓣膜成形术、跨瓣环补片扩大术或同时行其他心脏手术；若体外循环脱机困难，可能延长辅助循环时间或使用机械辅助装置，术者将与家属沟通后决定。\n\n七、术后注意事项：术后入住监护病房，需呼吸机辅助通气及血管活性药物支持；保持引流管通畅，观察引流量、尿量及生命体征；按医嘱使用抗生素预防感染；生物瓣者一般抗凝3～6个月，机械瓣者需终身服用华法林并定期监测INR；术后1个月、3个月、6个月复查超声心动图、心电图、肝肾功能及电解质，之后每年复查；避免剧烈运动、重体力劳动及屏气用力；注意口腔卫生，牙科及有创操作前预防性使用抗生素以防感染性心内膜炎；出现气促加重、下肢水肿、发热、晕厥、心悸等及时就诊。\n\n八、其他：住院费用按医保政策结算，具体以实际发生为准；患者及家属有权了解病情并可随时提出疑问。\n\n医师签名：____________　　日期：____年__月__日\n患者（或家属）签名：____________与患者关系：______　　日期：____年__月__日"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":830,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"88ceb7ccc541429d4f7a257b32029b195ee3e69d94d107012f84fd76ad6510da","pinyin":"feidongmaibanguanbibuquan","initials":"fdmbgbbq","setting":"mixed","caseName":"门诊病历698","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案","手术记录","手术知情同意书"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历698",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案 手术记录 手术知情同意书",30],["主要诊断编码","",30]]},{"id":"templates-a42d81e29065aead865f","key":"v1-c9ccc21dfe2a3058|templates-a42d81e29065aead865f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"联合瓣膜病","category":"门诊病历模板","raw":{"name":"联合瓣膜病","category":"门诊病历模板","case":{"case_name":"门诊病历699","templates":{"主诉":"气短1天","现病史":"患者1周前无明显诱因出现联合瓣膜病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以气短1天为主诉，一周来联合瓣膜病相关症状逐渐加重并伴乏力，无发热，门诊首诊需先完善血常规检查排除感染、贫血所致气短乏力；完善尿常规检查了解有无蛋白尿、血尿以评估肾脏受累情况；完善便常规检查排除消化道慢性失血导致贫血；患者后续需长期药物治疗，完善肝肾功能检查排除肝肾功能不全、明确药物代谢与排泄能力；完善血糖、血脂检查了解糖脂代谢水平，评估动脉粥样硬化危险因素；联合瓣膜病常继发心律失常并受利尿治疗影响，完善电解质检查排除低钾低镁等电解质紊乱所致心律失常。心脏瓣膜病变需客观证据支持，急查心电图观察有无心律失常及房室肥大表现；查胸部X线片了解心影形态、肺淤血及胸腔积液情况；查腹部超声评估肝脾大小及有无淤血性肝大、腹水。若条件允许，建议完善超声心动图以明确瓣膜狭窄或关闭不全的部位与程度、房室大小及左心室射血分数，必要时行心脏彩超加左心功能测定，为后续药物或手术方案提供依据。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 联合瓣膜病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 利尿消肿：呋塞米片20mg qd口服（可据尿量、体重及水肿程度调整为20mg bid），联合螺内酯片20mg qd，减轻肺循环及体循环淤血；用药期间每周复查电解质、肾功能及体重变化。\n2. 控制心室率（合并心房颤动、快速心室率时）：地高辛片0.125mg qd口服，心室率控制不佳者可联合美托洛尔缓释片23.75mg qd口服（静息心率不低于55次/分）；需抗凝者予华法林钠片2.5mg qd起始口服，定期监测INR调整剂量，非机械瓣者目标INR 2.0~3.0，机械瓣置换术后目标INR 2.5~3.5。\n3. 抗心力衰竭：伴左心功能不全者加用培哚普利片4mg qd口服（或缬沙坦胶囊80mg qd），监测血压、血肌酐及血钾；严重主动脉瓣狭窄者慎用。\n\n【一般治疗及生活指导】\n1. 休息与活动：心功能Ⅰ~Ⅱ级者可适度有氧活动（散步、太极拳等），避免剧烈运动及竞技性体育；心功能Ⅲ级及以上者以卧床休息为主，限制活动量，避免劳累诱发急性心力衰竭。\n2. 饮食：低盐低脂饮食，每日食盐摄入<5g（明显水肿者<3g），控制液体入量每日1500~2000ml，少食多餐，戒烟限酒，控制体重。\n3. 预防感染性心内膜炎：保持口腔卫生、防治呼吸道感染；拔牙、口腔及有创操作前1小时口服阿莫西林胶囊0.5g预防感染（青霉素过敏者改用克林霉素0.6g），出现不明原因发热、心悸、胸闷及时就诊。\n4. 避免诱发因素：避免剧烈咳嗽、用力屏气、负重及便秘时用力排便，育龄期女性妊娠前需心内科评估，避免使用非甾体抗炎药及拟交感类药物。\n\n【随诊要求】\n1. 每1~3个月门诊复诊1次，复查心电图、血常规、电解质、肝肾功能；心脏彩色多普勒超声每6~12个月复查1次；服用华法林者每周至每2周监测INR。\n2. 出现活动后气促明显加重、夜间阵发性呼吸困难、咯血、双下肢明显水肿、晕厥或黑矇、心悸持续不缓解时随时就诊；新发心房颤动或静息心率持续>110次/分时及时复诊。\n3. 出现重度瓣膜病变伴明显症状、心功能进行性下降或肺动脉高压加重等手术指征时，转心外科评估瓣膜成形或置换手术时机。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":831,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"aea651ce493f6f3a94b5182d27bf525e66a942d6f8cd11cbc841ff3c8c0a68e7","pinyin":"lianhebanmobing","initials":"lhbmb","setting":"out","caseName":"门诊病历699","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历699",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cb1b218e6551bb6432e4","key":"v1-c9ccc21dfe2a3058|templates-cb1b218e6551bb6432e4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肥厚性胃炎","category":"门诊病历模板","raw":{"name":"肥厚性胃炎","category":"门诊病历模板","case":{"case_name":"门诊病历700","templates":{"主诉":"上腹隐痛1天","现病史":"患者1周前无明显诱因出现肥厚性胃炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者上腹隐痛1天，一周来症状逐渐加重并伴轻度乏力，无发热及恶心呕吐，门诊首先完善血常规检查排除感染、贫血所致乏力；查便常规+潜血检查排除消化道出血，肥厚性胃炎黏膜粗大易并发出血，此项为筛查重点；上腹隐痛需与肝胆胰疾病鉴别，完善肝功能检查了解有无肝细胞损伤及胆道梗阻；完善淀粉酶、脂肪酶检查排除急性胰腺炎所致上腹痛；查腹部超声了解肝、胆、胰、脾形态及有无结石、胆管扩张等异常；查幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染，指导是否行根除治疗；需内镜直视评估黏膜肥厚性质及有无恶变，安排胃镜检查并取活检明确病变性质，必要时完善肠镜检查排除下消化道病变；必要时查腹部CT评估胃壁增厚范围及有无邻近侵犯、腹腔淋巴结肿大；若考虑内镜下活检或后续治疗，完善凝血功能检查评估出血风险。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 肥厚性胃炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抑酸治疗：质子泵抑制剂，雷贝拉唑钠肠溶片20mg qd（晨起空腹顿服）或奥美拉唑肠溶胶囊20mg qd，疗程4～8周，症状缓解后根据患者具体情况制定个体化方案减量或按需维持。\n2. 胃黏膜保护剂：替普瑞酮胶囊50mg tid（餐后口服），或瑞巴派特片0.1g tid，或铝碳酸镁咀嚼片1.0g tid（餐后1小时嚼服），疗程4～8周。\n3. 幽门螺杆菌（Hp）根除：13C或14C-尿素呼气试验阳性者，行铋剂四联方案14天：雷贝拉唑20mg bid＋枸橼酸铋钾220mg bid＋阿莫西林1.0g bid＋克拉霉素0.5g bid（青霉素过敏者以左氧氟沙星0.5g qd替代），停药4周后复查呼气试验。\n4. 合并明显低蛋白血症（血清白蛋白<30g/L）或蛋白丢失显著者：加用奥曲肽0.1mg皮下注射q8h，疗程2～4周，并配合口服高蛋白饮食或静脉补充人血白蛋白（在医师指导下调整）。\n\n【一般治疗及生活指导】\n1. 休息：急性期注意休息，保证充足睡眠，避免劳累、熬夜及精神紧张，以利胃黏膜修复。\n2. 饮食：少食多餐，选用易消化、富含优质蛋白和维生素的软食（如鱼肉、鸡蛋、瘦肉、豆腐、山药粥等），以纠正和预防低蛋白血症；避免粗糙、过硬、过烫及辛辣刺激性食物。\n3. 禁忌：戒烟限酒，忌浓茶、咖啡及碳酸饮料；避免使用非甾体抗炎药（布洛芬、阿司匹林等）及其他损伤胃黏膜的药物。\n4. 活动：症状缓解后可进行散步等轻中度活动，避免剧烈运动及腹部挤压。\n\n【随诊要求】\n1. 治疗后2～4周复诊，复查血清白蛋白、血红蛋白，评估低蛋白血症及贫血改善情况。\n2. 4～6周复查胃镜，观察胃黏膜皱襞形态改善情况；本病需长期随访，建议每6～12个月复查胃镜并多点活检，警惕恶变。\n3. 治疗期间如出现黑便、呕血、呕咖啡渣样物或剧烈腹痛，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":832,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"020f18a7449df3f14879d688884b8d9fa0955b23a7e1c3d4eef02144f62628c9","pinyin":"feihouxingweiyan","initials":"fhxwy","setting":"out","caseName":"门诊病历700","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历700",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d2698e001c94d40827f4","key":"v1-c9ccc21dfe2a3058|templates-d2698e001c94d40827f4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃溃疡","category":"门诊病历模板","raw":{"name":"胃溃疡","category":"门诊病历模板","case":{"case_name":"门诊病历701","templates":{"主诉":"反复上腹疼痛3年，再发5天","现病史":"患者于3年前开始反复上腹疼痛，表现为餐后痛（进食后30~60分钟出现，持续1~2小时，胃排空后缓解，呈进食-疼痛-缓解规律，以区别于十二指肠溃疡的空腹痛、饥饿痛、进食后缓解）、疼痛性质为烧灼样或钝痛、胀痛，部位在上腹正中或剑突下偏左，呈周期性发作（秋冬及冬春季节好发）。\n5天前再发，诱因：饮食不当、饮酒、精神紧张、服用NSAIDs（阿司匹林、布洛芬，为重要诱因），Hp感染（幽门螺杆菌，为胃溃疡主要病因之一，可行尿素呼气试验）；伴反酸嗳气、恶心、食欲减退、体重下降（胃溃疡者可消瘦，且有溃疡恶变风险，约1~3%，故胃溃疡需行胃镜活检，此点重要，不同于十二指肠溃疡之不恶变）。\n无出血（黑便、呕血，为溃疡出血，属最常见并发症）、无穿孔（突发上腹剧痛、板状腹，属急症）、无幽门梗阻（呕吐宿食、餐后加重、振水音），以上并发症需警惕。大便颜色正常，无黑便。今日来我院消化科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P80次/分，R18次/分，BP118/74mmHg。神志清楚，上腹轻压痛（剑突下或上腹偏左，局限）、无肌紧张及反跳痛（无穿孔）、肠鸣音正常、无贫血貌（无慢性出血）、无明显消瘦。","辅助检查":"【必做】胃镜加活检（确诊金标准，可见溃疡呈圆形或椭圆形，边缘光整，底覆白苔；胃溃疡必须取活检，以排除恶性溃疡（胃癌，边缘不规则隆起、质脆，即溃疡型胃癌，此点重要，胃溃疡活检为常规），并需治疗后复查，评估愈合，胃溃疡需经内镜随访确认愈合，重要）、幽门螺杆菌检测（尿素呼气试验（首选，无创）或胃镜活检快速尿素酶试验及病理检查（活检时同步进行），用于判断Hp现症感染，为根除依据）；\n【影像】胃镜禁忌者可行上消化道钡餐（可见龛影，提示溃疡），较少患者；\n【血液】血常规（贫血，提示出血）、大便隐血（阳性提示出血，随访转阴提示溃疡愈合）；\n【并发症】疑出血者行急诊胃镜（可内镜下止血），属急症。","初步诊断":"1. 胃溃疡（活动期（A期）；部位在胃角、胃窦或胃体；Hp阳性；活检排除恶性，考虑良性溃疡）。\n（注：治疗以抑酸加根除Hp为主，以促进溃疡愈合及防复发）\n①抑酸治疗：质子泵抑制剂（PPI，奥美拉唑20mg bid或埃索美拉唑20mg），疗程4~6周（胃溃疡疗程较十二指肠溃疡长，需评估愈合，为PPI标准疗程）；H2受体拮抗剂（用于轻症，为备选）。\n②根除幽门螺杆菌（Hp阳性者必须根除）：四联疗法，即PPI加铋剂加两种抗生素（阿莫西林1g加克拉霉素0.5g，或左氧氟沙星，均bid），疗程14天，规范方案根除率>90%；停药4周后复查尿素呼气试验以确认根除，重要，根除后复发率显著下降。\n③去除诱因：停用NSAIDs（必须停用；如不能停，可换用选择性COX-2抑制剂（塞来昔布）或加用PPI预防，并评估心血管风险、权衡利弊；需用阿司匹林者（心脑血管疾病）应加PPI保护）、戒烟酒（可加重病情并影响愈合，必须戒除）、避免刺激性饮食。\n④对症治疗：黏膜保护剂（铝碳酸镁或硫糖铝，作辅助以缓解症状）、促动力药（腹胀者予莫沙必利）。\n⑤并发症处理：出血（予急诊胃镜止血，可行注射、电凝或钛夹；大出血且内镜失败者行介入栓塞或手术，属急症）、穿孔（急诊手术，属急症）、幽门梗阻（予禁食及胃肠减压、静脉PPI；水肿性者经治疗消退后可保守，瘢痕性者需手术）。\n⑥随访：疗程结束后评估症状缓解情况；胃溃疡应复查胃镜（4~6周，确认愈合，重要）并行活检病理（排除恶性，若愈合不良或不愈合应再次活检，警惕癌性溃疡）；复查Hp（根除后）；预防复发（根除Hp加避免NSAIDs，可显著降低复发率；再次复发者复查胃镜并评估再根除）。由消化科规范治疗，胃溃疡需内镜随访，以鉴别恶性，重要。","处理方案":"【药物治疗】\n1. 抑酸治疗（首选质子泵抑制剂）：奥美拉唑肠溶胶囊20mg bid，早餐前及晚餐前30分钟口服，疗程4~6周；亦可选用埃索美拉唑镁肠溶片20mg qd，晨起空腹口服。\n2. 根除幽门螺杆菌（Hp阳性者）：铋剂四联方案，枸橼酸铋钾胶囊220mg bid + 奥美拉唑肠溶胶囊20mg bid + 阿莫西林胶囊1.0g bid + 克拉霉素片0.5g bid，三餐前及睡前口服，疗程14天。\n3. 胃黏膜保护剂：替普瑞酮胶囊50mg tid，餐后口服；或瑞巴派特片0.1g tid，餐后口服，疗程4周。\n4. 对症处理：腹胀明显者加用莫沙必利片5mg tid，餐前口服；夜间反酸明显者睡前加服法莫替丁片20mg qn。\n【一般治疗及生活指导】\n1. 饮食指导：规律三餐，定时定量，细嚼慢咽，避免过饱及饥饿；忌辛辣、生冷、粗糙、过酸过甜及油炸食物，戒烟、限酒，忌浓茶、咖啡及碳酸饮料。\n2. 休息与活动：溃疡活动期注意休息，避免劳累、熬夜及精神紧张，保证充足睡眠；缓解期可进行散步等适度活动，避免剧烈运动及餐后立即运动。\n3. 药物禁忌：避免使用阿司匹林、布洛芬、双氯芬酸等非甾体抗炎药及糖皮质激素，确需使用者应遵医嘱与PPI联用并评估风险；勿自行服用损伤胃黏膜的药物。\n4. 情志调护：保持情绪平稳，避免焦虑、抑郁及过度压力，必要时寻求心理疏导。\n【随诊要求】\n1. 疗程结束后（PPI停用2周以上、抗生素及铋剂停用4周以上）复查13C/14C尿素呼气试验，评估Hp根除效果；治疗后4~6周复查胃镜，评估溃疡愈合情况。\n2. 治疗期间如出现呕血、黑便、剧烈腹痛、进行性消瘦或贫血等，立即复诊或急诊就诊；胃溃疡有恶变可能，溃疡愈合后建议定期胃镜随访复查。\n3. 用药期间如出现皮疹、腹泻、味觉异常等药物不良反应，及时复诊调整用药方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":833,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c4d194e01e4c678a6006bb3f260502295ee94d60313cd42d921481451631d831","pinyin":"weikuiyang","initials":"wky","setting":"out","caseName":"门诊病历701","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历701",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2e783bcacaf77b934423","key":"v1-c9ccc21dfe2a3058|templates-2e783bcacaf77b934423","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"十二指肠溃疡","category":"门诊病历模板","raw":{"name":"十二指肠溃疡","category":"门诊病历模板","case":{"case_name":"门诊病历702","templates":{"主诉":"反复上腹空腹痛2年，再发4天","现病史":"患者于2年前开始反复上腹疼痛，表现为空腹痛或饥饿痛（餐前及夜间出现，午夜痛为其特征，可于凌晨痛醒，进食后缓解，呈疼痛-进食-缓解规律，因胃酸刺激十二指肠而进食可缓冲，此为特征，可与胃溃疡之餐后痛相鉴别）、疼痛部位在上腹正中偏右或脐上，性质为烧灼样或饥饿样不适，呈周期性（秋冬及冬春季节规律发作）。\n4天前再发，常伴反酸、烧心、嗳气、恶心，呕吐少见，食欲多正常（因进食可缓解，食欲好，体重多正常，与胃溃疡之消瘦不同）。\n十二指肠溃疡的主要病因：Hp感染（约占90%，幽门螺杆菌为最重要病因）、NSAIDs或阿司匹林（药物性）、胃酸分泌过多（Zollinger-Ellison综合征，即胃泌素瘤，少见，表现为顽固多发溃疡，需考虑，属卓艾综合征）、遗传因素。十二指肠溃疡不恶变，此点重要，属良性，与胃溃疡不同。\n无出血（黑便，为最常见并发症，呕血少见）、无穿孔（突发上腹剧痛、板状腹，属急症，多见于十二指肠前壁）、无幽门梗阻（少见，可由球部瘢痕致呕吐）、无穿透（疼痛向背部放射，提示穿透至胰腺）等并发症。今日来我院消化科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP116/72mmHg。上腹轻压痛（上腹偏右，局限）、无肌紧张及反跳痛、肠鸣音正常、无贫血貌（无慢性出血）。","辅助检查":"【必做】胃镜（确诊金标准，可见十二指肠球部溃疡，呈圆形或椭圆形，前壁多见，可多发（对吻溃疡）；十二指肠溃疡无需常规活检排除恶性（因不恶变，与胃溃疡不同），但需与少见的十二指肠腺癌鉴别（表现不典型、巨大溃疡者应活检））、幽门螺杆菌检测（尿素呼气试验为首选，用于判断Hp现症感染，为根除依据；十二指肠溃疡者根除Hp是愈合及防复发的核心）；\n【影像】胃镜禁忌者可行钡餐（可见龛影），较少患者；\n【血液】血常规（贫血，提示出血）、大便隐血（阳性者随访转阴）；\n【胃泌素】顽固多发溃疡、治疗后不愈或伴腹泻者（疑Zollinger-Ellison综合征）应查血胃泌素（空腹升高，>1000pg/ml提示卓艾综合征）、胃酸分泌（基础酸排量升高），此病少见，但需识别。","初步诊断":"1. 十二指肠溃疡（活动期；位于球部前壁；Hp阳性；需评估并发症）。\n（注：治疗与胃溃疡类似，以抑酸加根除Hp为主）\n①抑酸：PPI（奥美拉唑20mg bid或埃索美拉唑20mg），疗程4~6周（十二指肠溃疡愈合快，4周PPI多可愈合，之后渐减量，或按需给药（症状轻者），Hp未根除、继续用NSAIDs或复发高危者可予小剂量PPI维持）。\n②根除Hp（阳性者）：四联方案（PPI加铋剂加阿莫西林加克拉霉素或甲硝唑），疗程14天；停药4周后复查尿素呼气试验以确认根除；Hp根除可使十二指肠溃疡复发率由70%降至<5%，为核心措施。\n③去除诱因：停用NSAIDs及阿司匹林（不能停者需合用PPI保护）、戒烟酒。\n④对症治疗：黏膜保护剂、促动力药。\n⑤并发症处理：出血（予急诊胃镜，行钛夹或注射止血；十二指肠后壁溃疡出血可累及胃十二指肠动脉，大出血且内镜失败者行介入或手术）、穿孔（急诊手术，多见于前壁，属急症）、梗阻（少见，予胃肠减压及PPI，瘢痕性者手术）。\n⑥随访：症状（PPI治疗后数天可缓解）、愈合（多数不需常规内镜复查，与胃溃疡不同，症状消失者可不必复查胃镜，除非症状持续或复发；但曾有出血或并发症者应复查）、Hp复查（根除后4周行呼气试验）、复发预防（根除Hp加避免NSAIDs，为关键）、维持治疗（必须用NSAIDs者长期予PPI保护），由消化科随访。","处理方案":"【药物治疗】\n1. 抑酸治疗：雷贝拉唑钠肠溶片 20mg 口服 每日1次（早餐前30分钟），疗程4～6周；或奥美拉唑肠溶胶囊 20mg 每日1次，疗程4～6周。\n2. 根除幽门螺杆菌（Hp阳性者）：采用四联疗法14天，枸橼酸铋钾胶囊 220mg 口服 每日2次 + 阿莫西林胶囊 1.0g 口服 每日2次 + 克拉霉素片 500mg 口服 每日2次 + 奥美拉唑肠溶胶囊 20mg 口服 每日2次，疗程14天（青霉素过敏者以甲硝唑片 0.4g bid 替代阿莫西林）。\n3. 胃黏膜保护：铝碳酸镁咀嚼片 1.0g 口服 每日3次（餐后1小时嚼服），与PPI间隔1小时以上服用，疗程2～4周。\n【一般治疗及生活指导】\n1. 生活作息：规律作息，保证充足睡眠，避免熬夜、过度劳累及精神紧张，戒烟、戒酒。\n2. 饮食指导：定时定量、少食多餐，进易消化软食，细嚼慢咽；避免辛辣、生冷、油炸、过酸过甜食物，忌浓茶、咖啡及碳酸饮料。\n3. 用药禁忌：避免使用阿司匹林、布洛芬等非甾体抗炎药及糖皮质激素；如因合并疾病必须使用，医师指导下加用PPI并监测胃镜。\n【随诊要求】\n1. 服药2周后复诊，评估症状缓解情况及药物不良反应（皮疹、腹泻、味觉异常等）。\n2. Hp根除治疗结束4～6周后复查尿素呼气试验（13C/14C-UBT）确认根除效果，停药期间需停用PPI及抗生素至少2周。\n3. 抑酸治疗结束后4～6周复查胃镜，评估溃疡愈合及瘢痕情况；如治疗中出现呕血、黑便、剧烈腹痛或体重下降，应立即随诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":834,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e844add232bed9840d9f04910dd872abace3e42de217ff9ab663b4a53e84a7e8","pinyin":"shierzhichangkuiyang","initials":"sezcky","setting":"out","caseName":"门诊病历702","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历702",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d104abf1991dfef677e2","key":"v1-c9ccc21dfe2a3058|templates-d104abf1991dfef677e2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"复合性溃疡","category":"门诊病历模板","raw":{"name":"复合性溃疡","category":"门诊病历模板","case":{"case_name":"门诊病历703","templates":{"主诉":"上腹疼痛1天","现病史":"患者1周前无明显诱因出现复合性溃疡相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者上腹疼痛1天，一周来复合性溃疡相关症状逐渐加重并伴乏力，无发热及呕吐，门诊首先完善血常规检查排除溃疡出血所致贫血及感染；完善便常规+潜血检查明确有无活动性消化道出血，此项为溃疡病必查；上腹疼痛需与肝胆胰疾病鉴别，完善肝功能检查了解有无肝细胞损伤及胆道梗阻；完善淀粉酶、脂肪酶检查排除急性胰腺炎所致上腹痛；查腹部超声了解肝胆胰脾形态及有无结石、胆管扩张；复合性溃疡需同时评估胃与十二指肠病变，安排胃镜检查明确溃疡部位、大小、分期并取活检排除恶性溃疡，必要时完善肠镜检查排除下消化道病变；必要时查腹部CT了解溃疡有无穿透、周围粘连及腹腔淋巴结情况；查幽门螺杆菌检测（C13/C14呼气试验）明确有无感染，指导根除方案；因溃疡易并发出血，完善凝血功能检查评估出血风险并指导抑酸及内镜治疗。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 复合性溃疡\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 根除幽门螺杆菌（若阳性）四联疗法：埃索美拉唑镁肠溶片20mg bid＋枸橼酸铋钾颗粒220mg bid＋阿莫西林胶囊1.0g bid（青霉素过敏者改用四环素片0.75g bid）＋克拉霉素片0.5g bid；PPI及铋剂餐前30分钟服用，抗生素餐后服用，疗程14天。\n2. 抑酸治疗：根除疗程结束后继续口服质子泵抑制剂，埃索美拉唑镁肠溶片20mg qd（晨起空腹）或奥美拉唑肠溶片20mg qd，疗程4-8周（复合性溃疡含胃溃疡成分，愈合较慢，建议不少于8周）。\n3. 胃黏膜保护剂：硫糖铝混悬液10ml tid（餐前1小时及睡前服用），或瑞巴派特片0.1g tid（餐后服用），疗程4-8周，与PPI间隔2小时以上服用。\n\n【一般治疗及生活指导】\n1. 规律作息，保证充足睡眠，避免熬夜、过度劳累及精神紧张，保持情绪平稳，减少应激性胃酸分泌。\n2. 饮食定时定量、少食多餐、细嚼慢咽，避免辛辣刺激、油腻、过冷过热食物，避免浓茶、咖啡及烈酒，戒烟限酒。\n3. 避免服用NSAIDs（阿司匹林、布洛芬等）及糖皮质激素等损伤胃黏膜的药物；因心脑血管病需长期抗血小板治疗者，医师指导下联合PPI保护。\n4. 幽门螺杆菌阳性者实行分餐制、餐具单独消毒，家庭成员建议同步检测并规范治疗，避免交叉再感染。\n\n【随诊要求】\n1. 根除治疗结束后至少停药4周（其中PPI停用2周以上），复查13C/14C-尿素呼气试验评估幽门螺杆菌根除效果；未根除者间隔3-6个月后行补救治疗。\n2. 治疗结束后4-8周复查胃镜，观察溃疡愈合情况并常规取活检送病理（胃溃疡须排除恶性病变）；愈合不良或症状持续者需进一步评估并延长疗程。\n3. 治疗期间及停药后如出现黑便、呕血、反复上腹痛、消瘦、贫血等，及时就诊；症状缓解后不可自行停药，务必完成全疗程。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":835,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3accc9a35fdfae2a60123267b7b933efc5861246d070ed3de99faa36bea2fc35","pinyin":"fuhexingkuiyang","initials":"fhxky","setting":"out","caseName":"门诊病历703","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历703",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-66a4ce32409585291a05","key":"v1-c9ccc21dfe2a3058|templates-66a4ce32409585291a05","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"应激性溃疡","category":"门诊病历模板","raw":{"name":"应激性溃疡","category":"门诊病历模板","case":{"case_name":"门诊病历704","templates":{"主诉":"严重应激后呕血、黑便1天，加重2小时。","现病史":"患者处于严重应激状态（重症监护，机械通气>48小时；严重创伤或颅脑损伤（Cushing溃疡，颅脑损伤所致应激性溃疡，具特点）；大面积烧伤（Curling溃疡，烧伤所致应激性溃疡）；脓毒症或休克；大手术（重大手术后）；多器官功能衰竭；长期禁食或肠外营养；凝血功能障碍；使用激素或NSAIDs（可增加风险）），于应激后5天出现（多在数天至2周内，常发生于ICU期间）以下表现：\n上消化道出血：呕血（呈咖啡样或鲜红色，提示活动性出血）、黑便（柏油样）、胃管引流出血性液体（ICU监测中可见，胃液潜血阳性有助于早期识别）、血红蛋白下降、血压下降（大出血所致休克）、心率增快（失血后代偿）、呕血后腹胀（胃内积血）。\n本病为急性胃黏膜病变（应激致黏膜缺血、胃酸损伤，形成糜烂或溃疡并出血），属应激性溃疡出血，为ICU常见并发症，可增加死亡率。\n预防方面：ICU危重症患者应予应激性溃疡预防（质子泵抑制剂（PPI，奥美拉唑，静脉给药）或H2受体拮抗剂（法莫替丁），为ICU常规，凡有应激因素者应预防，重要，可防出血）；并需评估预防适应证（机械通气>48小时、凝血障碍、严重创伤或颅脑损伤及烧伤、脓毒症休克、多器官衰竭、大剂量激素）；不适用者不常规预防（以防过度用药增加肺炎风险，需权衡）。今日来我院急诊或ICU就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.2℃，P108次/分（增快，失血所致），R22次/分，BP92/60mmHg（低血压，大出血可致休克）。神志清楚或淡漠（失血或休克所致）；贫血貌（急性失血可见苍白）；腹部（上腹轻压痛，为胃黏膜病变所致；腹胀，因胃内积血）；肠鸣音活跃（血液刺激所致）；血流动力学（监测心率、血压及中心静脉压，评估休克）；可见基础病体征（创伤、烧伤或颅脑损伤等原发应激表现）。","辅助检查":"【必做】血常规（血红蛋白动态下降，为出血评估的重要指标，初始可因血液浓缩而正常，需复查；并查血细胞比容）、大便隐血及胃液潜血（为早期出血线索）、凝血功能（评估原发病，如脓毒症或创伤所致DIC，可加重出血）、肝肾功能、血型及交叉配血（大出血者备血、输血）、血气分析及乳酸（评估休克）；\n【确诊】急诊胃镜（用于活动性出血的诊断及治疗，可行内镜下止血（注射、电凝或钛夹）；按Forrest分级，活动性喷血（Ⅰa）、渗血（Ⅰb）及血管裸露（Ⅱa）为高危，应内镜止血加PPI；大出血者行内镜，时机为血流动力学稳定后急诊进行）；\n【影像】较少患者；内镜不可及时可行血管造影（介入栓塞，用于大出血且内镜失败者）。","初步诊断":"1. 应激性溃疡（急性胃黏膜病变；处于预防期并已出血（Forrest分级Ⅱa，血管裸露，属近期出血高危）；基础应激为重症监护及机械通气）。\n（注：治疗以预防为主，出血时予综合止血）\n①预防（ICU危重症并有应激因素者应药物预防）：PPI（奥美拉唑40mg静注qd）或H2受体拮抗剂（法莫替丁20mg静注bid，为备选），应激期间患者，重要，可显著降低出血风险；早期肠内营养（可保护黏膜，应尽量早期开始，不仅为营养，亦可防应激性溃疡）；避免NSAIDs及激素（必须使用者加PPI保护）；抗酸剂（目标为胃内pH>4）。并评估不需预防者（无应激因素或普通住院者不预防，以防药物不良反应，如胃酸抑制致细菌定植引起肺炎，需权衡）。\n②出血处理（一旦出血即属急症）：禁食，静脉予PPI（奥美拉唑80mg负荷后以8mg/h持续静滴，大剂量抑酸以促进凝血，血小板聚集需pH>6，为关键，可止血）、内镜止血（急诊胃镜，ForrestⅠa、Ⅰb、Ⅱa者行内镜止血，如注射肾上腺素加电凝或钛夹，成功率高）、输血（血红蛋白<70g/L或休克者输红细胞；凝血障碍者输新鲜冰冻血浆或血小板；补液（晶体液）抗休克，需监测以防过量（肺水肿，老年及心功能不全者尤需注意），输血目标血红蛋白70~90g/L）。\n③内镜失败或再出血：行介入治疗（血管造影栓塞胃左动脉）或手术（较少需要，出血持续者行手术缝扎）。\n④病因处理：治疗原发应激（感染予抗感染、休克予复苏、颅脑损伤予神经外科处理），应激解除后黏膜可修复。\n⑤随访：出血停止（胃液转清、大便转黄，复查血红蛋白稳定）、内镜复查（止血后评估溃疡愈合）、预防再出血（应激期间维持PPI）。由ICU及消化科多学科协作，以预防为重点（ICU患者应评估预防适应证并规范用药）。","处理方案":"【药物治疗】\n1. 质子泵抑制剂（首选抑酸治疗）：奥美拉唑肠溶胶囊20mg bid，早、晚餐前30分钟整粒吞服，疗程4～8周；症状缓解后可改雷贝拉唑肠溶片10mg qd晨服维持治疗。\n2. H2受体拮抗剂（PPI不耐受或轻症替代）：法莫替丁片20mg bid口服，餐后服用，疗程4周。\n3. 胃黏膜保护剂：硫糖铝混悬液10ml tid，餐前1小时及睡前服用（与PPI间隔至少1小时）；或铝碳酸镁咀嚼片1g tid，餐后1小时嚼碎服用。\n4. 存在应激高危因素（如长期服用NSAIDs、糖皮质激素，或重大创伤、严重感染恢复期）者，可予奥美拉唑肠溶胶囊20mg qd口服预防性治疗，疗程至危险因素去除后2～4周。\n\n【一般治疗及生活指导】\n1. 休息：急性期注意休息，保证充足睡眠，避免劳累及精神紧张、焦虑等应激刺激，保持情绪平稳。\n2. 饮食：少量多餐，进食温软、易消化、少渣饮食（如米粥、软面条、蒸蛋羹、藕粉），细嚼慢咽；忌食辛辣、粗糙、生冷、过烫食物，禁饮咖啡、浓茶、碳酸饮料及酒精。\n3. 禁忌：避免使用阿司匹林、布洛芬等非甾体抗炎药（NSAIDs）及糖皮质激素等损伤胃黏膜的药物；确需使用者应遵医嘱联合PPI保护胃黏膜，勿自行增减药物。\n4. 活动：适当室内活动或散步，避免剧烈运动、过度弯腰及腹部撞击，保持大便通畅，避免用力排便。\n\n【随诊要求】\n1. 治疗后2～4周门诊复诊，评估症状缓解情况及抑酸治疗疗效，必要时调整用药或减量维持。\n2. 治疗期间如出现呕血、黑便、腹痛加剧、头晕、心悸、乏力等上消化道出血或休克表现，立即急诊就诊。\n3. 症状反复或内镜复查有糜烂、溃疡者，按医嘱4～8周复查胃镜；长期服用NSAIDs或激素等高危人群应定期随访，监测病情变化。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":836,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"154d6d324b99648d6f1127f1d1e10821e34f8619cc380a2b4e4b4029debadb0d","pinyin":"yingjixingkuiyang","initials":"yjxky","setting":"out","caseName":"门诊病历704","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历704",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-55cbcf1e1440c301e9a0","key":"v1-c9ccc21dfe2a3058|templates-55cbcf1e1440c301e9a0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"吻合口溃疡","category":"门诊病历模板","raw":{"name":"吻合口溃疡","category":"门诊病历模板","case":{"case_name":"门诊病历705","templates":{"主诉":"上腹疼痛1天","现病史":"患者1周前无明显诱因出现吻合口溃疡相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者上腹疼痛1天，一周来吻合口溃疡相关症状逐渐加重并伴乏力，无发热及呕吐，门诊首先完善血常规检查排除溃疡出血所致贫血及感染；完善便常规+潜血检查明确吻合口有无活动性出血，为吻合口溃疡必查项目；上腹疼痛需与肝胆胰病变鉴别，完善肝功能检查了解有无肝细胞损伤及胆道梗阻；完善淀粉酶、脂肪酶检查排除急性胰腺炎所致上腹痛；查腹部超声了解肝胆胰脾形态及有无结石、胆管扩张；吻合口溃疡需内镜直视评估，安排胃镜检查明确吻合口溃疡大小、深度及有无吻合口狭窄、瘘管，并取活检排除吻合口癌；必要时完善肠镜检查评估下消化道情况；查腹部CT了解吻合口周围有无炎症包裹、脓肿及腹腔淋巴结肿大；查幽门螺杆菌检测（C13/C14呼气试验）明确有无感染，指导根除治疗；因溃疡易并发出血，完善凝血功能检查评估出血风险并指导内镜治疗。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 吻合口溃疡\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抑酸治疗（首选）：质子泵抑制剂足量抑酸，如雷贝拉唑肠溶胶囊20mg 每日1次，晨起空腹口服，疗程4～8周；症状明显或夜间痛重者增至20mg 每日2次（早、晚餐前），直至内镜下溃疡愈合。\n2. 幽门螺杆菌（Hp）根除治疗：Hp阳性者予含铋剂四联方案14天：雷贝拉唑肠溶胶囊20mg bid＋枸橼酸铋钾胶囊220mg bid（均餐前半小时）＋阿莫西林胶囊1.0g bid＋克拉霉素片0.5g bid（均餐后），共14天；青霉素过敏者将阿莫西林改为甲硝唑片0.4g bid。\n3. 黏膜保护及抗胆汁反流：铝碳酸镁咀嚼片1.0g tid，餐后1小时嚼服，中和胃酸及结合反流胆汁、保护吻合口黏膜，连用4周。\n4. 对症治疗：餐后腹胀、恶心、反流者加用莫沙必利片5mg tid，餐前15～30分钟口服；合并黑便、缺铁性贫血者加用硫酸亚铁缓释片0.45g qd口服。\n\n【一般治疗及生活指导】\n1. 饮食：少食多餐（每日5～6餐），以软烂、易消化食物为主，细嚼慢咽；忌生冷、粗糙、过酸过甜及辛辣刺激性食物，避免浓茶、咖啡、碳酸饮料。\n2. 戒除烟酒，避免服用非甾体抗炎药（布洛芬、双氯芬酸等）及阿司匹林等损伤黏膜药物，确需服用者医师指导下联合PPI护胃。\n3. 规律作息，保证充足睡眠，避免劳累、熬夜及精神紧张、焦虑，保持情绪稳定。\n4. 适当活动，避免剧烈运动及腹压骤增动作（如举重、屏气用力、用力排便），防止吻合口出血或穿孔。\n\n【随诊要求】\n1. 规范治疗4～8周后复查胃镜，评估吻合口溃疡愈合情况，并常规取活检排除吻合口炎症及残胃癌变。\n2. 行Hp根除治疗者，停药至少4周后复查13C-或14C-尿素呼气试验，确认根除是否成功，失败者需调整方案行补救根除。\n3. 治疗期间出现黑便、呕血、腹痛突然加重、频繁呕吐或停止排气排便等，立即就诊。\n4. 吻合口溃疡复发率高，建议长期随访，每6～12个月复查胃镜1次，同时监测营养状况及维生素B12、铁代谢指标。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":837,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9ff7eba615ee58efe0c6039147522090294aafc54d376f2705b568f67fe68f8b","pinyin":"wenhekoukuiyang","initials":"whkky","setting":"out","caseName":"门诊病历705","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历705",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-00688f36f05cea700dfd","key":"v1-c9ccc21dfe2a3058|templates-00688f36f05cea700dfd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"细菌性食物中毒","category":"门诊病历模板","raw":{"name":"细菌性食物中毒","category":"门诊病历模板","case":{"case_name":"门诊病历706","templates":{"主诉":"恶心呕吐1天","现病史":"患者1周前无明显诱因出现细菌性食物中毒相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者恶心呕吐1天，一周来细菌性食物中毒相关症状逐渐加重并伴乏力，无发热，首先完善血常规检查明确有无细菌感染及血液浓缩；患者呕吐腹泻易致脱水及电解质紊乱，完善生化全项检查评估肝肾功能、电解质与酸碱平衡；呕吐剧烈可致心肌损伤，完善心肌酶谱、肌钙蛋白检查排除急性心肌损伤及心肌炎；完善凝血功能检查评估凝血状态，为补液及必要时抗感染治疗提供基线；完善血气分析明确有无代谢性酸中毒及缺氧。查心电图观察有无电解质紊乱相关心律失常及心肌缺血改变；查胸部X线片排除误吸所致肺部感染及有无胸腔积液；患者有恶心呕吐需与颅内病变鉴别，查头颅CT排除颅内出血、占位等中枢性呕吐病因；查腹部超声了解肝胆胰脾及有无肠管扩张、腹腔积液；必要时行床旁超声动态评估胃肠道及腹腔情况；完善D-二聚体检查排除血栓性疾病；完善BNP检查评估心功能，指导补液速度与容量管理；查乳酸了解组织灌注与缺氧程度，评估病情严重程度。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、心肌酶谱、肌钙蛋白、凝血功能、血气分析\n\n【影像学检查】\n心电图、胸部X线片、头颅CT、腹部超声\n\n【其他检查】\n床旁超声、D-二聚体、BNP、乳酸","初步诊断":"1. 细菌性食物中毒\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据病情紧急处理，具体用药根据诊断和生命体征决定。\n\n【一般治疗及生活指导】\n卧床休息，密切监测生命体征，保持呼吸道通畅，建立静脉通路。\n\n【随诊要求】\n根据病情决定是否住院或留观，如症状加重立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":838,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"55390d9850b7599b40f1583d190af3732536a5f2f67c5deff27c4f800c73191b","pinyin":"xijunxingshiwuzhongdu","initials":"xjxswzd","setting":"out","caseName":"门诊病历706","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历706",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-09112891eb1ed2d51909","key":"v1-c9ccc21dfe2a3058|templates-09112891eb1ed2d51909","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"病毒性肠炎","category":"门诊病历模板","raw":{"name":"病毒性肠炎","category":"门诊病历模板","case":{"case_name":"门诊病历707","templates":{"主诉":"腹泻1天","现病史":"患者1周前无明显诱因出现病毒性肠炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者腹泻1天，一周来病毒性肠炎相关症状逐渐加重并伴乏力，无发热及呕吐，首先完善血常规检查排除细菌感染、了解有无脱水所致血液浓缩；完善便常规+潜血检查明确有无白细胞、红细胞及潜血，鉴别病毒性与侵袭性细菌性肠炎并排除消化道出血；腹泻可伴发肝损伤，完善肝功能检查了解有无肝细胞损伤及胆道梗阻；完善淀粉酶、脂肪酶检查排除胰腺炎所致腹泻腹痛；查腹部超声了解肝胆胰脾形态及有无肠管扩张、腹腔积液；若腹泻持续或需明确肠道病变性质，安排胃镜或肠镜检查并取活检排除炎症性肠病及器质性病变；必要时查腹部CT了解肠壁增厚及有无腹腔并发症；查幽门螺杆菌检测（C13/C14呼气试验）明确有无感染以指导后续治疗；患者存在脱水及营养摄入不足，完善凝血功能检查评估凝血状态，为补液及营养支持提供基线。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 病毒性肠炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 口服补液盐Ⅲ（低渗性ORS）：1袋溶于250ml温水中，少量多次频服，首日按每次稀便后补充200-300ml、总量约500-1000ml/日，视脱水程度及尿量调整，腹泻停止后停用；轻中度脱水者必要时联合静脉补液（如复方氯化钠注射液）纠正电解质紊乱。\n2. 蒙脱石散3g tid，餐前口服，首剂加倍（6g），与其他药物间隔2小时以上服用，腹泻缓解后逐渐减量至停用。\n3. 双歧杆菌三联活菌胶囊420mg tid，餐后用40℃以下温水送服，与蒙脱石散间隔2小时，连用5-7天以恢复肠道菌群。\n4. 洛哌丁胺胶囊：仅用于腹泻频繁（≥6次/日）影响生活且无发热、便血者，首剂4mg，以后每次稀便后加服2mg，每日总量不超过16mg，腹泻停止即停药；发热、脓血便或疑似细菌性肠炎者禁用。\n\n【一般治疗及生活指导】\n1. 充分休息，保证睡眠，避免劳累；便后及饭前严格洗手，餐具独立清洗消毒，排泄物妥善处理，避免家庭内交叉感染。\n2. 饮食以清淡、易消化流质或半流质为主：米汤、稀粥、烂面条、蒸蛋羹，少量多餐；暂禁牛奶、豆浆、油腻、辛辣、生冷及粗纤维食物，症状缓解后逐步过渡至软食、普食。\n3. 每日饮水1500-2000ml（温开水或口服补液盐），注意腹部保暖，避免受凉；呕吐频繁者可暂禁食4-6小时，再少量试饮温水。\n\n【随诊要求】\n1. 病毒性肠炎多呈自限性，病程约3-7天；若腹泻超过1周未缓解或反复，建议复诊复查大便常规+隐血及电解质，排除其他病因。\n2. 治疗期间如出现持续高热不退、脓血便、剧烈腹痛、频繁呕吐不能进食进水、尿量明显减少（<400ml/日）、口干眼窝凹陷、精神萎靡等脱水及重症征象，应立即复诊或急诊就医。\n3. 老年、孕妇及合并糖尿病等基础疾病者，若口服补液2-3天仍无好转，应及时复诊评估静脉补液及进一步检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":839,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"84ab746bc41c9a71572964be3753c03136e1f39cb5131bdc9ea37b004bf557dc","pinyin":"bingduxingchangyan","initials":"bdxcy","setting":"out","caseName":"门诊病历707","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历707",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a48ddbb63f8d077ea0c7","key":"v1-c9ccc21dfe2a3058|templates-a48ddbb63f8d077ea0c7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"真菌性肠炎","category":"门诊病历模板","raw":{"name":"真菌性肠炎","category":"门诊病历模板","case":{"case_name":"门诊病历708","templates":{"主诉":"腹泻1天","现病史":"患者1周前无明显诱因出现真菌性肠炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者腹泻1天，一周来真菌性肠炎相关症状逐渐加重并伴乏力，无发热及呕吐，首先完善血常规检查了解白细胞及分类、有无感染及贫血；完善便常规+潜血检查寻找真菌孢子与菌丝、明确有无潜血，为真菌性肠炎诊断提供直接依据；抗真菌药物多经肝脏代谢，完善肝功能检查评估肝细胞功能并为用药提供基线；完善淀粉酶、脂肪酶检查排除胰腺炎所致腹泻腹痛；查腹部超声了解肝胆胰脾形态及有无肠管扩张、腹腔积液；为明确肠道黏膜受累范围及有无溃疡、假膜，安排胃镜或肠镜检查并取活检行病理及真菌染色，必要时查腹部CT评估肠壁增厚及有无腹腔并发症；长期腹泻及食欲下降者需查凝血功能检查评估凝血状态，为内镜活检及营养支持提供依据；查幽门螺杆菌检测（C13/C14呼气试验）明确有无合并感染，指导综合治疗。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 真菌性肠炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 首选口服不吸收抗真菌药：制霉菌素片50万U qid口服，连用7-14天（直接作用于肠道内念珠菌，全身吸收少，不良反应小）。\n2. 若症状较重或制霉菌素疗效欠佳：氟康唑胶囊150mg qd口服，首剂加倍300mg，连用7-14天。\n3. 联合微生态制剂调节菌群：双歧杆菌三联活菌胶囊（培菲康）420mg tid口服，与抗真菌药间隔2小时以上服用。\n4. 腹泻明显者可加用蒙脱石散3g tid空腹口服，与抗真菌药及益生菌均间隔2小时服用。\n\n【一般治疗及生活指导】\n1. 充分休息，避免劳累；进食清淡、易消化饮食（米粥、烂面条等），少量多餐，忌生冷、油腻、辛辣及高糖食物（高糖促进真菌生长）。\n2. 在医师指导下停用或减量广谱抗生素、糖皮质激素及免疫抑制剂等诱因药物，纠正菌群失调。\n3. 注意饮食卫生，饭前便后洗手，餐具煮沸消毒，内衣裤勤换洗；保持肛周皮肤清洁干燥，避免局部真菌蔓延及交叉感染。\n\n【随诊要求】\n1. 治疗1周后复诊，复查粪便常规、真菌镜检及真菌培养，评估疗效以决定是否调整用药。\n2. 治疗期间若腹泻加重、出现发热、黏液脓血便或明显脱水（口干、尿少、乏力）时，及时就诊。\n3. 疗程结束后建议复诊1次复查大便真菌检查；反复发作或病程迁延者可行肠镜检查排除其他肠道疾病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":840,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e2a5bd1e463ee5529c6c0120ec9ccb033880e278553f1bb251f7da4347ba24ac","pinyin":"zhenjunxingchangyan","initials":"zjxcy","setting":"out","caseName":"门诊病历708","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历708",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-71d79731ad0cb02d670c","key":"v1-c9ccc21dfe2a3058|templates-71d79731ad0cb02d670c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"寄生虫性肠炎","category":"门诊病历模板","raw":{"name":"寄生虫性肠炎","category":"门诊病历模板","case":{"case_name":"门诊病历709","templates":{"主诉":"腹泻1天","现病史":"患者1周前无明显诱因出现寄生虫性肠炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者腹泻1天，一周来寄生虫性肠炎相关症状逐渐加重并伴乏力，无发热及呕吐，首先完善血常规检查了解有无嗜酸性粒细胞增多及贫血，为寄生虫感染提供线索；完善便常规+潜血检查寻找虫卵、滋养体及潜血，此项为寄生虫性肠炎确诊的关键检查；寄生虫可累及肝胆，完善肝功能检查了解有无肝细胞损伤及胆道梗阻；完善淀粉酶、脂肪酶检查排除胰腺炎所致腹泻腹痛；查腹部超声了解肝胆胰脾形态及有无胆道虫体、肠管扩张、腹腔积液；为明确肠道黏膜病变及虫体附着部位，安排胃镜或肠镜检查并取活检行病理检查，必要时查腹部CT评估肠壁增厚及有无腹腔并发症；内镜及活检前需查凝血功能检查评估出血风险，同时评估长期腹泻所致营养及凝血异常；查幽门螺杆菌检测（C13/C14呼气试验）明确有无合并感染，指导综合治疗。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 寄生虫性肠炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗阿米巴原虫治疗（肠阿米巴病）：甲硝唑片0.4g po tid×7～10天，疗程结束后继服二氯尼特糠酸酯片500mg po tid×10天，以清除肠腔内包囊防止复发；或替硝唑片2g单次顿服。\n2. 抗贾第鞭毛虫治疗：甲硝唑片0.4g po tid×5～7天；或替硝唑片2g单次顿服；或阿苯达唑片400mg po qd×5天。\n3. 驱线虫治疗（蛔虫、钩虫、鞭虫感染）：阿苯达唑片400mg（2片）po 单次顿服，钩虫、鞭虫感染者于2周后重复顿服1次。\n4. 抗绦虫/吸虫治疗：吡喹酮片，绦虫病15～25mg/kg单次顿服（总量不超过2g）；华支睾吸虫病25mg/kg po tid×1天（总量约1.5g）。\n【一般治疗及生活指导】\n1. 急性期卧床休息，注意隔离，实施消化道隔离至症状消失、粪检连续3次阴性；便后及饭前用肥皂流水彻底洗手，便器需消毒，避免污染食物及水源。\n2. 给予清淡易消化流质或半流质饮食，少食多餐，忌辛辣、油腻及生冷食物，不饮酒；腹泻明显者注意补充水分及电解质，可口服补液盐（ORS）。\n3. 注意饮食卫生，不喝生水，不吃未洗净的蔬菜、瓜果及未煮熟的肉类、鱼虾，生熟砧板刀具分开；勤剪指甲，杜绝病从口入。\n4. 同餐居住的密切接触者应同步粪检筛查，阳性者一并驱虫治疗，防止家庭内交叉传播。\n【随诊要求】\n1. 疗程结束后1周、2周各复查粪便常规及寄生虫卵/包囊检查，连续3次阴性方为治愈。\n2. 若症状反复或便检持续阳性，及时复诊，必要时行结肠镜检查及黏膜活检明确诊断，调整驱虫方案。\n3. 治疗期间出现剧烈腹痛、高热、大量便血、脱水或便闭等情况随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":841,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5472185f3ac7dc397d1e0bfcfe5fb9551492f7679e656c67d45f002198b1aeef","pinyin":"jishengchongxingchangyan","initials":"jscxcy","setting":"out","caseName":"门诊病历709","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历709",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]}]);